# The two tiers of Get-PasswordInDescription as one regex each, for the
# CREDENTIAL_IN_DESCRIPTION triggers. The password word is the check's: password, passwd,
# passwort (EN/DE/LU), passord (NO), pasvorto (EO).
#
# An assignment is such a word with "=" or ":" and a value of three characters or more,
# or credentials in the userinfo part of a URL. A value that is a row of asterisks or an
# angle-bracket placeholder holds no credential, which the lookaheads say.
$Script:CredentialAssignmentPattern = '(?:pas(?:sw\S*|sord|vorto)|pwd|pw|\bpass|kennwort|\bparol[ae]?)\s*[=:]\s*(?!\*+(?:\s|$))(?!<[^>]+>)\S{3,}' +
    '|[a-z][a-z0-9+.-]*://[^\s/:@]+:(?!\*+@)(?!<[^>]+>@)[^\s/@]+@'
# A mention, as the check's tier 2 has it.
$Script:CredentialMentionPattern = 'pas(?:sw\S*|sord|vorto)|\bparol[ae]?\b|\bcred(ential)?s?\b|\b(secret|token)\s*[=:]\s*\S{5,}'
# What the mention triggers leave alone: an assignment, which the finding triggers take, and
# a masked or placeholder value, which the check does not report at all.
$Script:CredentialNoMentionPattern = $Script:CredentialAssignmentPattern +
    '|(?:pas(?:sw\S*|sord|vorto)|pwd|pw|\bpass|kennwort|\bparol[ae]?)\s*[=:]\s*(?:\*+(?:\s|$)|<[^>]+>)' +
    '|://[^\s/:@]+:(?:\*+|<[^>]+>)@'

# Central Finding Definitions
# Structure: FindingID => @{ Title, Risk, BaseScore, Description, Impact, Attack, Remediation, References, Tools, MITRE }
#
# BaseScore values (0-100) represent intrinsic risk:
#   100     : Immediate domain compromise (DCSync, Golden Ticket)
#   80-99   : Direct privilege escalation (ESC1, Unconstrained Delegation)
#   60-79   : High-risk credential exposure or ACL abuse
#   40-59   : Credential exposure requiring cracking or significant ACL issues
#   30-39   : Configuration weaknesses enabling attacks
#   20-29   : Policy violations or informational findings
#   10-19   : Low-risk informational items
#   0       : Secure configurations (positive findings)
#
$Script:FindingDefinitions = @{

    # ============================================================================
    # KERBEROS FINDINGS
    # ============================================================================

    'KERBEROASTABLE_SPN' = @{
        Title = "Kerberoastable Service Account"
        Risk = "Finding"
        BaseScore = 35  # Requires offline password cracking
        Description = "This user account has a Service Principal Name (SPN) set, making it vulnerable to Kerberoasting. Any authenticated domain user can request a Kerberos service ticket (TGS) for this account and attempt to crack the password offline."
        Impact = @(
            "Attackers can obtain the account's password hash without triggering account lockout"
            "Offline password cracking can be performed indefinitely"
            "If the password is weak, the account can be compromised within hours or days"
            "Service accounts often have elevated privileges, enabling lateral movement or privilege escalation"
        )
        Attack = @(
            "1. Attacker authenticates to the domain with any valid user credentials"
            "2. Requests a TGS ticket for the service principal name"
            "3. Extracts the ticket from memory (encrypted with service account's password hash)"
            "4. Cracks the password offline using tools like Hashcat or John the Ripper"
            "5. Uses the cracked password to authenticate as the service account"
        )
        Remediation = @(
            "Use Group Managed Service Accounts (gMSA) instead of regular user accounts for services"
            "Set strong, randomly generated passwords (25+ characters) for service accounts"
            "Enable AES encryption for service accounts (reduces cracking speed significantly)"
            "Regularly rotate service account passwords"
            "Monitor for TGS requests to service accounts from unusual sources"
        )
        RemediationCommands = @(
            @{
                Description = "Enable AES encryption for the service account"
                Command = "Set-ADUser -Identity 'SERVICE_ACCOUNT' -KerberosEncryptionType AES128,AES256"
            }
            @{
                Description = "Set a strong random password (25+ chars)"
                Command = "`$NewPwd = [System.Web.Security.Membership]::GeneratePassword(25,5); Set-ADAccountPassword -Identity 'SERVICE_ACCOUNT' -NewPassword (ConvertTo-SecureString `$NewPwd -AsPlainText -Force)"
            }
            @{
                Description = "Remove the SPN if the service is no longer needed"
                Command = "Set-ADUser -Identity 'SERVICE_ACCOUNT' -ServicePrincipalNames @{Remove='SPN_VALUE'}"
            }
        )
        References = @(
            @{ Title = "Kerberoasting - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1558/003/" }
            @{ Title = "Kerberoasting - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/kerberoast.html" }
            @{ Title = "Detecting Kerberoasting - Microsoft"; Url = "https://docs.microsoft.com/en-us/defender-for-identity/compromised-credentials-alerts" }
            @{ Title = "Kerberoasting Revisited - Harmj0y"; Url = "https://blog.harmj0y.net/redteaming/kerberoasting-revisited/" }
        )
        Tools = @("Rubeus", "Impacket", "PowerView", "Hashcat", "John the Ripper")
        MITRE = "T1558.003"
        Triggers = @(
            @{ Attribute = 'servicePrincipalName'; Custom = 'is_not_computer'; Severity = 'Finding' }
        )
    }

    'ASREP_ROASTABLE' = @{
        Title = "AS-REP Roastable Account (No Pre-Authentication)"
        Risk = "Finding"
        BaseScore = 30  # Requires offline password cracking, no auth needed
        Description = "This account has Kerberos pre-authentication disabled (DONT_REQUIRE_PREAUTH flag). This allows attackers to request an AS-REP ticket for this account without knowing the password, which can then be cracked offline."
        Impact = @(
            "Attackers can obtain the account's password hash without ANY authentication"
            "No failed login attempts are logged during the attack"
            "Offline password cracking can be performed indefinitely"
            "Compromised accounts can be used for initial access or privilege escalation"
        )
        Attack = @(
            "1. Attacker identifies accounts with DONT_REQUIRE_PREAUTH flag"
            "2. Sends AS-REQ to the KDC for the target account"
            "3. KDC responds with AS-REP encrypted with the account's password hash"
            "4. Attacker cracks the password offline using Hashcat or John the Ripper"
            "5. Uses the cracked password to authenticate as the target account"
        )
        Remediation = @(
            "Enable Kerberos pre-authentication for all accounts"
            "Review why pre-authentication was disabled and find alternatives"
            "Use strong passwords for accounts that must have pre-auth disabled"
            "Monitor for AS-REQ requests without pre-authentication"
        )
        RemediationCommands = @(
            @{
                Description = "Enable Kerberos pre-authentication for the account"
                Command = "Set-ADAccountControl -Identity 'USERNAME' -DoesNotRequirePreAuth `$false"
            }
            @{
                Description = "Find all accounts with pre-auth disabled"
                Command = "Get-ADUser -Filter {DoesNotRequirePreAuth -eq `$true} -Properties DoesNotRequirePreAuth"
            }
        )
        References = @(
            @{ Title = "AS-REP Roasting - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1558/004/" }
            @{ Title = "AS-REP Roasting - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/asreproast.html" }
            @{ Title = "Kerberos Pre-Authentication - Microsoft"; Url = "https://learn.microsoft.com/en-us/defender-for-identity/security-posture-assessments/accounts" }
            @{ Title = "Roasting AS-REPs - Harmj0y"; Url = "https://blog.harmj0y.net/activedirectory/roasting-as-reps/" }
        )
        Tools = @("Rubeus", "Impacket", "Hashcat", "John the Ripper")
        MITRE = "T1558.004"
        Triggers = @(
            @{ Attribute = 'userAccountControl'; Pattern = 'DONT_REQ_PREAUTH'; Severity = 'Finding' }

            # Membership in Protected Users does not clear the flag, so the row stays a
            # finding - but RC4 is refused for a member and the AS-REP comes back AES-
            # encrypted, which is the difference between a crack and a cracking budget.
            @{ Attribute = 'protectedUsersMember'; Severity = 'Hint' }
        )
    }

    # Reached through the summary line of Get-ASREPRoastableAccounts (-FindingId), which
    # is written only when an account without pre-authentication exists and at least one
    # account carries an SPN.
    'KERBEROAST_WITHOUT_PREAUTH' = @{
        Title = "Kerberoasting Without Credentials Through an Account Without Pre-Authentication"
        Risk = "Finding"
        BaseScore = 35
        Description = "An account that does not require Kerberos pre-authentication lets anybody send an AS-REQ for it, and the service name in that request may be any account with a service principal name. The KDC answers with a service ticket for that service, encrypted with its account's key - which is all Kerberoasting needs. With one such account in the domain, every kerberoastable account can be roasted by an attacker who holds no credentials at all, only a list of account names."
        Impact = @(
            "Kerberoasting no longer needs a domain account - network access to a domain controller is enough"
            "Every service account with an SPN is exposed, whatever its own pre-authentication setting"
            "The requests carry no pre-authentication and show up only as AS-REQs for the one account without it"
        )
        Attack = @(
            "1. Attacker learns the name of an account without pre-authentication and of the accounts with an SPN"
            "2. Sends an AS-REQ for the first account whose sname is one of the SPN accounts (Rubeus kerberoast /nopreauth, impacket GetUserSPNs -no-preauth)"
            "3. Cracks the service tickets offline like any Kerberoast result"
        )
        Remediation = @(
            "Require pre-authentication on every account - removing the last account without it closes this path for all SPN accounts at once"
            "Give the accounts with an SPN long random passwords, or move them to gMSAs, which closes it for each of them whatever else happens"
        )
        RemediationCommands = @(
            @{
                Description = "Find the accounts without pre-authentication"
                Command = "Get-ADUser -Filter {DoesNotRequirePreAuth -eq `$true} -Properties DoesNotRequirePreAuth | Select-Object Name,SamAccountName"
            }
        )
        References = @(
            @{ Title = "New Attack Paths? AS Requested Service Tickets - Semperis"; Url = "https://www.semperis.com/blog/new-attack-paths-as-requested-sts/" }
            @{ Title = "Kerberoasting - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1558/003/" }
        )
        Tools = @("Rubeus", "Impacket")
        MITRE = "T1558.003"
    }

    'KERBEROS_HASH_CRACKABLE' = @{
        Title = "Kerberos Hash - Offline Cracking"
        Risk = "Finding"
        BaseScore = 35
        Description = "This hash was extracted from a Kerberos ticket (TGS for Kerberoasting or AS-REP for AS-REP Roasting). The hash is encrypted with the target account's password and can be cracked offline without any interaction with the domain."
        Impact = @(
            "Offline cracking can run indefinitely without triggering account lockout"
            "Weak passwords can be cracked within minutes using modern GPUs"
            "Even complex passwords may fall to dictionary attacks with rules"
            "Once cracked, the attacker has valid credentials for the target account"
            "No logs are generated during offline cracking - the attack is undetectable"
        )
        Attack = @(
            "1. Save the hash to a file (e.g., hash.txt)"
            "2. Identify the hash type (Kerberoast: mode 13100/18200/19600/19700, AS-REP: mode 18200)"
            "3. Run Hashcat with a wordlist and rules for maximum effectiveness"
            "4. Wait for the password to be cracked"
            "5. Use the recovered password to authenticate as the service account"
        )
        Remediation = @(
            "Set strong, randomly generated passwords (25+ characters) for service accounts"
            "Use Group Managed Service Accounts (gMSA) which have 240-character auto-rotating passwords"
            "Enable AES encryption to slow down cracking (still crackable, but significantly slower)"
            "Implement a password policy that prevents dictionary words"
            "Regularly rotate service account passwords"
        )
        RemediationCommands = @(
            @{
                Description = "Crack Kerberoast hash (RC4/NTLM)"
                Command = "hashcat -m 13100 -a 0 hash.txt wordlist.txt -r rules/best64.rule"
            }
            @{
                Description = "Crack Kerberoast hash (AES256)"
                Command = "hashcat -m 19700 -a 0 hash.txt wordlist.txt -r rules/best64.rule"
            }
            @{
                Description = "Crack AS-REP hash"
                Command = "hashcat -m 18200 -a 0 hash.txt wordlist.txt -r rules/best64.rule"
            }
            @{
                Description = "Using John the Ripper"
                Command = "john --wordlist=wordlist.txt --rules=best64 hash.txt"
            }
        )
        References = @(
            @{ Title = "Hashcat Wiki - Kerberos TGS-REP"; Url = "https://hashcat.net/wiki/doku.php?id=example_hashes" }
            @{ Title = "Kerberoasting - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/kerberoast.html" }
            @{ Title = "AS-REP Roasting - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/asreproast.html" }
            @{ Title = "Managed Service Accounts - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/group-managed-service-accounts-overview" }
        )
        Tools = @("Hashcat", "John the Ripper")
        MITRE = "T1110.002"
        Triggers = @(
            @{ Attribute = 'KerberoastingHash'; Severity = 'Finding' }
            @{ Attribute = 'ASREPRoastingHash'; Severity = 'Finding' }
        )
    }

    'KRBTGT_PASSWORD_OLD' = @{
        Title = "krbtgt Password Not Rotated"
        Risk = "Finding"
        BaseScore = 80
        Description = "The krbtgt account password has not been changed in an extended period. This account is used to encrypt all Kerberos tickets in the domain. If compromised, attackers can create Golden Tickets with unlimited validity."
        Impact = @(
            "Attackers with access to the krbtgt hash can forge any Kerberos ticket"
            "Golden Tickets provide complete domain compromise with persistence"
            "Tickets can be created for non-existent users with any group membership"
            "Standard password resets do not invalidate existing Golden Tickets"
            "Recovery requires rotating krbtgt password TWICE with proper timing"
        )
        Attack = @(
            "1. Attacker obtains the krbtgt password hash (via DCSync, NTDS.dit extraction)"
            "2. Creates a Golden Ticket with arbitrary user/group SIDs"
            "3. Uses the ticket to access any resource in the domain"
            "4. Ticket remains valid until krbtgt password is rotated twice"
        )
        Remediation = @(
            "Rotate krbtgt password every 180 days minimum"
            "After suspected compromise, rotate TWICE with 10+ hours between rotations"
            "Monitor for Kerberos ticket anomalies (long lifetime, unusual encryption)"
            "Implement tiered administration to protect krbtgt access"
        )
        RemediationCommands = @(
            @{
                Description = "Reset krbtgt password (use Microsoft script for production)"
                Command = "Set-ADAccountPassword -Identity 'krbtgt' -Reset -NewPassword (ConvertTo-SecureString -AsPlainText 'NewRandomPassword123!' -Force)"
            }
            @{
                Description = "Check krbtgt last password change"
                Command = "Get-ADUser krbtgt -Properties PasswordLastSet | Select-Object Name, PasswordLastSet"
            }
        )
        References = @(
            @{ Title = "Golden Ticket - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1558/001/" }
            @{ Title = "Golden Ticket - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/golden-ticket.html" }
            @{ Title = "krbtgt Account Password Reset - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-reset-the-krbtgt-password" }
            @{ Title = "Detecting Golden Tickets"; Url = "https://adsecurity.org/?p=1515" }
        )
        Tools = @("Mimikatz", "Impacket", "Rubeus")
        MITRE = "T1558.001"
        Triggers = @(
            @{ Attribute = 'krbtgtPasswordAge'; Custom = 'days_over_365'; Severity = 'Finding' }
            @{ Attribute = 'krbtgtPasswordAge'; Custom = 'days_181_to_365'; Severity = 'Hint' }
        )
    }

    'GUEST_ACCOUNT_ENABLED' = @{
        Title = "Guest Account Enabled"
        Risk = "Finding"
        BaseScore = 70
        Description = "The built-in Guest account (RID 501) is enabled and potentially accessible for anonymous or low-privilege access. This account should normally be disabled as it provides an unnecessary attack vector."
        Impact = @(
            "Allows unauthenticated or minimally authenticated access"
            "Can be used for initial foothold in the network"
            "Often has weak or no password protection"
            "May have been granted unintended permissions over time"
        )
        Attack = @(
            "1. Attacker identifies enabled Guest account"
            "2. Attempts authentication with blank or common passwords"
            "3. Enumerates accessible resources and permissions"
            "4. Uses Guest access for lateral movement or privilege escalation"
        )
        Remediation = @(
            "Disable the Guest account immediately"
            "Review group memberships and remove from all groups"
            "Audit any permissions explicitly granted to Guest"
            "Monitor for attempts to re-enable the account"
        )
        RemediationCommands = @(
            @{
                Description = "Disable Guest account via PowerShell"
                Command = "Disable-ADAccount -Identity 'Guest'"
            }
            @{
                Description = "Verify Guest account is disabled"
                Command = "Get-ADUser -Identity 'Guest' -Properties Enabled | Select-Object Name,Enabled,SID"
            }
            @{
                Description = "Disable Guest account via Group Policy (domain-wide enforcement)"
                Command = "# In Group Policy Management: Computer Configuration > Policies > Windows Settings > Security Settings > Local Policies > Security Options > 'Accounts: Guest account status' = Disabled"
            }
            @{
                Description = "Remove Guest account from all group memberships"
                Command = "Get-ADUser -Identity 'Guest' -Properties MemberOf | Select-Object -ExpandProperty MemberOf | ForEach-Object { Remove-ADGroupMember -Identity `$_ -Members 'Guest' -Confirm:`$false }"
            }
            @{
                Description = "Check for permissions explicitly granted to Guest account"
                Command = "(Get-Acl 'AD:\DC=domain,DC=com').Access | Where-Object {`$_.IdentityReference -like '*Guest*'} | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize"
            }
        )
        References = @(
            @{ Title = "Microsoft Security Baseline - Guest Account"; Url = "https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/accounts-guest-account-status" }
            @{ Title = "CIS Benchmark - Disable Guest Account"; Url = "https://www.cisecurity.org/benchmark/microsoft_windows_server" }
            @{ Title = "Accounts: Guest account status - Windows 10"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/accounts-guest-account-status" }
        )
        Tools = @()
        MITRE = "T1078.001"
        Triggers = @(
            @{ Attribute = 'accountStatus'; Pattern = 'ENABLED'; Severity = 'Hint' }
        )
    }

    'GUEST_ACCOUNT_DISABLED' = @{
        Title = "Guest Account Disabled"
        Risk = "Secure"
        BaseScore = 0
        Description = "The built-in Guest account (RID 501) is properly disabled. This is a secure configuration that prevents unauthenticated or low-privilege access through this legacy account."
        Impact = @(
            "Blocks anonymous or minimally authenticated access via Guest account"
            "Prevents attackers from using Guest account as initial foothold"
            "Reduces attack surface by disabling unnecessary account"
        )
        Attack = @()
        Remediation = @(
            "No action required - Guest account is already disabled"
            "Ensure the account remains disabled through Group Policy"
            "Regularly audit that the account has not been re-enabled"
        )
        RemediationCommands = @()
        References = @(
            @{ Title = "Microsoft Security Baseline - Guest Account"; Url = "https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/accounts-guest-account-status" }
            @{ Title = "CIS Benchmark - Disable Guest Account"; Url = "https://www.cisecurity.org/benchmark/microsoft_windows_server" }
        )
        Tools = @()
        MITRE = ""
        Triggers = @(
            @{ Attribute = 'accountStatus'; Pattern = 'Disabled'; Severity = 'Secure' }
        )
    }

    # ============================================================================
    # DELEGATION FINDINGS
    # ============================================================================

    'UNCONSTRAINED_DELEGATION' = @{
        Title = "Unconstrained Delegation Enabled"
        Risk = "Finding"
        BaseScore = 85
        Description = "This computer or user has unconstrained delegation enabled (TRUSTED_FOR_DELEGATION). Any user who authenticates to this system will have their TGT stored in memory, allowing the system to impersonate them to ANY service in the domain."
        Impact = @(
            "TGTs of all authenticating users are cached on the system"
            "Attackers who compromise this system can steal TGTs of privileged users"
            "Enables impersonation attacks against any domain service"
            "Domain Controllers authenticate to computers via print spooler (PrinterBug)"
            "Can lead to complete domain compromise within minutes"
        )
        Attack = @(
            "1. Attacker compromises the unconstrained delegation system"
            "2. Coerces authentication from a Domain Controller (PrinterBug, PetitPotam)"
            "3. Captures the DC's TGT from memory"
            "4. Uses the TGT to perform DCSync and extract all domain credentials"
            "5. Creates Golden Tickets for persistent access"
        )
        Remediation = @(
            "Replace unconstrained delegation with constrained delegation or RBCD"
            "Add high-value accounts to 'Protected Users' group"
            "Enable 'Account is sensitive and cannot be delegated' for privileged accounts"
            "Disable the Print Spooler service on Domain Controllers"
            "Monitor for TGT requests from unconstrained delegation systems"
        )
        RemediationCommands = @(
            @{
                Description = "Remove unconstrained delegation from computer"
                Command = "Set-ADComputer -Identity 'COMPUTERNAME' -TrustedForDelegation `$false"
            }
            @{
                Description = "Add admin account to Protected Users group"
                Command = "Add-ADGroupMember -Identity 'Protected Users' -Members 'ADMIN_ACCOUNT'"
            }
            @{
                Description = "Make account sensitive (cannot be delegated)"
                Command = "Set-ADUser -Identity 'ADMIN_ACCOUNT' -AccountNotDelegated `$true"
            }
            @{
                Description = "Disable Print Spooler on Domain Controller"
                Command = "Invoke-Command -ComputerName 'DC_NAME' -ScriptBlock { Stop-Service Spooler; Set-Service Spooler -StartupType Disabled }"
            }
        )
        References = @(
            @{ Title = "Unconstrained Delegation - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/unconstrained-delegation.html" }
            @{ Title = "Kerberos Delegation - Microsoft"; Url = "https://learn.microsoft.com/en-us/defender-for-identity/security-posture-assessments/accounts" }
            @{ Title = "Kerberos Delegation Explained"; Url = "https://adsecurity.org/?p=1667" }
            @{ Title = "PrinterBug Attack"; Url = "https://github.com/leechristensen/SpoolSample" }
        )
        Tools = @("Rubeus", "Mimikatz", "SpoolSample", "PetitPotam", "Impacket")
        MITRE = "T1550.003"
        Triggers = @(
            # Not on a domain controller. A DC carries TRUSTED_FOR_DELEGATION by design,
            # and this card's first remediation command - Set-ADComputer
            # -TrustedForDelegation $false - takes a DC out of service. A DC gets
            # UNCONSTRAINED_DELEGATION_DC below instead. The severity was already damped
            # to Hint for a DC by UAC_SEVERITY_OVERRIDE, but a SeverityOnly trigger
            # changes no finding id, so the DC inventory carried a red card's text in a
            # yellow line.
            @{ Attribute = 'userAccountControl'; Pattern = 'TRUSTED_FOR_DELEGATION'; Custom = 'is_not_dc_uac'; Severity = 'Finding' }
        )
    }

    'UNCONSTRAINED_DELEGATION_DC' = @{
        Title = "Unconstrained Delegation on a Domain Controller"
        Risk = "Hint"
        BaseScore = 15
        Description = "This domain controller has TRUSTED_FOR_DELEGATION set, which is its normal state: a DC accepts forwardable TGTs by design. It is listed because it is the target that makes coercion worth something - a relayed or coerced authentication from a privileged account lands its TGT in this machine's memory."
        Impact = @(
            "TGTs of authenticating users are cached on the domain controller"
            "A coercion primitive (PrinterBug, PetitPotam, DFSCoerce) can direct a privileged account's authentication here"
            "The flag itself is not a misconfiguration and cannot be removed without breaking the DC"
        )
        Attack = @(
            "1. Attacker gains code execution on the domain controller, or relays an authentication to it"
            "2. Extracts cached TGTs from LSASS"
            "3. Impersonates the accounts whose tickets were cached"
        )
        Remediation = @(
            "Do not clear the flag - a domain controller needs it. The controls are elsewhere"
            "Put Tier 0 accounts in Protected Users, or set 'Account is sensitive and cannot be delegated', so their TGTs are never forwarded here"
            "Disable the Print Spooler service on domain controllers, which removes the PrinterBug coercion primitive"
            "Enable LDAP signing and channel binding, and EPA on the certificate enrollment endpoints, so a coerced authentication cannot be relayed"
            "Patch and monitor the coercion primitives (PetitPotam, DFSCoerce, ShadowCoerce)"
        )
        RemediationCommands = @(
            @{
                Description = "Add a privileged account to Protected Users, so its TGT is never forwarded"
                Command = "Add-ADGroupMember -Identity 'Protected Users' -Members 'ADMIN_ACCOUNT'"
            }
            @{
                Description = "Mark an account as sensitive and not delegatable"
                Command = "Set-ADUser -Identity 'ADMIN_ACCOUNT' -AccountNotDelegated `$true"
            }
            @{
                Description = "Disable the Print Spooler on a domain controller"
                Command = "Invoke-Command -ComputerName 'DC_NAME' -ScriptBlock { Stop-Service Spooler; Set-Service Spooler -StartupType Disabled }"
            }
        )
        References = @(
            @{ Title = "Unconstrained Delegation - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/unconstrained-delegation.html" }
            @{ Title = "PrinterBug Attack"; Url = "https://github.com/leechristensen/SpoolSample" }
            @{ Title = "Protected Users Security Group"; Url = "https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group" }
        )
        Tools = @("Rubeus", "Mimikatz", "SpoolSample", "PetitPotam")
        MITRE = "T1550.003"
        Triggers = @(
            @{ Attribute = 'userAccountControl'; Pattern = 'TRUSTED_FOR_DELEGATION'; Custom = 'is_dc_uac'; Severity = 'Hint' }
        )
    }

    'UNCONSTRAINED_DELEGATION_EXPOSED_ACCOUNTS' = @{
        Title = "Privileged Accounts Hand Their TGT to Unconstrained Delegation Hosts"
        Risk = "Finding"
        BaseScore = 40
        Description = "These privileged accounts are neither marked 'Account is sensitive and cannot be delegated' nor in Protected Users. When one of them logs on with Kerberos to a host trusted for unconstrained delegation, the ticket it presents carries a copy of its TGT, and the host keeps it in memory: whoever controls the host can act as that account anywhere in the domain. The sensitive flag stops this at every domain functional level, Protected Users at Windows Server 2012 R2 or higher."
        Impact = @(
            "A routine logon to the host - a remote desktop session, a mapped drive, a management console - leaves a reusable TGT of a privileged account behind"
            "With the TGT of a Domain Admin the host's controller can replicate the directory (DCSync)"
            "A Domain Controller's own machine account is not covered by either control, so a coerced Domain Controller still hands its TGT to these hosts whatever is done here"
        )
        Attack = @(
            "1. Attacker gains administrative control of a host with unconstrained delegation"
            "2. Waits for, or provokes, a Kerberos logon of one of the listed accounts to that host"
            "3. Extracts the forwarded TGT from memory (Rubeus monitor, Mimikatz sekurlsa::tickets)"
            "4. Uses the TGT as that account"
        )
        Remediation = @(
            "Mark every privileged account 'Account is sensitive and cannot be delegated'"
            "Put privileged user accounts in Protected Users once the domain functional level is Windows Server 2012 R2 or higher - not service or computer accounts"
            "Replace unconstrained delegation on the hosts with constrained delegation or resource-based constrained delegation"
        )
        RemediationCommands = @(
            @{
                Description = "Mark an account as sensitive and not delegatable"
                Command = "Set-ADUser -Identity 'ADMIN_ACCOUNT' -AccountNotDelegated `$true"
            }
            @{
                Description = "Add a privileged user to Protected Users"
                Command = "Add-ADGroupMember -Identity 'Protected Users' -Members 'ADMIN_ACCOUNT'"
            }
            @{
                Description = "List the accounts with adminCount that can still be delegated"
                Command = "Get-ADUser -LDAPFilter '(&(adminCount=1)(!(userAccountControl:1.2.840.113556.1.4.803:=1048576)))' | Select-Object SamAccountName"
            }
        )
        References = @(
            @{ Title = "Protected Users Security Group - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group" }
            @{ Title = "Kerberos Delegation Explained"; Url = "https://adsecurity.org/?p=1667" }
            @{ Title = "Unconstrained Delegation - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/unconstrained-delegation.html" }
        )
        Tools = @("Rubeus", "Mimikatz")
        MITRE = "T1550.003"
    }

    'CONSTRAINED_DELEGATION_PROTOCOL_TRANSITION' = @{
        Title = "Constrained Delegation with Protocol Transition"
        Risk = "Finding"
        BaseScore = 50
        Description = "This account has constrained delegation with protocol transition enabled (TRUSTED_TO_AUTH_FOR_DELEGATION). This allows the account to impersonate ANY user to the configured services without requiring the user's authentication."
        Impact = @(
            "Account can impersonate any user (including Domain Admins) to target services"
            "No authentication from the impersonated user is required"
            "If any target SPN points at a Domain Controller, this is a direct path to Domain Admin"
            "Attackers who compromise this account gain significant lateral movement capability"
        )
        Attack = @(
            "1. Attacker compromises the account with protocol transition"
            "2. Uses S4U2Self to obtain a service ticket for any user"
            "3. Uses S4U2Proxy to access the configured target services as that user"
            "4. If LDAP is a target, performs privileged AD operations"
        )
        Remediation = @(
            "Review if protocol transition is actually required"
            "Switch to Resource-Based Constrained Delegation (RBCD) where possible"
            "Do not delegate to a Domain Controller at all - restricting the service class is no protection"
            "Add privileged accounts to 'Protected Users' group"
            "Monitor S4U2Self and S4U2Proxy requests"
        )
        RemediationCommands = @(
            @{
                Description = "Disable protocol transition (TrustedToAuthForDelegation flag)"
                Command = "Set-ADAccountControl -Identity 'ACCOUNT_NAME' -TrustedToAuthForDelegation `$false"
            }
            @{
                Description = "Find all accounts with protocol transition enabled"
                Command = "Get-ADObject -LDAPFilter '(userAccountControl:1.2.840.113556.1.4.803:=16777216)' -Properties userAccountControl,servicePrincipalName,msDS-AllowedToDelegateTo"
            }
            @{
                Description = "Enable auditing for Kerberos service ticket operations"
                Command = "auditpol /set /subcategory:'Kerberos Service Ticket Operations' /success:enable /failure:enable"
            }
        )
        References = @(
            @{ Title = "S4U2Self Abuse"; Url = "https://blog.harmj0y.net/activedirectory/s4u2pwnage/" }
            @{ Title = "Constrained Delegation - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/constrained-delegation.html" }
            @{ Title = "Constrained Delegation - Microsoft"; Url = "https://docs.microsoft.com/en-us/windows-server/security/kerberos/kerberos-constrained-delegation-overview" }
        )
        Tools = @("Rubeus", "Impacket", "PowerView")
        MITRE = "T1550.003"
        Triggers = @(
            # Only the UAC flag means protocol transition (S4U2Self + S4U2Proxy, exploitable
            # without the victim doing anything). The bare presence of
            # msDS-AllowedToDelegateTo does NOT - that is plain Kerberos-only constrained
            # delegation and belongs to CONSTRAINED_DELEGATION, which now carries that
            # trigger. Before, the pattern-less trigger here claimed every constrained
            # delegation and told the reader "protocol transition enabled" about accounts
            # that had no such flag, while CONSTRAINED_DELEGATION had no triggers at all and
            # was unreachable.
            @{ Attribute = 'userAccountControl'; Pattern = 'TRUSTED_TO_AUTH_FOR_DELEGATION'; Severity = 'Finding' }

            # The delegation targets of such an account carry this card too, not the
            # milder one. Only the userAccountControl row used to say which of the two
            # kinds of constrained delegation this is, and a reader looking at the
            # services the account may impersonate users to was told the weaker story.
            @{ Attribute = 'msDS-AllowedToDelegateTo'; Custom = 'is_protocol_transition_delegation'; Severity = 'Finding' }
        )
    }

    'GPO_NOT_CURRENTLY_EFFECTIVE' = @{
        Title = "This GPO Setting Does Not Currently Apply"
        Risk = "Note"
        BaseScore = 10
        Description = "The setting reported above is written into a Group Policy Object that does not currently deliver it: the half of the policy it lives in is switched off, or the GPO is linked nowhere. The setting is real and it is still in the directory; it simply does not reach a machine as things stand."
        Impact = @(
            "Nothing today - which is the point of saying so, because an identical entry in an active GPO is a live exposure"
            "One click away from applying: re-enabling the disabled half, or linking the GPO, makes it effective with no further change"
            "A forgotten policy is the usual reason a setting like this survives, and a forgotten policy is the one nobody reviews before re-linking it"
        )
        Attack = @(
            "1. The setting sits dormant and out of mind"
            "2. Someone links the GPO or re-enables the disabled half, for an unrelated reason"
            "3. The setting takes effect on every machine in scope, with nobody having reviewed it"
        )
        Remediation = @(
            "Fix or remove the setting rather than relying on the GPO staying switched off"
            "Delete a GPO that is no longer wanted, instead of unlinking it and leaving it in the directory"
            "Check who may link GPOs and who may edit this one - see the GPO permission findings"
        )
        RemediationCommands = @(
            @{
                Description = "Show the status and the links of the GPO"
                Command = "Get-GPO -Name 'GPO_NAME' | Select-Object DisplayName,GpoStatus; Get-GPOReport -Name 'GPO_NAME' -ReportType Xml"
            }
            @{
                Description = "Delete a GPO that is no longer needed"
                Command = "Remove-GPO -Name 'GPO_NAME'"
            }
        )
        References = @(
            @{ Title = "Group Policy Object status"; Url = "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/set-gpostatus" }
        )
        Tools = @("Group Policy Management Console")
        MITRE = "T1484.001"
        Triggers = @(
            # GPOStatus carries this now, in the vocabulary Get-DomainGPO decodes the flags
            # attribute into. It used to be a sentence of its own that repeated what the
            # LinkedOUs row above it had already said.
            @{ Attribute = 'GPOStatus'; Severity = 'Note' }
        )
    }

    'PRIVILEGED_ACCOUNT_AFFECTED' = @{
        Title = "The Affected Account Is Privileged"
        Risk = "Finding"
        BaseScore = 80
        Description = "The weakness reported on this account is not confined to it: the account holds privileged rights in the domain, so whatever the finding above allows an attacker to obtain applies with those rights."
        Impact = @(
            "The account's credential is worth the domain rather than one service"
            "Privilege is established from group membership resolved through the chain, not from adminCount - that attribute is set by AdminSDHolder and never cleared, and it never appears on some privileged groups at all"
        )
        Attack = @(
            "1. Attacker exploits the weakness reported on the account"
            "2. The rights that come with it are the account's own, so no further escalation is needed"
        )
        Remediation = @(
            "Treat this account ahead of the others in the same finding"
            "Question whether the account needs the privilege, the exposure, or either"
            "Add it to 'Protected Users' where the account type allows it"
        )
        References = @(
            @{ Title = "AdminSDHolder and adminCount"; Url = "https://learn.microsoft.com/en-us/previous-versions/technet-magazine/ee361593(v=msdn.10)" }
            @{ Title = "Securing Privileged Access"; Url = "https://learn.microsoft.com/en-us/security/privileged-access-workstations/overview" }
        )
        Tools = @("PowerView", "BloodHound")
        MITRE = "T1078.002"
        Triggers = @(
            # Written for checks that set PrivilegedAccount on a privileged account only,
            # with the reason as its value. Get-CredentialRoaming writes Yes or No on every
            # row, and without the exclusion this pattern-less trigger put the red
            # "affected account is privileged" card on every No.
            @{ Attribute = 'PrivilegedAccount'; ExcludePattern = '^No$'; Severity = 'Finding' }
        )
    }

    'ROASTABLE_PRIVILEGED_ACCOUNT' = @{
        Title = "Roastable Account with Privileged Rights"
        Risk = "Finding"
        BaseScore = 85
        Description = "This account can be Kerberoasted or AS-REP roasted and it holds privileged rights in the domain. Every roastable account hands out a hash to crack offline; on this one, cracking it is a domain compromise rather than the compromise of a service."
        Impact = @(
            "The hash of a privileged account is obtainable by any authenticated user, and for AS-REP roasting by anyone at all"
            "Cracking happens offline, so no lockout policy, no failed logon, nothing to alert on"
            "Success grants the account's rights directly - no further escalation needed"
            "Service account passwords are set once and rarely rotated, which is what makes the offline attack worth running"
        )
        Attack = @(
            "1. Attacker requests a service ticket for the SPN, or an AS-REP for the account"
            "2. The reply is encrypted with a key derived from the account's password"
            "3. The hash is cracked offline against a wordlist, with no interaction with the domain"
            "4. The recovered password is used directly with the account's privileges"
        )
        Remediation = @(
            "A privileged account should not be roastable at all: remove the SPN, or move the service to a group Managed Service Account whose 240-byte password cannot be cracked"
            "If the account carries DONT_REQ_PREAUTH, clear it - pre-authentication is what makes AS-REP roasting impossible"
            "Take the privilege away rather than the exposure where the service does not need it"
            "Add the account to 'Protected Users', which forbids RC4 and shortens the ticket lifetime"
            "Where the account must stay as it is, give it a password long enough that offline cracking is not worth the electricity - 25 characters or more"
        )
        RemediationCommands = @(
            @{
                Description = "Show the SPNs and the group memberships of the account"
                Command = "Get-ADUser -Identity 'ACCOUNT_NAME' -Properties servicePrincipalName,memberOf,userAccountControl,pwdLastSet"
            }
            @{
                Description = "Remove the SPN that makes the account kerberoastable"
                Command = "Set-ADUser -Identity 'ACCOUNT_NAME' -ServicePrincipalNames @{Remove='SERVICE/HOST'}"
            }
            @{
                Description = "Require Kerberos pre-authentication again"
                Command = "Set-ADAccountControl -Identity 'ACCOUNT_NAME' -DoesNotRequirePreAuth `$false"
            }
        )
        References = @(
            @{ Title = "Kerberoasting - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/kerberoast.html" }
            @{ Title = "AS-REP Roasting - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/asreproast.html" }
            @{ Title = "Protected Users Security Group"; Url = "https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group" }
        )
        Tools = @("Rubeus", "Impacket", "hashcat", "John the Ripper")
        MITRE = "T1558.003"
        Triggers = @(
            @{ Attribute = 'PrivilegedRoastTarget'; Severity = 'Finding' }
        )
    }

    'CONSTRAINED_DELEGATION_TO_DC' = @{
        Title = "Constrained Delegation to a Domain Controller"
        Risk = "Finding"
        BaseScore = 80
        Description = "This account is allowed to delegate to a service running on a Domain Controller. Whoever controls the account can obtain a service ticket to that Domain Controller as any user the delegation permits, which is a direct path to Domain Admin."
        Impact = @(
            "Compromise of this account is equivalent to compromise of the domain"
            "The service class named in the SPN is not a restriction - see below"
            "With protocol transition the account needs no cooperation from the impersonated user"
            "Reachable by anyone who can take over the account, including through its ACL or its service password"
        )
        Attack = @(
            "1. Attacker compromises the account or its password hash"
            "2. S4U2Self obtains a ticket for a privileged user - forwardable if protocol transition is set"
            "3. S4U2Proxy exchanges it for a service ticket to the configured SPN on the Domain Controller"
            "4. The service class in that ticket is rewritten to the one wanted, for example ldap or cifs"
            "5. The rewritten ticket is used against the Domain Controller, for example for DCSync"
        )
        Remediation = @(
            "Remove the Domain Controller from msDS-AllowedToDelegateTo - restricting the service class does not help"
            "If the application needs delegation, move the target service off the Domain Controller"
            "Prefer Resource-Based Constrained Delegation, which lets the target decide who may delegate to it"
            "Put privileged accounts in 'Protected Users' or mark them 'Account is sensitive and cannot be delegated'"
        )
        RemediationCommands = @(
            @{
                Description = "Show the current delegation targets of the account"
                Command = "Get-ADObject -Identity 'ACCOUNT_DN' -Properties msDS-AllowedToDelegateTo | Select-Object -ExpandProperty msDS-AllowedToDelegateTo"
            }
            @{
                Description = "Remove all delegation targets from the account"
                Command = "Set-ADObject -Identity 'ACCOUNT_DN' -Clear msDS-AllowedToDelegateTo"
            }
        )
        References = @(
            @{ Title = "S4U2Self and S4U2Proxy Abuse"; Url = "https://blog.harmj0y.net/activedirectory/s4u2pwnage/" }
            @{ Title = "Constrained Delegation - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/constrained-delegation.html" }
            @{ Title = "Rubeus - alternate service name"; Url = "https://github.com/GhostPack/Rubeus#s4u" }
        )
        Tools = @("Rubeus", "Impacket", "PowerView")
        MITRE = "T1550.003"
        Triggers = @(
            @{ Attribute = 'DelegationTargetsOnDC'; Severity = 'Finding' }
        )
    }

    'CONSTRAINED_DELEGATION_TRANSITION_NO_TARGET' = @{
        Title = "Protocol Transition Without a Delegation Target"
        Risk = "Finding"
        BaseScore = 45
        Description = "This account carries TRUSTED_TO_AUTH_FOR_DELEGATION but msDS-AllowedToDelegateTo is empty. The delegation the flag exists for is not configured, so the setting has no purpose here - and the flag on its own still changes what tickets the account can obtain."
        Impact = @(
            "S4U2Self returns a forwardable ticket for any user against this account's own services"
            "That ticket can be used locally against services this account hosts"
            "The flag is one write away from being usable: an attacker who can also set msDS-AllowedToDelegateTo gains full constrained delegation"
            "Set on its own it is more often a leftover or an attacker's groundwork than an intended configuration"
        )
        Attack = @(
            "1. Attacker compromises the account"
            "2. S4U2Self obtains a forwardable ticket impersonating a privileged user"
            "3. The ticket is presented to a service the account itself hosts"
            "4. If the attacker can write msDS-AllowedToDelegateTo, any target of choice is added"
        )
        Remediation = @(
            "Clear the flag if delegation is not in use"
            "If delegation is intended, configure the target services explicitly and review them"
            "Check who can write userAccountControl and msDS-AllowedToDelegateTo on this account"
        )
        RemediationCommands = @(
            @{
                Description = "Clear protocol transition on the account"
                Command = "Set-ADAccountControl -Identity 'ACCOUNT_NAME' -TrustedToAuthForDelegation `$false"
            }
            @{
                Description = "Find every account carrying the flag without a target list"
                Command = "Get-ADObject -LDAPFilter '(&(userAccountControl:1.2.840.113556.1.4.803:=16777216)(!(msDS-AllowedToDelegateTo=*)))' -Properties userAccountControl"
            }
        )
        References = @(
            @{ Title = "S4U2Self Abuse"; Url = "https://blog.harmj0y.net/activedirectory/s4u2pwnage/" }
            @{ Title = "Kerberos Delegation - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-constrained-delegation-overview" }
        )
        Tools = @("Rubeus", "PowerView")
        MITRE = "T1550.003"
        Triggers = @(
            @{ Attribute = 'DelegationAnomaly'; Severity = 'Finding' }
        )
    }

    'RBCD_DANGEROUS_PRINCIPALS' = @{
        Title = "Resource-Based Constrained Delegation Misconfiguration"
        Risk = "Finding"
        BaseScore = 55
        Description = "The msDS-AllowedToActOnBehalfOfOtherIdentity attribute is set with principals that could allow privilege escalation. Attackers who control these principals can impersonate any user to this resource."
        Impact = @(
            "Principals in the RBCD list can impersonate any user to this computer"
            "If attackers control a listed principal, they can compromise this system"
            "Enables lateral movement through S4U2Proxy abuse"
        )
        Attack = @(
            "1. Attacker identifies computers with misconfigured RBCD"
            "2. Compromises or creates a principal in the allowed list"
            "3. Uses S4U2Self and S4U2Proxy to obtain a service ticket as any user"
            "4. Uses the ticket to access the target computer as Domain Admin"
        )
        Remediation = @(
            "Audit msDS-AllowedToActOnBehalfOfOtherIdentity on all computers"
            "Remove unnecessary principals from RBCD configurations"
            "Ensure only explicitly required accounts are in the delegation list"
            "Monitor changes to this attribute"
        )
        RemediationCommands = @(
            @{
                Description = "View current RBCD configuration for a computer"
                Command = "Get-ADComputer 'COMPUTERNAME' -Properties msDS-AllowedToActOnBehalfOfOtherIdentity,PrincipalsAllowedToDelegateToAccount | Select-Object Name,@{Name='AllowedPrincipals';Expression={`$_.PrincipalsAllowedToDelegateToAccount}}"
            }
            @{
                Description = "Remove ALL RBCD delegation from a computer (complete removal)"
                Command = "Set-ADComputer 'COMPUTERNAME' -Clear 'msDS-AllowedToActOnBehalfOfOtherIdentity'"
            }
            @{
                Description = "Remove ALL RBCD delegation using friendly property name"
                Command = "Set-ADComputer 'COMPUTERNAME' -PrincipalsAllowedToDelegateToAccount `$null"
            }
            @{
                Description = "Find all computers with RBCD configured"
                Command = "Get-ADComputer -Filter {msDS-AllowedToActOnBehalfOfOtherIdentity -like '*'} -Properties msDS-AllowedToActOnBehalfOfOtherIdentity,PrincipalsAllowedToDelegateToAccount | Select-Object Name,DNSHostName,@{Name='AllowedPrincipals';Expression={`$_.PrincipalsAllowedToDelegateToAccount}}"
            }
        )
        References = @(
            @{ Title = "Resource-Based Constrained Delegation Abuse"; Url = "https://shenaniganslabs.io/2019/01/28/Wagging-the-Dog.html" }
            @{ Title = "Set-ADComputer PrincipalsAllowedToDelegateToAccount"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/set-adcomputer" }
            @{ Title = "RBCD - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/resource-based-constrained-delegation.html" }
            @{ Title = "Kerberos RBCD - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-constrained-delegation-overview" }
        )
        Tools = @("Rubeus", "PowerView", "Impacket")
        MITRE = "T1550.003"
        Triggers = @(
            # The verdict, which the check now computes: who is listed, and whether the
            # resource is a domain controller.
            #
            # This definition used to hang off the bare presence of the attribute, so the
            # Microsoft-documented frontend-to-backend pattern and an attacker-set entry on
            # a domain controller carried the same title - "Misconfiguration" - and the
            # same score. RBCD is a feature; what decides is who may use it and on what.
            @{ Attribute = 'rbcdTarget'; Severity = 'Finding' }
            @{ Attribute = 'rbcdPrincipalRisk'; Pattern = 'a broad group|not an identity this domain expects|unresolved - a deleted or foreign principal'; Severity = 'Finding' }

            # The attribute itself follows the verdict rather than carrying one: red where
            # the check found something to say, and otherwise the colour its own row earns.
            @{ Attribute = 'msDS-AllowedToActOnBehalfOfOtherIdentity'; Custom = 'rbcd_principal_is_dangerous'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'msDS-AllowedToActOnBehalfOfOtherIdentity'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    # ============================================================================
    # ADCS (CERTIFICATE SERVICES) FINDINGS
    # ============================================================================

    'ESC1_TEMPLATE' = @{
        Title = "ESC1 - Vulnerable Certificate Template"
        Risk = "Finding"
        BaseScore = 90
        Description = "This certificate template allows the enrollee to specify a Subject Alternative Name (SAN) and enables Client Authentication. Any user who can enroll can request a certificate for any other user, including Domain Admins."
        Impact = @(
            "Any enrolling user can impersonate any other domain user"
            "Enables immediate privilege escalation to Domain Admin"
            "Certificates are valid for the template's lifetime (often 1-2 years)"
            "No password required - certificate-based authentication bypasses password policies"
        )
        Attack = @(
            "1. Attacker enrolls for a certificate using the vulnerable template"
            "2. Specifies Domain Admin's UPN in the Subject Alternative Name"
            "3. Uses the certificate for PKINIT authentication as Domain Admin"
            "4. Performs any privileged operations in the domain"
        )
        Remediation = @(
            "Clear both enrollee-supplied-subject flags: CT_FLAG_ENROLLEE_SUPPLIES_SUBJECT (0x1) and CT_FLAG_ENROLLEE_SUPPLIES_SUBJECT_ALT_NAME (0x10000) - the second one alone is enough to put another account's UPN into the SAN, which is the ESC1 primitive"
            "Expect this to break every workflow that supplies its own subject or SAN, web server certificates first - plan the replacement template before clearing the flag"
            "Require CA Manager approval for certificate requests"
            "Restrict enrollment permissions to specific required groups"
            "Use 'Supply in the request' only when absolutely necessary with strong controls"
        )
        RemediationCommands = @(
            @{
                Description = "Remove both enrollee-supplied-subject flags from the template (requires Enterprise Admin)"
                Command = @'
# Get template DN (replace 'VulnerableTemplate' with actual template name)
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Get current flag value
$template = Get-ADObject -Identity $templateDN -Properties msPKI-Certificate-Name-Flag
$currentFlag = $template.'msPKI-Certificate-Name-Flag'

# Remove CT_FLAG_ENROLLEE_SUPPLIES_SUBJECT (0x00000001) and
# CT_FLAG_ENROLLEE_SUPPLIES_SUBJECT_ALT_NAME (0x00010000).
#
# Both are ESC1: whoever may supply the SAN writes another account's UPN into it.
# This command used to clear 0x1 alone, so a template flagged for the SAN variant was
# reported as remediated and stayed exactly as exploitable as before.
$newFlag = $currentFlag -band (-bnot 0x00010001)

# Update template
Set-ADObject -Identity $templateDN -Replace @{'msPKI-Certificate-Name-Flag' = $newFlag}
'@
            }
            @{
                Description = "Require CA Manager approval (CT_FLAG_PEND_ALL_REQUESTS = 0x00000002)"
                Command = @'
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Get current enrollment flag
$template = Get-ADObject -Identity $templateDN -Properties msPKI-Enrollment-Flag
$currentFlag = $template.'msPKI-Enrollment-Flag'

# Add CT_FLAG_PEND_ALL_REQUESTS (0x00000002)
$newFlag = $currentFlag -bor 0x00000002

# Update template
Set-ADObject -Identity $templateDN -Replace @{'msPKI-Enrollment-Flag' = $newFlag}
'@
            }
            @{
                Description = "Remove template from CA (stop issuing certificates immediately)"
                Command = @'
# On the CA server, remove the vulnerable template
certutil -deltemplate "VulnerableTemplate"

# Or via PowerShell (run on CA server)
$caName = "$env:COMPUTERNAME\$(certutil -dump | Select-String 'Config:' | ForEach-Object { ($_ -split '\\')[-1].Trim() })"
Remove-CATemplate -Name "VulnerableTemplate" -Force
'@
            }
        )
        References = @(
            @{ Title = "Certified Pre-Owned - SpecterOps"; Url = "https://posts.specterops.io/certified-pre-owned-d95910965cd2" }
            @{ Title = "AD CS ESC1 - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/ad-certificates/domain-escalation.html#esc1" }
            @{ Title = "Certificate Template Security - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
        )
        Tools = @("Certify", "Certipy", "ForgeCert", "Rubeus")
        MITRE = "T1649"
        Triggers = @(
            # Negative lookahead prevents this definition from claiming ESC13 and ESC15,
            # which both start with the literal "ESC1".
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC1(?!\d)'; Severity = 'Finding' }
            # Colour only. ENROLLEE_SUPPLIES_SUBJECT is one of four conditions ESC1 needs -
            # the others are an authentication EKU, enrollment rights for a principal the
            # attacker controls, and no manager approval - and Get-ADCSVulnerabilities
            # checks all four before it writes Vulnerabilities. These two triggers named
            # the 90-point card from the flag alone, which made every template that lets
            # the requester name the subject an ESC1, approval and EKU notwithstanding.
            #
            # The flag is worth highlighting wherever a template is rendered, which is why
            # the triggers stay. The verdict belongs to the check that applied the gates.
            @{ Attribute = 'CertificateNameFlagDisplay'; Pattern = 'ENROLLEE_SUPPLIES_SUBJECT'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'EnrolleeSuppliesSubject'; Pattern = '^(True|Yes)$'; Severity = 'Finding'; SeverityOnly = $true }
        )
    }

    'ESC_ENROLLMENT_RIGHTS_UNREAD' = @{
        Title = "Enrollment Rights of This Template Could Not Be Read"
        Risk = "Hint"
        BaseScore = 25
        Description = "Every ESC finding on a certificate template rests on an unprivileged principal being able to enroll for it. For this template that could not be established: no Certificate-Enrollment ACE was readable. The template's own settings - the subject flag, the EKUs, the schema version - are read from the object and hold regardless; what is missing is who could use them."
        Impact = @(
            "The ESC findings reported for this template cannot be confirmed as exploitable, and cannot be ruled out either"
            "A template that withdraws Read-Control from Authenticated Users arrives without a security descriptor, so the hardening itself produces this state"
            "An enrollment ACE written as GENERIC_ALL reads the same way, and that is the form impacket and Certipy write"
        )
        Attack = @(
            "1. Nothing here is an attack by itself - this is a gap in what the scan could see"
            "2. The value of knowing it: an attacker who already owns the template can produce exactly this state by writing a GENERIC_ALL ACE"
            "3. A hardened template produces it too, which is why it is a hint rather than a finding"
        )
        Remediation = @(
            "Read the template's security descriptor with an account that holds Read-Control on it, and re-run the scan"
            "Check the descriptor by hand for an ACE written with the generic access bits rather than named rights"
            "If Read-Control was withdrawn deliberately, nothing needs doing - but the ESC verdicts for this template stay undecided until somebody can read it"
        )
        RemediationCommands = @(
            @{
                Description = "Show the template's DACL in SDDL, where a generic-bit ACE is visible as GA"
                Command = "(Get-Acl -Path `"AD:CN=TEMPLATENAME,CN=Certificate Templates,CN=Public Key Services,CN=Services,CN=Configuration,DC=DOMAIN,DC=COM`").Sddl"
            }
            @{
                Description = "List who holds Certificate-Enrollment on the template"
                Command = "(Get-Acl -Path `"AD:CN=TEMPLATENAME,CN=Certificate Templates,CN=Public Key Services,CN=Services,CN=Configuration,DC=DOMAIN,DC=COM`").Access | Where-Object { `$_.ObjectType -eq '0e10c968-78fb-11d2-90d4-00c04f79dc55' }"
            }
        )
        References = @(
            @{ Title = "Certified Pre-Owned"; Url = "https://posts.specterops.io/certified-pre-owned-d95910965cd2" }
            @{ Title = "Certificate Templates - MS-CRTD"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-crtd/" }
        )
        Tools = @("Certipy", "Certify", "PowerView")
        MITRE = "T1649"
        Triggers = @(
            # The card, on the attribute Get-ADCSVulnerabilities writes when the state is
            # Unknown. Nothing else writes it.
            @{ Attribute = 'escEnrollmentRightsUnread'; Severity = 'Hint' }

            # And the damping, which reaches every ESC row rather than only this one: the
            # trigger index is keyed by attribute, so a severity-only trigger on
            # Vulnerabilities is consulted for whatever value that attribute carries. The
            # ESC card and its remediation stay; the colour says the verdict is undecided.
            # This is the mechanism ra_signature_gated and manager_approval_gated already
            # use for the two barriers.
            @{ Attribute = 'Vulnerabilities'; Custom = 'esc_enrollment_rights_unread'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    'ESC2_TEMPLATE' = @{
        Title = "ESC2 - Any Purpose or SubCA Certificate Template"
        Risk = "Finding"
        BaseScore = 80
        Description = "This certificate template has 'Any Purpose' EKU or 'SubCA' capability, allowing the issued certificate to be used for any purpose including Client Authentication, Code Signing, or even issuing other certificates."
        Impact = @(
            "Certificates can be used for authentication as any user"
            "SubCA certificates can issue other certificates"
            "Enables code signing for malware"
            "Complete compromise of PKI trust chain possible"
        )
        Attack = @(
            "1. Attacker enrolls for a certificate with Any Purpose/SubCA"
            "2. For SubCA: Issues certificates for any user"
            "3. For Any Purpose: Uses certificate for Client Authentication as target user"
            "4. Bypasses all certificate-based access controls"
        )
        Remediation = @(
            "Remove 'Any Purpose' EKU - specify only required purposes"
            "Never allow SubCA certificates to be issued to non-CA systems"
            "Restrict enrollment permissions"
            "Require CA Manager approval"
        )
        RemediationCommands = @(
            @{
                Description = "Remove 'Any Purpose' EKU and set specific EKUs (requires Enterprise Admin)"
                Command = @'
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Define specific EKUs (replace with required OIDs)
# Common EKUs:
# 1.3.6.1.5.5.7.3.2 = Client Authentication
# 1.3.6.1.5.5.7.3.1 = Server Authentication
# 1.3.6.1.4.1.311.10.3.12 = Document Signing
$specificEKUs = @(
    "1.3.6.1.5.5.7.3.2"  # Client Authentication
)

# Update template EKUs (removes Any Purpose OID 2.5.29.37.0)
Set-ADObject -Identity $templateDN -Replace @{'msPKI-Certificate-Application-Policy' = $specificEKUs}
'@
            }
            @{
                Description = "Unpublish the template from every CA - the way to take a SubCA template out of use"
                Command = @'
# CT_FLAG_IS_CA is bit 0x80 of the template's "flags" attribute (MS-CRTD 2.4), not of
# msPKI-Enrollment-Flag, where 0x80 is not assigned at all. The predecessor of this
# command cleared an undefined bit in the wrong attribute, returned no error, and left the
# SubCA capability exactly where it was.
#
# Clearing the bit is also not a supported change on a V1 default template. Taking the
# template off the CAs is, and it is what stops the enrollment:
$configNC = (Get-ADRootDSE).configurationNamingContext
Get-ADObject -SearchBase "CN=Enrollment Services,CN=Public Key Services,CN=Services,$configNC" `
    -LDAPFilter '(objectClass=pKIEnrollmentService)' -Properties certificateTemplates |
    ForEach-Object {
        Set-ADObject -Identity $_.DistinguishedName -Remove @{ certificateTemplates = 'VulnerableTemplate' }
    }
'@
            }
            @{
                Description = "Read the flag that actually carries the SubCA capability, to confirm the state"
                Command = @'
$configNC = (Get-ADRootDSE).configurationNamingContext
Get-ADObject -SearchBase "CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC" `
    -LDAPFilter '(objectClass=pKICertificateTemplate)' -Properties flags, msPKI-Certificate-Application-Policy |
    Select-Object Name, flags, @{n='IsCA'; e={ ($_.flags -band 0x80) -ne 0 }}
'@
            }
            @{
                Description = "Restrict enrollment permissions to specific groups only"
                Command = @'
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Remove Authenticated Users / Domain Users enrollment rights
$template = Get-ADObject -Identity $templateDN
$acl = Get-Acl -Path "AD:\$templateDN"

# Remove enrollment rights for Authenticated Users
$sid = New-Object System.Security.Principal.SecurityIdentifier("S-1-5-11")  # Authenticated Users
$acl.Access | Where-Object {$_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]) -eq $sid -and $_.ActiveDirectoryRights -match "ExtendedRight"} | ForEach-Object {
    $acl.RemoveAccessRule($_) | Out-Null
}

# Add specific group (replace with your group)
$groupSID = (Get-ADGroup "SpecificEnrollmentGroup").SID
$ace = New-Object System.DirectoryServices.ActiveDirectoryAccessRule(
    $groupSID,
    [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight,
    [System.Security.AccessControl.AccessControlType]::Allow,
    [Guid]"0e10c968-78fb-11d2-90d4-00c04f79dc55"  # Certificate-Enrollment
)
$acl.AddAccessRule($ace)

Set-Acl -Path "AD:\$templateDN" -AclObject $acl
'@
            }
        )
        References = @(
            @{ Title = "Certified Pre-Owned - SpecterOps"; Url = "https://posts.specterops.io/certified-pre-owned-d95910965cd2" }
            @{ Title = "AD CS ESC2 - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/ad-certificates/domain-escalation.html#esc2" }
            @{ Title = "Certificate EKU Configuration - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
        )
        Tools = @("Certify", "Certipy")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC2'; Severity = 'Finding' }
            # Colour only, for the same reason as ESC1: Any Purpose (or no EKU at all) is
            # what makes a certificate usable for authentication, but ESC2 also needs
            # enrollment rights and no manager approval. Vulnerabilities carries the
            # verdict once the check has established both.
            @{ Attribute = 'AnyPurpose'; Pattern = '^(True|Yes)$'; Severity = 'Finding'; SeverityOnly = $true }
            # The other half of the same finding, and colour-only for the same reason:
            # CT_FLAG_IS_CA makes the issued certificate a CA certificate, but ESC2 still
            # needs enrollment rights before it is a finding. The card is named by the
            # Vulnerabilities trigger above, which is why this one may be severity-only.
            @{ Attribute = 'IsCA'; Pattern = '^(True|Yes)$'; Severity = 'Finding'; SeverityOnly = $true }
            # ExtendedKeyUsage: Any Purpose OID or Certificate Request Agent OID = Finding
            @{ Attribute = 'ExtendedKeyUsage'; Pattern = '2\.5\.29\.37\.0|Any Purpose'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'ExtendedKeyUsage'; Pattern = '1\.3\.6\.1\.4\.1\.311\.20\.2\.1|Certificate Request Agent'; Severity = 'Finding'; SeverityOnly = $true }
        )
    }

    'ESC3_TEMPLATE' = @{
        Title = "ESC3 - Certificate Request Agent Template"
        Risk = "Finding"
        BaseScore = 75
        Description = "This template allows enrollment for a Certificate Request Agent (Enrollment Agent) certificate, which can then be used to enroll for certificates on behalf of other users, bypassing normal enrollment restrictions."
        Impact = @(
            "Enrollment Agent can request certificates for any user"
            "Bypasses per-user enrollment restrictions on other templates"
            "Enables escalation through certificate impersonation"
        )
        Attack = @(
            "1. Attacker enrolls for Certificate Request Agent certificate"
            "2. Uses the agent certificate to request certificates for other users"
            "3. Obtains certificate for Domain Admin or other privileged account"
            "4. Authenticates using the obtained certificate"
        )
        Remediation = @(
            "Restrict Enrollment Agent certificate issuance to specific users"
            "Enable 'Restrict enrollment agents' on the CA"
            "Configure enrollment agent restrictions to limit which templates agents can use"
            "Monitor enrollment agent certificate requests"
        )
        RemediationCommands = @(
            @{
                Description = "Restrict enrollment permissions on Certificate Request Agent template (requires Enterprise Admin)"
                Command = @'
$templateName = "EnrollmentAgent"  # Or your Certificate Request Agent template name
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Get current ACL
$acl = Get-Acl -Path "AD:\$templateDN"

# Remove Authenticated Users / Domain Users enrollment rights
$authenticatedUsersSID = New-Object System.Security.Principal.SecurityIdentifier("S-1-5-11")  # Authenticated Users
$domainUsersSID = (Get-ADGroup "Domain Users").SID

$acl.Access | Where-Object {
    ($_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]) -eq $authenticatedUsersSID -or
     $_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]) -eq $domainUsersSID) -and
    $_.ActiveDirectoryRights -match "ExtendedRight"
} | ForEach-Object {
    $acl.RemoveAccessRule($_) | Out-Null
}

# Add specific trusted group only
$trustedGroupSID = (Get-ADGroup "EnrollmentAgentAdmins").SID
$enrollmentGuid = [Guid]"0e10c968-78fb-11d2-90d4-00c04f79dc55"  # Certificate-Enrollment
$ace = New-Object System.DirectoryServices.ActiveDirectoryAccessRule(
    $trustedGroupSID,
    [System.DirectoryServices.ActiveDirectoryRights]::ExtendedRight,
    [System.Security.AccessControl.AccessControlType]::Allow,
    $enrollmentGuid
)
$acl.AddAccessRule($ace)

Set-Acl -Path "AD:\$templateDN" -AclObject $acl
'@
            }
            @{
                Description = "Configure CA enrollment agent restrictions (run on CA server)"
                Command = @'
# Enable enrollment agent restrictions on the CA
certutil -setreg policy\EnableEnrollmentAgentRestrictions 1

# Create restriction policy file (example: restrict to specific templates)
$restrictionXml = @"
<EnrollmentAgentRestrictions>
  <EnrollmentAgentRestriction>
    <EnrollmentAgentCertificate>
      <Template>EnrollmentAgent</Template>
    </EnrollmentAgentCertificate>
    <AllowedTemplates>
      <Template>SpecificTemplate1</Template>
      <Template>SpecificTemplate2</Template>
    </AllowedTemplates>
  </EnrollmentAgentRestriction>
</EnrollmentAgentRestrictions>
"@

# Save and apply restrictions
$restrictionXml | Out-File "C:\EnrollmentAgentRestrictions.xml"
certutil -setreg policy\EnrollmentAgentRestrictions "@C:\EnrollmentAgentRestrictions.xml"

# Restart CA service
net stop certsvc
net start certsvc
'@
            }
            @{
                Description = "Disable template or require manager approval"
                Command = @'
$templateName = "EnrollmentAgent"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Option 1: Require CA Manager approval
$template = Get-ADObject -Identity $templateDN -Properties msPKI-Enrollment-Flag
$currentFlag = $template.'msPKI-Enrollment-Flag'
$newFlag = $currentFlag -bor 0x00000002  # CT_FLAG_PEND_ALL_REQUESTS
Set-ADObject -Identity $templateDN -Replace @{'msPKI-Enrollment-Flag' = $newFlag}

# Option 2: Remove template from CA entirely
# certutil -deltemplate "EnrollmentAgent"
'@
            }
        )
        References = @(
            @{ Title = "Certified Pre-Owned - SpecterOps"; Url = "https://posts.specterops.io/certified-pre-owned-d95910965cd2" }
            @{ Title = "AD CS ESC3 - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/ad-certificates/domain-escalation.html#esc3" }
            @{ Title = "Enrollment Agent Restrictions - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
        )
        Tools = @("Certify", "Certipy")
        MITRE = "T1649"
        Triggers = @(
            # Negative lookahead keeps this definition from claiming "ESC3-TARGET", which is the
            # opposite side of the chain and has its own definition below.
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC3(?!-)'; Severity = 'Finding' }
            # Colour only. The Certificate Request Agent EKU is what an ESC3 enrollment
            # agent template has, and on its own it is the documented configuration of
            # every legitimate enrollment agent in the domain. ESC3 is that template plus
            # enrollment rights for the wrong principal, which the check establishes.
            @{ Attribute = 'EnrollmentAgent'; Pattern = '^(True|Yes)$'; Severity = 'Finding'; SeverityOnly = $true }
        )
    }

    'ESC3_TARGET_TEMPLATE' = @{
        Title = "ESC3 - Enrollment Agent Target Template (On-Behalf-Of Enrollment)"
        Risk = "Finding"
        BaseScore = 70
        Description = "This certificate template requires the request to be co-signed by a Certificate Request Agent (msPKI-RA-Signature >= 1 with 1.3.6.1.4.1.311.20.2.1 in msPKI-RA-Application-Policies) and supports client authentication. It is the target half of ESC3: an enrollment agent chooses the subject, so anyone holding an enrollment agent certificate can obtain a client-authentication certificate for any principal permitted to enroll here - including privileged users. The co-signature requirement is not a security boundary unless enrollment agent restrictions are configured on the CA; by default a single enrollment agent certificate covers every template of this kind."
        Impact = @(
            "Holder of an enrollment agent certificate can request certificates for arbitrary principals"
            "Resulting certificate authenticates via PKINIT/Schannel as the impersonated user"
            "Without CA-side enrollment agent restrictions, one agent certificate covers all such templates"
            "Broad enrollment scope (Domain Users, Authenticated Users) widens the set of impersonatable targets"
        )
        Attack = @(
            "1. Attacker obtains an enrollment agent certificate (ESC3 condition 1 template, stolen key, or a legitimately issued agent certificate)"
            "2. Builds a request against this template naming a privileged principal as the subject"
            "3. Co-signs the request with the enrollment agent certificate (CMC full PKI request)"
            "4. CA issues a client-authentication certificate for the named principal"
            "5. Attacker authenticates as that principal via PKINIT"
        )
        Remediation = @(
            "Enable enrollment agent restrictions on the CA and scope each agent to specific templates and target principals"
            "Restrict enrollment on this template to the principals that actually need it"
            "Require CA manager approval (CT_FLAG_PEND_ALL_REQUESTS) for this template"
            "Audit which certificates carrying the Certificate Request Agent EKU have been issued and revoke unneeded ones"
            "Unpublish the template from the CA if on-behalf-of enrollment is no longer used"
        )
        RemediationCommands = @(
            @{
                Description = "Enable and configure enrollment agent restrictions on the CA (run on the CA server)"
                Command = @'
# Without this setting ANY enrollment agent certificate can enroll on behalf of ANY user
# for EVERY template that requires an agent signature.
certutil -setreg policy\EnableEnrollmentAgentRestrictions 1

$restrictionXml = @"
<EnrollmentAgentRestrictions>
  <EnrollmentAgentRestriction>
    <EnrollmentAgentCertificate>
      <Template>EnrollmentAgent</Template>
    </EnrollmentAgentCertificate>
    <Templates>
      <Template>TargetTemplateName</Template>
    </Templates>
    <Permissions>
      <Allow>DOMAIN\MDM-Enrollment-Targets</Allow>
    </Permissions>
  </EnrollmentAgentRestriction>
</EnrollmentAgentRestrictions>
"@

$restrictionXml | Out-File "C:\EnrollmentAgentRestrictions.xml" -Encoding UTF8
certutil -setreg policy\EnrollmentAgentRestrictions "@C:\EnrollmentAgentRestrictions.xml"

net stop certsvc
net start certsvc
'@
            }
            @{
                Description = "Require CA manager approval for this template (requires Enterprise Admin)"
                Command = @'
$templateName = "TargetTemplateName"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

$template = Get-ADObject -Identity $templateDN -Properties msPKI-Enrollment-Flag
$newFlag = $template.'msPKI-Enrollment-Flag' -bor 0x00000002  # CT_FLAG_PEND_ALL_REQUESTS
Set-ADObject -Identity $templateDN -Replace @{'msPKI-Enrollment-Flag' = $newFlag}
'@
            }
            @{
                Description = "List issued certificates that carry the Certificate Request Agent EKU (run on the CA server)"
                Command = @'
certutil -view -restrict "Disposition=20" -out "RequestID,CommonName,CertificateTemplate,NotAfter"
# Cross-check the CertificateTemplate column against templates whose EKUs include
# 1.3.6.1.4.1.311.20.2.1 and revoke agent certificates that are no longer needed:
# certutil -revoke <RequestID> 4
'@
            }
        )
        References = @(
            @{ Title = "Certified Pre-Owned - SpecterOps"; Url = "https://posts.specterops.io/certified-pre-owned-d95910965cd2" }
            @{ Title = "AD CS ESC3 - Certipy Wiki"; Url = "https://github.com/ly4k/Certipy/wiki/06-%E2%80%90-Privilege-Escalation#esc3" }
            @{ Title = "Restricted Enrollment Agents - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
        )
        Tools = @("Certipy", "Certify")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC3-TARGET'; Severity = 'Finding' }
            # Colour only: this attribute says the template *requires* an enrollment agent
            # signature, which is the mitigation rather than the finding. The two
            # predicates below decide whether it is actually in force.
            @{ Attribute = 'RAApplicationPolicies'; Pattern = '1\.3\.6\.1\.4\.1\.311\.20\.2\.1'; Severity = 'Hint'; SeverityOnly = $true }
            # Central severity damping for every enrollment-driven ESC on this attribute.
            # SeverityOnly means it decides the colour but never the tooltip, so ESC1/ESC2/ESC9/
            # ESC13/ESC15 keep their own finding cards while being reported as a two-step attack
            # rather than a direct one. Deliberately parked on this definition because this is
            # where the co-signature mechanic is documented - see Test-CustomTrigger for the rules.
            @{ Attribute = 'Vulnerabilities'; Custom = 'ra_signature_gated'; Severity = 'Hint'; SeverityOnly = $true }
            # The second barrier of the same kind, parked here for the same reason: manager
            # approval holds every request until a person releases it. See Test-CustomTrigger.
            @{ Attribute = 'Vulnerabilities'; Custom = 'manager_approval_gated'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    # NOTE: the owner of a template is reported as an ESC4 entry with the right "Owner".
    # An owner may rewrite the DACL at will, so it holds every right this card describes
    # whether or not an ACE says so.
    'ESC4_TEMPLATE' = @{
        Title = "ESC4 - Certificate Template with Dangerous ACL"
        Risk = "Finding"
        BaseScore = 70
        Description = "This certificate template has ACL entries that allow unprivileged users to modify the template configuration. Attackers can modify the template to enable ESC1/ESC2 conditions and then exploit them."
        Impact = @(
            "Attackers can modify template to allow arbitrary SANs"
            "Can enable Any Purpose or Client Authentication EKUs"
            "Effectively converts to ESC1/ESC2 vulnerability"
            "Changes to templates take effect immediately"
        )
        Attack = @(
            "1. Attacker identifies template with writable ACL"
            "2. Modifies template to enable ENROLLEE_SUPPLIES_SUBJECT"
            "3. Adds Client Authentication EKU if not present"
            "4. Enrolls for certificate with Domain Admin SAN"
            "5. Authenticates as Domain Admin"
        )
        Remediation = @(
            "Audit template ACLs - remove unnecessary write permissions"
            "Only Domain Admins and Enterprise Admins should modify templates"
            "Monitor template modifications via Windows event logs"
        )
        RemediationCommands = @(
            @{
                Description = "Remove dangerous write permissions from certificate template (requires Enterprise Admin)"
                Command = @'
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Get current ACL
$acl = Get-Acl -Path "AD:\$templateDN"

# Define dangerous permissions to remove
$dangerousRights = @(
    [System.DirectoryServices.ActiveDirectoryRights]::WriteProperty,
    [System.DirectoryServices.ActiveDirectoryRights]::WriteDacl,
    [System.DirectoryServices.ActiveDirectoryRights]::WriteOwner,
    [System.DirectoryServices.ActiveDirectoryRights]::GenericWrite,
    [System.DirectoryServices.ActiveDirectoryRights]::GenericAll
)

# Remove dangerous rights for non-admin users
$acl.Access | Where-Object {
    # Keep only Domain Admins, Enterprise Admins, and SYSTEM
    $sid = $_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier])
    $isAdmin = ($sid.Value -match '-512$') -or  # Domain Admins
               ($sid.Value -match '-519$') -or  # Enterprise Admins
               ($sid.Value -eq 'S-1-5-18')      # SYSTEM

    -not $isAdmin -and ($_.ActiveDirectoryRights -band $dangerousRights)
} | ForEach-Object {
    $acl.RemoveAccessRule($_) | Out-Null
}

Set-Acl -Path "AD:\$templateDN" -AclObject $acl
'@
            }
            @{
                Description = "Audit all certificate template ACLs for dangerous permissions"
                Command = @'
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateContainer = "CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Get all certificate templates
$templates = Get-ADObject -SearchBase $templateContainer -Filter {objectClass -eq "pKICertificateTemplate"} -Properties nTSecurityDescriptor

$dangerousTemplates = @()

foreach ($template in $templates) {
    $acl = $template.nTSecurityDescriptor

    # Check for dangerous permissions granted to non-admin users
    $acl.Access | Where-Object {
        $sid = $_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier])
        $isAdmin = ($sid.Value -match '-512$|-519$') -or ($sid.Value -eq 'S-1-5-18')

        -not $isAdmin -and (
            $_.ActiveDirectoryRights -match "WriteProperty|WriteDacl|WriteOwner|GenericWrite|GenericAll"
        )
    } | ForEach-Object {
        $dangerousTemplates += [PSCustomObject]@{
            Template = $template.Name
            Principal = $_.IdentityReference
            Rights = $_.ActiveDirectoryRights
            AccessControlType = $_.AccessControlType
        }
    }
}

# Display results
$dangerousTemplates | Format-Table -AutoSize

# Export to CSV
$dangerousTemplates | Export-Csv "DangerousTemplateACLs.csv" -NoTypeInformation
'@
            }
        )
        References = @(
            @{ Title = "Certified Pre-Owned - SpecterOps"; Url = "https://posts.specterops.io/certified-pre-owned-d95910965cd2" }
            @{ Title = "AD CS ESC4 - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/ad-certificates/domain-escalation.html#esc4" }
            @{ Title = "Certificate Template Permissions - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
        )
        Tools = @("Certify", "Certipy", "PowerView")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC4'; Severity = 'Finding' }
        )
    }

