    'OU_PERM_SELF_ALL_VALIDATED' = @{
        Title = "All Validated Writes on OU"
        Risk = "Finding"
        BaseScore = 56
        Description = "A principal holds the Self right with no ObjectType on objects in this OU, which grants every validated write at once rather than one of them. In practice that is Self-Membership, Validated-SPN and Validated-DNS-Host-Name together: the trustee can add itself to any group in the OU, set a service principal name on any user or computer in it, and set the dNSHostName of any computer."
        Impact = @(
            "Self-Membership on every group in the OU: the trustee can join a privileged group there without being added by anyone"
            "Validated-SPN on every user and computer: a service principal name the trustee controls makes the account Kerberoastable on demand"
            "Validated-DNS-Host-Name on every computer: the basis of the machine-account attacks that depend on a controlled name"
            "One ACE grants all three, so a delegation that looks like a single entry in the ACL editor is three separate escalation paths"
        )
        Attack = @(
            "1. Attacker controls a principal holding Self with no ObjectType on the OU"
            "2. Adds itself to a privileged group in the OU through the Self-Membership write"
            "3. Obtains a new Kerberos ticket to pick up the group SID"
            "4. Or, where no privileged group is in reach, sets an SPN on an account in the OU and Kerberoasts it"
        )
        Remediation = @(
            "Replace the blanket delegation with the one validated write that is actually needed"
            "The ACL editor presents these as separate checkboxes - an ACE with no ObjectType means none of them was chosen"
            "Segregate privileged groups into OUs that carry no self-service delegation at all"
            "Monitor group membership changes (Event ID 4728, 4732, 4756) and servicePrincipalName writes"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        RemediationCommands = @(
            @{
                Description = "Show the principals holding Self with no ObjectType on the OU"
                Command = '(Get-Acl -Path "AD:OU=TARGET_OU,DC=DOMAIN,DC=COM").Access | Where-Object { $_.ActiveDirectoryRights -match "Self" -and $_.ObjectType -eq [GUID]::Empty } | Format-Table IdentityReference,ActiveDirectoryRights,InheritanceFlags,AccessControlType -AutoSize'
            }
            @{
                Description = "Remove the blanket validated-write delegation from a specific principal"
                Command = '$acl = Get-Acl -Path "AD:OU=TARGET_OU,DC=DOMAIN,DC=COM"; $ace = $acl.Access | Where-Object { $_.IdentityReference -eq "DOMAIN\USER" -and $_.ActiveDirectoryRights -match "Self" -and $_.ObjectType -eq [GUID]::Empty }; $ace | ForEach-Object { $acl.RemoveAccessRule($_) }; Set-Acl -Path "AD:OU=TARGET_OU,DC=DOMAIN,DC=COM" -AclObject $acl'
            }
        )
        References = @(
            @{ Title = "Validated Writes in AD"; Url = "https://docs.microsoft.com/en-us/windows/win32/adschema/validated-writes" }
            @{ Title = "AddSelf - BloodHound"; Url = "https://bloodhound.specterops.io/resources/edges/add-self" }
            @{ Title = "ADS_RIGHT_DS_SELF - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/api/iads/ne-iads-ads_rights_enum" }
        )
        Tools = @("BloodHound", "PowerView", "Rubeus")
        MITRE = "T1098"
        Triggers = @(
            # Scored above OU_PERM_SELF_MEMBERSHIP (50) because this one grants that right
            # and two more, and below the cards for a blanket WriteProperty (60) and for
            # GenericAll, each of which is a superset of it in turn. Measured: no other
            # pattern on this attribute matches the text, so before this definition the
            # row would have been a finding with no write-up behind it.
            @{ Attribute = 'dangerousRights'; Pattern = 'Self \(All Validated Writes\)'; Severity = 'Finding' }
        )
    }
    'OU_PERM_SELF_MEMBERSHIP' = @{
        Title = "Self-Membership Rights on OU"
        Risk = "Finding"
        BaseScore = 50
        Description = "A principal holds the Self right scoped to the Self-Membership validated write on groups in this OU. AD reuses the schemaIDGUID of the 'member' attribute as the rightsGUID of that validated write, so only the ACE type distinguishes the two: WriteProperty adds arbitrary members, Self adds the trustee itself and nobody else. The right is narrower, the escalation is the same - if a privileged group sits in this OU, the trustee can join it."
        Impact = @(
            "The trustee can add its own account to any group in the OU"
            "If Domain Admins or another privileged group is in the OU, instant privilege escalation"
            "Requires no additional account to be compromised first - the trustee escalates itself"
            "Often delegated for self-service distribution lists and then inherited by security groups"
        )
        Attack = @(
            "1. Attacker enumerates groups in the target OU and their privileges"
            "2. Adds its own account to the privileged group using the Self-Membership write"
            "3. Obtains a new Kerberos ticket to pick up the added group SID"
            "4. Gains all privileges of the group, then removes itself again"
        )
        Remediation = @(
            "Segregate privileged groups into protected OUs that carry no self-service delegation"
            "Scope self-service membership delegation to distribution groups, never to security groups"
            "Use AdminSDHolder to protect privileged groups"
            "Monitor group membership changes (Event ID 4728, 4732, 4756)"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        RemediationCommands = @(
            @{
                Description = "View current ACL on OU to identify principals with the Self right on the member attribute"
                Command = "(Get-Acl 'AD:\OU=TARGET_OU,DC=domain,DC=com').Access | Where-Object {`$_.ActiveDirectoryRights -match 'Self' -and `$_.ObjectType -eq 'bf9679c0-0de6-11d0-a285-00aa003049e2'} | Format-Table IdentityReference,ActiveDirectoryRights,ObjectType,AccessControlType -AutoSize"
            }
            @{
                Description = "Remove the Self-Membership permission from a specific principal"
                Command = "`$acl = Get-Acl 'AD:\OU=TARGET_OU,DC=domain,DC=com'; `$ace = `$acl.Access | Where-Object {`$_.IdentityReference -eq 'DOMAIN\USER' -and `$_.ActiveDirectoryRights -match 'Self' -and `$_.ObjectType -eq 'bf9679c0-0de6-11d0-a285-00aa003049e2'}; `$ace | ForEach-Object {`$acl.RemoveAccessRule(`$_)}; Set-Acl -Path 'AD:\OU=TARGET_OU,DC=domain,DC=com' -AclObject `$acl"
            }
            @{
                Description = "Identify privileged groups in the OU that the right can be used against"
                Command = "Get-ADGroup -Filter * -SearchBase 'OU=TARGET_OU,DC=domain,DC=com' -Properties AdminCount,Member | Where-Object {`$_.AdminCount -eq 1 -or `$_.Name -match 'Admin|Operator'} | Select-Object Name,DistinguishedName"
            }
            @{
                Description = "Enable auditing for group membership changes (Event IDs 4728, 4732, 4756)"
                Command = "# Configure via Group Policy: Computer Configuration > Policies > Windows Settings > Security Settings > Advanced Audit Policy > Account Management > Audit Security Group Management = Success, Failure"
            }
        )
        References = @(
            @{ Title = "AddSelf - BloodHound"; Url = "https://bloodhound.specterops.io/resources/edges/add-self" }
            @{ Title = "Validated Writes in AD"; Url = "https://docs.microsoft.com/en-us/windows/win32/adschema/validated-writes" }
            @{ Title = "Self-Membership - MS-ADTS Control Access Rights"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/1522b774-6464-41a3-87a5-1e5633c3fbbb" }
        )
        Tools = @("BloodHound", "PowerView")
        MITRE = "T1098"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'Self \(Self-Membership\)'; Severity = 'Finding' }
        )
    }

    'OU_PERM_SPN_WRITE' = @{
        Title = "WriteProperty (servicePrincipalName) on OU"
        Risk = "Finding"
        BaseScore = 50
        Description = "A principal can modify the servicePrincipalName attribute on user accounts in this OU. This enables targeted Kerberoasting attacks by adding SPNs to accounts that don't normally have them, making their password hashes extractable."
        Impact = @(
            "Can add SPNs to ANY user account in the OU"
            "Enables Kerberoasting of accounts without existing SPNs"
            "If privileged accounts are in the OU, their hashes become crackable"
            "SPN changes are rarely monitored"
        )
        Attack = @(
            "1. Attacker adds SPN to target privileged user account"
            "2. Requests TGS ticket for the new SPN (Kerberoasting)"
            "3. Extracts ticket encrypted with user's password hash"
            "4. Cracks password offline"
            "5. Optionally removes SPN to cover tracks"
        )
        Remediation = @(
            "Remove SPN write permissions from non-admin principals"
            "Use gMSA for service accounts instead of user accounts"
            "Monitor for SPN changes on user accounts (Event ID 4742)"
            "Protect privileged accounts in separate OUs"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        RemediationCommands = @(
            @{
                Description = "View current ACL on OU to identify principals with WriteProperty on servicePrincipalName"
                Command = "(Get-Acl 'AD:\OU=TARGET_OU,DC=domain,DC=com').Access | Where-Object {`$_.ActiveDirectoryRights -match 'WriteProperty' -and `$_.ObjectType -eq 'f3a64788-5306-11d1-a9c5-0000f80367c1'} | Format-Table IdentityReference,ActiveDirectoryRights,ObjectType,AccessControlType -AutoSize"
            }
            @{
                Description = "Remove WriteProperty permission on servicePrincipalName from specific principal"
                Command = "`$acl = Get-Acl 'AD:\OU=TARGET_OU,DC=domain,DC=com'; `$ace = `$acl.Access | Where-Object {`$_.IdentityReference -eq 'DOMAIN\USER' -and `$_.ActiveDirectoryRights -match 'WriteProperty' -and `$_.ObjectType -eq 'f3a64788-5306-11d1-a9c5-0000f80367c1'}; `$ace | ForEach-Object {`$acl.RemoveAccessRule(`$_)}; Set-Acl -Path 'AD:\OU=TARGET_OU,DC=domain,DC=com' -AclObject `$acl"
            }
            @{
                Description = "Find all user accounts with SPNs in the OU (potential Kerberoasting targets)"
                Command = "Get-ADUser -Filter {ServicePrincipalName -like '*'} -SearchBase 'OU=TARGET_OU,DC=domain,DC=com' -Properties ServicePrincipalName,AdminCount | Select-Object Name,SamAccountName,@{Name='SPNs';Expression={`$_.ServicePrincipalName -join '; '}},AdminCount"
            }
            @{
                Description = "Enable auditing for SPN changes on user accounts (Event ID 4742)"
                Command = "# Configure via Group Policy: Computer Configuration > Policies > Windows Settings > Security Settings > Advanced Audit Policy > Account Management > Audit User Account Management = Success, Failure"
            }
        )
        References = @(
            @{ Title = "Targeted Kerberoasting"; Url = "https://blog.harmj0y.net/activedirectory/targeted-kerberoasting/" }
            @{ Title = "WriteSPN - BloodHound"; Url = "https://bloodhound.specterops.io/resources/edges/write-spn" }
            @{ Title = "SPN Attribute - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-serviceprincipalname" }
            @{ Title = "Set-Acl - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.security/set-acl" }
        )
        Tools = @("Rubeus", "Impacket", "PowerView", "Hashcat")
        MITRE = "T1558.003"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'WriteProperty \(servicePrincipalName\)'; Severity = 'Finding' }
        )
    }

    'OU_PERM_VALIDATED_SPN' = @{
        Title = "Validated-SPN Rights on OU"
        Risk = "Hint"
        BaseScore = 35
        Description = "A principal has Validated-SPN rights (Self or WriteProperty) on objects in this OU. This validated write allows modifying servicePrincipalName with certain restrictions. While more limited than direct WriteProperty, it can still enable targeted Kerberoasting in some scenarios."
        Impact = @(
            "Can add SPNs with validation constraints"
            "Validated writes are commonly delegated for legitimate purposes"
            "Computer accounts often have Self rights for SPN management"
            "Less dangerous than direct WriteProperty but still noteworthy"
        )
        Attack = @(
            "1. If target is a user account, same Kerberoasting attack applies"
            "2. Validation may prevent some attack scenarios"
            "3. Still allows adding SPNs within validation rules"
        )
        Remediation = @(
            "Review if Validated-SPN delegation is necessary"
            "For computer objects, this is often legitimate (computer self-management)"
            "For user objects in privileged OUs, consider removing"
            "Monitor SPN changes regardless of method used"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        RemediationCommands = @(
            @{
                Description = "Find who has Validated-SPN rights on OU"
                Command = "(Get-Acl 'AD:\OU=Users,DC=domain,DC=com').Access | Where-Object { `$_.ObjectType -eq 'f3a64788-5306-11d1-a9c5-0000f80367c1' }"
            }
            @{
                Description = "Remove Validated-SPN ACE from OU (replace PRINCIPAL_SID with actual SID)"
                Command = @'
`$ou = 'OU=Users,DC=domain,DC=com'
`$acl = Get-Acl "AD:\`$ou"
`$ace = `$acl.Access | Where-Object { `$_.IdentityReference -match 'PRINCIPAL_SID' -and `$_.ObjectType -eq 'f3a64788-5306-11d1-a9c5-0000f80367c1' }
`$acl.RemoveAccessRule(`$ace)
Set-Acl -Path "AD:\`$ou" -AclObject `$acl
'@
            }
            @{
                Description = "Enable auditing for SPN changes"
                Command = "auditpol /set /subcategory:'Directory Service Changes' /success:enable"
            }
        )
        References = @(
            @{ Title = "Validated Writes in AD"; Url = "https://docs.microsoft.com/en-us/windows/win32/adschema/validated-writes" }
            @{ Title = "Validated-SPN GUID f3a64788-5306-11d1-a9c5-0000f80367c1"; Url = "https://docs.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/1522b774-6464-41a3-87a5-1e5633c3fbbb" }
        )
        Tools = @("BloodHound", "PowerView")
        MITRE = "T1558.003"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'Validated-SPN|Self \(Validated-SPN\)|WriteProperty \(Validated-SPN\)'; Severity = 'Hint' }
        )
    }

    'OU_PERM_DNSHOSTNAME_WRITE' = @{
        Title = "WriteProperty (dNSHostName) on OU"
        Risk = "Finding"
        BaseScore = 50
        Description = "A principal can modify the dNSHostName attribute on computer accounts in this OU. This can enable Kerberos relay attacks where an attacker impersonates the computer's identity to other services."
        Impact = @(
            "Can change computer's DNS hostname identity"
            "Enables Kerberos relay attacks against other services"
            "Can impersonate the computer to obtain service tickets"
            "Affects authentication flows that rely on dNSHostName"
        )
        Attack = @(
            "1. Attacker modifies dNSHostName of a computer account"
            "2. Sets it to match a target server (e.g., DC)"
            "3. Performs Kerberos relay to authenticate as the computer"
            "4. Obtains tickets for services trusting the DNS name"
        )
        Remediation = @(
            "Remove dNSHostName write permissions from non-admin principals"
            "Only machine accounts should modify their own dNSHostName"
            "Monitor for dNSHostName changes on computer accounts"
            "Use validated writes (Validated-DNS-Host-Name) instead of direct WriteProperty"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        RemediationCommands = @(
            @{
                Description = "View current ACL for dNSHostName attribute on OU"
                Command = "(Get-Acl 'AD:\OU=Computers,DC=domain,DC=com').Access | Where-Object {`$_.ObjectType -eq '72e39547-7b18-11d1-adef-00c04fd8d5cd'} | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize"
            }
            @{
                Description = "Remove WriteProperty permission for dNSHostName from specific principal"
                Command = "`$acl = Get-Acl 'AD:\OU=Computers,DC=domain,DC=com'; `$ace = `$acl.Access | Where-Object {`$_.IdentityReference -eq 'DOMAIN\User' -and `$_.ActiveDirectoryRights -match 'WriteProperty' -and `$_.ObjectType -eq '72e39547-7b18-11d1-adef-00c04fd8d5cd'}; `$ace | ForEach-Object {`$acl.RemoveAccessRule(`$_)}; Set-Acl -Path 'AD:\OU=Computers,DC=domain,DC=com' -AclObject `$acl"
            }
            @{
                Description = "Monitor dNSHostName changes via Event ID 5136 (Directory Service Changes)"
                Command = "Get-WinEvent -FilterHashtable @{LogName='Security'; Id=5136; StartTime=(Get-Date).AddDays(-7)} | Where-Object {`$_.Message -match 'dNSHostName'} | Select-Object TimeCreated,@{Name='Computer';Expression={`$_.Properties[10].Value}},@{Name='Attribute';Expression={`$_.Properties[8].Value}},@{Name='NewValue';Expression={`$_.Properties[11].Value}} | Format-Table -AutoSize"
            }
            @{
                Description = "Confirm that computers keep the validated write on their own dNSHostName (SELF, Self right) - it is granted by default, so nothing needs to be added, and an unvalidated WriteProperty for SELF would be the weakening this finding is about"
                Command = "(Get-Acl 'AD:\CN=COMPUTER01,OU=Computers,DC=domain,DC=com').Access | Where-Object { `$_.IdentityReference -eq 'NT AUTHORITY\SELF' -and `$_.ObjectType -eq '72e39547-7b18-11d1-adef-00c04fd8d5cd' } | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize"
            }
        )
        References = @(
            @{ Title = "Machine Account Quota Attacks"; Url = "https://www.thehacker.recipes/ad/movement/kerberos/delegations/rbcd" }
            @{ Title = "CVE-2022-26923 - Microsoft"; Url = "https://msrc.microsoft.com/update-guide/vulnerability/CVE-2022-26923" }
            @{ Title = "Understanding Get-ACL and AD Drive Output"; Url = "https://devblogs.microsoft.com/powershell-community/understanding-get-acl-and-ad-drive-output/" }
            @{ Title = "Using PowerShell to assign permissions on AD objects"; Url = "https://social.technet.microsoft.com/Forums/Lync/en-US/df3bfd33-c070-4a9c-be98-c4da6e591a0a/forum-faq-using-powershell-to-assign-permissions-on-active-directory-objects" }
        )
        Tools = @("Impacket", "krbrelayx", "Rubeus")
        MITRE = "T1557.001"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'WriteProperty \(dNSHostName\)'; Severity = 'Finding' }
        )
    }

    'OU_PERM_KEYCREDENTIALLINK_WRITE' = @{
        Title = "WriteProperty (msDS-KeyCredentialLink) on OU"
        Risk = "Finding"
        # Below WriteDacl and WriteOwner (55): a row that carries one of those as well has
        # to open their card, because they grant this right and everything else.
        BaseScore = 54
        Description = "A principal can write msDS-KeyCredentialLink on the users or computers in this OU - the Shadow Credentials attack. It adds a key pair of its own to an account and then authenticates as that account with PKINIT, without knowing or changing the password; the key keeps working across every password reset until somebody removes it. Key Admins and Enterprise Key Admins hold this right on the whole domain by design, for Windows Hello for Business, and are not reported."
        Impact = @(
            "Authentication as any user or computer in the OU, without the password and without changing it"
            "On a computer account: a ticket for the computer, and with S4U2Self administrative access to the machine"
            "Persistence that survives password resets, because the planted key is a credential of its own"
            "Needs a domain controller with a certificate for PKINIT, which every domain with AD CS or Windows Hello for Business has"
        )
        Attack = @(
            "1. Attacker writes a new key credential into msDS-KeyCredentialLink of a target account (Whisker, pyWhisker, Certipy shadow)"
            "2. Requests a TGT for the target with PKINIT, using the private key of that pair"
            "3. Recovers the target's NT hash from the PAC (UnPAC-the-hash) or uses the ticket directly"
            "4. Optionally leaves the key in place as a backdoor"
        )
        Remediation = @(
            "Remove the write right on msDS-KeyCredentialLink from every principal that is not Key Admins, Enterprise Key Admins or the account itself"
            "Audit msDS-KeyCredentialLink on the accounts in this OU for keys nobody can account for"
            "Monitor changes to msDS-KeyCredentialLink (Event ID 5136)"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        RemediationCommands = @(
            @{
                Description = "Show who may write msDS-KeyCredentialLink on an OU"
                Command = "(Get-Acl 'AD:\OU=TARGET_OU,DC=domain,DC=com').Access | Where-Object { `$_.ActiveDirectoryRights -match 'WriteProperty' -and `$_.ObjectType -eq '5b47d60f-6090-40b2-9f37-2a4de88f3063' } | Format-Table IdentityReference,ActiveDirectoryRights,IsInherited,AccessControlType -AutoSize"
            }
            @{
                Description = "List the accounts in the OU that carry key credentials"
                Command = "Get-ADObject -SearchBase 'OU=TARGET_OU,DC=domain,DC=com' -LDAPFilter '(msDS-KeyCredentialLink=*)' -Properties msDS-KeyCredentialLink | Select-Object Name,DistinguishedName"
            }
        )
        References = @(
            @{ Title = "Shadow Credentials: Abusing Key Trust Account Mapping for Account Takeover"; Url = "https://posts.specterops.io/shadow-credentials-abusing-key-trust-account-mapping-for-takeover-8ee1a53566ab" }
            @{ Title = "Key Credential Link - MS-ADTS"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/f3f01e95-6d0c-4fe6-8b43-d585167658fa" }
        )
        Tools = @("Whisker", "pyWhisker", "Certipy", "Rubeus")
        MITRE = "T1556"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'WriteProperty \(msDS-KeyCredentialLink\)'; Severity = 'Finding' }
        )
    }

    'ADMINSDHOLDER_PROPAGATED_RIGHT' = @{
        Title = "A Right on AdminSDHolder That SDProp Copies Onto Every Protected Object"
        Risk = "Finding"
        # Below WriteDacl and WriteOwner (55), for the same reason as the OU cards.
        BaseScore = 54
        Description = "A principal holds a right on CN=AdminSDHolder that is not one of its defaults. SDProp writes the AdminSDHolder security descriptor onto every protected group and every member of one - Domain Admins, Enterprise Admins, Schema Admins, Administrators and the operator groups among them - every hour, so a right here is that right on all of them, and it comes back after anyone removes it from one account. The row says which right and what it allows: adding a member to every protected group, writing a key credential, an SPN, a certificate mapping or userAccountControl on every protected account, resetting their passwords, or - for the owner - rewriting the template itself."
        Impact = @(
            "A member right makes the trustee a member of Domain Admins whenever it likes"
            "A key credential, SPN, certificate mapping or reset right takes over any administrator account"
            "SDProp restores the right every hour, which makes it a persistence mechanism as much as an escalation"
            "Ownership of AdminSDHolder lets the owner grant itself anything here"
        )
        Attack = @(
            "1. Attacker uses the right on one protected object - SDProp has already copied it there"
            "2. For a member right: adds itself to Domain Admins; for an account right: takes over an administrator"
            "3. Keeps the access, because the next SDProp run puts the right back if it is removed below"
        )
        Remediation = @(
            "Remove the ACE from CN=AdminSDHolder,CN=System - removing it from a protected object alone does not last"
            "Wait for SDProp or trigger it (runProtectAdminGroupsTask on the PDC emulator), then confirm the protected objects no longer carry it"
            "For an owner finding, set the owner of AdminSDHolder back to Domain Admins"
            "Treat a non-default ACE here as a sign of compromise and review the protected accounts"
        )
        RemediationCommands = @(
            @{
                Description = "Show the explicit ACEs and the owner of AdminSDHolder"
                Command = "`$acl = Get-Acl 'AD:\CN=AdminSDHolder,CN=System,DC=domain,DC=com'; `$acl.Owner; `$acl.Access | Where-Object { -not `$_.IsInherited } | Format-Table IdentityReference,ActiveDirectoryRights,ObjectType,AccessControlType -AutoSize"
            }
        )
        References = @(
            @{ Title = "AdminSDHolder and SDProp"; Url = "https://adsecurity.org/?p=1906" }
            @{ Title = "Appendix C: Protected Accounts and Groups in Active Directory"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-c--protected-accounts-and-groups-in-active-directory" }
        )
        Tools = @("PowerView", "BloodHound", "ADACLScanner")
        MITRE = "T1098"
        Triggers = @(
            # The rows Get-PrivilegedGroupMembers writes for AdminSDHolder; their wording
            # names every protected group or account, which no other producer does. The
            # member rows had no card before.
            @{ Attribute = 'dangerousRights'; Pattern = ' - may .+ every protected (group|account)'; Severity = 'Finding' }
        )
    }

