        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'WriteProperty \(gPOptions\)'; Severity = 'Finding' }
        )
    }

    'OU_PERM_GENERICWRITE' = @{
        Title = "GenericWrite on OU"
        Risk = "Finding"
        BaseScore = 55
        Description = "A principal has GenericWrite permission on this OU. GenericWrite includes WriteProperty, WriteSelf, and WritePropertyExtended rights, allowing modification of many attributes including security-sensitive ones."
        Impact = @(
            "Can write to most attributes on affected objects"
            "Includes ability to modify SPN, scriptPath, and delegation settings"
            "Less than GenericAll but still very powerful"
            "Enables targeted Kerberoasting and other attacks"
        )
        Attack = @(
            "Same attacks as WriteProperty (All Properties)"
            "Add SPN for Kerberoasting"
            "Modify scriptPath for code execution"
            "Configure delegation attributes"
        )
        Remediation = @(
            "Replace GenericWrite with specific attribute permissions"
            "GenericWrite is overly broad for most delegation needs"
            "Review all principals with GenericWrite"
            "Use delegation wizards for specific tasks"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        RemediationCommands = @(
            @{
                Description = "View current ACL on OU to identify principals with GenericWrite"
                Command = "(Get-Acl 'AD:\OU=TARGET_OU,DC=domain,DC=com').Access | Where-Object {`$_.ActiveDirectoryRights -match 'GenericWrite'} | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize"
            }
            @{
                Description = "Remove GenericWrite permission from specific principal"
                Command = "`$acl = Get-Acl 'AD:\OU=TARGET_OU,DC=domain,DC=com'; `$ace = `$acl.Access | Where-Object {`$_.IdentityReference -eq 'DOMAIN\USER' -and `$_.ActiveDirectoryRights -match 'GenericWrite'}; `$ace | ForEach-Object {`$acl.RemoveAccessRule(`$_)}; Set-Acl -Path 'AD:\OU=TARGET_OU,DC=domain,DC=com' -AclObject `$acl"
            }
            @{
                Description = "Delegate specific task using Delegation of Control Wizard (safer than GenericWrite)"
                Command = "# Use Active Directory Users and Computers > OU > Right-click > Delegate Control > Choose specific task (e.g., Reset user passwords) instead of granting GenericWrite"
            }
            @{
                Description = "List common delegation tasks that can replace GenericWrite"
                Command = "# Common delegation tasks: Reset user passwords, Modify group membership, Manage user accounts, Join computer to domain - Use Delegation of Control Wizard for granular permissions"
            }
        )
        References = @(
            @{ Title = "BloodHound GenericWrite"; Url = "https://bloodhound.specterops.io/resources/edges/generic-write" }
            @{ Title = "AD Delegation Best Practices - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/delegating-administration-by-using-ou-objects" }
            @{ Title = "Set-Acl - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.security/set-acl" }
        )
        Tools = @("BloodHound", "PowerView", "ADACLScanner")
        MITRE = "T1222.001"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'GenericWrite'; Severity = 'Finding' }
        )
    }

    'OU_PERM_READALL' = @{
        Title = "ReadProperty (All Properties) on OU"
        Risk = "Hint"
        BaseScore = 20
        Description = "A principal has ReadProperty (All Properties) permission on an OU. While read-only, this grants access to all attributes of objects in the OU, including sensitive ones like LAPS passwords, confidential attributes, and security descriptors."
        Impact = @(
            "Can read LAPS passwords if stored on computer objects in this OU"
            "Can enumerate all user attributes including confidential ones"
            "Can read security descriptors to map further attack paths"
        )
        Remediation = @(
            "Review if broad read access is necessary for this principal"
            "Consider using more granular read permissions per attribute"
            "Ensure LAPS password read is restricted via separate ACLs"
            "If the finding names an inherited source the entry is not on this OU - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this OU inherits"
        )
        References = @(
            @{ Title = "AD Confidential Attributes"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/mark-attribute-as-confidential" }
        )
        Tools = @("BloodHound", "PowerView", "ADACLScanner")
        MITRE = "T1087.002"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'ReadProperty \(All Properties\)'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # ACCOUNT SECURITY FINDINGS
    # ============================================================================

    'PASSWORD_NEVER_EXPIRES' = @{
        Title = "Password Never Expires"
        Risk = "Hint"
        BaseScore = 25
        Description = "This account has the 'Password never expires' flag set. While sometimes required for service accounts, this increases the risk of credential compromise over time as passwords are not rotated."
        Impact = @(
            "Passwords are not rotated, increasing compromise window"
            "If password is leaked or cracked, it remains valid indefinitely"
            "Service accounts with old passwords are high-value targets"
            "Violates security best practices and compliance requirements"
        )
        Attack = @(
            "1. Attacker obtains password through phishing, leak, or cracking"
            "2. Password remains valid indefinitely"
            "3. Attacker maintains persistent access"
        )
        Remediation = @(
            "Enable password expiration for user accounts"
            "For service accounts, use Group Managed Service Accounts (gMSA)"
            "Implement regular password rotation policies"
            "Monitor for accounts with this flag set"
        )
        RemediationCommands = @(
            @{
                Description = "Enable password expiration for a single user account"
                Command = "Set-ADUser -Identity 'USERNAME' -PasswordNeverExpires `$false"
            }
            @{
                Description = "Enable password expiration for all users in a specific OU"
                Command = "Get-ADUser -Filter {PasswordNeverExpires -eq `$true} -SearchBase 'OU=Users,DC=domain,DC=com' | Set-ADUser -PasswordNeverExpires `$false"
            }
            @{
                Description = "View all users with PasswordNeverExpires flag set"
                Command = "Get-ADUser -Filter {PasswordNeverExpires -eq `$true} -Properties PasswordNeverExpires,PasswordLastSet | Select-Object Name,SamAccountName,PasswordNeverExpires,PasswordLastSet"
            }
        )
        References = @(
            @{ Title = "Set-ADUser PasswordNeverExpires - Microsoft Q&A"; Url = "https://learn.microsoft.com/en-us/answers/questions/316870/powershell-active-directory-password-never-expires" }
            @{ Title = "Password Policy Best Practices"; Url = "https://docs.microsoft.com/en-us/azure/active-directory/authentication/concept-password-ban-bad-on-premises" }
        )
        Tools = @("PowerView", "AD Administrative Center")
        MITRE = "T1078"
        Triggers = @(
            @{ Attribute = 'userAccountControl'; Pattern = 'DONT_EXPIRE_PASSWORD|PASSWORD_NEVER_EXPIRES'; Severity = 'Hint' }
        )
    }

    'PASSWORD_NOT_REQUIRED' = @{
        Title = "Password Not Required Flag Set"
        Risk = "Finding"
        BaseScore = 35
        Description = "This account has the PASSWD_NOTREQD flag set, meaning the account can have an empty password. This is a severe security misconfiguration that allows authentication without a password."
        Impact = @(
            "Account may have no password set"
            "Enables authentication with blank password"
            "Often indicates legacy or misconfigured accounts"
            "Easy target for attackers"
        )
        Attack = @(
            "1. Attacker identifies accounts with PASSWD_NOTREQD"
            "2. Attempts authentication with empty password"
            "3. If successful, gains access to the account"
        )
        Remediation = @(
            "Remove the PASSWD_NOTREQD flag from all accounts"
            "Set strong passwords on these accounts"
            "Investigate why the flag was set and remediate root cause"
            "Consider disabling accounts that don't need to be active"
        )
        RemediationCommands = @(
            @{
                Description = "Remove PasswordNotRequired flag from a single user account"
                Command = "Set-ADUser -Identity 'USERNAME' -PasswordNotRequired `$false"
            }
            @{
                Description = "Remove flag from all users in a specific OU (using LDAP filter for userAccountControl bit 32)"
                Command = "Get-ADUser -LDAPFilter '(&(objectClass=user)(userAccountControl:1.2.840.113556.1.4.803:=32))' -SearchBase 'OU=Users,DC=domain,DC=com' | Set-ADUser -PasswordNotRequired `$false"
            }
            @{
                Description = "Find all enabled accounts with PasswordNotRequired flag set"
                Command = "Get-ADUser -Filter {PasswordNotRequired -eq `$true -and Enabled -eq `$true} -Properties PasswordNotRequired,PasswordLastSet | Select-Object Name,SamAccountName,PasswordNotRequired,PasswordLastSet,Enabled"
            }
            @{
                Description = "Set a strong password after removing the flag"
                Command = "`$NewPwd = ConvertTo-SecureString -String 'NewStrongPassword123!' -AsPlainText -Force; Set-ADAccountPassword -Identity 'USERNAME' -NewPassword `$NewPwd -Reset"
            }
        )
        References = @(
            @{ Title = "Removing PasswordNotRequired - Microsoft Q&A"; Url = "https://learn.microsoft.com/en-us/answers/questions/988004/removing-passwordnotrequired-settings-or-poilcy-fr" }
            @{ Title = "Understanding PASSWD_NOTREQD - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/archive/blogs/russellt/passwd_notreqd" }
            @{ Title = "AD Account Properties"; Url = "https://docs.microsoft.com/en-us/troubleshoot/windows-server/identity/useraccountcontrol-manipulate-account-properties" }
        )
        Tools = @("PowerView", "LDAP queries")
        MITRE = "T1078"
        Triggers = @(
            @{ Attribute = 'userAccountControl'; Pattern = 'PASSWD_NOTREQD'; Severity = 'Finding' }
            # The per-account verdict Get-PasswordNotRequired writes. One flat list used
            # to come out of that check: a trust account, for which this flag is the
            # default, a kiosk account and a Domain Admin, all rendered the same way.
            # Anchored on the first word, because two triggers on one attribute whose
            # patterns can both match a value pick their winner by hashtable order.
            @{ Attribute = 'passwordNotRequiredVerdict'; Pattern = '^EMPTY'; Severity = 'Finding' }
            @{ Attribute = 'passwordNotRequiredVerdict'; Pattern = '^PRIVILEGED'; Severity = 'Finding' }
            @{ Attribute = 'passwordNotRequiredVerdict'; Pattern = '^Exempt'; Severity = 'Hint' }
            # A computer account with the flag that has logged on. The one that has not is
            # PRECREATED_COMPUTER_ACCOUNT.
            @{ Attribute = 'passwordNotRequiredVerdict'; Pattern = '^Has logged on'; Severity = 'Hint' }
        )
    }

    'PRECREATED_COMPUTER_ACCOUNT' = @{
        Title = "Pre-Created Computer Account That Has Never Logged On"
        Risk = "Finding"
        BaseScore = 30
        Description = "This enabled computer account carries PASSWD_NOTREQD and has never logged on - the signature of an account created ahead of its computer (userAccountControl 4128). Created with 'Assign this computer account as a pre-Windows 2000 computer', its password is the computer name in lowercase without the trailing dollar sign, and it stays that until a computer joins the domain with the account, which sets a random password and clears the flag. Without that option the password is random; the directory does not record which of the two was used."
        Impact = @(
            "Trying computer names as passwords yields a domain account without any credentials"
            "A machine account under the attacker's control is what resource-based constrained delegation attacks need, even where the machine account quota is 0"
            "Over NTLM the right password returns STATUS_NOLOGON_WORKSTATION_TRUST_ACCOUNT instead of a logon, which still confirms it; Kerberos accepts it outright"
        )
        Attack = @(
            "1. Attacker collects computer names - from DNS, from NetBIOS, or from the directory"
            "2. Requests a TGT for each account with its name in lowercase as password - tools cut the name to 14 characters"
            "3. Uses the machine account to enumerate the domain, roast service accounts or stage a resource-based constrained delegation attack"
        )
        Remediation = @(
            "Delete pre-created computer accounts that no computer is going to join with"
            "Set a random password on the ones still needed, or join the computer, which also clears the flag"
            "Remove the 'Password Not Required' flag"
        )
        RemediationCommands = @(
            @{
                Description = "List the enabled computer accounts that carry the flag, with their last logon"
                Command = "Get-ADComputer -LDAPFilter '(&(userAccountControl:1.2.840.113556.1.4.803:=32)(!(userAccountControl:1.2.840.113556.1.4.803:=2)))' -Properties lastLogonTimestamp,pwdLastSet | Select-Object Name,lastLogonTimestamp,pwdLastSet"
            }
            @{
                Description = "Delete a pre-created account that is no longer needed"
                Command = "Remove-ADComputer -Identity 'COMPUTERNAME'"
            }
            @{
                Description = "Set a random password on a pre-created account that has not been joined yet, and remove the flag"
                Command = "Set-ADAccountPassword -Identity 'COMPUTERNAME$' -Reset -NewPassword (ConvertTo-SecureString -AsPlainText -Force ([guid]::NewGuid().ToString() + [guid]::NewGuid().ToString())); Set-ADAccountControl -Identity 'COMPUTERNAME$' -PasswordNotRequired `$false"
            }
        )
        References = @(
            @{ Title = "Diving into Pre-Created Computer Accounts - TrustedSec"; Url = "https://trustedsec.com/blog/diving-into-pre-created-computer-accounts" }
            @{ Title = "Diving Deeper Into Pre-Created Computer Accounts - Optiv"; Url = "https://www.optiv.com/insights/discover/blog/diving-deeper-pre-created-computer-accounts" }
            @{ Title = "Pre-Windows 2000 computers - The Hacker Recipes"; Url = "https://www.thehacker.recipes/ad/movement/builtins/pre-windows-2000-computers" }
        )
        Tools = @("pre2k", "NetExec")
        MITRE = "T1078.002"
        Triggers = @(
            @{ Attribute = 'passwordNotRequiredVerdict'; Pattern = '^NEVER LOGGED ON'; Severity = 'Finding' }
        )
    }

    'INTERDOMAIN_TRUST_ACCOUNT' = @{
        Title = "Inter-Domain Trust Account"
        Risk = "Hint"
        BaseScore = 20
        Description = "This is a trust account (INTERDOMAIN_TRUST_ACCOUNT) representing a trust relationship between two Active Directory domains. Trust accounts store a shared secret used to authenticate cross-domain Kerberos requests. The account name typically matches the trusted domain name with a trailing dollar sign. Windows creates every trust account with PASSWD_NOTREQD set (userAccountControl 2080); the flag does not make the password empty - the domain controllers generate the trust password and change it every 30 days."
        Impact = @(
            "Trust accounts hold the shared secret for the entire trust relationship"
            "Compromising the trust key allows forging inter-realm TGTs"
            "An attacker with the trust key can create cross-domain Golden Tickets"
            "Trust keys are equivalent to krbtgt keys for cross-domain access"
        )
        Attack = @(
            "1. Extract the trust key from the trust account (DCSync or NTDS.dit)"
            "2. Forge an inter-realm TGT with SIDHistory of Enterprise Admins"
            "3. Present the forged ticket to the trusted domain's KDC"
            "4. Gain administrative access across the trust boundary"
        )
        Remediation = @(
            "Leave PASSWD_NOTREQD on the trust account alone - Windows sets it on every trust account, and it is not a weakness there"
            "Reset the trust password after a suspected compromise of either domain (netdom trust ... /reset); Windows changes it every 30 days on its own"
            "Monitor trust account modifications with Event ID 4738"
            "Consider Selective Authentication to limit trust scope"
            "Use SID Filtering to prevent SIDHistory-based escalation across trusts"
        )
        References = @(
            @{ Title = "Trust Account Attack - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/inter-forest-and-cross-domain-attacks.html" }
            @{ Title = "Golden Ticket - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1558/001/" }
            @{ Title = "Domain Trust Discovery - Microsoft"; Url = "https://learn.microsoft.com/en-us/defender-for-identity/security-assessment-unsecure-domain-trust" }
        )
        Tools = @("Mimikatz", "Impacket", "Rubeus", "netdom")
        MITRE = "T1134.005"
        Triggers = @(
            @{ Attribute = 'userAccountControl'; Pattern = 'INTERDOMAIN_TRUST_ACCOUNT'; Severity = 'Hint' }
        )
    }

    'ESX_ADMINS_MEMBER' = @{
        Title = "Member of ESX Admins (VMware ESXi Administrators)"
        Risk = "Hint"
        BaseScore = 35
        Description = "This account is a member of a domain group named ESX Admins. A VMware ESXi host joined to the domain makes every member of a group of that name a full administrator of the host. It matches the name alone and does not check that the group existed when the host was joined, so a group created later - or another group renamed to it - counts the same (CVE-2024-37085). An administrator of the hypervisor controls every virtual machine on it, domain controllers included, whose disks hold the directory database. Microsoft reported ransomware operators creating this group and adding themselves to it in 2024. Whoever may add a member to the group has the same reach."
        Impact = @(
            "Full administrative control of every ESXi host joined to the domain that still uses the default group"
            "Access to the disks of the virtual machines on those hosts - a domain controller's disk holds the directory database"
            "Mass encryption of the virtual machines, as in the ransomware cases Microsoft reported"
        )
        Attack = @(
            "1. Attacker becomes a member of ESX Admins - or creates or renames a group to that name if none exists"
            "2. Logs on to a domain-joined ESXi host with domain credentials and is its administrator"
            "3. Copies a domain controller's virtual disk, or encrypts the virtual machines"
        )
        Remediation = @(
            "Treat the group as Tier 0: keep its membership minimal and let only the domain's administrators change it"
            "On every ESXi host joined to the domain, point Config.HostAgent.plugins.hostsvc.esxAdminsGroup to a dedicated group, or leave the domain where the join is not needed"
            "Update ESXi to a version with the fix for CVE-2024-37085 - Broadcom fixed 8.0 and VMware Cloud Foundation 5.x"
        )
        References = @(
            @{ Title = "Ransomware operators exploit ESXi hypervisor vulnerability for mass encryption - Microsoft"; Url = "https://www.microsoft.com/en-us/security/blog/2024/07/29/ransomware-operators-exploit-esxi-hypervisor-vulnerability-for-mass-encryption/" }
        )
        Tools = @("PowerView", "BloodHound")
        MITRE = "T1098"
        Triggers = @(
            @{ Attribute = 'privilegedGroups'; Custom = 'is_esxadmins_sid'; Severity = 'Hint' }
            @{ Attribute = 'MemberOf'; Custom = 'is_esxadmins_sid'; Severity = 'Hint' }
        )
    }

    'PRIVILEGED_GROUP_MEMBERSHIP' = @{
        Title = "Privileged Group Membership (Tier 0)"
        Risk = "Finding"
        BaseScore = 15
        Description = "This account is a member of one or more highly privileged Active Directory groups. According to Microsoft's Enterprise Access Model (Tier Model), these are Tier 0 assets - the most sensitive resources that control the identity infrastructure. Compromise of Tier 0 accounts enables full domain/forest takeover."
        Impact = @(
            "Tier 0 - Domain Admins: Full control over all domain objects and Domain Controllers"
            "Tier 0 - Enterprise Admins: Full control over all domains in the forest"
            "Tier 0 - Schema Admins: Can modify the AD schema (forest-wide impact)"
            "Tier 0 - Administrators: Local admin on all Domain Controllers"
            "Tier 0 - Account/Server/Backup Operators: Can escalate to Domain Admin through various techniques"
            "Tier violation: If a Tier 0 account is used on Tier 1/2 systems, credentials can be stolen"
        )
        Attack = @(
            "1. Attacker compromises the Tier 0 account (phishing, credential theft, Tier violation)"
            "2. Uses privileges to access Domain Controllers"
            "3. Extracts all credentials via DCSync, LSASS dump, or NTDS.dit"
            "4. Creates Golden Tickets for persistent forest-wide access"
        )
        Remediation = @(
            "Implement Microsoft's Enterprise Access Model (Tier Model)"
            "Tier 0 accounts: Only use on Tier 0 systems (DCs, PAWs)"
            "Minimize the number of Tier 0 accounts"
            "Use dedicated admin accounts (not used for daily activities)"
            "Add Tier 0 USER accounts to 'Protected Users'. It ends NTLM, CredSSP, Digest, RC4 and delegation for those accounts and stops their credentials being cached, so anything that depends on one of those breaks - test before rolling it out broadly"
            "Do not put a computer account or a gMSA in 'Protected Users' - Microsoft advises against it and it has no effect there. Use 'Account is sensitive and cannot be delegated', msDS-SupportedEncryptionTypes set to AES only, and an authentication policy silo instead"
            "Implement Privileged Access Workstations (PAWs) for Tier 0 administration"
            "Enable multi-factor authentication for Tier 0 accounts"
            "Monitor for Tier violations (Tier 0 credentials on non-Tier 0 systems)"
        )
        References = @(
            @{ Title = "Microsoft Enterprise Access Model"; Url = "https://docs.microsoft.com/en-us/security/compass/privileged-access-access-model" }
            @{ Title = "Securing Privileged Access"; Url = "https://docs.microsoft.com/en-us/security/compass/privileged-access-accounts" }
            @{ Title = "Active Directory Tier Model"; Url = "https://adsecurity.org/?p=3299" }
            @{ Title = "Get-ADGroupMember"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adgroupmember" }
            @{ Title = "Remove-ADGroupMember"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/remove-adgroupmember" }
            @{ Title = "Securing Domain Admins Groups"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-f--securing-domain-admins-groups-in-active-directory" }
        )
        RemediationCommands = @(
            @{
                Description = "List all members of Domain Admins group (including nested)"
                Command = "Get-ADGroupMember -Identity 'Domain Admins' -Recursive | Select-Object Name,SamAccountName,ObjectClass,DistinguishedName | Format-Table -AutoSize"
            }
            @{
                Description = "List all members of Enterprise Admins group (including nested)"
                Command = "Get-ADGroupMember -Identity 'Enterprise Admins' -Recursive | Select-Object Name,SamAccountName,ObjectClass,DistinguishedName | Format-Table -AutoSize"
            }
            @{
                Description = "List all members of Schema Admins group (including nested)"
                Command = "Get-ADGroupMember -Identity 'Schema Admins' -Recursive | Select-Object Name,SamAccountName,ObjectClass,DistinguishedName | Format-Table -AutoSize"
            }
            @{
                Description = "Remove specific user from Domain Admins group"
                Command = "Remove-ADGroupMember -Identity 'Domain Admins' -Members 'USERNAME' -Confirm:`$false"
            }
            @{
                Description = "Audit all privileged group memberships (Tier 0 groups)"
                Command = "`$privilegedGroups = @('Domain Admins','Enterprise Admins','Schema Admins','Administrators','Account Operators','Server Operators','Backup Operators','Print Operators'); `$privilegedGroups | ForEach-Object { Write-Host `"Group: `$_`" -ForegroundColor Cyan; Get-ADGroupMember -Identity `$_ -Recursive -ErrorAction SilentlyContinue | Select-Object Name,SamAccountName | Format-Table -AutoSize }"
            }
            @{
                Description = "Add a Tier 0 user account to Protected Users - a user account, and after checking what it depends on"
                Command = @'
# Protected Users ends NTLM, CredSSP, Digest, RC4 and delegation for the member and stops
# its credentials being cached. For a user account that is the point; for a computer
# account or a gMSA it has no effect and Microsoft advises against it, so neither belongs
# in this group - and this finding attaches to all three kinds of member.
Add-ADGroupMember -Identity 'Protected Users' -Members 'TIER0_USER_ACCOUNT'

# For a computer account or a gMSA, use these instead:
Set-ADAccountControl -Identity 'TIER0_COMPUTER$' -AccountNotDelegated $true
Set-ADComputer -Identity 'TIER0_COMPUTER$' -Replace @{ 'msDS-SupportedEncryptionTypes' = 24 }  # AES128 + AES256 only
'@
            }
        )
        Tools = @("BloodHound", "PowerView", "PingCastle")
        MITRE = "T1078.002"
        Triggers = @(
            # SID-based classification: Privileged group SID = Finding
            # Order matters: is_privileged_sid MUST come before is_dnsadmins_sid
            @{ Attribute = 'privilegedGroups'; Custom = 'is_privileged_sid'; Severity = 'Finding' }
            @{ Attribute = 'privilegedGroups'; Custom = 'is_dnsadmins_sid'; Severity = 'Finding' }
            @{ Attribute = 'Member'; Custom = 'is_privileged_sid'; Severity = 'Finding' }
            @{ Attribute = 'MemberOf'; Custom = 'is_privileged_sid'; Severity = 'Finding' }
            @{ Attribute = 'MemberOf'; Custom = 'is_dnsadmins_sid'; Severity = 'Finding' }
        )
    }

    # Operator/Broad Group Membership (Yellow/Hint)
    'OPERATOR_GROUP_MEMBERSHIP' = @{
        Title = "Operator or Broad Group Membership"
        Risk = "Hint"
        BaseScore = 10
        Description = "This account is a member of an operator-level or broad-access group such as Account Operators, Backup Operators, Print Operators, Cert Publishers, or similar groups with elevated but not full domain control privileges. These groups have specific permissions that can be abused for privilege escalation."
        Impact = @(
            "Account Operators: Can create accounts and modify non-admin accounts"
            "Backup Operators: Can back up and restore files on DCs, including NTDS.dit"
            "Print Operators: Can load drivers on DCs (potential kernel-mode code execution)"
            "Cert Publishers: Can modify certificate templates and CA configuration"
            "Server Operators: Can log on to DCs and manage services"
        )
        Remediation = @(
            "Review if membership in this group is necessary"
            "Follow least-privilege principle for group assignments"
            "Monitor membership changes in these groups"
            "Consider using delegated permissions instead of broad group membership"
        )
        References = @(
            @{ Title = "AD Built-In Groups"; Url = "https://docs.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-b--privileged-accounts-and-groups-in-active-directory" }
            @{ Title = "Abusing Backup Operators"; Url = "https://www.bordergate.co.uk/backup-operator-privilege-escalation/" }
        )
        MITRE = "T1078.002"
        Triggers = @(
            # SID-based classification: Operator group SID = Hint
            @{ Attribute = 'privilegedGroups'; Custom = 'is_operator_sid'; Severity = 'Hint' }
            @{ Attribute = 'Member'; Custom = 'is_operator_sid'; Severity = 'Hint' }
            @{ Attribute = 'MemberOf'; Custom = 'is_operator_sid'; Severity = 'Hint' }
        )
    }

    'EXCHANGE_GROUP_PERMISSIONS' = @{
        Title = "Exchange Service Group Permissions (By-Design)"
        Risk = "Note"
        BaseScore = 45
        Description = "This is an Exchange service group with extensive Active Directory permissions. These permissions are required for Exchange Server to function properly and cannot be removed without breaking Exchange functionality. The group resides in the 'OU=Microsoft Exchange Security Groups' organizational unit."
        Impact = @(
            "Exchange groups have broad permissions including password reset rights on certain OUs"
            "These permissions are by-design and necessary for Exchange operations"
            "Compromise of these groups would grant significant AD access"
            "However, these groups are managed by Exchange and not directly user-controlled"
        )
        Attack = @(
            "Attackers may target Exchange servers to gain access to these privileged groups"
            "Exchange vulnerabilities (e.g., ProxyLogon, ProxyShell) could provide access"
            "Once Exchange is compromised, attackers can leverage these permissions"
        )
        Remediation = @(
            "NOTE: These permissions CANNOT and SHOULD NOT be removed"
            "Keep Exchange servers fully patched and updated"
            "Monitor Exchange service group membership for unexpected changes"
            "Implement network segmentation for Exchange servers"
            "Use dedicated admin accounts for Exchange administration"
            "Consider implementing Extended Protection for Authentication (EPA)"
        )
        References = @(
            @{ Title = "Exchange Permissions Deep Dive"; Url = "https://docs.microsoft.com/en-us/exchange/permissions" }
            @{ Title = "ProxyLogon Vulnerability"; Url = "https://msrc.microsoft.com/update-guide/vulnerability/CVE-2021-26855" }
        )
        Tools = @("BloodHound", "PingCastle")
        MITRE = "T1078.002"
    }

    'EXCHANGE_GROUP_LOW_PRIV_MEMBER' = @{
        Title = "Low-Privileged Account in Exchange Service Group"
        Risk = "Finding"
        BaseScore = 20
        Description = "A low-privileged (non-administrator) account is a member of an Exchange service group. Exchange service groups have extensive Active Directory permissions and should only contain Exchange service accounts, computer accounts, and administrative accounts. Regular users should NEVER be members of these groups."
        Impact = @(
            "Low-privileged user gains Exchange-level permissions in Active Directory"
            "Can potentially reset passwords for users in affected OUs"
            "May be able to modify Exchange-related attributes"
            "Significant privilege escalation pathway"
        )
        Attack = @(
            "1. Attacker compromises the low-privileged account"
            "2. Account is already member of Exchange service group (misconfiguration)"
            "3. Attacker leverages Exchange group permissions for privilege escalation"
            "4. Can potentially reset admin passwords or modify sensitive attributes"
        )
        Remediation = @(
            "IMMEDIATELY remove the low-privileged account from the Exchange service group"
            "Audit all Exchange service group memberships"
            "Investigate how the account was added (intentional or compromise)"
            "Review group membership change logs in Security Event Log"
            "Implement alerting for changes to Exchange security groups"
        )
        RemediationCommands = @(
            @{
                Description = "Remove a specific user from an Exchange service group"
                Command = "Remove-ADGroupMember -Identity 'Exchange Trusted Subsystem' -Members 'CN=User Name,OU=Users,DC=contoso,DC=com' -Confirm:`$false"
            }
            @{
                Description = "List all members of Exchange service groups to audit membership"
                Command = "Get-ADGroup -Filter ""Name -like 'Exchange*'"" | ForEach-Object { Write-Host `"Group: `$(`$_.Name)`" -ForegroundColor Yellow; Get-ADGroupMember -Identity `$_ | Select-Object Name, ObjectClass, SamAccountName }"
            }
            @{
                Description = "Find all Exchange security groups in the domain"
                Command = "Get-ADGroup -Filter ""(Name -like 'Exchange*') -and (GroupCategory -eq 'Security')"" -Properties Description | Select-Object Name, GroupScope, Description"
            }
            @{
                Description = "Check recent group membership changes in Security Event Log (Event ID 4728, 4732, 4756)"
                Command = "Get-WinEvent -FilterHashtable @{LogName='Security'; Id=4728,4732,4756; StartTime=(Get-Date).AddDays(-7)} | Where-Object { `$_.Message -match 'Exchange' } | Select-Object TimeCreated, Message | Format-List"
            }
        )
        References = @(
            @{ Title = "Exchange Security Groups"; Url = "https://docs.microsoft.com/en-us/exchange/permissions/permissions?view=exchserver-2019" }
            @{ Title = "AD Group Membership Auditing"; Url = "https://docs.microsoft.com/en-us/windows/security/threat-protection/auditing/audit-security-group-management" }
            @{ Title = "Remove-ADGroupMember"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/remove-adgroupmember" }
            @{ Title = "Get-ADGroup Filter Examples"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adgroup" }
        )
        Tools = @("BloodHound", "PowerView")
        MITRE = "T1078.002"
    }

    # ============================================================================
    # LDAP / DOMAIN CONFIGURATION FINDINGS
    # ============================================================================

    'LDAP_SIGNING_NOT_REQUIRED' = @{
        Title = "LDAP Signing Not Required"
        Risk = "Finding"
        BaseScore = 25
        Description = "The GPO does not configure LDAP signing requirements. Note: 'Not Configured' in GPO does not necessarily mean the setting is insecure - it may be configured locally on the Domain Controller or enforced by OS defaults (Windows Server 2025+ requires signing by default). However, best practice is to enforce security settings via GPO for consistent configuration across all systems."
        Impact = @(
            "LDAP traffic can be intercepted and modified"
            "NTLM relay attacks can target LDAP services"
            "Credentials can be captured or modified in transit"
            "Enables attacks like NTLM relay to LDAP for adding users to groups"
        )
        Attack = @(
            "1. Attacker positions for man-in-the-middle"
            "2. Coerces authentication from target (PetitPotam, PrinterBug)"
            "3. Relays NTLM authentication to DC LDAP"
            "4. Performs privileged LDAP operations (RBCD, group membership)"
        )
        Remediation = @(
            "Enable 'Domain controller: LDAP server signing requirements' = Require signing"
            "Configure via GPO: Computer Configuration > Policies > Windows Settings > Security Settings > Local Policies > Security Options"
            "Best practice: Always configure security settings via GPO rather than local policy"
            "Measure before enforcing, do not survey: set the diagnostic 16 LDAP Interface Events to 2 on the DCs and read the Directory Service log. 2886 and 2887 are the standing reminder and the 24-hour count; 2889 names the client address and the account for each unsigned or cleartext bind. That list is what enforcing breaks, by name"
            "What is usually on it: printers, scanners and multifunction devices doing a simple bind on port 389, appliances with an LDAP user directory behind them (VPN gateways, load balancers, NAS), older monitoring and backup agents, Linux hosts whose nss/pam/sssd configuration points at ldap:// without TLS, and in-house tools that bind with no authentication type set"
            "Every one of those is fixed on the client - LDAPS or StartTLS, or a SASL bind that requests signing - and not by leaving the domain controller as it is"
        )
        RemediationCommands = @(
            @{
                Description = "Enable LDAP signing requirement via registry on Domain Controller (Value 2 = Require Signing)"
                Command = "New-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Services\NTDS\Parameters' -Name LdapServerIntegrity -Value 2 -PropertyType DWORD -Force"
            }
            @{
                Description = "Verify current LDAP signing configuration on Domain Controller"
                Command = "Get-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Services\NTDS\Parameters' -Name LdapServerIntegrity | Select-Object LdapServerIntegrity"
            }
            @{
                Description = "Configure LDAP signing via Group Policy (preferred method for consistent configuration)"
                Command = "# In Group Policy Management: Default Domain Controller Policy > Computer Configuration > Policies > Windows Settings > Security Settings > Local Policies > Security Options > 'Domain controller: LDAP server signing requirements' = Require signing"
            }
            @{
                Description = "Test LDAP signing enforcement before deployment (check for unsigned binds)"
                Command = "# Use Event Viewer on DC: Security log Event ID 2889 indicates unsigned LDAP binds. Filter by Task Category 'LDAP Interface' to identify clients requiring updates"
            }
        )
        References = @(
            @{ Title = "How to enable LDAP signing - Windows Server"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/enable-ldap-signing-in-windows-server" }
            @{ Title = "Domain controller: LDAP server signing requirements"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/domain-controller-ldap-server-signing-requirements" }
            @{ Title = "Manage LDAP signing using Group Policy for Active Directory"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/manage-ldap-signing-group-policy" }
            @{ Title = "LDAP Relay Attacks"; Url = "https://dirkjanm.io/worst-of-both-worlds-ntlm-relaying-and-kerberos-delegation/" }
        )
        Tools = @("ntlmrelayx", "Impacket", "Responder")
        MITRE = "T1557"
        Triggers = @(
            @{ Attribute = 'LDAPSigning'; Pattern = '^(None|Disabled|Not Required|Unknown)$'; Severity = 'Finding' }
            @{ Attribute = 'LDAPSigning'; Pattern = '^Optional$'; Severity = 'Hint' }
            @{ Attribute = 'LDAPSigning'; Pattern = '^Not Configured$'; Severity = 'Hint' }
        )
    }

    'LDAP_CHANNEL_BINDING_NOT_REQUIRED' = @{
        Title = "LDAP Channel Binding Not Enforced"
        Risk = "Finding"
        BaseScore = 25
        Description = "The GPO does not configure LDAP channel binding. Note: 'Not Configured' in GPO does not necessarily mean the setting is insecure - it may be configured locally on the Domain Controller via registry or enforced by OS defaults (Windows Server 2025+ enforces channel binding by default). However, best practice is to enforce security settings via GPO for consistent configuration across all DCs."
        Impact = @(
            "LDAPS connections can be relayed"
            "Provides additional attack surface for NTLM relay"
            "Weakens overall LDAP security posture"
        )
        Attack = @(
            "1. Attacker performs LDAP relay over TLS"
            "2. Without channel binding, relay succeeds"
            "3. Attacker performs privileged LDAP operations"
        )
        Remediation = @(
            "Enable LDAP channel binding on Domain Controllers"
            "Set registry: HKEY_LOCAL_MACHINE\System\CurrentControlSet\Services\NTDS\Parameters\LdapEnforceChannelBinding = 2"
            "Best practice: Deploy via GPO Preferences for consistent configuration"
            "Go through 1 (When supported) first: it demands the token only from clients that announce they can supply one, which leaves the rest working while they are found. 2 (Always) once the audit is quiet"
            "The audit in between: with 16 LDAP Interface Events at 2, the Directory Service log writes 3039 per client, and 3040 and 3041 as the 24-hour summary. The clients named there are the ones that stop working at 2"
            "What this setting does not touch: a simple bind over LDAPS carries no channel binding token at all and is unaffected - it is the SASL binds (Negotiate, Kerberos, NTLM) over TLS that have to supply one. Windows clients do once the March 2020 updates are in, so what is usually left is non-Windows LDAP libraries and appliance firmware that never implemented CBT"
        )
        RemediationCommands = @(
            @{
                Description = "Enable LDAP channel binding enforcement on Domain Controller (Value 2 = Always require channel binding)"
                Command = "New-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Services\NTDS\Parameters' -Name LdapEnforceChannelBinding -Value 2 -PropertyType DWORD -Force"
            }
            @{
                Description = "Set to 'When Supported' mode for initial testing (Value 1 = Only enforce for updated clients)"
                Command = "New-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Services\NTDS\Parameters' -Name LdapEnforceChannelBinding -Value 1 -PropertyType DWORD -Force"
            }
            @{
                Description = "Verify current LDAP channel binding configuration on Domain Controller"
                Command = "Get-ItemProperty -Path 'HKLM:\System\CurrentControlSet\Services\NTDS\Parameters' -Name LdapEnforceChannelBinding -ErrorAction SilentlyContinue | Select-Object LdapEnforceChannelBinding"
            }
            @{
                Description = "Configure LDAP channel binding via Group Policy (Server 2025+)"
                Command = "# In Group Policy Management: Default Domain Controller Policy > Computer Configuration > Policies > Windows Settings > Security Settings > Local Policies > Security Options > 'Domain controller: LDAP server channel binding token requirements' = Always"
            }
        )
        References = @(
            @{ Title = "2020, 2023, and 2024 LDAP channel binding and LDAP signing requirements"; Url = "https://support.microsoft.com/en-us/topic/2020-2023-and-2024-ldap-channel-binding-and-ldap-signing-requirements-for-windows-kb4520412-ef185fb8-00f7-167d-744c-f299a66fc00a" }
            @{ Title = "KB4034879: Use the LdapEnforceChannelBinding registry entry"; Url = "https://support.microsoft.com/en-us/topic/kb4034879-use-the-ldapenforcechannelbinding-registry-entry-to-make-ldap-authentication-over-ssl-tls-more-secure-e9ecfa27-5e57-8519-6ba3-d2c06b21812e" }
            @{ Title = "Active Directory Hardening Series - Part 5 - Enforcing LDAP Channel Binding"; Url = "https://techcommunity.microsoft.com/blog/coreinfrastructureandsecurityblog/active-directory-hardening-series---part-5-%E2%80%93-enforcing-ldap-channel-binding/4235497" }
        )
        Tools = @("ntlmrelayx", "Impacket")
        MITRE = "T1557"
        Triggers = @(
            @{ Attribute = 'ChannelBinding'; Pattern = '^(Never|Disabled|Not Required)$'; Severity = 'Finding' }
            @{ Attribute = 'ChannelBinding'; Pattern = '^When Supported$'; Severity = 'Hint' }
            @{ Attribute = 'ChannelBinding'; Pattern = '^Not Configured$'; Severity = 'Hint' }
        )
    }

    'LDAP_ANONYMOUS_BINDING_ALLOWED' = @{
        # The card used to describe a GPO setting ("The GPO does not restrict anonymous
        # LDAP binding") and remediate it with 'Do not allow anonymous enumeration of SAM
        # accounts and shares', an SMB null-session control. Get-LDAPConfiguration raises
        # this card from dsHeuristics character 7 alone, and no GPO setting governs that.
        Title = "Anonymous LDAP Operations Allowed"
        Risk = "Finding"
        BaseScore = 30
        Description = "Character 7 of dsHeuristics (fLDAPBlockAnonOps) is 2 on CN=Directory Service in the configuration partition, so every domain controller of the forest lets an anonymous client do more than bind and read rootDSE: it can search the directory and read whatever the ACLs grant ANONYMOUS LOGON. Out of the box that is little. ANONYMOUS LOGON in Pre-Windows 2000 Compatible Access, an ACE for ANONYMOUS LOGON, or 'Network access: Let Everyone permissions apply to anonymous users' turns it into users, groups and their attributes for anyone who reaches port 389. No GPO setting governs this - the attribute is the only place it is configured."
        Impact = @(
            "Unauthenticated reading of whatever the ACLs grant ANONYMOUS LOGON - with Pre-Windows 2000 Compatible Access holding it, users, groups and their attributes"
            "Account names for password spraying and the group structure for choosing targets, without a domain account"
            "The setting is forest-wide: it applies on every domain controller of every domain"
        )
        Attack = @(
            "1. Attacker reaches a domain controller on port 389 without credentials"
            "2. Binds anonymously and searches the domain partition"
            "3. Collects users, groups and descriptions as far as the ACLs let ANONYMOUS LOGON read"
            "4. Uses the account list for password spraying or targeted attacks"
        )
        Remediation = @(
            "Set character 7 of dsHeuristics back to 0 and keep every other character as it is"
            "Find the application that needed anonymous LDAP first - the setting is off by default, so somebody turned it on"
            "Remove ANONYMOUS LOGON and Everyone from Pre-Windows 2000 Compatible Access where nothing depends on them"
        )
        RemediationCommands = @(
            @{
                Description = "Show the current dsHeuristics value (character 7 is fLDAPBlockAnonOps)"
                Command = "Get-ADObject 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com' -Properties dsHeuristics | Select-Object dsHeuristics"
            }
            @{
                Description = "Set character 7 back to 0, leaving every other character as it is"
                Command = "`$dn = 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com'; `$current = (Get-ADObject `$dn -Properties dsHeuristics).dsHeuristics; if (`$current.Length -ge 7) { `$new = `$current.Substring(0,6) + '0' + `$current.Substring(7); Set-ADObject `$dn -Replace @{dsHeuristics=`$new} }"
            }
            @{
                Description = "Test anonymous LDAP access (should fail after the change)"
                Command = "# From non-domain-joined system: ldapsearch -x -h dc01.domain.com -b 'DC=domain,DC=com' '(objectClass=user)' sAMAccountName"
            }
        )
        References = @(
            @{ Title = "Anonymous LDAP Operations"; Url = "https://docs.microsoft.com/en-us/troubleshoot/windows-server/identity/anonymous-ldap-operations-active-directory-disabled" }
            @{ Title = "dSHeuristics - MS-ADTS 6.1.1.2.4.1.2"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/e5899be4-862e-496f-9a38-33950617d2c5" }
        )
        Tools = @("ldapsearch", "windapsearch", "ldapdomaindump")
        MITRE = "T1087"
        Triggers = @(
            # Pattern, not a bare attribute match. Without it this trigger claimed every
            # value of anonymousLDAPAccess including "Restricted", which made the Secure
            # counterpart below dead code - Get-TriggerMatch had no way to prefer it.
            #
            # The AnonymousBinding triggers that used to sit here are gone with the
            # attribute: RestrictAnonymous and LSAAnonymousNameLookup are SMB null-session
            # controls, not LDAP, and this definition's own remediation always said the
            # LDAP answer lives in dsHeuristics. Get-LDAPConfiguration reads it now.
            #
            # Anchored: both producers start the value with ENABLED, and "Not tested"
            # carries the reason the test did not run - matched without case, a reason
            # that said "enabled" would have turned that row red.
            @{ Attribute = 'anonymousLDAPAccess'; Pattern = '^ENABLED'; Severity = 'Finding' }
        )
    }

    # The other characters of dsHeuristics that switch a protection off, read by
    # Get-LDAPConfiguration through ConvertFrom-DSHeuristics (MS-ADTS 6.1.1.2.4.1.2).
    'DSHEURISTICS_ANONYMOUS_NSPI' = @{
        Title = "Anonymous NSPI Access Allowed"
        Risk = "Finding"
        BaseScore = 30
        Description = "Character 8 of dsHeuristics (fAllowAnonNSPI) is not 0 on CN=Directory Service in the configuration partition, so every domain controller of the forest accepts anonymous calls to the bind method of NSPI, the Name Service Provider Interface - the address book protocol over RPC that Outlook and Exchange use to browse the directory. Otherwise only authenticated clients may bind. An unauthenticated client can then read the address book as far as the directory lets an anonymous caller; in an organization with Exchange that is the global address list. The heuristic is off by default."
        Impact = @(
            "Unauthenticated reading of the address book - with Exchange, the names and mail addresses of the organization"
            "Account names for password spraying and phishing, without a domain account"
            "The setting is forest-wide: it applies on every domain controller of every domain"
        )
        Attack = @(
            "1. Attacker reaches the RPC endpoint of a domain controller without credentials"
            "2. Binds to the NSPI interface anonymously"
            "3. Reads the address book entries the directory shows an anonymous caller"
            "4. Uses the names and addresses for password spraying or phishing"
        )
        Remediation = @(
            "Set character 8 of dsHeuristics back to 0 and keep every other character as it is"
            "Find the client that needed anonymous NSPI first - the setting is off by default, so somebody turned it on"
        )
        RemediationCommands = @(
            @{
                Description = "Show the current dsHeuristics value (character 8 is fAllowAnonNSPI)"
                Command = "Get-ADObject 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com' -Properties dsHeuristics | Select-Object dsHeuristics"
            }
            @{
                Description = "Set character 8 back to 0, leaving every other character as it is"
                Command = "`$dn = 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com'; `$current = (Get-ADObject `$dn -Properties dsHeuristics).dsHeuristics; if (`$current.Length -ge 8) { `$new = `$current.Substring(0,7) + '0' + `$current.Substring(8); Set-ADObject `$dn -Replace @{dsHeuristics=`$new} }"
            }
        )
        References = @(
            @{ Title = "dSHeuristics - MS-ADTS 6.1.1.2.4.1.2"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/e5899be4-862e-496f-9a38-33950617d2c5" }
        )
        Tools = @()
        MITRE = "T1087.002"
        Triggers = @(
            @{ Attribute = 'anonymousNSPIAccess'; Pattern = '^ENABLED'; Severity = 'Finding' }
        )
    }

    'DSHEURISTICS_ADMINSDHOLDER_EXCLUSION' = @{
        Title = "Operator Groups Excluded from AdminSDHolder Protection"
        Risk = "Finding"
        BaseScore = 40
        Description = "Character 16 of dsHeuristics (dwAdminSDExMask) takes operator groups out of AdminSDHolder protection - bit 0x1 Account Operators, 0x2 Server Operators, 0x4 Print Operators, 0x8 Backup Operators. In every domain of the forest SDProp then no longer resets the security descriptor of these groups, nor of the accounts and groups that are their members directly or through nesting, unless another protected group covers them as well: a right somebody grants on them stays, and so does one they inherit once inheritance is switched back on. The exclusion exists so that such members can be managed by delegation, and that is the risk - the groups are privileged in all but name. Backup Operators back up and restore files on the domain controllers, the directory database included; Print Operators load drivers on them; Server Operators log on to them and manage their services; Account Operators manage most accounts and groups of the domain. Whoever may change such a group or take over one of its members gets what the group can do."
        Impact = @(
            "A right granted on an excluded group or on one of its members is no longer removed within the hour"
            "Delegated permissions on an OU reach the members once their inheritance is switched back on"
            "The operator groups lead to the domain controllers: the directory database, drivers, services"
        )
        Attack = @(
            "1. Attacker controls an account with a delegated right over a member of an excluded group - the helpdesk delegation the exclusion is usually set for"
            "2. Resets the member's password or adds an account to the group; SDProp no longer removes the right that allowed it"
            "3. Uses the group's rights on a domain controller, e.g. backs up the directory database as a member of Backup Operators"
        )
        Remediation = @(
            "Set character 16 of dsHeuristics back to 0 and keep every other character as it is; SDProp protects the groups and their members again at its next run"
            "Better still, empty the operator groups and delegate through dedicated groups that hold only the rights the task needs"
            "Review the rights already granted on the groups and their members while they were excluded - SDProp overwrites the DACL of a protected object, but the rights may already have been used"
        )
        RemediationCommands = @(
            @{
                Description = "Show the current dsHeuristics value (character 16 is dwAdminSDExMask)"
                Command = "Get-ADObject 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com' -Properties dsHeuristics | Select-Object dsHeuristics"
            }
            @{
                Description = "Set character 16 back to 0, leaving every other character as it is"
                Command = "`$dn = 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com'; `$current = (Get-ADObject `$dn -Properties dsHeuristics).dsHeuristics; if (`$current.Length -ge 16) { `$new = `$current.Substring(0,15) + '0' + `$current.Substring(16); Set-ADObject `$dn -Replace @{dsHeuristics=`$new} }"
            }
            @{
                Description = "List the members of the four operator groups, by SID so a localized domain works too"
                Command = "foreach (`$sid in 'S-1-5-32-548','S-1-5-32-549','S-1-5-32-550','S-1-5-32-551') { Get-ADGroupMember -Identity `$sid -Recursive | Select-Object @{n='Group';e={`$sid}}, SamAccountName, objectClass }"
            }
        )
        References = @(
            @{ Title = "AdminSDHolder configurable state (dwAdminSDExMask) - MS-ADTS 3.1.1.6.1.4"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/50097362-ede5-40fa-973e-8d65e782e384" }
            @{ Title = "Appendix C: Protected Accounts and Groups in Active Directory"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-c--protected-accounts-and-groups-in-active-directory" }
        )
        Tools = @()
        MITRE = "T1098"
        Triggers = @(
            @{ Attribute = 'adminSDHolderExclusion'; Pattern = ' - not protected by AdminSDHolder$'; Severity = 'Finding' }
        )
    }

    'DSHEURISTICS_UNIQUENESS_DISABLED' = @{
        Title = "UPN or SPN Uniqueness Checks Switched Off"
        Risk = "Finding"
        BaseScore = 35
        Description = "Character 21 of dsHeuristics (DoNotVerifyUPNAndOrSPNUniqueness) switches off checks the domain controllers make on every write since Windows Server 2012 R2: bit 0 the uniqueness of userPrincipalName, bit 1 of servicePrincipalName, bit 2 of SPN aliases - an SPN such as cifs/server that the HOST/server of another account already stands for. Two accounts can then hold the same name. With the alias check off, a principal that may write the SPNs of an account can claim cifs/, http/ or another service of a server for it, and Kerberos then issues the tickets for that service to the account the attacker controls, which can pose as the server (KB5008382, CVE-2021-42282). A duplicate UPN or SPN makes logons and service tickets for the name fail or depend on which account a lookup finds. Microsoft added the switch for migration tools and recommends setting it back once the migration is done."
        Impact = @(
            "Two accounts can hold the same UPN or SPN, so the name no longer identifies one account"
            "With the SPN alias check off, a service of a server can be claimed for another account, which then poses as that server to Kerberos clients"
            "Logons and service tickets for a duplicated name fail or reach the wrong account"
            "The setting is forest-wide: it applies on every domain controller of every domain"
        )
        Attack = @(
            "1. Attacker controls an account that may write the UPN or the SPNs of some account - through a delegation, or GenericWrite on a computer"
            "2. Writes a name another account already holds, or an alias such as cifs/server beside that server's HOST/server; the domain controller accepts it"
            "3. With an alias, clients of the service get tickets for the attacker's account, whose machine then poses as the server; with a duplicate, logons and tickets for the name fail"
        )
        Remediation = @(
            "Set character 21 of dsHeuristics back to 0 and keep every other character as it is"
            "The switch exists for migration tools - set it back once the migration is done"
            "The checks apply to new writes only: find the duplicates created while they were off and remove them"
        )
        RemediationCommands = @(
            @{
                Description = "Show the current dsHeuristics value (character 21 is DoNotVerifyUPNAndOrSPNUniqueness)"
                Command = "Get-ADObject 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com' -Properties dsHeuristics | Select-Object dsHeuristics"
            }
            @{
                Description = "Set character 21 back to 0, leaving every other character as it is"
                Command = "`$dn = 'CN=Directory Service,CN=Windows NT,CN=Services,CN=Configuration,DC=domain,DC=com'; `$current = (Get-ADObject `$dn -Properties dsHeuristics).dsHeuristics; if (`$current.Length -ge 21) { `$new = `$current.Substring(0,20) + '0' + `$current.Substring(21); Set-ADObject `$dn -Replace @{dsHeuristics=`$new} }"
            }
            @{
                Description = "List duplicate SPNs in the forest"
                Command = "setspn -X -F"
            }
            @{
                Description = "List UPNs that more than one account holds"
                Command = "Get-ADObject -LDAPFilter '(userPrincipalName=*)' -Properties userPrincipalName | Group-Object userPrincipalName | Where-Object { `$_.Count -gt 1 } | Select-Object Name, Count"
            }
        )
        References = @(
            @{ Title = "dSHeuristics - MS-ADTS 6.1.1.2.4.1.2"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/e5899be4-862e-496f-9a38-33950617d2c5" }
            @{ Title = "SPN and UPN uniqueness - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/dn535779(v=ws.11)" }
            @{ Title = "KB5008382 - Verification of uniqueness for UPN, SPN and the SPN alias (CVE-2021-42282)"; Url = "https://support.microsoft.com/topic/4651b175-290c-4e59-8fcb-e4e5cd0cdb29" }
        )
        Tools = @("setspn")
        MITRE = "T1557"
        Triggers = @(
            @{ Attribute = 'principalNameUniqueness'; Pattern = '^Not checked: '; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # SID HISTORY FINDINGS
    # ============================================================================

    'SID_HISTORY_INJECTION' = @{
        Title = "Privileged SID of This Domain in SID History"
        Risk = "Finding"
        BaseScore = 80
        Description = "This account carries a privileged SID of this very domain in sIDHistory. sIDHistory exists to hold the SID an account had in a *source* domain, so no migration can produce an entry from the domain the object already lives in - somebody wrote it. The account is granted everything that SID is granted, with no group membership to show it."
        Impact = @(
            "Account may have hidden privileged access through historical SIDs"
            "Access is granted based on SID History without group membership visibility"
            "Attackers can inject Domain Admin SIDs for persistent access"
            "Very difficult to detect without specifically checking SID History"
            "Survives password resets and most remediation attempts"
        )
        Attack = @(
            "1. Attacker gains write access to an account's SID History"
            "2. Injects Domain Admin SID (RID 512) into SID History"
            "3. Account now has Domain Admin access without visible group membership"
            "4. Standard 'net group' and 'Get-ADGroupMember' won't show the access"
            "5. Attacker maintains access even after initial compromise is remediated"
        )
        Remediation = @(
            "Audit all accounts with SID History entries"
            "Remove SID History after migration is complete"
            "Use 'Get-ADUser -Properties SIDHistory' to identify affected accounts"
            "Enable SID Filtering on trusts to block SID History injection"
            "Monitor for SID History modifications (Event ID 4765, 4766)"
        )
        RemediationCommands = @(
            @{
                Description = "Find all users with SID History"
                Command = "Get-ADUser -Filter {SIDHistory -like '*'} -Properties SIDHistory,SamAccountName | Select-Object SamAccountName,@{Name='SIDHistory';Expression={`$_.SIDHistory -join '; '}}"
            }
            @{
                Description = "Remove all SID History entries from a specific user"
                Command = "Get-ADUser 'USERNAME' -Properties SIDHistory | ForEach-Object { Set-ADUser `$_ -Remove @{SIDHistory=`$_.SIDHistory.Value} }"
            }
            @{
                Description = "Remove SID History from all users in a specific OU"
                Command = "Get-ADUser -SearchBase 'OU=MigratedUsers,DC=domain,DC=com' -Filter {SIDHistory -like '*'} -Properties SIDHistory | ForEach-Object { Set-ADUser `$_ -Remove @{SIDHistory=`$_.SIDHistory.Value} }"
            }
            @{
                Description = "Enable SID Filtering on a trust to block SID History injection (quarantine trust)"
                Command = "netdom trust TRUSTINGDOMAIN /domain:TRUSTEDDOMAIN /quarantine:yes"
            }
        )
        References = @(
            @{ Title = "SID History Injection - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1134/005/" }
            @{ Title = "Accounts security posture assessment - unsecure SID History"; Url = "https://learn.microsoft.com/en-us/defender-for-identity/security-assessment-unsecure-sid-history-attribute" }
            @{ Title = "SID History Attack"; Url = "https://adsecurity.org/?p=1772" }
            @{ Title = "SID Filtering and SID History - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-cleanup" }
        )
        Tools = @("Mimikatz", "DSInternals", "PowerView")
        MITRE = "T1134.005"
        Triggers = @(
            # The raw attribute colours its row and names no card. Which card an entry
            # deserves depends on where the SID comes from, and the row cannot tell: only
            # the check compares against the domain SID. Before, a pattern-less trigger
            # here gave every sIDHistory value this card - so a migration artifact was
            # rendered yellow and pointed at the 80-point injection write-up, remediation
            # included.
            #
            # Two triggers, each the inverse of the other, so the colour does not depend on
            # which one the index holds first.
            @{ Attribute = 'sIDHistory'; Custom = 'is_local_privileged_sid_history'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'sIDHistory'; Custom = 'is_not_local_privileged_sid_history'; Severity = 'Hint'; SeverityOnly = $true }

            # What the check writes once it has sorted the entry by source domain. These
            # name the card.
            @{ Attribute = 'privilegedSIDHistory'; Severity = 'Finding' }
            @{ Attribute = 'sidHistoryNotFromSourceDomain'; Severity = 'Finding' }
        )
    }

    'SID_HISTORY_OWN_DOMAIN' = @{
        Title = "SID of This Domain in SID History"
        Risk = "Finding"
        BaseScore = 60
        Description = "This account carries a SID of this very domain in sIDHistory. The RID is not one of the well-known privileged ones, which is why it is scored below an outright injection - but sIDHistory holds the SID an account had in a source domain, so an entry from the local domain cannot be a migration artifact. The account it points at may be unprivileged by group membership and still hold exactly the access somebody wanted: a DCSync ACE, write access to a GPO, a wide share."
        Impact = @(
            "The account is granted whatever the referenced local account or group is granted"
            "Nothing in the group memberships of either object shows the relationship"
            "An unprivileged target is not a harmless target - delegated ACEs and share permissions do not appear in any group"
            "No migration produces this, so the entry was written deliberately"
        )
        Attack = @(
            "1. Attacker gains write access to an account's sIDHistory"
            "2. Writes the SID of a local account or group that holds a delegated right"
            "3. The account now holds that right, with no group membership to audit"
            "4. The access survives password resets and group clean-ups"
        )
        Remediation = @(
            "Establish what the referenced SID is granted before removing anything - that is the access to review"
            "Remove the sIDHistory entry; nothing in this domain needs it"
            "Check who can write sIDHistory on this object"
            "Monitor for sIDHistory modifications (Event ID 4765, 4766)"
        )
        RemediationCommands = @(
            @{
                Description = "Show the SID History entries of this account"
                Command = "Get-ADUser 'USERNAME' -Properties SIDHistory | Select-Object -ExpandProperty SIDHistory"
            }
            @{
                Description = "Resolve the referenced SID to see what it is"
                Command = "(New-Object System.Security.Principal.SecurityIdentifier('SID')).Translate([System.Security.Principal.NTAccount])"
            }
            @{
                Description = "Remove all SID History entries from this account"
                Command = "Get-ADUser 'USERNAME' -Properties SIDHistory | ForEach-Object { Set-ADUser `$_ -Remove @{SIDHistory=`$_.SIDHistory.Value} }"
            }
        )
        References = @(
            @{ Title = "SID History Injection - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1134/005/" }
            @{ Title = "Unsecure SID History attribute"; Url = "https://learn.microsoft.com/en-us/defender-for-identity/security-assessment-unsecure-sid-history-attribute" }
        )
        Tools = @("DSInternals", "PowerView")
        MITRE = "T1134.005"
        Triggers = @(
            @{ Attribute = 'sidHistoryOwnDomain'; Severity = 'Finding' }
            @{ Attribute = 'ownDomainSIDHistory'; Severity = 'Finding' }
        )
    }

    'SID_HISTORY_FOREIGN_PRIVILEGED' = @{
        Title = "Privileged SID of Another Domain in SID History"
        Risk = "Hint"
        BaseScore = 35
        Description = "This account carries a privileged SID of another domain in sIDHistory. That is the documented result of a domain migration: ADMT writes the source SID of every account it moves, so every migrated administrator ends up with the -512 of the domain they came from. It is also how cross-forest SID history injection presents, and the two look identical in the directory. What separates them is whether SID filtering is enforced on the trust, and whether the source domain still exists."
        Impact = @(
            "If SID filtering is not enforced on the trust, the SID is honoured and grants privileged access from the other domain"
            "If the source domain is gone, the SID still lands in the token at every logon here and is honoured by every ACL that names it - sidHistorySource says whether a trust or the forest still leads to it"
            "A reader who cannot tell a migration leftover from an injection cannot act on either"
        )
        Attack = @(
            "1. Attacker controls, or compromises, a domain on the far side of a trust without SID filtering"
            "2. Writes a privileged SID of the target domain into an account's sIDHistory"
            "3. Authenticates across the trust; the SID is honoured and lands in the token"
            "4. The access is indistinguishable from an ordinary migration record"
        )
        Remediation = @(
            "Check whether SID filtering is enforced on the trust this SID comes from - adPEAS reports that in the Domain Trusts section"
            "Establish whether the source domain still exists; if it does not, the entry is clutter and can go"
            "Remove sIDHistory once the migration it belongs to is complete - it is meant to be temporary"
            "Monitor for sIDHistory modifications (Event ID 4765, 4766)"
        )
        RemediationCommands = @(
            @{
                Description = "Show the SID filtering state of every trust"
                Command = "Get-ADTrust -Filter * | Select-Object Name,Direction,SIDFilteringQuarantined,SIDFilteringForestAware"
            }
            @{
                Description = "Enforce SID filtering on an external trust"
                Command = "netdom trust TRUSTINGDOMAIN /domain:TRUSTEDDOMAIN /quarantine:yes"
            }
            @{
                Description = "Remove all SID History entries from this account once the migration is complete"
                Command = "Get-ADUser 'USERNAME' -Properties SIDHistory | ForEach-Object { Set-ADUser `$_ -Remove @{SIDHistory=`$_.SIDHistory.Value} }"
            }
        )
        References = @(
            @{ Title = "SID filtering and SID history"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-cleanup" }
            @{ Title = "SID History Injection - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1134/005/" }
        )
        Tools = @("DSInternals", "PowerView")
        MITRE = "T1134.005"
        Triggers = @(
            @{ Attribute = 'sidHistoryForeignPrivileged'; Severity = 'Hint' }
            @{ Attribute = 'foreignPrivilegedSIDHistory'; Severity = 'Hint' }
        )
    }

    'SID_HISTORY_ORPHANED' = @{
        Title = "SID History From a Domain Neither Trusted Nor in the Forest"
        Risk = "Hint"
        BaseScore = 15
        Description = "sIDHistory of these accounts names a domain that is neither a domain of this forest nor trusted by this domain - the source of a migration that ended with the domain decommissioned or the trust removed. sIDHistory exists to bridge a migration, so the entries are leftovers. They are not inert: a SID in sIDHistory goes into the account's token at every logon in this domain and is honoured by every ACL that names it - on file servers migrated with their old permissions, for instance - while nothing in the directory says any more what it was or who else holds it."
        Impact = @(
            "Access granted to the old domain's SIDs still works for these accounts wherever an ACL names them"
            "Nobody can tell from the directory what the SIDs grant, so the access is never reviewed"
            "Entries that should be gone hide a deliberately written one among them"
        )
        Remediation = @(
            "Re-permission the resources that still name the old SIDs with groups of this domain, then remove sIDHistory from the accounts"
            "Remove sIDHistory once the migration it belongs to is complete - it is meant to be temporary"
            "Monitor for sIDHistory changes (Event ID 4765, 4766)"
        )
        RemediationCommands = @(
            @{
                Description = "List the accounts that carry sIDHistory from one source domain (replace the domain SID)"
                Command = "Get-ADObject -LDAPFilter '(sIDHistory=*)' -Properties sIDHistory | Where-Object { `$_.sIDHistory.Value -like 'S-1-5-21-1111111111-2222222222-3333333333-*' } | Select-Object Name, sIDHistory"
            }
            @{
                Description = "Remove all SID History entries from an account once its resources no longer need them"
                Command = "Get-ADUser 'USERNAME' -Properties SIDHistory | ForEach-Object { Set-ADUser `$_ -Remove @{SIDHistory=`$_.SIDHistory.Value} }"
            }
        )
        References = @(
            @{ Title = "SID History Injection - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1134/005/" }
        )
        Tools = @("PowerView")
        MITRE = "T1134.005"
        Triggers = @(
            @{ Attribute = 'sidHistorySource'; Pattern = ' - neither a domain of this forest nor trusted by this domain$'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # GPO SECURITY FINDINGS
    # ============================================================================

    'GPO_DANGEROUS_PERMISSIONS' = @{
        Title = "Dangerous GPO Permissions"
        Risk = "Finding"
        BaseScore = 50
        Description = "This Group Policy Object has dangerous permissions that allow non-privileged users to modify it. GPO modifications can be used to execute code, deploy malware, or change security settings on all computers where the GPO is linked."
        Impact = @(
            "Attacker can modify GPO to execute code on target computers"
            "Can deploy scheduled tasks, startup scripts, or registry modifications"
            "Affects all computers and users in the GPO's scope"
            "Changes propagate automatically during Group Policy refresh"
            "Can be used to compromise Domain Controllers if linked at domain level"
        )
        Attack = @(
            "1. Attacker identifies GPO with write permissions"
            "2. Modifies GPO to add malicious scheduled task or startup script"
            "3. Waits for Group Policy refresh (or forces via gpupdate)"
            "4. Malicious code executes on all affected computers"
            "5. If targeting DCs, achieves domain compromise"
        )
        Remediation = @(
            "Remove unnecessary write permissions from GPOs"
            "An inherited ACE does not go away here: it has to be removed where it is written, usually on CN=Policies,CN=System, or inheritance has to be broken on the GPO. Set-GPPermission and the GPMC delegation tab cannot touch an inherited entry at all, so check the row for whether the grant is inherited before acting on it"
            "Set-GPPermission does not change the owner either. A trustee that owns the GPO can re-grant itself everything that was just removed, so an owner outside the administrative tier is its own task: Set-Acl on the AD object, or dsacls with /takeownership"
            "Only Domain Admins and specific GPO management groups should have write access"
            "Use GPO delegation carefully - prefer read-only access"
            "Monitor GPO modifications (Event ID 5136) - that event covers the directory object. The attack path here is the policy content in SYSVOL, and a change to those files raises no 5136: it needs file system auditing (4663) on the SYSVOL policy folder"
            "Implement GPO change management process"
        )
        RemediationCommands = @(
            @{
                Description = "View current GPO permissions"
                Command = "Get-GPPermission -Name 'GPO_NAME' -All | Format-Table Trustee,Permission,Inherited -AutoSize"
            }
            @{
                Description = "Remove all permissions for a specific user/group from a GPO (set to None)"
                Command = "Set-GPPermission -Name 'GPO_NAME' -PermissionLevel None -TargetName 'DOMAIN\User' -TargetType User -Replace"
            }
            @{
                Description = "Grant read-only access instead of write access to a GPO"
                Command = "Set-GPPermission -Name 'GPO_NAME' -PermissionLevel GpoRead -TargetName 'DOMAIN\Group' -TargetType Group -Replace"
            }
            @{
                Description = "Find all GPOs with write permissions for a specific principal"
                Command = "Get-GPO -All | ForEach-Object { `$perms = Get-GPPermission -Guid `$_.Id -All | Where-Object { `$_.Trustee.Name -eq 'USERNAME' -and `$_.Permission -match 'Edit|Write' }; if (`$perms) { [PSCustomObject]@{GPOName=`$_.DisplayName; Permission=`$perms.Permission} } }"
            }
        )
        References = @(
            @{ Title = "GPO Abuse - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1484/001/" }
            @{ Title = "Set-GPPermission cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/set-gppermission" }
            @{ Title = "Get-GPPermission cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/get-gppermission" }
            @{ Title = "GPO Abuse - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/acl-persistence-abuse/README.html#gpo-abuse" }
        )
        Tools = @("BloodHound", "PowerView", "SharpGPOAbuse")
        MITRE = "T1484.001"
        Triggers = @(
            @{ Attribute = 'DangerousSettings'; Severity = 'Finding' }
        )
    }

    'GPO_SCOPE_DOMAIN_WIDE' = @{
        Title = "GPO Linked at Domain Root (Domain-Wide Scope)"
        Risk = "Finding"
        BaseScore = 40
        Description = "This Group Policy Object is linked directly at the domain root. This means it applies to ALL computers and users in the domain, making any misconfiguration or vulnerability a domain-wide issue."
        Impact = @(
            "Every computer in the domain processes this GPO during Group Policy refresh"
            "Every user logging on to any domain computer is affected"
            "Malicious modifications impact the entire domain simultaneously"
            "Domain Controllers are also affected (highest security impact)"
            "Scope amplifies any other finding on this GPO to critical severity"
        )
        Attack = @(
            "1. Attacker identifies a domain-wide GPO with weak permissions"
            "2. Modifies GPO to deploy a scheduled task or startup script"
            "3. Within 90 minutes (default refresh), ALL domain computers execute the payload"
            "4. Includes Domain Controllers - immediate domain compromise"
        )
        Remediation = @(
            "Minimize the number of GPOs linked at domain root"
            "Ensure strict permissions on domain-wide GPOs (only Domain Admins)"
            "Use OU-level GPO linking for more granular control"
            "Narrow the scope with security filtering - and leave Domain Computers a read, which MS16-072 made a precondition for user policies"
            "A WMI filter is a different mechanism from security filtering: it is evaluated on the client at every refresh and costs time there, and it does not take the read away from anybody"
            "Monitor GPO link changes at domain level (Event ID 5136)"
        )
        RemediationCommands = @(
            @{
                Description = "List all GPOs linked at domain root"
                Command = "Get-ADDomain | Select-Object -ExpandProperty LinkedGroupPolicyObjects | ForEach-Object { Get-GPO -Guid (`$_ -replace '.*\{|\}.*') } | Select-Object DisplayName,Id,GpoStatus"
            }
            @{
                Description = "Unlink a GPO from the domain root"
                Command = "Remove-GPLink -Name 'GPO_NAME' -Target (Get-ADDomain).DistinguishedName"
            }
            @{
                Description = "Link a GPO to a specific OU instead of domain root"
                Command = "New-GPLink -Name 'GPO_NAME' -Target 'OU=Workstations,DC=domain,DC=com' -LinkEnabled Yes"
            }
            @{
                Description = "Apply security filtering to limit GPO scope - Domain Computers keeps read, which MS16-072 made a precondition"
                Command = @'
# Since MS16-072 / KB3163622 group policy is retrieved in the security context of the
# COMPUTER account, user policies included. Removing Authenticated Users without leaving
# a computer-side read behind stops the GPO applying to users altogether - and the outage
# does not look like a permission problem. Microsoft's own MS16-072 guidance is this
# extra step, so it comes first here.
Set-GPPermission -Name 'GPO_NAME' -TargetName 'Domain Computers' -TargetType Group -PermissionLevel GpoRead

# Only then narrow the scope. GpoApply on a user group alone is not enough for a user
# policy; the computers that the users log on to need the read above.
Set-GPPermission -Name 'GPO_NAME' -TargetName 'DOMAIN\SpecificGroup' -TargetType Group -PermissionLevel GpoApply
Set-GPPermission -Name 'GPO_NAME' -TargetName 'Authenticated Users' -TargetType Group -PermissionLevel None -Replace
'@
            }
        )
        References = @(
            @{ Title = "GPO Abuse - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1484/001/" }
            @{ Title = "Remove-GPLink cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/remove-gplink" }
            @{ Title = "New-GPLink cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/new-gplink" }
            @{ Title = "Group Policy Security - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-overview" }
        )
        Tools = @("BloodHound", "PowerView", "SharpGPOAbuse")
        MITRE = "T1484.001"
        Triggers = @(
            # The domain-root link is what makes a dangerous GPO reach every machine. It
            # used to be matched on the Scope attribute's "Domain-wide" as well; that
            # attribute is gone, and the link itself says it.
            @{ Attribute = 'LinkedOUs'; Pattern = '^DC=[^,]+,DC='; Custom = 'is_gpo_finding_object'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # LAPS FINDINGS
    # ============================================================================

    'LAPS_NOT_DEPLOYED' = @{
        Title = "LAPS Not Deployed"
        Risk = "Finding"
        BaseScore = 35
        Description = "Local Administrator Password Solution (LAPS) is not deployed on this computer. Without LAPS, local administrator passwords are likely the same across multiple systems, enabling lateral movement if one password is compromised."
        Impact = @(
            "Local admin passwords may be identical across systems"
            "Compromising one system's local admin enables lateral movement"
            "No automatic password rotation for local accounts"
            "Pass-the-Hash attacks are highly effective"
            "Violates security best practices and compliance requirements"
        )
        Attack = @(
            "1. Attacker compromises one workstation and extracts local admin hash"
            "2. Uses hash to authenticate to other workstations (Pass-the-Hash)"
            "3. Moves laterally across the network"
            "4. Eventually reaches high-value targets"
        )
        Remediation = @(
            "Deploy Windows LAPS (built into Windows 11 22H2+ and Server 2019+)"
            "Or deploy legacy Microsoft LAPS for older systems"
            "Configure LAPS via GPO for password complexity and rotation"
            "Restrict LAPS password read access to appropriate administrators"
            "Enable LAPS password encryption for enhanced security"
        )
        RemediationCommands = @(
            @{
                Description = "Update Active Directory schema to support Windows LAPS (one-time forest-wide operation)"
                Command = "Update-LapsADSchema"
            }
            @{
                Description = "Grant computer objects permission to update their LAPS passwords in a specific OU"
                Command = "Set-LapsADComputerSelfPermission -Identity 'OU=Workstations,DC=domain,DC=com'"
            }
            @{
                Description = "Enable LAPS via Group Policy (Computer Configuration -> Policies -> Administrative Templates -> System -> LAPS)"
                Command = "# Set 'Enable password backup' to Enabled in GPO, then configure password complexity, length, and maximum age settings"
            }
            @{
                Description = "Verify LAPS deployment status for all computers in an OU"
                Command = "Get-ADComputer -Filter * -SearchBase 'OU=Workstations,DC=domain,DC=com' -Properties ms-Mcs-AdmPwdExpirationTime | Select-Object Name,DNSHostName,ms-Mcs-AdmPwdExpirationTime"
            }
        )
        References = @(
            @{ Title = "Windows LAPS Overview"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview" }
            @{ Title = "Get started with Windows LAPS and Windows Server Active Directory"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-scenarios-windows-server-active-directory" }
            @{ Title = "Set-LapsADComputerSelfPermission cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/laps/set-lapsadcomputerselfpermission" }
            @{ Title = "Configure Policy Settings for Windows LAPS"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings" }
            @{ Title = "LAPS - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/laps.html" }
        )
        Tools = @("LAPSToolkit", "PowerView")
        MITRE = "T1078.003"
        Triggers = @(
            @{ Attribute = 'affectedComputers'; Severity = 'Finding' }
        )
    }

    'LAPS_PASSWORD_READABLE' = @{
        Title = "LAPS Password Readable"
        Risk = "Finding"
        BaseScore = 55
        Description = "The current user can read the LAPS password for this computer. While this may be intentional for IT administrators, unexpected read access could enable privilege escalation or lateral movement."
        Impact = @(
            "LAPS password provides local administrator access to the computer"
            "If attacker can read password, they can fully compromise the system"
            "Local admin access enables credential harvesting (Mimikatz)"
            "Can be used as stepping stone for lateral movement"
        )
        Attack = @(
            "1. Attacker identifies computers where they can read LAPS password"
            "2. Reads ms-Mcs-AdmPwd or msLAPS-Password attribute"
            "3. Uses password to gain local admin access"
            "4. Dumps credentials from memory for further attacks"
        )
        Remediation = @(
            "Review LAPS password read permissions"
            "Use tiered administration - only Tier 0 admins read DC LAPS passwords"
            "Enable LAPS password encryption (Windows LAPS)"
            "Audit LAPS password reads (Event ID 4662)"
            "Use Just-In-Time access for LAPS password retrieval"
        )
        RemediationCommands = @(
            @{
                Description = "Grant specific group permission to read LAPS passwords for computers in an OU"
                Command = "Set-LapsADReadPasswordPermission -Identity 'OU=Workstations,DC=domain,DC=com' -AllowedPrincipals 'DOMAIN\IT-Admins'"
            }
            @{
                Description = "View current LAPS password read permissions on an OU using Active Directory ACL"
                Command = "(Get-Acl 'AD:\OU=Workstations,DC=domain,DC=com').Access | Where-Object {`$_.ObjectType -eq 'ms-Mcs-AdmPwd' -or `$_.ObjectType -eq 'msLAPS-Password'} | Select-Object IdentityReference,ActiveDirectoryRights,AccessControlType"
            }
            @{
                Description = "Enable auditing for LAPS password reads (requires legacy LAPS PowerShell module for Set-AdmPwdAuditing)"
                Command = "Import-Module AdmPwd.PS; Set-AdmPwdAuditing -OrgUnit 'OU=Workstations,DC=domain,DC=com' -AuditedPrincipals 'DOMAIN\IT-Admins'"
            }
            @{
                Description = "Query who has read access to LAPS passwords in a specific OU"
                Command = "Find-AdmPwdExtendedRights -Identity 'OU=Workstations,DC=domain,DC=com' | Select-Object ExtendedRightHolders"
            }
        )
        References = @(
            @{ Title = "Windows LAPS Security"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-concepts-overview" }
            @{ Title = "Set-LapsADReadPasswordPermission cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/laps/set-lapsadreadpasswordpermission" }
            @{ Title = "Auditing Access to LAPS Passwords"; Url = "https://petri.com/auditing-access-to-laps-passwords-in-active-directory/" }
            @{ Title = "LAPS - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/laps.html" }
        )
        Tools = @("LAPSToolkit", "PowerView")
        MITRE = "T1552.004"
        Triggers = @(
            # The two attributes that ARE the password. The encrypted one is deliberately
            # not here: Get-LAPSCredentialAccess decrypts where it can, and on success it
            # replaces msLAPS-EncryptedPassword on the object with msLAPS-Password - so a
            # row that still carries the blob is the case where decryption did not happen.
            # This card calls that "the current user can read the LAPS password for this
            # computer", with "they can fully compromise the system" under Impact, for a
            # blob the holder cannot open. LAPS_ENCRYPTED_PASSWORD says what it is.
            @{ Attribute = 'ms-Mcs-AdmPwd'; Severity = 'Finding' }
            @{ Attribute = 'msLAPS-Password'; Severity = 'Finding' }

            # Read access that the account was given on purpose. Get-LAPSCredentialAccess
            # puts lapsReadContext on the row when the bound principal is privileged, and
            # then every LAPS-managed machine in the domain is readable by design - a red
            # row each would be 2000 findings that say nothing. SeverityOnly: the card
            # still explains what a readable LAPS password is, it just stops calling an
            # expected one a finding.
            @{ Attribute = 'ms-Mcs-AdmPwd'; Custom = 'laps_read_is_expected'; Severity = 'Hint'; SeverityOnly = $true }
            @{ Attribute = 'msLAPS-Password'; Custom = 'laps_read_is_expected'; Severity = 'Hint'; SeverityOnly = $true }
            @{ Attribute = 'lapsReadContext'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    'BITLOCKER_KEY_READABLE' = @{
        Title = "BitLocker Recovery Key Readable"
        Risk = "Hint"
        BaseScore = 30
        Description = "The current user can read the escrowed BitLocker recovery password for this computer. BitLocker recovery keys are stored as msFVE-RecoveryInformation child objects and their read access is controlled by ACLs. Read access is often legitimate (recovery and helpdesk roles) and is not by itself a vulnerability, but it is worth reviewing: a readable recovery key lets the holder unlock the computer's BitLocker-protected volume offline, so unexpectedly broad access may indicate over-permissive delegation on the computer OUs."
        Impact = @(
            "The recovery key can unlock the computer's BitLocker-protected volume offline"
            "Relevant when a disk is lost, stolen, decommissioned, or imaged"
            "Broad read access may exceed what recovery/helpdesk roles actually require"
            "Often correlates with over-permissive ACLs on the computer OUs"
        )
        Attack = @(
            "1. Review which principals can read msFVE-RecoveryPassword on computer objects"
            "2. With the 48-digit key, a holder can unlock BitLocker given physical access or a disk image"
            "3. Confirm read access is limited to the intended recovery/helpdesk roles"
        )
        Remediation = @(
            "Review who can read msFVE-RecoveryPassword on computer OUs"
            "Restrict recovery key read access to dedicated recovery/helpdesk roles (tiered administration)"
            "Use security groups for recovery key access, not broad or individual grants"
            "Audit recovery key reads (Event ID 4662 on msFVE-RecoveryInformation objects)"
            "Ensure recovery keys are only escrowed where AD ACLs are properly hardened"
        )
        RemediationCommands = @(
            @{
                Description = "List who has read access to BitLocker recovery passwords on an OU"
                Command = "(Get-Acl 'AD:\OU=Workstations,DC=domain,DC=com').Access | Where-Object {`$_.ObjectType -eq '43061ac1-c8ad-4ccc-b785-2bfac20fc60a'} | Select-Object IdentityReference,ActiveDirectoryRights,AccessControlType,IsInherited"
            }
            @{
                Description = "View escrowed BitLocker recovery information for a computer (RSAT BitLocker tools)"
                Command = "Get-ADObject -Filter {objectClass -eq 'msFVE-RecoveryInformation'} -SearchBase 'CN=COMPUTER01,OU=Workstations,DC=domain,DC=com' -Properties msFVE-RecoveryPassword"
            }
        )
        References = @(
            @{ Title = "BitLocker recovery information in AD DS"; Url = "https://learn.microsoft.com/en-us/windows/security/operating-system-security/data-protection/bitlocker/configure?tabs=common#store-recovery-information-in-active-directory-domain-services" }
            @{ Title = "msFVE-RecoveryInformation class"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-ada2/" }
            @{ Title = "Attacking and defending BitLocker recovery keys in AD"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/index.html" }
        )
        Tools = @("PowerView", "DSInternals")
        MITRE = "T1552"
        Triggers = @(
            @{ Attribute = 'msFVE-RecoveryPassword'; Severity = 'Hint' }
        )
    }

    'BITLOCKER_RECOVERY_DELEGATED' = @{
        Title = "BitLocker Recovery Password - Read Delegated to a Principal"
        Risk = "Finding"
        BaseScore = 40
        Description = "A principal holds a read of the BitLocker recovery password on a container holding computers. The password sits on an msFVE-RecoveryInformation object below each computer, and the schema grants that object to Domain Admins and SYSTEM only, so every other reader was given the right by somebody - usually through the delegation wizard, for a helpdesk or recovery role. That can be intended, and the question to put to the owner of the delegation is whether this principal is that role. The 48-digit password unlocks the volume of every computer below the container offline, given the disk or an image of it. Whether the right works today depends on the schema: the attribute is confidential, so a read takes READ_PROPERTY and CONTROL_ACCESS on the same objects, and the row says which applies."
        Impact = @(
            "The holder reads the recovery password of every computer below the container with a plain LDAP query"
            "With the disk or an image of it - a stolen laptop, a retired drive, a virtual machine's disk file - the volume opens offline"
            "Disabling the computer account does not change the recovery password; it stays valid for the disk wherever the disk went"
            "An opened system volume yields the computer's local secrets, and on a domain controller the directory database"
            "A right the confidential flag currently blocks becomes live the moment somebody clears the flag"
        )
        Attack = @(
            "1. As the delegated principal, read msFVE-RecoveryPassword from the msFVE-RecoveryInformation objects below the computers in scope"
            "2. Obtain the disk of one of those computers, or an image of it"
            "3. Unlock the volume with the 48-digit recovery password (manage-bde -unlock -RecoveryPassword, or dislocker)"
            "4. Read the volume offline: SAM and LSA secrets, DPAPI material, and on a domain controller ntds.dit"
        )
        Remediation = @(
            "Confirm the principal is the recovery or helpdesk role the delegation was meant for; remove the ACE otherwise"
            "Scope the delegation to the containers whose computers that role supports, and keep servers and domain controllers out of it"
            "Keep the confidential flag on msFVE-RecoveryPassword - it is what makes a plain read of all properties insufficient"
            "Audit reads of recovery passwords (event 4662 on msFVE-RecoveryInformation objects)"
        )
        RemediationCommands = @(
            @{
                Description = "Show the ACEs on a container that reach the recovery passwords below its computers"
                Command = @'
$recoveryInformation = [guid]'ea715d30-8f53-40d0-bd1e-6109186d782c'
$recoveryPassword    = [guid]'43061ac1-c8ad-4ccc-b785-2bfac20fc60a'
(Get-Acl "AD:\<container DN>").Access |
    Where-Object {
        ($_.InheritedObjectType -in @($recoveryInformation, [guid]::Empty)) -and
        ($_.ObjectType -in @($recoveryPassword, [guid]::Empty)) -and
        ($_.ActiveDirectoryRights -match 'GenericAll|ReadProperty|ExtendedRight')
    } |
    Select-Object IdentityReference, ActiveDirectoryRights, ObjectType, InheritedObjectType, IsInherited
'@
            }
            @{
                Description = "Remove one delegated read. Check the output above first - the ACE may be inherited, in which case it has to go from the container it is inherited from"
                Command = @'
$acl = Get-Acl "AD:\<container DN>"
$ace = $acl.Access | Where-Object {
    $_.IdentityReference -eq '<DOMAIN\principal>' -and
    $_.InheritedObjectType -eq 'ea715d30-8f53-40d0-bd1e-6109186d782c'
}
$null = $acl.RemoveAccessRule($ace)
Set-Acl -Path "AD:\<container DN>" -AclObject $acl
'@
            }
        )
        References = @(
            @{ Title = "ms-FVE-RecoveryInformation class - default security descriptor (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/c-msfve-recoveryinformation" }
            @{ Title = "ms-FVE-RecoveryPassword attribute - searchFlags (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-msfve-recoverypassword" }
            @{ Title = "Confidential attributes - READ_PROPERTY plus CONTROL_ACCESS"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/mark-attribute-as-confidential" }
        )
        Tools = @("adPEAS", "PowerView", "manage-bde", "dislocker")
        MITRE = "T1552"
        Triggers = @(
            # Both label shapes Get-OUPermissions writes for this check type: the attribute
            # named, or an unscoped right that includes it. Neither phrase occurs in another
            # check's rights strings.
            @{ Attribute = 'dangerousRights'; Pattern = 'msFVE-RecoveryPassword|includes the recovery password'; Severity = 'Finding' }

            # The verdict row, an attribute of its own rather than EffectiveToday: those
            # three patterns belong to the Credential Roaming card, and two definitions
            # matching one value pick their card by score, not by check.
            @{ Attribute = 'ReadableToday'; Pattern = '^Yes'; Severity = 'Finding' }
            @{ Attribute = 'ReadableToday'; Pattern = '^No'; Severity = 'Secure' }
            @{ Attribute = 'ReadableToday'; Pattern = '^Unknown'; Severity = 'Hint' }
        )
    }

    # =========================================================================
    # GPO USER RIGHTS - one definition per right (Get-GPOUserRightsAssignment)
    # =========================================================================
    # GPO_DANGEROUS_USER_RIGHT used to be the tooltip for every one of the 22 rights the
    # check compared then (29 now), from SeDebugPrivilege to SeShutdownPrivilege alike - a reader hovering
    # a Tier-2 logon right got the same "leads directly to SYSTEM" prose written for
    # SeDebugPrivilege. Split into one definition per right, so the Title, Description,
    # Impact, Attack and Remediation match what that specific right actually does.
    #
    # Each carries two triggers: an exact match on 'userRight' colours and tooltips the
    # right's own name, and a Custom-gated match on 'GrantedBeyondDefault' does the same for
    # the holder names underneath it - the row a reader actually acts on. The gate is a
    # single shared evaluator (Test-CustomTrigger's 'user_right_is_*' case) dispatched from
    # the CustomType string itself, because Get-TriggerMatch always resolves FindingId to the
    # owning definition's own key - a trigger cannot redirect to a different one.

    'GPO_USERRIGHT_SEDEBUG' = @{
        Title = "'Debug Programs' (SeDebugPrivilege) Granted Beyond the Windows Default via GPO"
        Risk = "Finding"
        BaseScore = 85
        Description = "A Group Policy grants SeDebugPrivilege to a principal beyond the Windows default of Administrators only. The holder can open a handle to any process on the machine - LSASS included - and no object ACL can stop it, because the privilege itself overrides the access check."
        Impact = @(
            "Direct read access to LSASS memory: NT hashes, Kerberos tickets and cached cleartext credentials of every signed-in user"
            "Every process on the machine is exposed, not only the holder's own - service accounts and other users' sessions included"
            "The privilege bypasses the process ACL check itself, so hardening the target process does not help"
        )
        Attack = @(
            "1. Authenticate as the holder on a machine the policy reaches"
            "2. Open a handle to lsass.exe - SeDebugPrivilege removes the ACL check that would otherwise deny it"
            "3. Dump the process (comsvcs.dll MiniDump, Task Manager, or a dedicated tool)"
            "4. Recover credentials from the dump offline"
        )
        Remediation = @(
            "Remove the principal; only built-in Administrators should hold this right"
            "If a monitoring or EDR agent genuinely needs it, scope the GPO to the specific hosts that agent runs on"
        )
        References = @(
            @{ Title = "LSASS Memory - MITRE ATT&CK T1003.001"; Url = "https://attack.mitre.org/techniques/T1003/001/" }
        )
        Tools = @("Mimikatz", "ProcDump", "Task Manager")
        MITRE = "T1003.001"
        Triggers = @(
            @{ Attribute = 'UserRight'; Pattern = '^SeDebugPrivilege$'; Severity = 'Finding' }
            @{ Attribute = 'GrantedBeyondDefault'; Custom = 'user_right_is_SeDebugPrivilege'; Severity = 'Finding' }
        )
    }

    'GPO_USERRIGHT_SETCB' = @{
