    # =========================================================================
    # The two attributes every GPO user-rights finding can carry regardless of which
    # right it is about - not a specific right, so not part of the per-right split above.
    # =========================================================================

    'GPO_USERRIGHT_DEFAULT_REMOVED' = @{
        Title = "GPO Removes a Default Holder of a User Right"
        Risk = "Note"
        BaseScore = 0
        Description = "A Group Policy's [Privilege Rights] section is absolute: the principals it lists become the complete set of holders on every machine the policy reaches, so leaving one out removes a default holder rather than merely not mentioning it. Removing a default holder is hardening far more often than not."
        Impact = @(
            "Usually intended: a documented default holder (e.g. Backup Operators, Server Operators) is deliberately excluded on a hardened build"
            "Occasionally an operational foot-gun: if the removed holder actually needed the right for something running today, that functionality breaks the moment the policy applies"
        )
        Attack = @(
            "Not an attack path - reported so the reader can tell a deliberate removal from an accidental one, and confirm nothing that still needs the right lost it"
        )
        Remediation = @(
            "Confirm the removal was deliberate hardening rather than an accident"
            "If something on the affected machines relied on the removed holder having this right, restore it explicitly rather than leaving the policy to guess"
        )
        References = @(
            @{ Title = "User Rights Assignment - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/user-rights-assignment" }
        )
        Tools = @("-")
        MITRE = "-"
        Triggers = @(
            @{ Attribute = 'RemovedFromDefault'; Severity = 'Note' }
        )
    }

    'GPO_USERRIGHT_BASELINE_UNKNOWN' = @{
        Title = "User Right Has No Documented Windows Default"
        Risk = "Hint"
        BaseScore = 10
        Description = "Windows publishes no fixed default holder set for this right - who holds it varies with what is installed on the machine (SQL, Exchange, IIS and similar products each add their own accounts). The comparison this check is built around cannot run for it, so every holder is reported unfiltered rather than only the ones beyond a default that does not exist."
        Impact = @(
            "The list below has not been checked against a Windows baseline - judge each holder against what this domain actually runs, not against an assumed default"
            "A privileged or broad principal in the list is still worth the same scrutiny it would get anywhere else"
        )
        Attack = @(
            "Not an attack path on its own - it is a disclaimer on the holder list next to it, whose own severity carries the actual finding"
        )
        Remediation = @(
            "Review the holder list by hand against the services actually installed on the targeted machines"
        )
        References = @(
            @{ Title = "User Rights Assignment - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/user-rights-assignment" }
        )
        Tools = @("-")
        MITRE = "-"
        Triggers = @(
            @{ Attribute = 'BaselineUnknown'; Severity = 'Hint' }
        )
    }

    'LAPS_ENCRYPTED_READ_NO_DECRYPTOR' = @{
        Title = "Read Access to the Encrypted LAPS Password"
        Risk = "Hint"
        BaseScore = 25
        Description = "A principal can read msLAPS-EncryptedPassword on computers in this OU, and nothing else that carries the password. What that right returns is a blob: Windows LAPS encrypts the password for the principal named in ADPasswordEncryptionPrincipal, and only that principal can open it through NCryptUnprotectSecret. A read of the attribute alone is therefore not a password read - which is the whole point of the encrypted generation."
        Impact = @(
            "The blob cannot be opened without being the configured decryptor, so this is not a password read today"
            "It becomes one the moment the principal is added to the decryptor group, which is a group membership rather than an ACL change"
            "The delegation is still wrong: no account needs to read an attribute it cannot use"
            "Reported as a hint and not as a finding, because telling the reader otherwise teaches them the encryption buys nothing"
        )
        Attack = @(
            "1. Attacker controls a principal that can read msLAPS-EncryptedPassword"
            "2. Collects the blobs, which is quiet and needs no further right"
            "3. Looks for a path into the group named in ADPasswordEncryptionPrincipal, by default Domain Admins"
            "4. Opens every blob collected earlier as soon as that path exists"
        )
        Remediation = @(
            "Remove the read right - a principal that cannot decrypt has no use for the attribute"
            "Confirm who ADPasswordEncryptionPrincipal names, and keep that group as small as the password itself deserves"
            "Prefer this generation over the legacy plaintext attribute: a read right on ms-Mcs-AdmPwd is the password"
        )
        RemediationCommands = @(
            @{
                Description = "Show who can read the encrypted LAPS password on an OU - the attribute's GUID is read from this forest's schema rather than written down"
                Command = '$schema = (Get-ADRootDSE).schemaNamingContext; $guid = [guid]::new([byte[]](Get-ADObject -SearchBase $schema -LDAPFilter "(lDAPDisplayName=msLAPS-EncryptedPassword)" -Properties schemaIDGUID).schemaIDGUID); (Get-Acl -Path "AD:OU=TARGET_OU,DC=DOMAIN,DC=COM").Access | Where-Object { $_.ObjectType -eq $guid } | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize'
            }
            @{
                Description = "Read the configured decryptor from the LAPS policy"
                Command = 'Get-ADObject -LDAPFilter "(objectClass=groupPolicyContainer)" -Properties displayName | ForEach-Object { $_.displayName }  # then inspect ADPasswordEncryptionPrincipal in the Windows LAPS policy'
            }
        )
        References = @(
            @{ Title = "Windows LAPS password encryption - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-concepts-overview" }
            @{ Title = "NCryptUnprotectSecret - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/api/ncryptprotect/nf-ncryptprotect-ncryptunprotectsecret" }
        )
        Tools = @("LAPSToolkit", "PowerView")
        MITRE = "T1552.001"
        Triggers = @(
            # LAPS_PASSWORD_READ_ACCESS matches the words "LAPS Password Read", which this
            # text necessarily contains, and it scores 45 against this one's 25 - so that
            # card would have claimed the row and described a password read the holder
            # cannot perform. Its trigger carries an ExcludePattern for this wording
            # instead, the same way the DCSync card gives up the partial replication grant.
            @{ Attribute = 'dangerousRights'; Pattern = 'needs the authorized decryptor'; Severity = 'Hint' }
        )
    }
    'LAPS_PASSWORD_READ_ACCESS' = @{
        Title = "LAPS Password Read Permissions"
        Risk = "Finding"
        BaseScore = 45
        Description = "A non-privileged principal has been granted explicit permissions to read LAPS passwords. This allows them to obtain local administrator credentials for computers in the affected OUs, potentially enabling lateral movement."
        Impact = @(
            "Principal can read local admin passwords for affected computers"
            "Enables lateral movement to any computer where they have read access"
            "Compromising this principal grants access to all computers in scope"
            "May violate tiered administration model"
        )
        Attack = @(
            "1. Attacker compromises account with LAPS read permissions"
            "2. Enumerates computers where the account can read passwords"
            "3. Retrieves LAPS passwords via LDAP (ms-Mcs-AdmPwd or msLAPS-Password)"
            "4. Uses credentials for local admin access and credential harvesting"
        )
        Remediation = @(
            "Review and restrict LAPS password read permissions"
            "Follow tiered administration - only appropriate tier admins should read passwords"
            "Use security groups for LAPS access, not individual accounts"
            "Consider Windows LAPS with encrypted passwords for additional protection"
            "Audit LAPS password reads (Event ID 4662)"
        )
        RemediationCommands = @(
            @{
                Description = "Enumerate who has LAPS password read permissions on a specific OU"
                Command = "Find-AdmPwdExtendedRights -Identity 'OU=Workstations,DC=domain,DC=com' | Select-Object ExtendedRightHolders,ObjectDN"
            }
            @{
                Description = "View detailed ACL entries for LAPS password attributes on an OU"
                Command = "(Get-Acl 'AD:\OU=Workstations,DC=domain,DC=com').Access | Where-Object {`$_.ObjectType -eq 'ms-Mcs-AdmPwd' -or `$_.ObjectType -eq 'msLAPS-Password'} | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType,IsInherited -AutoSize"
            }
            @{
                Description = "Remove explicit LAPS read permission for a specific principal using Active Directory ACL manipulation"
                Command = "`$ou = [ADSI]'LDAP://OU=Workstations,DC=domain,DC=com'; `$acl = `$ou.PSBase.ObjectSecurity; `$ace = `$acl.Access | Where-Object {`$_.IdentityReference -eq 'DOMAIN\Username' -and `$_.ObjectType -eq 'ms-Mcs-AdmPwd'}; `$acl.RemoveAccessRule(`$ace); `$ou.PSBase.CommitChanges()"
            }
            @{
                Description = "Grant LAPS read permission to appropriate security group only"
                Command = "Set-LapsADReadPasswordPermission -Identity 'OU=Workstations,DC=domain,DC=com' -AllowedPrincipals 'DOMAIN\Tier1-Admins'"
            }
        )
        References = @(
            @{ Title = "Windows LAPS Security"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-concepts-overview" }
            @{ Title = "LAPS Access Control"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-scenarios-windows-server-active-directory" }
            @{ Title = "Set-LapsADReadPasswordPermission cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/laps/set-lapsadreadpasswordpermission" }
        )
        Tools = @("LAPSToolkit", "PowerView", "Get-LapsADPassword")
        MITRE = "T1552.004"
        Triggers = @(
            # The encrypted attribute read alone is reported with a wording that
            # contains these words and is not a password read: the blob needs the
            # decryptor from the policy. ExcludePattern is checked before Pattern, so
            # LAPS_ENCRYPTED_READ_NO_DECRYPTOR gets that row - the same way the DCSync
            # card gives up a partial replication grant.
            @{ Attribute = 'dangerousRights'; Pattern = 'LAPS Password Read'; ExcludePattern = 'needs the authorized decryptor'; Severity = 'Finding' }
            @{ Attribute = 'DangerousPermissions'; Pattern = 'LAPS Password Read'; Severity = 'Finding' }
        )
    }

    'LAPS_READ_BLOCKED_BY_CONFIDENTIAL' = @{
        Title = "Read All Properties on a Computer OU, Blocked by the Confidential Flag"
        Risk = "Hint"
        BaseScore = 20
        Description = "A non-privileged principal may read all properties of the computer objects in this OU. That does not include the LAPS password today: the password attributes are marked confidential in the schema (searchFlags bit 7), and MS-ADTS requires READ_PROPERTY and CONTROL_ACCESS together for a confidential attribute - which is why Set-AdmPwdReadPasswordPermission writes two ACEs. The delegation becomes a password read the moment that flag is cleared, or if the principal is granted CONTROL_ACCESS anywhere on the path."
        Impact = @(
            "Every other attribute of the computer objects is readable, which is reconnaissance rather than credential access"
            "Clearing the confidential flag on a LAPS password attribute turns this into a read of every local administrator password in the OU"
            "A later ACE granting CONTROL_ACCESS to the same principal does the same thing"
        )
        Attack = @(
            "1. Attacker holds, or takes over, the delegated principal"
            "2. Reads the computer objects of the OU - every attribute except the confidential ones"
            "3. Waits for, or brings about, the removal of the confidential flag, then reads the passwords"
        )
        Remediation = @(
            "Leave the confidential flag in place - it is what makes this harmless, and it is set by the LAPS schema extension"
            "Remove the all-properties delegation anyway if nothing needs it: it is wider than it looks and it is one schema change away from a password read"
            "Verify the flag rather than assuming it: searchFlags on ms-Mcs-AdmPwd, msLAPS-Password and msLAPS-EncryptedPassword must have bit 7 set"
        )
        RemediationCommands = @(
            @{
                Description = "Read the confidential flag on the LAPS password attributes"
                Command = @'
$schema = (Get-ADRootDSE).schemaNamingContext
Get-ADObject -SearchBase $schema `
    -LDAPFilter '(|(lDAPDisplayName=ms-Mcs-AdmPwd)(lDAPDisplayName=msLAPS-Password)(lDAPDisplayName=msLAPS-EncryptedPassword))' `
    -Properties lDAPDisplayName, searchFlags |
    Select-Object lDAPDisplayName, searchFlags, @{n='Confidential'; e={ ($_.searchFlags -band 128) -ne 0 }}
'@
            }
        )
        References = @(
            @{ Title = "Confidential attributes"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/mark-attribute-as-confidential" }
            @{ Title = "Windows LAPS Security"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-concepts-overview" }
        )
        Tools = @("LAPSToolkit", "PowerView")
        MITRE = "T1087.002"
        Triggers = @(
            @{ Attribute = 'dangerousRights'; Pattern = 'blocked by the confidential flag'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # SMB SIGNING FINDINGS
    # ============================================================================

    'SMB_SIGNING_DISABLED' = @{
        Title = "SMB Signing Not Required"
        Risk = "Finding"
        BaseScore = 30
        Description = "The GPO does not configure SMB signing requirements. Note: 'Not Configured' in GPO does not necessarily mean SMB signing is disabled - it may be configured locally on the system or enforced by OS defaults (Windows Server 2022+ and Windows 11 require SMB signing by default). However, best practice is to enforce security settings via GPO for consistent configuration across all systems, especially for in-place upgraded systems that may retain legacy settings."
        Impact = @(
            "SMB connections can be intercepted and relayed"
            "NTLM relay attacks can target SMB services"
            "Attackers can authenticate to other systems using relayed credentials"
            "Can lead to remote code execution on target systems"
            "Enables lateral movement without knowing passwords"
        )
        Attack = @(
            "1. Attacker positions for man-in-the-middle"
            "2. Coerces authentication from target (PetitPotam, PrinterBug, etc.)"
            "3. Relays NTLM authentication to a system without SMB signing"
            "4. Executes commands or accesses files as the relayed user"
        )
        Remediation = @(
            "Enable SMB signing on all systems: RequireSecuritySignature = True"
            "Deploy via GPO: Computer Configuration > Policies > Windows Settings > Security Settings > Local Policies > Security Options"
            "Microsoft network server: Digitally sign communications (always) = Enabled"
            "Best practice: Always configure security settings via GPO rather than relying on local policy or OS defaults"
            "Domain controllers already require it through the Default Domain Controllers Policy, so the work is member servers and clients - per OU, not domain-wide in one step"
            "What breaks: devices that cannot sign at all. Multifunction printers and scanners writing to a share, embedded NAS and SAN firmware, imaging and backup appliances, anything still speaking SMB1. Such a device cannot be exempted from a server that requires signing - either its firmware is updated, or its share moves to a server deliberately kept outside the enforcing OU and documented as the exception it is"
            "What it costs: signing is computed per packet. With SMB 3 and AES-based signing on current CPUs that is cheap, but it is still measurable on sequential file-server loads over fast links - worth measuring throughput on the busiest file server before the change rather than after"
        )
        RemediationCommands = @(
            @{
                Description = "Enable SMB server signing (require signing for inbound connections)"
                Command = "Set-SmbServerConfiguration -RequireSecuritySignature `$true -Force"
            }
            @{
                Description = "Enable SMB client signing (require signing for outbound connections)"
                Command = "Set-SmbClientConfiguration -RequireSecuritySignature `$true -Force"
            }
            @{
                Description = "Verify current SMB signing configuration"
                Command = "Get-SmbServerConfiguration | Select-Object RequireSecuritySignature,EnableSecuritySignature; Get-SmbClientConfiguration | Select-Object RequireSecuritySignature,EnableSecuritySignature"
            }
            @{
                Description = "Configure SMB signing via Group Policy (recommended for domain-wide enforcement)"
                Command = "# In Group Policy Management: Computer Configuration > Policies > Windows Settings > Security Settings > Local Policies > Security Options > 'Microsoft network server: Digitally sign communications (always)' = Enabled AND 'Microsoft network client: Digitally sign communications (always)' = Enabled"
            }
        )
        References = @(
            @{ Title = "Control SMB signing behavior"; Url = "https://learn.microsoft.com/en-us/windows-server/storage/file-server/smb-signing" }
            @{ Title = "Configure SMB Signing with Confidence"; Url = "https://techcommunity.microsoft.com/blog/filecab/configure-smb-signing-with-confidence/2418102" }
            @{ Title = "SMB Signing Overview"; Url = "https://docs.microsoft.com/en-us/troubleshoot/windows-server/networking/overview-server-message-block-signing" }
            @{ Title = "NTLM Relay - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/ntlm/index.html" }
        )
        Tools = @("ntlmrelayx", "Responder", "NetExec")
        MITRE = "T1557.001"
        Triggers = @(
            @{ Attribute = 'ServerSigning'; Pattern = '^Disabled$'; Severity = 'Finding' }
            @{ Attribute = 'ServerSigning'; Pattern = '^(Optional|Not Configured|Not Required)$'; Severity = 'Hint' }

            # An unset server-side value reads differently per role, and Get-SMBSigningStatus
            # says which role it is - it knows the scope the policy is linked at. On a domain
            # controller the default requires signing, so the silence is not the exposure:
            # neutral, and no card, because there is nothing here to write up. Anywhere else
            # the default is "not required" until Windows Server 2025, which is the state a
            # relay needs, and that keeps the hint and the card it always had.
            @{ Attribute = 'ServerSigning'; Pattern = '^Not configured \(DC default'; Severity = 'Note'; SeverityOnly = $true }
            @{ Attribute = 'ServerSigning'; Pattern = '^Not configured \(not required'; Severity = 'Hint' }
            @{ Attribute = 'ClientSigning'; Pattern = '^Disabled$'; Severity = 'Finding' }
            @{ Attribute = 'ClientSigning'; Pattern = '^(Optional|Not Configured|Not Required)$'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # CREDENTIAL EXPOSURE FINDINGS
    # ============================================================================

    'CREDENTIAL_IN_DESCRIPTION' = @{
        Title = "Credentials Found in a Free-Text Attribute"
        Risk = "Finding"
        BaseScore = 45
        Description = "A free-text attribute of this object - description, info, comment, adminDescription, a link in wWWHomePage or url, a path in scriptPath, homeDirectory or profilePath, or an extension attribute - contains what appears to be a password or credential. These fields are readable by any authenticated user, exposing credentials to all domain users."
        Impact = @(
            "Passwords visible to any authenticated domain user"
            "Often contains actual working passwords"
            "Common for service accounts and shared accounts"
            "No authentication or special permissions required to read"
            "Credentials may grant access to critical systems"
        )
        Attack = @(
            "1. Attacker queries AD for all objects with non-empty description/info"
            "2. Parses for password patterns (pass=, pwd:, password, etc.)"
            "3. Tests discovered credentials against accounts"
            "4. Uses valid credentials for access or privilege escalation"
        )
        Remediation = @(
            "Change the password first. The attribute was readable by every authenticated user in the domain, usually for years; emptying the field afterwards changes nothing about who already has the value, and the old content is in every AD backup"
            "Remove the password from the attribute the row names - description, info, comment, adminDescription, the link or the extension attribute"
            "Use a proper password manager for credential storage"
            "Educate administrators about this security risk"
            "Implement regular scans for credentials in AD attributes"
            "Consider using managed service accounts (gMSA/sMSA) which don't need stored passwords"
        )
        RemediationCommands = @(
            @{
                Description = "Find all users with potentially sensitive data in description field"
                Command = "Get-ADUser -Filter {Description -like '*pass*' -or Description -like '*pwd*' -or Description -like '*pw:*'} -Properties Description | Select-Object SamAccountName,Description"
            }
            @{
                Description = "Clear description field for a specific user"
                Command = "Set-ADUser -Identity 'USERNAME' -Description `$null"
            }
            @{
                Description = "Find all users with potentially sensitive data in info field"
                Command = "Get-ADUser -Filter * -Properties Info | Where-Object {`$_.Info -match 'pass|pwd|pw:|secret|credential'} | Select-Object SamAccountName,Info"
            }
            @{
                Description = "Clear info field for a specific user"
                Command = "Set-ADUser -Identity 'USERNAME' -Clear Info"
            }
        )
        References = @(
            @{ Title = "Finding Passwords in AD"; Url = "https://adsecurity.org/?p=2288" }
            @{ Title = "Credential Hunting - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1552/006/" }
            @{ Title = "AD Attribute Security - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory" }
        )
        Tools = @("PowerView", "ADRecon", "LDAP queries")
        MITRE = "T1552.001"
        # Two tiers, as Get-PasswordInDescription has them: an assignment with a value is a
        # finding, a word that only mentions a password is a hint. One pattern covered
        # both and coloured every mention red - the hint objects of that check carried a
        # red row, and a description saying "passwords" anywhere in the report did too.
        # The hint triggers exclude the assignment, so at most one of the two matches.
        Triggers = @(
            @{ Attribute = 'description'; Pattern = $Script:CredentialAssignmentPattern; Severity = 'Finding' }
            @{ Attribute = 'info';        Pattern = $Script:CredentialAssignmentPattern; Severity = 'Finding' }
            @{ Attribute = 'description'; Pattern = $Script:CredentialMentionPattern; ExcludePattern = $Script:CredentialNoMentionPattern; Severity = 'Hint' }
            @{ Attribute = 'info';        Pattern = $Script:CredentialMentionPattern; ExcludePattern = $Script:CredentialNoMentionPattern; Severity = 'Hint' }
        )
    }

    'CREDENTIAL_GPP_PASSWORD' = @{
        Title = "Group Policy Preferences Password (GPP)"
        Risk = "Finding"
        BaseScore = 50
        Description = "A Group Policy Preferences (GPP) file contains an encrypted password (cpassword attribute). The encryption key was publicly disclosed by Microsoft in 2012 (MS14-025), allowing anyone to decrypt these passwords. This is a well-known vulnerability actively exploited in penetration tests and real attacks."
        Impact = @(
            "Password can be instantly decrypted by any domain user"
            "GPP files are readable by all authenticated users via SYSVOL"
            "Often contains local administrator or service account passwords"
            "Credentials may still be valid and in use"
            "Common finding in domain compromises"
        )
        Attack = @(
            "1. Attacker accesses SYSVOL share (any domain user can read)"
            "2. Searches for Groups.xml, ScheduledTasks.xml, Services.xml, etc."
            "3. Extracts cpassword attribute from XML files"
            "4. Decrypts password using publicly known AES key"
            "5. Uses credentials for lateral movement or privilege escalation"
        )
        Remediation = @(
            "Change the password first, before the cleanup. Deleting the XML does not revoke it: the file is cached on every client that applied the policy (%ProgramData%\Microsoft\Group Policy\History), it is in every SYSVOL and system-state backup, and anybody who read it keeps it. A retest after the deletion alone shows the finding gone and the risk unchanged"
            "Delete ALL GPP files containing cpassword attributes immediately"
            "Install KB2962486 to prevent new GPP passwords from being created"
            "Use LAPS for local administrator password management"
            "Use gMSA for service accounts instead of GPP-deployed passwords"
        )
        RemediationCommands = @(
            @{
                Description = "Find all XML files in SYSVOL containing cpassword attributes (recursively)"
                Command = "Get-ChildItem -Path '\\domain.com\SYSVOL\domain.com\Policies' -Recurse -Include *.xml | Select-String -Pattern 'cpassword' | Select-Object Path,LineNumber"
            }
            @{
                Description = "Find specific GPP files that commonly contain passwords (Groups.xml, ScheduledTasks.xml, Services.xml, DataSources.xml)"
                Command = "`$gpoPath = '\\domain.com\SYSVOL\domain.com\Policies'; Get-ChildItem -Path `$gpoPath -Recurse -Include Groups.xml,ScheduledTasks.xml,Services.xml,DataSources.xml,Printers.xml,Drives.xml | ForEach-Object { if (Select-String -Path `$_.FullName -Pattern 'cpassword' -Quiet) { `$_ } }"
            }
            @{
                Description = "Remove cpassword from GPP via GPMC (recommended method - opens GPO for manual cleanup)"
                Command = "# In GPMC: Navigate to GPO > User/Computer Configuration > Preferences, locate the affected preference item, change Action to 'Delete' or remove the password field, save changes, then after GPO refresh cycles complete, delete the entire preference item"
            }
            @{
                Description = "Delete specific GPP XML file after backing up (use with caution - ensure GPO is no longer needed)"
                Command = "# Backup first: Copy-Item 'PATH_TO_GPP_FILE.xml' 'PATH_TO_BACKUP_LOCATION'; Remove-Item 'PATH_TO_GPP_FILE.xml' -Force"
            }
            @{
                Description = "Change the password the file carried - this is the step that revokes it"
                Command = @'
# A domain account:
Set-ADAccountPassword -Identity 'ACCOUNTNAME' -Reset -NewPassword (Read-Host -AsSecureString)

# A local account on many machines is what a GPP item usually deploys, and one shared
# local password is the problem rather than the GPO. Hand that account to LAPS, which
# gives every machine its own, instead of setting a new shared one.
'@
            }
        )
        References = @(
            @{ Title = "MS14-025 - GPP Password Vulnerability"; Url = "https://support.microsoft.com/en-us/topic/ms14-025-vulnerability-in-group-policy-preferences-could-allow-elevation-of-privilege-may-13-2014-60734e15-af79-26ca-ea53-8cd617073c30" }
            @{ Title = "How to remove cPassword values from Active Directory"; Url = "https://www.grouppolicy.biz/2014/05/remove-cpassword-values-active-directory/" }
            @{ Title = "Finding Passwords in SYSVOL - ADSecurity"; Url = "https://adsecurity.org/?p=2288" }
            @{ Title = "Exploiting GPP - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/acl-persistence-abuse/README.html#gpp-group-policy-preferences" }
        )
        Tools = @("Get-GPPPassword", "gpp-decrypt", "PowerSploit", "Impacket")
        MITRE = "T1552.006"
        Triggers = @(
            @{ Attribute = 'credentialType'; Pattern = 'GPP Password'; Severity = 'Finding' }
        )
    }

    'CREDENTIAL_AUTOADMINLOGON' = @{
        Title = "AutoAdminLogon Credentials in GPO"
        Risk = "Finding"
        BaseScore = 45
        Description = "A Group Policy deploys AutoAdminLogon registry settings with plaintext credentials. These credentials are stored unencrypted in Registry.xml files in SYSVOL, readable by any authenticated domain user. AutoAdminLogon automatically logs in a user at system startup."
        Impact = @(
            "Username and password stored in PLAINTEXT (not even encrypted like GPP)"
            "Readable by ANY authenticated domain user via SYSVOL"
            "Often contains administrative credentials for unattended deployments"
            "Credentials apply to workstations/servers where the GPO is linked"
            "Enables automatic administrative access to target systems"
        )
        Attack = @(
            "1. Attacker accesses SYSVOL share (any domain user can read)"
            "2. Searches for Registry.xml files containing the Winlogon DefaultPassword value"
            "3. Extracts DefaultUserName, DefaultPassword, and DefaultDomainName"
            "4. Uses credentials directly (no decryption needed!)"
            "5. Logs into systems where AutoAdminLogon is configured"
        )
        Remediation = @(
            "Change the exposed password first - the value stood in clear text in SYSVOL, readable by every authenticated user, and removing the policy does not revoke it"
            "Remove the Preferences registry item from the GPO (Registry.xml, not Administrative Templates)"
            "Use Windows Autopilot or MDT for unattended deployments instead"
            "If AutoAdminLogon is required, configure it locally (not via GPO)"
            "Consider using autologon.exe from Sysinternals which encrypts credentials"
        )
        RemediationCommands = @(
            @{
                Description = "Search SYSVOL for Registry.xml files containing AutoAdminLogon settings"
                Command = "Get-ChildItem -Path '\\domain.com\SYSVOL\domain.com\Policies' -Recurse -Include Registry.xml | Select-String -Pattern 'AutoAdminLogon|DefaultUserName|DefaultPassword' | Select-Object Path,LineNumber"
            }
            @{
                Description = "Remove the preference item in GPMC - this finding comes from Registry.xml, which is Group Policy Preferences"
                Command = @'
# Remove-GPRegistryValue works on the registry policy path (Registry.pol, Administrative
# Templates) and does nothing to a value deployed through the Preferences extension. This
# finding is read out of Registry.xml, so the cmdlet was guaranteed to miss it and report
# either an error or a success without effect.
#
# GPMC: the GPO > Computer Configuration (or User Configuration) > Preferences >
#       Windows Settings > Registry > delete the item that sets AutoAdminLogon,
#       DefaultUserName and DefaultPassword.
#
# A preference item with Action "Update" does not take the value back off the clients it
# already reached, so add an item with Action "Delete" for the same three values, let it
# apply, and remove that item afterwards as well.
'@
            }
            @{
                Description = "Find the Registry.xml items in a GPO folder, to know which GPO to open"
                Command = "Get-ChildItem -Path '\\domain.com\SYSVOL\domain.com\Policies' -Recurse -Include Registry.xml | Where-Object { Select-String -Path `$_.FullName -Pattern 'DefaultPassword' -Quiet } | Select-Object FullName"
            }
            @{
                Description = "Disable AutoAdminLogon locally on a specific computer"
                Command = "Set-ItemProperty -Path 'HKLM:\Software\Microsoft\Windows NT\CurrentVersion\Winlogon' -Name 'AutoAdminLogon' -Value 0"
            }
        )
        References = @(
            @{ Title = "Winlogon AutoAdminLogon Registry Keys"; Url = "https://docs.microsoft.com/en-us/troubleshoot/windows-server/user-profiles-and-logon/turn-on-automatic-logon" }
            @{ Title = "SYSVOL Credential Hunting"; Url = "https://adsecurity.org/?p=2288" }
            @{ Title = "Remove-GPRegistryValue cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/remove-gpregistryvalue" }
        )
        Tools = @("PowerView", "Snaffler", "Manual SYSVOL search")
        MITRE = "T1552.001"
        Triggers = @(
            @{ Attribute = 'credentialType'; Pattern = 'AutoAdminLogon'; Severity = 'Finding' }
        )
    }

    'GPO_REGISTRY_PASSWORD' = @{
        Title = "Password in a Registry Value Deployed by Group Policy"
        Risk = "Finding"
        BaseScore = 45
        Description = "A Group Policy Object deploys a string registry value whose name says it holds a password - Password, ProxyPassword, ServiceAccountPassword, Pwd and the like. An Administrative Template keeps it in Registry.pol, a preference item in Registry.xml, and both files sit in SYSVOL in clear text, readable by every authenticated user of the domain. The value name is what marks it; whether the password still works is not tested."
        Impact = @(
            "Any domain user can read the password from SYSVOL"
            "The password often belongs to a service, a proxy or a management agent that runs with more rights than the user reading it"
            "Every computer the GPO applies to receives it in its registry as well"
        )
        Attack = @(
            "1. Attacker with any domain account reads Registry.pol and Registry.xml from SYSVOL"
            "2. Picks the values named like a password"
            "3. Uses the password against the service or account it belongs to"
        )
        Remediation = @(
            "Remove the value from the GPO - in GPMC, the Administrative Template setting or the preference item that writes it"
            "Change the password, since it has been readable for as long as the GPO existed"
            "Hand the credential to the application another way - a managed service account, or a secret store"
        )
        RemediationCommands = @(
            @{
                Description = "Remove a value an Administrative Template deploys (Registry.pol)"
                Command = "Remove-GPRegistryValue -Name 'GPO_NAME' -Key 'HKLM\Software\VENDOR\KEY' -ValueName 'VALUE_NAME'"
            }
        )
        References = @(
            @{ Title = "Registry Policy File Format - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/desktop/policy/registry-policy-file-format" }
            @{ Title = "Unsecured Credentials: Credentials In Files - MITRE"; Url = "https://attack.mitre.org/techniques/T1552/001/" }
        )
        Tools = @("Snaffler", "Manual SYSVOL search")
        MITRE = "T1552.001"
        Triggers = @(
            @{ Attribute = 'credentialType'; Pattern = '^Registry Value$'; Severity = 'Finding' }
        )
    }

    'CREDENTIAL_UNATTEND_PASSWORD' = @{
        Title = "Password in a Windows Answer File"
        Risk = "Finding"
        BaseScore = 50
        Description = "A Windows answer file (unattend.xml or the like) readable here carries a password: the built-in administrator's, a local account's, the automatic logon's, or the account that joins the machine to the domain. Windows SIM can 'hide' the first three, and Microsoft says that this 'does not provide encryption or other security benefits' - the value is the Base64 of the password with the setting's name appended, and is shown decoded here. The domain join account cannot be hidden at all."
        Impact = @(
            "The local administrator password of every machine built from the file - often the same on all of them"
            "The domain join account's password, a domain credential, in clear text"
            "Readable by whoever can read the share the file sits on - in SYSVOL or NETLOGON, every authenticated user"
        )
        Attack = @(
            "1. Read the answer file from the share"
            "2. Decode a hidden value: Base64, then UTF-16LE, then cut AdministratorPassword or Password off the end"
            "3. Log on with the local administrator password to every machine built from the file, or with the domain join account to the domain"
        )
        Remediation = @(
            "Change the exposed passwords first - every machine built from the file, and the domain join account"
            "Remove the answer file from the share; keep deployment files where only the deployment service reads them"
            "Use Windows LAPS for the local administrator, and a join account that may only join computers, ideally with a pre-staged computer object"
        )
        RemediationCommands = @(
            @{
                Description = "Find answer files in SYSVOL"
                Command = "Get-ChildItem -Path '\\domain.com\SYSVOL\domain.com' -Recurse -Include *.xml | Where-Object { Select-String -Path `$_.FullName -Pattern 'urn:schemas-microsoft-com:unattend' -Quiet } | Select-Object FullName"
            }
        )
        References = @(
            @{ Title = "Hide Sensitive Data in an Answer File - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-hardware/customize/desktop/wsim/hide-sensitive-data-in-an-answer-file" }
            @{ Title = "Unsecured Credentials: Credentials In Files - MITRE"; Url = "https://attack.mitre.org/techniques/T1552/001/" }
        )
        Tools = @("Snaffler", "Manual SYSVOL search")
        MITRE = "T1552.001"
        Triggers = @(
            @{ Attribute = 'credentialType'; Pattern = '^Unattend Answer File$'; Severity = 'Finding' }
        )
    }

    'CREDENTIAL_NET_USE' = @{
        Title = "Net Use Command with Embedded Password"
        Risk = "Finding"
        BaseScore = 40
        Description = "A login script or batch file contains a 'net use' command with an embedded password. These scripts are stored in SYSVOL and readable by all authenticated domain users, exposing the credentials to potential attackers."
        Impact = @(
            "Password visible in plaintext in script files"
            "Scripts in SYSVOL/NETLOGON readable by all domain users"
            "Often used to map network drives at user logon"
            "May contain service account or shared account credentials"
            "Credentials may provide access to file servers or other resources"
        )
        Attack = @(
            "1. Attacker accesses SYSVOL/NETLOGON share"
            "2. Searches login scripts for 'net use' with /user: parameter"
            "3. Extracts username and password from the command"
            "4. Uses credentials to access the target resource"
            "5. Potentially pivots to other systems using same credentials"
        )
        Remediation = @(
            "Remove passwords from all login scripts immediately"
            "Use Group Policy Preferences drive mappings (without cpassword)"
            "Implement Kerberos authentication for network resources"
            "Use the user's own credentials via SSO for drive mappings"
            "Change any exposed passwords"
        )
        RemediationCommands = @(
            @{
                Description = "Search SYSVOL for login scripts containing 'net use' with passwords"
                Command = "Get-ChildItem -Path '\\domain.com\SYSVOL\domain.com\' -Recurse -Include *.bat,*.cmd,*.vbs,*.ps1 | Select-String -Pattern 'net use.*\/user:.*' | Select-Object Path,LineNumber,Line"
            }
            @{
                Description = "Find specific patterns for net use commands with embedded credentials"
                Command = "`$patterns = 'net use .* \/user:', 'net use .* /user:', 'password'; Get-ChildItem '\\domain.com\SYSVOL' -Recurse -Include *.bat,*.cmd | ForEach-Object { Select-String -Path `$_.FullName -Pattern `$patterns }"
            }
            @{
                Description = "Remove login script path from all users in a specific OU"
                Command = "Get-ADUser -Filter * -SearchBase 'OU=Users,DC=domain,DC=com' -Properties scriptPath | Where-Object {`$_.scriptPath} | Set-ADUser -Clear scriptPath"
            }
            @{
                Description = "List all users with login scripts assigned to identify affected accounts"
                Command = "Get-ADUser -Filter {scriptPath -like '*'} -Properties scriptPath,distinguishedName | Select-Object Name,scriptPath,distinguishedName"
            }
        )
        References = @(
            @{ Title = "Credential Hunting in Scripts"; Url = "https://adsecurity.org/?p=2288" }
            @{ Title = "SYSVOL Security - Microsoft"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-client/group-policy/create-and-manage-central-store" }
            @{ Title = "Hunting Passwords In SYSVOL"; Url = "https://www.networkintelligence.ai/blogs/hunting-passwords-in-sysvol/" }
        )
        Tools = @("Snaffler", "grep/findstr", "Manual script review")
        MITRE = "T1552.001"
        Triggers = @(
            @{ Attribute = 'credentialType'; Pattern = 'Net Use'; Severity = 'Finding' }
        )
    }

    'CREDENTIAL_SCRIPT_PASSWORD' = @{
        Title = "Password Found in Script File"
        Risk = "Finding"
        BaseScore = 45
        Description = "A script file in SYSVOL contains what appears to be a hardcoded password or credential. Scripts in SYSVOL are readable by all authenticated domain users, exposing these credentials to the entire domain."
        Impact = @(
            "Credentials visible to any authenticated domain user"
            "May be used for service accounts, database connections, or administrative access"
            "Scripts often contain credentials for automation purposes"
            "Could expose access to critical systems or databases"
        )
        Attack = @(
            "1. Attacker searches SYSVOL for common password patterns"
            "2. Reviews scripts for hardcoded credentials"
            "3. Identifies context of the credential (database, service, admin)"
            "4. Uses credential to access the target resource or system"
        )
        Remediation = @(
            "Remove all hardcoded credentials from scripts"
            "Use Windows Credential Manager or secure vaults"
            "Implement service accounts with Kerberos delegation"
            "Use gMSA accounts for services where possible"
            "Change all exposed passwords immediately"
        )
        RemediationCommands = @(
            @{
                Description = "Search SYSVOL for script files with common password patterns"
                Command = "`$patterns = 'password\s*=', 'pwd\s*=', 'passwd\s*=', 'credential', 'SecureString', 'ConvertTo-SecureString', '-AsPlainText'; Get-ChildItem '\\domain.com\SYSVOL' -Recurse -Include *.ps1,*.vbs,*.bat,*.cmd,*.ini,*.config | Select-String -Pattern `$patterns | Select-Object Path,LineNumber,Line"
            }
            @{
                Description = "Install PowerShell SecretManagement module for secure credential storage"
                Command = "Install-Module -Name Microsoft.PowerShell.SecretManagement -Force -Scope CurrentUser; Install-Module -Name Microsoft.PowerShell.SecretStore -Force -Scope CurrentUser"
            }
            @{
                Description = "Register a SecretStore vault and store credentials securely"
                Command = "Register-SecretVault -Name LocalVault -ModuleName Microsoft.PowerShell.SecretStore -DefaultVault; Set-Secret -Name 'ServiceAccountPassword' -Secret (Read-Host -AsSecureString -Prompt 'Enter Password')"
            }
            @{
                Description = "Retrieve credentials from SecretStore vault in scripts instead of hardcoding"
                Command = "`$password = Get-Secret -Name 'ServiceAccountPassword' -AsPlainText; `$credential = New-Object System.Management.Automation.PSCredential('domain\user', (Get-Secret -Name 'ServiceAccountPassword'))"
            }
        )
        References = @(
            @{ Title = "Credential Hunting Techniques"; Url = "https://attack.mitre.org/techniques/T1552/" }
            @{ Title = "SYSVOL Security - Microsoft"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-client/group-policy/create-and-manage-central-store" }
            @{ Title = "PowerShell Secret Management"; Url = "https://learn.microsoft.com/en-us/powershell/utility-modules/secretmanagement/how-to/manage-secretstore" }
            @{ Title = "Secure Password Management in PowerShell"; Url = "https://www.secureideas.com/blog/secure-password-management-in-powershell-best-practices" }
        )
        Tools = @("Snaffler", "trufflehog", "grep", "Manual review")
        MITRE = "T1552.001"
        Triggers = @(
            # Both of these matched a Tier 2 row as well, and at BaseScore 45 against the
            # Tier 2 card's 20 they won it. Three of the five Tier 2 descriptions contain
            # "password" or "credential", and the matchedLine trigger has no pattern at all,
            # so it matched every line of either tier.
            #
            # The marker sits on credentialType, which is why the two triggers exclude it
            # differently: an ExcludePattern tests the value, and the value of a matchedLine
            # row is the line, where "(needs review)" never appears.
            @{ Attribute = 'credentialType'; Pattern = 'Password|Credential|PSExec|Schtasks|Cmdkey|SecureString|API key'; ExcludePattern = '\(needs review\)'; Severity = 'Finding' }
            @{ Attribute = 'matchedLine'; Custom = 'credential_not_needs_review'; Severity = 'Finding' }
        )
    }

    'CREDENTIAL_CONNECTION_STRING' = @{
        Title = "Database Connection String with Credentials"
        Risk = "Finding"
        BaseScore = 40
        Description = "A configuration file or script contains a database connection string with embedded credentials. These files are often stored in SYSVOL or shared locations, exposing database access credentials to domain users."
        Impact = @(
            "Direct access to database server without further authentication"
            "May expose SQL Server, Oracle, MySQL, or other database credentials"
            "Database may contain sensitive business data, PII, or financial records"
            "SQL Server accounts may have elevated privileges (sysadmin)"
        )
        Attack = @(
            "1. Attacker finds connection string in config file or script"
            "2. Extracts server, database, username, and password"
            "3. Connects to database server using exposed credentials"
            "4. Extracts data or escalates privileges (xp_cmdshell, etc.)"
        )
        Remediation = @(
            "Remove credentials from connection strings"
            "Use Windows Integrated Authentication where possible"
            "Store connection strings in encrypted configuration sections"
            "Use Azure Key Vault or similar secret management"
            "Rotate all exposed database credentials"
        )
        RemediationCommands = @(
            @{
                Description = "Search SYSVOL for files containing database connection strings"
                Command = "`$patterns = 'Server=', 'Data Source=', 'Initial Catalog=', 'User ID=', 'Password=', 'connection\s*string'; Get-ChildItem '\\domain.com\SYSVOL' -Recurse -Include *.config,*.xml,*.ini,*.ps1,*.vbs | Select-String -Pattern `$patterns | Select-Object Path,LineNumber,Line"
            }
            @{
                Description = "Convert SQL Server connection string to Windows Integrated Authentication (remove credentials)"
                Command = "# Replace: 'Server=myServer;Database=myDB;User Id=sa;Password=P@ss;' with: 'Server=myServer;Database=myDB;Integrated Security=SSPI;Trusted_Connection=Yes;Encrypt=True;'"
            }
            @{
                Description = "Find all connection strings with embedded credentials in configuration files"
                Command = "Get-ChildItem -Path '\\domain.com\SYSVOL' -Recurse -Include *.config | ForEach-Object { Select-Xml -Path `$_.FullName -XPath '//connectionStrings/add[@connectionString]' | Where-Object { `$_.Node.connectionString -match 'password=|pwd=' } | Select-Object @{Name='File';Expression={`$_.Path}}, @{Name='Name';Expression={`$_.Node.name}}, @{Name='ConnectionString';Expression={`$_.Node.connectionString}} }"
            }
            @{
                Description = "Store database credentials securely in Azure Key Vault (alternative to hardcoded connection strings)"
                Command = "# Install-Module Az.KeyVault; `$secret = ConvertTo-SecureString 'MySecretPassword' -AsPlainText -Force; Set-AzKeyVaultSecret -VaultName 'MyVault' -Name 'DbPassword' -SecretValue `$secret"
            }
        )
        References = @(
            @{ Title = "Connection String Attacks"; Url = "https://book.hacktricks.wiki/en/network-services-pentesting/pentesting-mssql-microsoft-sql-server.html" }
            @{ Title = "SQL Server Security - Microsoft"; Url = "https://learn.microsoft.com/en-us/sql/relational-databases/security/securing-sql-server" }
            @{ Title = "SQL Server Connection String Syntax"; Url = "https://learn.microsoft.com/en-us/sql/connect/ado-net/connection-string-syntax" }
            @{ Title = "How to Access SQL Server Using Windows Integrated Security"; Url = "https://learn.microsoft.com/en-us/previous-versions/aspnet/bsz5788z(v=vs.100)" }
        )
        Tools = @("Snaffler", "trufflehog", "sqlcmd")
        MITRE = "T1552.001"
        Triggers = @(
            @{ Attribute = 'credentialType'; Pattern = 'connection\s*string|DB connection'; Severity = 'Finding' }
        )
    }

    'CREDENTIAL_MENTION_REVIEW' = @{
        Title = "Possible Credential Reference (Needs Review)"
        Risk = "Hint"
        BaseScore = 20
        Description = "A script or configuration file contains a term that may indicate credential storage or usage. This is a lower-confidence finding that requires manual review to determine if actual credentials are exposed."
        Impact = @(
            "May indicate hardcoded passwords requiring further investigation"
            "Could be documentation, comments, or actual credential exposure"
            "False positives are common with generic password mentions"
            "Manual review needed to assess actual risk"
        )
        Attack = @(
            "1. Attacker searches scripts for credential keywords"
            "2. Reviews context to determine if actual credentials are present"
            "3. If credentials found, extracts and uses them for access"
        )
        Remediation = @(
            "Review the matched line to determine if credentials are present"
            "If credentials exist, remove them and use secure alternatives"
            "Document password policies rather than embedding examples"
            "Use secure credential storage mechanisms"
        )
        References = @(
            @{ Title = "Credential Hunting - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1552/" }
            @{ Title = "SYSVOL Security - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory" }
        )
        Tools = @("Manual review", "Snaffler")
        MITRE = "T1552.001"
        Triggers = @(
            # The matchedLine trigger was Context-bound, and -Context reaches
            # Get-TriggerMatch from exactly one place in the project: the Owner transformer,
            # which fills it itself. Nothing supplies a context for a credential row, so the
            # guard skipped this trigger every time and the line fell through to
            # CREDENTIAL_SCRIPT_PASSWORD - BaseScore 45, "Password Found in Script File",
            # with an attack path that ends in using the credential - for a line whose only
            # offence is containing the word "credential". The predicate below reads the
            # marker off the object instead, which is where the check writes it.
            @{ Attribute = 'credentialType'; Pattern = '\(needs review\)'; Severity = 'Hint' }
            @{ Attribute = 'matchedLine'; Custom = 'credential_needs_review'; Severity = 'Hint' }
        )
    }

    'REVERSIBLE_ENCRYPTION' = @{
        Title = "Password Stored with Reversible Encryption"
        Risk = "Finding"
        BaseScore = 30
        Description = "This account has 'Store password using reversible encryption' enabled. This means the password is stored in a way that can be decrypted, effectively storing it in clear text."
        Impact = @(
            "Password can be recovered in clear text from AD database"
            "Anyone with DCSync rights can extract the actual password"
            "NTDS.dit extraction reveals the password"
            "Required for some legacy protocols but severe security risk"
        )
        Attack = @(
            "1. Attacker performs DCSync or extracts NTDS.dit"
            "2. Uses DSInternals to decrypt reversibly encrypted passwords"
            "3. Obtains actual password in clear text"
            "4. Uses password for authentication or further attacks"
        )
        Remediation = @(
            "Disable 'Store password using reversible encryption' for all accounts"
            "Force password change after disabling the setting"
            "Review applications requiring this setting - find alternatives"
            "Use modern authentication protocols that don't require reversible encryption"
        )
        RemediationCommands = @(
            @{
                Description = "Disable reversible encryption for a single user account"
                Command = "Set-ADUser -Identity 'USERNAME' -AllowReversiblePasswordEncryption `$false"
            }
            @{
                Description = "Disable reversible encryption for all users in a specific OU"
                Command = "Get-ADUser -Filter {AllowReversiblePasswordEncryption -eq `$true} -SearchBase 'OU=Users,DC=domain,DC=com' | Set-ADUser -AllowReversiblePasswordEncryption `$false"
            }
            @{
                Description = "Find all users with reversible encryption enabled"
                Command = "Get-ADUser -Filter {AllowReversiblePasswordEncryption -eq `$true} -Properties AllowReversiblePasswordEncryption,PasswordLastSet | Select-Object Name,SamAccountName,AllowReversiblePasswordEncryption,PasswordLastSet"
            }
            @{
                Description = "Force password change after disabling (required to remove stored reversible password)"
                Command = "Set-ADUser -Identity 'USERNAME' -ChangePasswordAtLogon `$true"
            }
        )
        References = @(
            @{ Title = "Reversible Encryption Password Storage"; Url = "https://docs.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/store-passwords-using-reversible-encryption" }
            @{ Title = "Extracting Reversible Passwords"; Url = "https://adsecurity.org/?p=2288" }
        )
        Tools = @("DSInternals", "Mimikatz", "Impacket")
        MITRE = "T1003.006"
        Triggers = @(
            @{ Attribute = 'userAccountControl'; Pattern = 'ENCRYPTED_TEXT_PWD_ALLOWED'; Severity = 'Finding' }
            @{ Attribute = 'reversibleEncryption'; Pattern = 'Enabled'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # GMSA / SERVICE ACCOUNT FINDINGS
    # ============================================================================

    'GMSA_PASSWORD_READABLE' = @{
        Title = "gMSA Password Retrievable"
        Risk = "Finding"
        BaseScore = 55
        Description = "The current user can read the managed password for this Group Managed Service Account. gMSA passwords are cryptographically strong but grant full access to the service account if retrieved."
        Impact = @(
            "gMSA password allows impersonation of the service account"
            "Service accounts often have elevated privileges"
            "Can access all resources the gMSA has permissions to"
            "May enable lateral movement or privilege escalation"
        )
        Attack = @(
            "1. Attacker identifies gMSA accounts they can read"
            "2. Retrieves msDS-ManagedPassword attribute"
            "3. Decodes the BLOB to obtain NT hash"
            "4. Uses hash for Pass-the-Hash or Kerberos ticket requests"
        )
        Remediation = @(
            "Review PrincipalsAllowedToRetrieveManagedPassword"
            "Restrict password retrieval to only systems that need it"
            "Use tiered administration for gMSA management"
            "Audit gMSA password retrievals"
        )
        RemediationCommands = @(
            @{
                Description = "View which principals can retrieve the gMSA password"
                Command = "Get-ADServiceAccount -Identity 'GMSA_NAME' -Properties PrincipalsAllowedToRetrieveManagedPassword | Select-Object Name,PrincipalsAllowedToRetrieveManagedPassword"
            }
            @{
                Description = "Set specific security group as the only principal allowed to retrieve gMSA password"
                Command = "Set-ADServiceAccount -Identity 'GMSA_NAME' -PrincipalsAllowedToRetrieveManagedPassword 'DOMAIN\Tier1-Servers'"
            }
            @{
                Description = "Add additional principals to retrieve gMSA password (append to existing list)"
                Command = "`$current = (Get-ADServiceAccount -Identity 'GMSA_NAME' -Properties PrincipalsAllowedToRetrieveManagedPassword).PrincipalsAllowedToRetrieveManagedPassword; `$current += Get-ADComputer 'SERVER01'; Set-ADServiceAccount -Identity 'GMSA_NAME' -PrincipalsAllowedToRetrieveManagedPassword `$current"
            }
            @{
                Description = "Find all gMSA accounts and check their retrieval permissions"
                Command = "Get-ADServiceAccount -Filter {ObjectClass -eq 'msDS-GroupManagedServiceAccount'} -Properties PrincipalsAllowedToRetrieveManagedPassword | Select-Object Name,PrincipalsAllowedToRetrieveManagedPassword"
            }
        )
        References = @(
            @{ Title = "Group Managed Service Accounts"; Url = "https://docs.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/group-managed-service-accounts-overview" }
            @{ Title = "gMSA - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/golden-dmsa-gmsa.html" }
            @{ Title = "gMSA Attack Techniques"; Url = "https://adsecurity.org/?p=4367" }
            @{ Title = "Set-ADServiceAccount cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/set-adserviceaccount" }
            @{ Title = "Manage Group Managed Service Accounts"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts/manage-group-managed-service-accounts" }
        )
        Tools = @("GMSAPasswordReader", "DSInternals", "Impacket")
        MITRE = "T1552"
        Triggers = @(
            @{ Attribute = 'msDS-ManagedPassword'; Severity = 'Finding' }
            @{ Attribute = 'ntHash'; Severity = 'Finding' }
            @{ Attribute = 'previousNTHash'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # SHADOW CREDENTIALS FINDINGS
    # ============================================================================

    'SHADOW_CREDENTIALS' = @{
        Title = "Key Credential Present (msDS-KeyCredentialLink)"
        Risk = "Note"
        BaseScore = 5
        Description = "The account carries one or more key credentials in msDS-KeyCredentialLink. Windows Hello for Business, FIDO2 security keys and Entra hybrid join write them in normal operation, so a populated attribute is information, not a finding. The Shadow Credentials attack needs write access to the attribute, and that is what the ACL checks report - a right on msDS-KeyCredentialLink, GenericWrite or GenericAll delegated on an OU, and the same rights on AdminSDHolder, which SDProp copies onto every administrator. The row lists each key with its source and, on a computer, how long after the account it appeared: a device key registers within minutes of the join, so one added days or weeks later on a computer that does not use Windows Hello is worth a look."
        Impact = @(
            "A key credential lets its holder authenticate with PKINIT without the password"
            "Expected on accounts enrolled in Windows Hello for Business or FIDO2, and on hybrid-joined computers"
            "A key nobody can account for is persistence that survives password resets"
        )
        Attack = @(
            "1. Shadow Credentials needs write access to msDS-KeyCredentialLink on the target - reported by the ACL checks, not by this row"
            "2. With it, an attacker adds a key pair of their own to the attribute"
            "3. The private key authenticates as the target with PKINIT"
            "4. The planted key stays valid across password changes until it is removed"
        )
        Remediation = @(
            "Account for the keys on privileged accounts - an administrator who does not use Windows Hello or FIDO2 should carry none"
            "Remove write access to msDS-KeyCredentialLink from principals that do not need it (see the ACL findings)"
            "Monitor changes to msDS-KeyCredentialLink (Event ID 5136)"
        )
        RemediationCommands = @(
            @{
                Description = "View all key credentials in msDS-KeyCredentialLink for a user or computer"
                Command = "Get-ADUser -Identity 'USERNAME' -Properties msDS-KeyCredentialLink | Select-Object Name,msDS-KeyCredentialLink"
            }
            @{
                Description = "Clear all key credentials from msDS-KeyCredentialLink attribute (WARNING: Breaks Windows Hello for Business if configured)"
                Command = "Set-ADUser -Identity 'USERNAME' -Clear msDS-KeyCredentialLink"
            }
            @{
                Description = "View ACL permissions on msDS-KeyCredentialLink to identify who can write to this attribute"
                Command = "(Get-Acl 'AD:\CN=User,OU=Users,DC=domain,DC=com').Access | Where-Object {`$_.ObjectType -eq '5b47d60f-6090-40b2-9f37-2a4de88f3063'} | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize"
            }
            @{
                Description = "Enable auditing for changes to msDS-KeyCredentialLink (Event ID 5136 for directory service changes)"
                Command = "# In Group Policy: Computer Configuration > Policies > Windows Settings > Security Settings > Advanced Audit Policy Configuration > DS Access > Audit Directory Service Changes = Success, Failure"
            }
        )
        References = @(
            @{ Title = "Shadow Credentials Attack"; Url = "https://posts.specterops.io/shadow-credentials-abusing-key-trust-account-mapping-for-takeover-8ee1a53566ab" }
            @{ Title = "Shadow Credentials - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/acl-persistence-abuse/shadow-credentials.html" }
            @{ Title = "Key Credential Link"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/f3f01e95-6d0c-4fe6-8b43-d585167658fa" }
            @{ Title = "Exploiting and Detecting Shadow Credentials"; Url = "https://medium.com/@NightFox007/exploiting-and-detecting-shadow-credentials-and-msds-keycredentiallink-in-active-directory-9268a587d204" }
            @{ Title = "Detecting Shadow Credentials"; Url = "https://cyberstoph.org/posts/2022/03/detecting-shadow-credentials/" }
        )
        Tools = @("Whisker", "Certipy", "PyWhisker", "DSInternals")
        MITRE = "T1556.006"
        Triggers = @(
            # Information, by user decision 2026-10-16: the attribute is populated on every
            # account enrolled in Windows Hello for Business or FIDO2 and on every
            # hybrid-joined computer. As a Finding/60 it put a red Shadow Credentials card,
            # and its score, on all of them. The attack is the write right, which the ACL
            # checks report.
            @{ Attribute = 'msDS-KeyCredentialLink'; Severity = 'Note' }
        )
    }

    # ============================================================================
    # TRUST RELATIONSHIP FINDINGS
    # ============================================================================

    'TRUST_SID_FILTERING_DISABLED' = @{
        Title = "SID Filtering Disabled on Trust"
        Risk = "Finding"
        BaseScore = 50
        Description = "SID Filtering is disabled on this trust relationship. This allows SID History from the trusted domain to be honored, enabling cross-trust privilege escalation attacks."
        Impact = @(
            "Attackers in trusted domain can inject privileged SIDs"
            "SID History injection enables Domain Admin access across trusts"
            "Compromising trusted domain can lead to trusting domain compromise"
            "Bypasses normal forest trust boundaries"
        )
        Attack = @(
            "1. Attacker compromises account in trusted domain"
            "2. Injects trusting domain's DA SID into their SID History"
            "3. Authenticates across trust using injected SID"
            "4. Gains Domain Admin access in trusting domain"
        )
        Remediation = @(
            "This is the external or realm trust case, and quarantine is the lever: netdom trust THIS.DOMAIN /domain:TRUSTED.DOMAIN /quarantine:yes. It is also the default for such a trust, so somebody cleared it. A forest trust is relaxed by a different flag and has its own write-up - TRUST_TREAT_AS_EXTERNAL"
            "Find out what it was cleared for before setting it back. Quarantine stops this domain honouring sIDHistory from the other side, so accounts migrated out of the trusted domain that still reach resources here through an old SID of theirs lose that access the moment it is on - after a domain consolidation that is a working arrangement rather than an oversight, and it is the usual reason the flag is gone"
            "Where migrated accounts still depend on it: re-permission the resources onto the current SIDs first, then enable quarantine"
            "Selective Authentication limits which principals may authenticate across the trust at all - worth having in addition, not instead"
            "Until it is on, treat the trusted domain as part of this domain's attack surface and watch cross-trust authentication for SID history abuse"
        )
        RemediationCommands = @(
            @{
                Description = "Enable SID Filtering (quarantine) on trust"
                Command = "netdom trust TRUSTINGDOMAIN /domain:TRUSTEDDOMAIN /quarantine:yes"
            }
            @{
                Description = "Verify SID Filtering status on all trusts"
                Command = "Get-ADTrust -Filter * | Select-Object Name,Direction,SIDFilteringQuarantined,TrustType"
            }
            @{
                Description = "Enable SID Filtering using PowerShell (alternative method)"
                Command = "Set-ADTrust -Identity 'TrustedDomain' -SIDFilteringQuarantined `$true"
            }
        )
        References = @(
            @{ Title = "SID Filtering - Microsoft"; Url = "https://docs.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2003/cc772633(v=ws.10)" }
            @{ Title = "Get-ADTrust cmdlet"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/get-adtrust" }
            @{ Title = "SID History Injection - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/sid-history-injection.html" }
        )
        Tools = @("Mimikatz", "Rubeus")
        MITRE = "T1134.005"
        Triggers = @(
            # The verdict is on sidFiltering, whose value Get-TrustSIDFilteringVerdict
            # starts with DISABLED only where the combination is actually dangerous.
            #
            # It used to hang off isQuarantined being False, guarded only against a
            # within-forest trust, and that got two cases wrong in opposite directions. A
            # forest trust does not use QUARANTINED_DOMAIN at all - it filters SIDs from
            # outside the trusted forest by default - so every correctly configured forest
            # trust in existence was reported, which is the fastest way to teach a reader
            # to skip the colour. And an inbound-only trust was reported although the
            # exposure belongs to the partner: inbound means they trust us.
            #
            # The card follows the regime. Two combinations are dangerous - an external
            # trust without quarantine, and a forest trust carrying TREAT_AS_EXTERNAL - and
            # they are undone by different commands; a single card on a shared risk
            # sentence (trustRisk, gone) handed one of the two a remediation that cannot
            # work on it: netdom /quarantine:yes is not the lever on a forest trust.
            # sidFiltering states which regime applies, in a prefix
            # Get-TrustSIDFilteringVerdict writes; the forest half is TRUST_TREAT_AS_EXTERNAL.
            @{ Attribute = 'sidFiltering'; Pattern = '^DISABLED'; Severity = 'Finding' }

            # Filtering in force, on either kind of trust. The external case also has the
            # bit itself below, but a forest trust does not carry QUARANTINED_DOMAIN at
            # all, so without this line its good news rendered as colourless as the bad.
            @{ Attribute = 'sidFiltering'; Pattern = '^Enabled'; Severity = 'Secure'; SeverityOnly = $true }

            # The plain state of the bit, without a verdict attached to it.
            @{ Attribute = 'isQuarantined'; Pattern = '^True$'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'RBCD_CONFIGURED' = @{
        Title = "Resource-Based Constrained Delegation Configured"
        Risk = "Hint"
        BaseScore = 20
        Description = "This resource has msDS-AllowedToActOnBehalfOfOtherIdentity set, and the principals it names were assessed: none of them is a broad group, none is an identity this domain does not expect to delegate, and the resource itself is not a domain controller. RBCD is a feature rather than a misconfiguration - it is how a front-end service is allowed to act for a user against a back-end, and Microsoft documents it as the successor to the older constrained delegation. What makes it a finding is who may use it and on what, which is the other card: RBCD_DANGEROUS_PRINCIPALS."
        Impact = @(
            "Whoever controls a principal listed here can obtain a service ticket to this resource as any account the resource accepts"
            "That is the intended behaviour of the feature, so the question is whether the principals are the ones that should hold it"
            "An attacker who can write this attribute adds themselves to it, which is why write access to the resource object matters as much as the current contents"
        )
        Attack = @(
            "1. Attacker gains control of a principal named in the descriptor - or write access to this attribute, which the owner of the object has"
            "2. Requests a service ticket to this resource on behalf of a chosen account (S4U2Self, then S4U2Proxy)"
            "3. Uses it against the resource as that account"
        )
        Remediation = @(
            "Confirm the entries are the ones intended, and remove the rest: Set-ADComputer -Identity RESOURCE -Clear msDS-AllowedToActOnBehalfOfOtherIdentity removes all of them"
            "Who may write the attribute decides who may add themselves to it - review the ACL of the resource object and its owner, which Get-DangerousACLs and the owner checks report"
            "Put the accounts that must never be impersonated into Protected Users, or mark them sensitive and not delegated - that is what stops the S4U chain regardless of this attribute"
        )
        RemediationCommands = @(
            @{
                Description = "Show who may act on behalf of others against this resource"
                Command = "(Get-ADComputer -Identity 'RESOURCE' -Properties msDS-AllowedToActOnBehalfOfOtherIdentity).'msDS-AllowedToActOnBehalfOfOtherIdentity'.Access | Select-Object IdentityReference, AccessControlType"
            }
            @{
                Description = "Remove the delegation entirely"
                Command = "Set-ADComputer -Identity 'RESOURCE' -Clear msDS-AllowedToActOnBehalfOfOtherIdentity"
            }
        )
        References = @(
            @{ Title = "Resource-Based Constrained Delegation - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-constrained-delegation-overview" }
            @{ Title = "Resource-Based Constrained Delegation Abuse - HackTricks"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/resource-based-constrained-delegation.html" }
        )
        Tools = @("Rubeus", "PowerView", "Impacket")
        MITRE = "T1134.001"
        Triggers = @(
            # The assessed-and-unremarkable half of the RBCD verdict. The dangerous half
            # keeps RBCD_DANGEROUS_PRINCIPALS, whose title says "Misconfiguration" - which
            # is the wrong word for the documented frontend-to-backend pattern, and was the
            # only title this check had.
            @{ Attribute = 'rbcdPrincipalRisk'; Pattern = '^None - the attribute is set'; Severity = 'Note' }
            @{ Attribute = 'rbcdPrincipalRisk'; Severity = 'Hint' }
        )
    }

    'KERBEROS_TICKET_LIFETIME_EXTENDED' = @{
        Title = "Kerberos Ticket Lifetime Extended Beyond the Default"
        Risk = "Hint"
        BaseScore = 25
        Description = "The domain's Kerberos policy is wider than the Microsoft defaults: a ticket-granting ticket lives longer than 10 hours or never expires, tickets can be renewed for longer than 7 days, a service ticket lives longer than 600 minutes or never expires, or a clock more than 5 minutes off is accepted. The lifetimes decide how long a stolen ticket keeps working: a TGT taken out of LSASS, or forged with the krbtgt key, is accepted until it expires, and no password change and no account disable shortens that. The policy is read from the [Kerberos Policy] section of the GPOs linked to the domain, which is where the domain controllers take it from; the row names the GPO that sets each value."
        Impact = @(
            "A stolen or forged TGT is accepted for as long as the lifetime allows"
            "Disabling the account or resetting its password does not invalidate a ticket already issued"
            "The renewal window is the outer bound: a ticket renewed in time never has to be re-requested"
            "A longer lifetime widens every pass-the-ticket and Golden Ticket window by the same amount"
        )
        Attack = @(
            "1. Attacker obtains a TGT - from LSASS on a machine the user logged on to, or forged with the krbtgt key"
            "2. Uses it for the remainder of its lifetime, with no further contact with the password"
            "3. Renews it inside the renewal window, which costs one request and extends the hold"
        )
        Remediation = @(
            "Set the maximum lifetime for user tickets back to 10 hours, the renewal lifetime to 7 days, the service ticket lifetime to 600 minutes and the clock tolerance to 5 minutes"
            "They live in Default Domain Policy under Computer Configuration -> Policies -> Windows Settings -> Security Settings -> Account Policies -> Kerberos Policy; the row names the GPO that actually sets each value"
            "A longer lifetime is sometimes set for an application that cannot re-authenticate; the fix there belongs in the application, not in the domain policy"
        )
        RemediationCommands = @(
            @{
                Description = "Read the values where Group Policy keeps them - the Default Domain Policy's GptTmpl.inf (another domain-linked GPO may override them)"
                Command = "Get-Content '\\domain.com\SYSVOL\domain.com\Policies\{31B2F340-016D-11D2-945F-00C04FB984F9}\MACHINE\Microsoft\Windows NT\SecEdit\GptTmpl.inf' | Select-String -Pattern 'MaxTicketAge|MaxRenewAge|MaxServiceAge|MaxClockSkew'"
            }
            @{
                Description = "The policy path that sets them"
                Command = "# Default Domain Policy -> Computer Configuration -> Policies -> Windows Settings -> Security Settings -> Account Policies -> Kerberos Policy"
            }
        )
        References = @(
            @{ Title = "Kerberos Policy - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/kerberos-policy" }
            @{ Title = "Maximum lifetime for user ticket"; Url = "https://learn.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/maximum-lifetime-for-user-ticket" }
        )
        Tools = @("Rubeus", "mimikatz")
        MITRE = "T1550.003"
        Triggers = @(
            # The verdict Get-DomainInformation writes when one of the two values is above
            # its default. Anchored, and the attribute exists only in that case - an
            # ordinary domain gets no row and no card.
            @{ Attribute = 'ticketLifetime'; Pattern = '^EXTENDED'; Severity = 'Hint' }
        )
    }

    'TRUST_USES_RC4' = @{
        # The card claimed offline brute force of the trust key and "re-create the trust".
        # The password of an Active Directory trust is generated by the domain controllers
        # and long, and AES is switched on at the trust object (KB4492348) - no new trust.
        Title = "Trust Without AES for Kerberos"
        Risk = "Hint"
        BaseScore = 25
        Description = "Kerberos across this trust can use no AES. A referral ticket across a trust is encrypted with the trust key, in a type msDS-SupportedEncryptionTypes on the trust object allows - and a trust without that attribute supports RC4 and no AES (KB4492348). Microsoft's 2026 change that made AES the default for accounts leaves trusts alone (CVE-2026-20833). On an Active Directory trust the password behind the key is generated by the domain controllers and long, so RC4 is a weaker cipher rather than a key to guess; on a realm trust to MIT Kerberos it is the password an administrator typed, and a referral ticket into the realm - which any user of this domain can request where the realm trusts it - is encrypted with it: the same offline attack as Kerberoasting, made fast by RC4. A client that has RC4 switched off cannot cross such a trust and falls back to NTLM, or fails."
        Impact = @(
            "Referral tickets across the trust are RC4, so RC4 cannot be switched off on either side without breaking the trust"
            "Clients with RC4 disabled fall back to NTLM across the trust, or fail"
            "On a realm trust to MIT Kerberos with an administrator-chosen password: offline cracking of the trust key from a referral ticket any user can request where the realm trusts this domain"
        )
        Attack = @(
            "1. Attacker with any domain account requests a referral ticket into the partner realm, which works where the realm trusts this domain"
            "2. The ticket is encrypted with the RC4 trust key"
            "3. On a realm trust with a weak password, cracks the key offline like a Kerberoast hash"
            "4. With the key, forges inter-realm tickets into the partner realm"
        )
        Remediation = @(
            "Select 'The other domain supports Kerberos AES Encryption' in the properties of the trust, on both sides and for both directions - the trust stays, nothing is re-created"
            "Or keep RC4 for older clients and add AES with ksetup /setenctypeattr, run on a domain controller of the trusted domain"
            "On a realm trust to MIT Kerberos, give the trust a long random password and AES keys on both sides"
            "Monitor for RC4 across trusts: Event ID 4769 with ticket encryption type 0x17"
        )
        RemediationCommands = @(
            @{
                Description = "View the encryption types of every trust object"
                Command = "Get-ADObject -LDAPFilter '(objectClass=trustedDomain)' -Properties trustPartner,trustType,trustDirection,msDS-SupportedEncryptionTypes | Select-Object trustPartner,trustType,trustDirection,msDS-SupportedEncryptionTypes"
            }
            @{
                Description = "Add AES and keep RC4 for older clients (run on a DC of the trusted domain, naming the trusting one; repeat on the other side)"
                Command = "ksetup /setenctypeattr <trustingdomain> RC4-HMAC-MD5 AES128-CTS-HMAC-SHA1-96 AES256-CTS-HMAC-SHA1-96"
            }
            @{
                Description = "AES only: in Active Directory Domains and Trusts, Properties of the trust"
                Command = "# Trusts tab > the trust > Properties > 'The other domain supports Kerberos AES Encryption' - for incoming and outgoing, in both domains"
            }
            @{
                Description = "Monitor for RC4 usage in Kerberos (Event ID 4769 with encryption type 0x17)"
                Command = "Get-WinEvent -FilterHashtable @{LogName='Security';ID=4769} -MaxEvents 100 | Where-Object {`$_.Message -match '0x17'} | Select-Object TimeCreated,Message | Format-Table -Wrap"
            }
        )
        References = @(
            @{ Title = "Kerberos Unsupported etype error when authenticating across trust (KB4492348)"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/windows-security/unsupported-etype-error-accessing-trusted-domain" }
            @{ Title = "Kerberos KDC usage of RC4 - CVE-2026-20833"; Url = "https://support.microsoft.com/en-us/servicing/os/windows/2025/11/how-to-manage-kerberos-kdc-usage-of-rc4-for-service-account-ticket-issuance-changes-related-to-cve-2" }
            @{ Title = "Decrypting the Selection of Supported Kerberos Encryption Types"; Url = "https://techcommunity.microsoft.com/t5/core-infrastructure-and-security/decrypting-the-selection-of-supported-kerberos-encryption-types/ba-p/1628797" }
        )
        Tools = @("Rubeus", "Hashcat")
        MITRE = "T1558"
        Triggers = @(
            # On trustEncryptionTypes, not on the raw usesRC4 boolean.
            #
            # MS-ADTS defines TRUST_ATTRIBUTE_USES_RC4_ENCRYPTION for an MIT realm trust
            # only, so on an Active Directory trust the bit says nothing about the key -
            # and a trigger on the bare True made it a red finding worth 40 points on
            # every trust that happened to carry it. Get-DomainTrusts writes the bit into
            # trustEncryptionTypes only on a realm trust without the attribute, and the
            # severity is the one the module states: a weaker key is not on its own a
            # way in.
            #
            # Every value without AES: "Not set" (RC4 and no AES), RC4 alone, and DES
            # alone, which Windows refuses by default. The values are only ever these
            # and lists of RC4, AES and DES names.
            @{ Attribute = 'trustEncryptionTypes'; Pattern = '^(?!.*AES)'; Severity = 'Hint' }
        )
    }

    'TRUST_PASSWORD_STALE' = @{
        Title = "Trust Password No Longer Rotated"
        Risk = "Hint"
        BaseScore = 20
        Description = "The interdomain trust account of this trust - the user account <flatName>$ in this domain, which exists for every trust the partner extends to this domain (MS-ADTS 6.1.6.8) - has had the same password for 90 days or more. The trusting domain changes it about every 30 days, so the rotation has stopped: the partner is unreachable, decommissioned, or the change fails. The trust key derived from that password encrypts tickets across the trust. Whoever extracted it once - by DCSync of the trust account, or from a backup of a domain controller - keeps a working key, and the inter-realm tickets forged with it stay valid as long as the password does."
        Impact = @(
            "A trust key extracted once keeps working: inter-realm tickets forged with it stay valid"
            "A trust to a domain that no longer answers is left in place"
        )
        Attack = @(
            "1. Attacker with replication rights or a domain controller backup extracts the key of the trust account (DCSync of <flatName>$)"
            "2. Forges inter-realm tickets with it"
            "3. The key keeps working, because the password is no longer changed"
        )
        Remediation = @(
            "Verify the trust - netdom trust /verify, or Validate in Active Directory Domains and Trusts - and find out why the trusting domain stopped changing the password"
            "Remove trusts to domains that no longer exist"
            "Reset the trust password on both sides with netdom trust /resetOneSide and the same password; twice, if the key may have been extracted"
        )
        RemediationCommands = @(
            @{
                Description = "List the interdomain trust accounts and when their password was last set"
                Command = "Get-ADUser -LDAPFilter '(userAccountControl:1.2.840.113556.1.4.803:=2048)' -Properties pwdLastSet | Select-Object SamAccountName, @{n='PasswordLastSet';e={[DateTime]::FromFileTime(`$_.pwdLastSet)}}"
            }
            @{
                Description = "Verify the trust"
                Command = "netdom trust <trustingdomain> /domain:<trusteddomain> /verify"
            }
            @{
                Description = "Reset the trust password on this side (run on each side with the same password)"
                Command = "netdom trust <thisdomain> /domain:<otherdomain> /resetOneSide /passwordT:<password> /userO:administrator /passwordO:*"
            }
        )
        References = @(
            @{ Title = "How Domain and Forest Trusts Work - trust passwords (Microsoft)"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2003/cc773178(v=ws.10)" }
            @{ Title = "Essential Attributes of Interdomain Trust Accounts - MS-ADTS 6.1.6.8"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/ac527b5b-0e88-48a1-8c73-497d40388d04" }
            @{ Title = "Reset a trust password on one side of the trust - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/forest-recovery-guide/ad-forest-recovery-reset-trust" }
            @{ Title = "Reset Interdomain Trust Account (ITA) Credentials - CISA CM0145"; Url = "https://www.cisa.gov/eviction-strategies-tool/info-countermeasures/CM0145" }
        )
        Tools = @("Mimikatz", "Impacket")
        MITRE = "T1558"
        Triggers = @(
            @{ Attribute = 'trustPasswordRotation'; Pattern = '^Stale'; Severity = 'Hint' }
        )
    }

    'TRUST_BIDIRECTIONAL' = @{
        Title = "Bidirectional Trust Relationship"
        Risk = "Hint"
        BaseScore = 20
        Description = "This trust relationship is bidirectional, allowing authentication in both directions. While often required for functionality, this expands the attack surface compared to one-way trusts."
        Impact = @(
            "Compromise of either domain can affect the other"
            "Attack paths exist in both directions"
            "Lateral movement possible across trust boundary"
            "Increases blast radius of security incidents"
        )
        Attack = @(
            "1. Attacker compromises account in one domain"
            "2. Uses trust to access resources in partner domain"
            "3. Escalates privileges across trust boundary"
            "4. Potentially compromises both domains"
        )
        Remediation = @(
            "Review if bidirectional trust is required"
            "Consider one-way trust where possible"
            "Implement Selective Authentication to limit scope"
            "Enable SID Filtering to prevent SID History attacks"
        )
        References = @(
            @{ Title = "Trust Direction - Microsoft"; Url = "https://docs.microsoft.com/en-us/azure/active-directory-domain-services/concepts-forest-trust" }
        )
        Triggers = @(
            @{ Attribute = 'isBidirectional'; Pattern = '^True$'; Severity = 'Hint' }
        )
    }

    'TRUST_TRANSITIVE' = @{
        Title = "Transitive Trust Relationship"
        Risk = "Hint"
        BaseScore = 15
        Description = "This trust relationship is transitive, meaning trust extends to other domains that the partner trusts. This can create unintended trust paths and expand the attack surface."
        Impact = @(
            "Trust extends beyond directly connected domains"
            "May create unintended authentication paths"
            "Increases complexity of trust relationships"
            "Harder to audit all possible access paths"
        )
        Attack = @(
            "1. Attacker maps transitive trust chains"
            "2. Identifies indirect trust relationships"
            "3. Uses transitive trust to reach target domain"
            "4. Bypasses direct trust restrictions"
        )
        Remediation = @(
            "Document all transitive trust paths"
            "Consider non-transitive trusts for external partners"
            "Use Selective Authentication where possible"
            "Regularly audit trust relationships"
        )
        References = @(
            @{ Title = "Trust Transitivity - Microsoft"; Url = "https://docs.microsoft.com/en-us/azure/active-directory-domain-services/concepts-forest-trust" }
        )
        Triggers = @(
            # Within-forest trusts are always transitive by design (no special coloring)
            @{ Attribute = 'isTransitive'; Pattern = '^True$'; Custom = 'is_within_forest_trust'; Severity = 'Standard'; SeverityOnly = $true }
            @{ Attribute = 'isTransitive'; Pattern = '^True$'; Custom = 'is_not_within_forest_trust'; Severity = 'Hint' }
        )
    }

    'TRUST_SELECTIVE_AUTH' = @{
        Title = "Selective Authentication Enabled"
        Risk = "Secure"
        BaseScore = 0
        Description = "This trust has Selective Authentication (Cross-Organization) enabled. Users from the trusted domain can only access resources they have been explicitly granted permissions to, rather than having forest-wide authentication capability."
        Impact = @(
            "Restricts cross-trust authentication to explicitly permitted resources"
            "Prevents automatic forest-wide authentication for trusted users"
            "Requires explicit access grants on each resource server"
            "Significantly reduces the attack surface of the trust"
        )
        Remediation = @(
            "No action required - this is a recommended security configuration"
            "Ensure resource-side permissions are granted correctly"
            "Document which servers have Allowed-To-Authenticate configured"
        )
        References = @(
            @{ Title = "Selective Authentication - Microsoft"; Url = "https://docs.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/implementing-least-privilege-administrative-models" }
            @{ Title = "Trust Security Recommendations"; Url = "https://adsecurity.org/?p=1640" }
        )
        Triggers = @(
            @{ Attribute = 'isCrossOrg'; Pattern = '^True$'; Severity = 'Secure' }
        )
    }

    'TRUST_TREAT_AS_EXTERNAL' = @{
        Title = "Forest Trust Relaxed to External SID Filtering"
        Risk = "Finding"
        BaseScore = 70
        Description = "This forest trust carries TRUST_ATTRIBUTE_TREAT_AS_EXTERNAL. MS-ADTS 6.1.6.7.9 describes what that does: a cross-forest trust is treated as an external trust for the purposes of SID filtering, and cross-forest trusts are filtered more stringently than external ones - so the flag RELAXES the filtering rather than enforcing it. SID history naming any domain of the trusted forest is honoured here instead of only that forest's own namespaces."
        Impact = @(
            "SID history from the trusted forest is accepted for domains it does not own"
            "A Domain Admin SID of this domain, injected on the other side, is honoured on this one"
            "Whoever controls any domain of the trusted forest can reach this domain"
            "The flag is set deliberately, so it is a configuration decision rather than an oversight"
        )
        Attack = @(
            "1. Attacker gains control of any domain in the trusted forest"
            "2. Writes a SID of this domain into sIDHistory of an account there"
            "3. Authenticates across the trust, and this domain honours the injected SID"
        )
        Remediation = @(
            "Remove the flag unless the cross-forest SID history it allows is genuinely needed - and find out what needs it before removing it, because somebody set it for a migration"
            "Where a migration does need it, bound it in time: turn it off again once the SID history is no longer used"
            "Keep quarantine and SID filtering in place on every external and realm trust"
        )
        RemediationCommands = @(
            @{
                Description = "Show the trust attributes, so the flag can be confirmed before changing anything"
                Command = "Get-ADTrust -Filter * | Select-Object Name, Direction, ForestTransitive, SIDFilteringForestAware, SIDFilteringQuarantined, TrustAttributes"
            }
            @{
                Description = "Stop honouring SID history across the trust"
                Command = "netdom trust THIS.DOMAIN /domain:TRUSTED.FOREST /EnableSIDHistory:no"
            }
        )
        References = @(
            @{ Title = "Trust Attributes - MS-ADTS 6.1.6.7.9"; Url = "https://docs.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/e9a2d23c-c31e-4a6f-88a0-6646571e5720" }
            @{ Title = "Security Considerations for Trusts"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-considerations-for-trusts" }
        )
        Tools = @("netdom", "Get-ADTrust", "mimikatz")
        MITRE = "T1134.005"
        Triggers = @(
            # Only outside one forest. Within a single forest the flag is meaningless -
            # one forest is one security boundary - and a neutral line there is right.
            #
            # The definition used to read this flag as a hardening measure, Risk Secure
            # and "No action required - this is a recommended security configuration",
            # which is the opposite of what it does. The same module already knew: its
            # own sidFiltering row says "Weakened - TREAT_AS_EXTERNAL". Both appeared on
            # the same trust object, the green one carrying the tooltip that closed the
            # subject.
            @{ Attribute = 'isTreatAsExternal'; Pattern = '^True$'; Custom = 'is_not_within_forest_trust'; Severity = 'Finding' }

            # And the verdict line, so the row naming the regime carries this card instead
            # of the external-trust one, whose remediation - netdom /quarantine:yes - is
            # the wrong command here. "Weakened" is written only for a forest trust this
            # domain actually extends, which is the only place the flag does anything.
            @{ Attribute = 'sidFiltering'; Pattern = '^Weakened'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # OUTDATED SYSTEMS FINDINGS
    # ============================================================================

    'OS_EXTENDED_SECURITY_UPDATES_ONLY' = @{
        Title = "Operating System Past General Support, Inside the Paid ESU Window"
        Risk = "Hint"
        BaseScore = 30
        Description = "This machine's operating system is past the date Microsoft stopped shipping security updates to everyone, but within the window in which Extended Security Updates can be bought. Whether it is actually patched therefore depends on a purchase that Active Directory does not record: with ESU it receives critical and important fixes, without it has been unpatched since the general support end named on the row."
        Impact = @(
            "Without the extension the machine has the same exposure as any end-of-life system - known, unpatched vulnerabilities, and no fix coming"
            "With the extension it receives critical and important security updates only: no feature updates, no non-security fixes, and no new functionality"
            "ESU is not a state the directory records, so this is the one finding in the report that needs an answer from whoever administers the machine"
            "The window closes on the date named on the row, after which no extension is available at any price"
        )
        Attack = @(
            "The attacks are those of the underlying platform. For Windows Server 2012 R2 that includes every vulnerability patched since October 2023 on systems without ESU."
        )
        Remediation = @(
            "Establish whether Extended Security Updates were actually purchased and are being delivered - for Server 2012/2012 R2 that means an Azure Arc connection and an active subscription, for Windows 7 and Server 2008/2008 R2 a volume licensing agreement"
            "Plan the migration regardless: the ESU window has a hard end, named on the row, and there is nothing after it"
            "Where ESU is not in place, treat the machine as end-of-life today and isolate it accordingly - it has been unpatched since the general support end"
        )
        References = @(
            @{ Title = "Extended Security Updates FAQ"; Url = "https://learn.microsoft.com/en-us/lifecycle/faq/extended-security-updates" }
            @{ Title = "Microsoft Product Lifecycle"; Url = "https://learn.microsoft.com/en-us/lifecycle/products/" }
        )
        MITRE = "T1210"
        Triggers = @(
            @{ Attribute = 'osExtendedSecurityUpdates'; Severity = 'Hint' }
        )
    }

    'OUTDATED_OS' = @{
        Title = "End-of-Life Operating System"
        Risk = "Finding"
        BaseScore = 40
        Description = "This computer is running an operating system that has reached End-of-Life (EOL). EOL systems no longer receive security updates, making them vulnerable to all publicly disclosed exploits."
        Impact = @(
            "No security patches available for new vulnerabilities"
            "Known exploits exist with no fixes available"
            "Often targeted first in attacks due to guaranteed vulnerabilities"
            "May not support modern security features (Credential Guard, etc.)"
            "Compliance violations in regulated environments"
        )
        Attack = @(
            "1. Attacker identifies EOL systems in the environment"
            "2. Uses known exploits (EternalBlue, BlueKeep, etc.)"
            "3. Gains remote code execution"
            "4. Uses system as pivot point for further attacks"
        )
        Remediation = @(
            "Upgrade to supported operating system version"
            "If upgrade not possible, isolate system from network"
            "Implement compensating controls (strict firewall, monitoring)"
            "Plan migration path for legacy applications"
            "Document and accept risk if system must remain"
        )
        RemediationCommands = @(
            @{
                Description = "Identify all computers with end-of-life operating systems in the domain"
                Command = "Get-ADComputer -Filter * -Properties OperatingSystem,OperatingSystemVersion | Where-Object {`$_.OperatingSystem -match 'Windows (XP|Vista|7|8|Server 2003|Server 2008|Server 2012)'} | Select-Object Name,OperatingSystem,OperatingSystemVersion,DistinguishedName"
            }
            @{
                Description = "Check current OS version and build on local system"
                Command = "Get-ComputerInfo | Select-Object WindowsProductName,WindowsVersion,OsBuildNumber,OsHardwareAbstractionLayer"
            }
            @{
                Description = "Perform in-place upgrade to Windows Server 2025 (requires setup media)"
                Command = "# Mount Server 2025 ISO, then run: D:\setup.exe /auto upgrade /dynamicupdate enable /compat scanonly (test first), then: D:\setup.exe /auto upgrade /dynamicupdate enable (actual upgrade)"
            }
            @{
                Description = "Migrate server roles to new Windows Server using Windows Server Migration Tools"
                Command = "# On source server: Export-SmigServerSetting -Path C:\Migration -Verbose; On destination server: Import-SmigServerSetting -Path C:\Migration -SourcePhysicalAddress <MAC> -TargetPhysicalAddress <MAC> -Verbose"
            }
        )
        References = @(
            @{ Title = "Windows Lifecycle"; Url = "https://docs.microsoft.com/en-us/lifecycle/products/" }
            @{ Title = "EternalBlue (MS17-010)"; Url = "https://docs.microsoft.com/en-us/security-updates/securitybulletins/2017/ms17-010" }
            @{ Title = "Overview of Windows Server Upgrades"; Url = "https://learn.microsoft.com/en-us/windows-server/get-started/upgrade-overview" }
            @{ Title = "Perform an In-Place Upgrade of Windows Server"; Url = "https://learn.microsoft.com/en-us/windows-server/get-started/perform-in-place-upgrade" }
        )
        Tools = @("nmap", "Metasploit", "BlueKeep scanner")
        MITRE = "T1210"
        Triggers = @(
            @{ Attribute = 'eolDate'; Severity = 'Finding' }
            @{ Attribute = 'daysSinceEoL'; Severity = 'Finding' }
            @{ Attribute = 'operatingSystem'; Pattern = 'Windows (XP|Vista|7|8|Server 2003|Server 2008|Server 2012)'; Severity = 'Finding' }
        )
    }

    # Aging OS (Yellow/Hint) - still supported but nearing/past mainstream EOL
    'AGING_OS' = @{
        Title = "Aging Operating System"
        Risk = "Hint"
        BaseScore = 15
        Description = "This computer is running an operating system that is nearing end of extended support. While still receiving security updates (or ESU), these systems should be planned for migration before they reach EOL."
        Impact = @(
            "Windows Server 2016: Extended support ends Jan 2027 - approaching EOL"
            "Windows 10: Standard support ended Oct 2025, ESU available until Oct 2028"
            "May not support latest security features (Credential Guard enhancements, etc.)"
            "Reduced vendor support and slower security response"
        )
        Remediation = @(
            "Plan migration to current OS version (Server 2022/2025, Windows 11)"
            "Ensure Extended Security Updates (ESU) are active if available"
            "Monitor for security advisories specific to this OS version"
            "Prioritize these systems in your upgrade roadmap"
        )
        References = @(
            @{ Title = "Windows Server Lifecycle"; Url = "https://docs.microsoft.com/en-us/lifecycle/products/windows-server-2016" }
            @{ Title = "Windows 10 Lifecycle"; Url = "https://docs.microsoft.com/en-us/lifecycle/products/windows-10-enterprise-and-education" }
        )
        MITRE = "T1210"
        Triggers = @(
            @{ Attribute = 'operatingSystem'; Pattern = 'Windows 10\b|Server 2016'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # EXCHANGE FINDINGS
    # ============================================================================

    'EXCHANGE_VULNERABLE_VERSION' = @{
        Title = "Exchange Server Version Out of Support"
        Risk = "Finding"
        BaseScore = 45
        Description = "This Exchange server runs a product version whose support has ended, or ends within the year. What that means is that no security update exists for the next vulnerability of the ProxyLogon or ProxyShell class - and Exchange is the single most reliably attacked server role in an Active Directory, with a service account that reaches the directory. Which updates are installed is not visible from here: Active Directory records the product version, not the cumulative or security update level, so this finding is about the support status and not about a specific CVE. Confirming the patch level needs the Exchange Health Checker on the server itself, which is the first command below."
        Impact = @(
            "No security updates: the next critical vulnerability in this version stays open"
            "Exchange historically carries pre-authentication remote code execution bugs - ProxyLogon, ProxyShell and ProxyNotShell were all of that class"
            "The server reaches Active Directory through its own service account, so compromising it is rarely the last step"
            "Unsupported versions are the ones ransomware operators scan for, because the install base stays exploitable"
        )
        Attack = @(
            "1. Attacker fingerprints the Exchange version from the outside - the build number is in the OWA response"
            "2. Picks the published exploit chain for that version, or waits for the next one"
            "3. Gains code execution as SYSTEM on the Exchange server"
            "4. Uses the server's own directory permissions, or the credentials on it, to move into Active Directory"
        )
        Remediation = @(
            "Move to a supported version - Exchange Subscription Edition is the only line still receiving updates, and the upgrade path from 2016 and 2019 is in place"
            "Until then, run the Exchange Health Checker on the server to see which cumulative and security updates are missing: that is the question this finding cannot answer from the directory"
            "Enable Extended Protection for Authentication, which is what closes the relay half of these chains"
            "Keep the server off the internet where the role does not require it, and in front of a reverse proxy where it does"
            "Consider migration to Exchange Online"
        )
        RemediationCommands = @(
            @{
                Description = "Check current Exchange Server version and build number"
                Command = "Get-Command Exsetup.exe | ForEach-Object {`$_.FileVersionInfo}"
            }
            @{
                Description = "Download and run Exchange Server Health Checker script to identify missing patches"
                Command = "`$url='https://aka.ms/ExchangeHealthChecker'; `$path='C:\Temp\HealthChecker.ps1'; Invoke-WebRequest -Uri `$url -OutFile `$path; Set-Location C:\Temp; .\HealthChecker.ps1"
            }
            @{
                Description = "Check for latest Exchange security updates"
                Command = "# Visit https://learn.microsoft.com/en-us/exchange/new-features/build-numbers-and-release-dates to identify latest CU and SU for your Exchange version"
            }
            @{
                Description = "Enable Extended Protection for Authentication (mitigates NTLM relay attacks)"
                Command = "# Run Exchange Emergency Mitigation Service (EEMS): Get-Mitigations.ps1 script from Microsoft, or manually configure via IIS Manager for each virtual directory"
            }
        )
        References = @(
            @{ Title = "Exchange Vulnerabilities Overview"; Url = "https://docs.microsoft.com/en-us/exchange/new-features/build-numbers-and-release-dates" }
            @{ Title = "ProxyShell - CISA"; Url = "https://www.cisa.gov/uscert/ncas/alerts/aa21-321a" }
            @{ Title = "ProxyLogon Information"; Url = "https://proxylogon.com/" }
            @{ Title = "Microsoft Exchange ProxyNotShell Vulnerability"; Url = "https://www.csoonline.com/article/574205/microsoft-exchange-proxynotshell-vulnerability-explained-and-how-to-mitigate-it.html" }
        )
        Tools = @("Exchange Health Checker", "Nmap")
        MITRE = "T1190"
        Triggers = @(
            @{ Attribute = 'ExchangeVersion'; Custom = 'is_exchange_eol'; Severity = 'Finding' }
            @{ Attribute = 'ExchangeBuildNumber'; Custom = 'is_exchange_eol'; Severity = 'Finding' }
        )
    }

    # ========================================================================
    # EXCHANGE PERMISSIONS MODEL (Get-ExchangeInfrastructure)
    # Triggered on the 'PermissionsModel' attribute of ExchangePermissionsModel objects.
    # ========================================================================

    'EXCHANGE_SHARED_PERMISSIONS_MODEL' = @{
        Title = "Exchange Holds WriteDACL on the Domain Object (Shared Permissions Model)"
        Risk = "Finding"
        BaseScore = 75
        Description = "Exchange setup granted an Exchange group WriteDACL on the domain object itself, and the ACE is not inherit-only. Any member of that group can rewrite the domain DACL and add the replication rights DCSync needs. This is the escalation half of PrivExchange and it is what makes membership of Exchange Windows Permissions worth having."
        Impact = @(
            "A member of the group can grant itself DS-Replication-Get-Changes and -All"
            "That is DCSync: every password hash in the domain, including krbtgt"
            "Exchange Trusted Subsystem is nested in Exchange Windows Permissions, so every Exchange server computer account reaches this too"
            "An NTLM relay from an Exchange server is therefore a relay to domain compromise"
        )
        Attack = @(
            "1. Obtain any principal in Exchange Windows Permissions, or relay an Exchange server's machine authentication"
            "2. Write an ACE on the domain object granting the controlled principal the replication rights"
            "3. Run DCSync against a domain controller"
            "4. Forge a golden ticket from the krbtgt hash, or authenticate as any user"
        )
        Remediation = @(
            "Apply the inherit-only flag to the WriteDACL ACE so it no longer applies to the domain object (Microsoft documents this for the shared permissions model)"
            "Or move the organization to Active Directory split permissions, which removes the model entirely"
            "Keep Exchange Windows Permissions and Exchange Trusted Subsystem free of anything that is not an Exchange server"
            "Enable LDAP signing and channel binding so an Exchange server's authentication cannot be relayed to a domain controller"
        )
        RemediationCommands = @(
            @{
                Description = "Show the Exchange ACEs currently on the domain object"
                Command = "(Get-Acl 'AD:\DC=domain,DC=com').Access | Where-Object { `$_.IdentityReference -match 'Exchange' -and `$_.ActiveDirectoryRights -match 'WriteDacl|WriteOwner|GenericAll' } | Format-Table IdentityReference,ActiveDirectoryRights,PropagationFlags,InheritanceFlags -AutoSize"
            }
            @{
                Description = "Switch the organization to Active Directory split permissions"
                Command = "# Run from the Exchange installation media: .\Setup.exe /PrepareAD /ActiveDirectorySplitPermissions:true /IAcceptExchangeServerLicenseTerms"
            }
        )
        References = @(
            @{ Title = "Abusing Exchange: One API call away from Domain Admin"; Url = "https://dirkjanm.io/abusing-exchange-one-api-call-away-from-domain-admin/" }
            @{ Title = "Reducing permissions required to run Exchange Server when you use the Shared Permissions Model"; Url = "https://support.microsoft.com/en-us/topic/reducing-permissions-required-to-run-exchange-server-when-you-use-the-shared-permissions-model-e1972d47-d714-fd76-1fd5-7cdcb85408ed" }
            @{ Title = "Exchange-AD-Privesc - Domain Object"; Url = "https://github.com/gdedrouas/Exchange-AD-Privesc/blob/master/DomainObject/DomainObject.md" }
            @{ Title = "Configure Exchange for split permissions"; Url = "https://learn.microsoft.com/en-us/exchange/permissions/split-permissions/configure-exchange-for-split-permissions" }
        )
        Tools = @("PrivExchange", "ntlmrelayx", "BloodHound", "PowerView")
        MITRE = "T1068"
        Triggers = @(
            @{ Attribute = 'PermissionsModel'; Pattern = '^Shared permissions'; Severity = 'Finding' }
            # The evidence row too. It carries the ACE the verdict rests on, and leaving it
            # uncoloured put the one line that matters in the same grey as the four
            # inherit-only ones beside it.
            @{ Attribute = 'EffectiveDomainACEs'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_PERMISSIONS_MODEL_CLEAN' = @{
        Title = "Exchange Holds No Effective Escalation Rights on the Domain Object"
        Risk = "Secure"
        BaseScore = 0
        Description = "No Exchange group holds WriteDACL, WriteOwner or GenericAll on the domain object in a form that applies to that object. Either the ACE was narrowed with the inherit-only flag as Microsoft documents, the organization runs Active Directory split permissions, or the ACE was never present. The PrivExchange escalation path from Exchange group membership to DCSync does not exist here."
        Impact = @(
            "Membership of Exchange Windows Permissions does not by itself lead to DCSync"
            "Relaying an Exchange server's authentication does not reach the domain DACL through this path"
        )
        Remediation = @(
            "No action required for this check"
            "Keep LDAP signing and channel binding enforced - they close the relay path itself, not only its payoff"
        )
        References = @(
            @{ Title = "Exchange split permissions"; Url = "https://learn.microsoft.com/en-us/exchange/permissions/split-permissions/split-permissions" }
        )
        MITRE = "T1068"
        Triggers = @(
            @{ Attribute = 'PermissionsModel'; Pattern = '^Mitigated shared permissions|^Split permissions|^Clean'; Severity = 'Secure' }
        )
    }

    'EXCHANGE_AD_SPLIT_PERMISSIONS' = @{
        Title = "Exchange Runs With Active Directory Split Permissions"
        Risk = "Secure"
        BaseScore = 0
        Description = "The forest was prepared with /ActiveDirectorySplitPermissions, which is the hardened of the two Exchange permissions models. Exchange administrators and Exchange servers cannot create Active Directory security principals at all, and setup removed every Exchange Windows Permissions entry from the domain object - so membership of that group is no longer a route to the domain DACL. The Microsoft Exchange Protected Groups OU, which only this setup mode creates, is what records the choice."
        Impact = @(
            "Exchange Windows Permissions holds no access control entries on the domain object - that is what was read"
            "Creating users and groups, and changing distribution group membership, requires Active Directory tools and Active Directory permissions"
            "Not read here: whether Exchange Trusted Subsystem is a member of Exchange Windows Permissions. Setup does not nest them in this model, but the group membership itself is not part of this verdict - the privileged-groups section is where that is listed"
        )
        Remediation = @(
            "No action required - this is the hardened model"
            "Check the Exchange Trusted Subsystem entries separately: Microsoft's setup removes the Exchange Windows Permissions entries from the domain object, and names no others"
        )
        RemediationCommands = @(
            @{
                Description = "Show which Exchange groups still hold entries on the domain object"
                Command = "(Get-Acl 'AD:\DC=domain,DC=com').Access | Where-Object { `$_.IdentityReference -match 'Exchange' } | Format-Table IdentityReference,ActiveDirectoryRights,PropagationFlags,InheritedObjectType -AutoSize"
            }
        )
        References = @(
            @{ Title = "Split permissions in Exchange Server"; Url = "https://learn.microsoft.com/en-us/exchange/permissions/split-permissions/split-permissions" }
            @{ Title = "Configure Exchange Server for split permissions"; Url = "https://learn.microsoft.com/en-us/exchange/permissions/split-permissions/configure-exchange-for-split-permissions" }
        )
        MITRE = "T1068"
        Triggers = @(
            # Only the enabled state is coloured. "Not enabled" is Exchange's default, and
            # marking every stock installation would be noise - where it matters, the
            # PermissionsModel row above already carries the finding.
            @{ Attribute = 'ADSplitPermissions'; Pattern = '^Enabled'; Severity = 'Secure' }
        )
    }

    # ========================================================================
    # EXCHANGE SMTP RECEIVE CONNECTORS (Get-ExchangeInfrastructure)
    # Triggered on the 'RelayStatus' attribute of ExchangeReceiveConnector objects.
    # ========================================================================

    'EXCHANGE_SMTP_OPEN_RELAY' = @{
        Title = "SMTP Receive Connector Relays for Unauthenticated Senders"
        Risk = "Finding"
        BaseScore = 45
        Description = "The connector's security descriptor grants ms-Exch-SMTP-Accept-Any-Recipient to an unauthenticated principal (Anonymous Logon or Everyone). A session that presents no credential can therefore hand the server mail addressed to any domain, and the server will deliver it. This is usually an application relay connector whose remote IP range was widened past the application it was built for."
        Impact = @(
            "The server sends mail on behalf of anyone who can reach the listening port"
            "The organization's own IP reputation and mail domains carry the traffic"
            "Blocklisting of the sending address affects all legitimate mail from the organization"
            "Combined with an internal sender address it becomes internal phishing that passes every trust indicator"
        )
        Attack = @(
            "1. Reach the connector's listening port from an address inside its remote IP range"
            "2. Open an SMTP session without authenticating"
            "3. Issue MAIL FROM with an internal address and RCPT TO with an external one"
            "4. The message leaves the organization as legitimate outbound mail"
        )
        Remediation = @(
            "Narrow the connector's remote IP ranges to the hosts that actually need to relay"
            "Remove ms-Exch-SMTP-Accept-Any-Recipient from Anonymous Logon where relay is not required"
            "Prefer an authenticated relay connector over an anonymous one"
        )
        RemediationCommands = @(
            @{
                Description = "Show which principals hold relay rights on each receive connector"
                Command = "Get-ReceiveConnector | ForEach-Object { Get-ADPermission `$_.Identity | Where-Object { `$_.ExtendedRights -like '*Accept-Any-Recipient*' } | Select-Object Identity,User,ExtendedRights }"
            }
            @{
                Description = "Remove the anonymous relay permission from a connector"
                Command = "Get-ReceiveConnector 'CONNECTOR_NAME' | Remove-ADPermission -User 'NT AUTHORITY\ANONYMOUS LOGON' -ExtendedRights 'Ms-Exch-SMTP-Accept-Any-Recipient'"
            }
            @{
                Description = "Show the remote IP ranges a connector accepts"
                Command = "Get-ReceiveConnector | Select-Object Name,Bindings,RemoteIPRanges,PermissionGroups,AuthMechanism"
            }
        )
        References = @(
            @{ Title = "Allow anonymous relay on Exchange servers"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/allow-anonymous-relay" }
            @{ Title = "Receive connectors in Exchange Server"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/receive-connectors" }
        )
        Tools = @("swaks", "telnet", "nmap smtp-open-relay")
        MITRE = "T1566"
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Open relay'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_SMTP_ANONYMOUS_SPOOFING' = @{
        Title = "SMTP Receive Connector Lets Unauthenticated Senders Use Internal Addresses"
        Risk = "Finding"
        BaseScore = 50
        Description = "The connector grants ms-Exch-SMTP-Accept-Any-Sender or ms-Exch-SMTP-Accept-Authoritative-Domain-Sender to an unauthenticated principal. A session that presents no credential can put any address, including an internal one, in the sender field, and the message is then delivered as internal mail."
        Impact = @(
            "Mail arrives in employee mailboxes from an internal address that nobody sent"
            "SPF, DKIM and DMARC do not apply - the message never leaves the organization's own perimeter"
            "Outlook shows the sender as a known internal contact, photo and display name included"
            "It is the highest-fidelity phishing primitive an internal network offers"
        )
        Attack = @(
            "1. Reach the connector from an address inside its remote IP range"
            "2. Open an SMTP session without authenticating"
            "3. Set MAIL FROM to an executive's internal address and RCPT TO to a target employee"
            "4. The message is delivered as internal mail from that executive"
        )
        Remediation = @(
            "Remove the accept-sender extended rights from Anonymous Logon on this connector"
            "Where an application must send as an internal address, give it an authenticated connector instead"
            "Restrict the connector's remote IP ranges to the sending hosts"
        )
        RemediationCommands = @(
            @{
                Description = "Show which connectors let anonymous sessions choose the sender"
                Command = "Get-ReceiveConnector | ForEach-Object { Get-ADPermission `$_.Identity | Where-Object { `$_.User -like '*ANONYMOUS LOGON*' -and `$_.ExtendedRights -like '*Accept-A*-Sender*' } | Select-Object Identity,User,ExtendedRights }"
            }
            @{
                Description = "Remove the anonymous sender-spoofing permission from a connector"
                Command = "Get-ReceiveConnector 'CONNECTOR_NAME' | Remove-ADPermission -User 'NT AUTHORITY\ANONYMOUS LOGON' -ExtendedRights 'Ms-Exch-SMTP-Accept-Authoritative-Domain-Sender'"
            }
        )
        References = @(
            @{ Title = "Scenarios for custom Receive connectors"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/custom-receive-connectors" }
            @{ Title = "Allow anonymous relay on Exchange servers"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/allow-anonymous-relay" }
        )
        Tools = @("swaks", "telnet")
        MITRE = "T1534"
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Sender spoofing'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_SMTP_BROAD_RELAY' = @{
        Title = "SMTP Receive Connector Relays for Every Authenticated Principal"
        Risk = "Hint"
        BaseScore = 25
        Description = "The connector grants a relay or sender right to a broad principal such as Authenticated Users or Domain Users. Authentication is required, but every account in the domain satisfies it, so a single compromised low-privilege account can send mail through this connector."
        Impact = @(
            "Any domain account, including a service account with a weak password, can relay through this connector"
            "Outbound mail carries the organization's reputation"
        )
        Remediation = @(
            "Grant the relay rights to a dedicated group holding the accounts that actually relay"
            "Review the connector's remote IP ranges alongside the permission"
        )
        References = @(
            @{ Title = "Receive connectors in Exchange Server"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/receive-connectors" }
        )
        MITRE = "T1566"
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Broad relay'; Severity = 'Hint' }
        )
    }

    'EXCHANGE_SMTP_ANONYMOUS_AUTHENTICATED' = @{
        Title = "SMTP Receive Connector Treats Unauthenticated Mail as Authenticated"
        Risk = "Finding"
        BaseScore = 45
        Description = "This receive connector grants ms-Exch-SMTP-Accept-Authentication-Flag to an anonymous principal. The permission 'controls whether messages from SMTP clients or servers are treated as authenticated' (Microsoft): without it, unauthenticated mail is identified as external. With it, a message from anyone who reaches the connector counts as authenticated - it is accepted by distribution groups that take mail from internal senders only (RequireSenderAuthenticationEnabled), and it loses the marking that tells a recipient it came from outside. Only the Exchange server permission groups carry this right by default; the Anonymous users group never does."
        Impact = @(
            "Anonymous senders reach distribution groups restricted to internal senders"
            "Mail from outside is not marked as external, so recipients and transport rules take it for internal mail"
            "Combined with a spoofed internal sender address, phishing that looks entirely internal"
        )
        Attack = @(
            "1. Attacker finds the connector that accepts anonymous sessions"
            "2. Submits a message to a distribution group that accepts internal senders only"
            "3. The message is treated as authenticated and delivered without an external marking"
        )
        Remediation = @(
            "Remove ms-Exch-SMTP-Accept-Authentication-Flag from the anonymous principal: Remove-ADPermission -Identity 'CONNECTOR' -User 'NT AUTHORITY\ANONYMOUS LOGON' -ExtendedRights ms-Exch-SMTP-Accept-Authentication-Flag"
            "Where a trusted relay host needs it, give that host its own connector restricted by RemoteIPRanges and authenticate it"
            "Check whether the connector uses 'Externally secured' authentication on a network that is not actually secured"
        )
        RemediationCommands = @(
            @{
                Description = "Show the anonymous grants on the connector"
                Command = "Get-ADPermission -Identity 'CONNECTOR' -User 'NT AUTHORITY\ANONYMOUS LOGON' | Format-Table ExtendedRights -AutoSize"
            }
        )
        References = @(
            @{ Title = "Receive connectors - permission groups and permissions (Microsoft)"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/receive-connectors" }
        )
        Tools = @("swaks", "Exchange Management Shell")
        MITRE = "T1566"
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Unauthenticated mail treated as authenticated'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_SMTP_ANONYMOUS_BYPASS_ANTISPAM' = @{
        Title = "SMTP Receive Connector Lets Unauthenticated Mail Bypass Anti-Spam"
        Risk = "Finding"
        BaseScore = 50
        Description = "This receive connector grants ms-Exch-Bypass-Anti-Spam to an anonymous principal. Mail arriving unauthenticated on this connector therefore skips the spam and malware filtering that exists for exactly that path, and Exchange treats it as internally classified material from then on. The grant is normally made for an internal relay host or a scanning appliance that filters first; on a connector that anonymous senders can reach it is an open door for everything the filters exist to stop."
        Impact = @(
            "Unauthenticated mail reaches mailboxes without spam or malware filtering"
            "Exchange marks it as having passed inspection, so downstream rules that trust that marking also let it through"
            "Phishing and malware delivery become a question of reaching the connector, which is the easy part"
            "The same grant usually carries headers-routing, which lets the sender dictate how the message appears to have travelled"
        )
        Attack = @(
            "1. Attacker finds the connector that accepts anonymous sessions - port 25 on a published host"
            "2. Submits a message with a malicious attachment or a credential phishing link"
            "3. The bypass grant means no filtering is applied to it"
            "4. The message is delivered and looks like mail that passed inspection"
        )
        Remediation = @(
            "Remove ms-Exch-Bypass-Anti-Spam from the anonymous principal: Remove-ADPermission -Identity 'CONNECTOR' -User 'NT AUTHORITY\ANONYMOUS LOGON' -ExtendedRights ms-Exch-Bypass-Anti-Spam"
            "Where an upstream appliance really does the filtering, give that host its own connector restricted by RemoteIPRanges, and grant the bypass only there"
            "Confirm which hosts actually deliver to this connector before changing it - a shared internet-facing connector may carry both kinds of traffic"
        )
        RemediationCommands = @(
            @{
                Description = "Show the anonymous grants on the connector"
                Command = "Get-ADPermission -Identity 'CONNECTOR' -User 'NT AUTHORITY\ANONYMOUS LOGON' | Format-Table ExtendedRights -AutoSize"
            }
        )
        References = @(
            @{ Title = "Receive connector permissions - Microsoft"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/receive-connector-permissions" }
            @{ Title = "Anti-spam protection - Microsoft"; Url = "https://learn.microsoft.com/en-us/exchange/antispam-and-antimalware/antispam-protection/antispam-protection" }
        )
        Tools = @("swaks", "Exchange Management Shell")
        MITRE = "T1566"
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Anonymous anti-spam bypass'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_SMTP_BROAD_SPOOFING' = @{
        Title = "SMTP Receive Connector Lets Every Domain Principal Spoof an Internal Sender"
        Risk = "Finding"
        BaseScore = 55
        Description = "This receive connector grants ms-Exch-SMTP-Accept-Authoritative-Domain-Sender, or ms-Exch-SMTP-Accept-Any-Sender, to a broad principal - Authenticated Users, Domain Users, Everyone or one of their siblings. Any account in the domain can therefore submit mail whose From address is an internal one: the chief executive, the help desk, the payroll mailbox. The message arrives with every internal marker a recipient uses to trust it, and SPF, DKIM and DMARC say nothing about a message that never left the organisation."
        Impact = @(
            "Any domain account can send mail as any internal address through this connector"
            "The message is internal, so it passes the checks that exist for external mail and lands without a banner"
            "That is the opening move of most internal phishing: a password reset, an invoice change, an instruction from a manager"
            "It also defeats approval workflows that trust the sender address of an internal message"
        )
        Attack = @(
            "1. Attacker authenticates to the connector with any domain account"
            "2. Submits a message with MAIL FROM and the From header set to an internal address"
            "3. Exchange accepts it as authoritative because the connector grants the sender right"
            "4. The recipient sees an ordinary internal mail from a colleague"
        )
        Remediation = @(
            "Remove ms-Exch-SMTP-Accept-Authoritative-Domain-Sender and ms-Exch-SMTP-Accept-Any-Sender from the broad principal: Remove-ADPermission -Identity 'CONNECTOR' -User 'DOMAIN\Domain Users' -ExtendedRights ms-Exch-SMTP-Accept-Authoritative-Domain-Sender"
            "Where an application needs to send as an internal address, give that application its own account and grant the right to it alone, on a connector that only it can reach"
            "Restrict the connector's RemoteIPRanges to the hosts that are meant to use it"
            "Check the other connectors too: the grant is often copied from one to the next"
        )
        RemediationCommands = @(
            @{
                Description = "Show who holds sender rights on the connector"
                Command = "Get-ADPermission -Identity 'CONNECTOR' | Where-Object { `$_.ExtendedRights -like '*Sender*' } | Format-Table User, ExtendedRights -AutoSize"
            }
        )
        References = @(
            @{ Title = "Receive connector permissions - Microsoft"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/receive-connector-permissions" }
            @{ Title = "Anti-spoofing protection - Microsoft"; Url = "https://learn.microsoft.com/en-us/defender-office-365/anti-phishing-protection-spoofing-about" }
        )
        Tools = @("swaks", "telnet", "Exchange Management Shell")
        MITRE = "T1534"
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Broad sender spoofing'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_SMTP_CONNECTOR_AUTHENTICATED' = @{
        Title = "SMTP Receive Connector Requires Authentication"
        Risk = "Secure"
        BaseScore = 0
        Description = "The connector grants no SMTP extended right to an unauthenticated or broad principal. A sender has to authenticate before the connector will accept a message from it."
        Impact = @(
            "No anonymous relay and no anonymous sender spoofing through this connector"
        )
        Remediation = @(
            "No action required for this connector"
        )
        References = @(
            @{ Title = "Receive connectors in Exchange Server"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/receive-connectors" }
        )
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Authenticated senders only'; Severity = 'Secure' }
        )
    }

    'EXCHANGE_SMTP_CONNECTOR_UNREADABLE' = @{
        Title = "SMTP Receive Connector Permissions Could Not Be Read"
        Risk = "Hint"
        BaseScore = 10
        Description = "The connector object's security descriptor was not returned, so what it grants an unauthenticated sender is unknown. This is not the same as a clean connector - it is a connector that was not assessed."
        Impact = @(
            "The connector's relay and sender-spoofing exposure is unknown"
        )
        Remediation = @(
            "Re-run with an account that can read nTSecurityDescriptor on the Configuration partition"
            "Or review the connector directly with Get-ADPermission"
        )
        References = @(
            @{ Title = "Receive connectors in Exchange Server"; Url = "https://learn.microsoft.com/en-us/exchange/mail-flow/connectors/receive-connectors" }
        )
        Triggers = @(
            @{ Attribute = 'RelayStatus'; Pattern = '^Unknown'; Severity = 'Hint' }
        )
    }

    # ========================================================================
    # EXCHANGE HYBRID DEPLOYMENT (Get-ExchangeInfrastructure)
    # Triggered on the 'HybridStatus' attribute of ExchangeHybridConfiguration objects.
    # ========================================================================

    'EXCHANGE_HYBRID_DEPLOYMENT' = @{
        Title = "Exchange Hybrid Deployment - On-Premises Compromise Reaches the Cloud Tenant"
        Risk = "Hint"
        BaseScore = 30
        Description = "The organization is in a hybrid relationship with Exchange Online. In the classic model the on-premises servers and the cloud tenant share one service principal, and CVE-2025-53786 uses that shared trust to escalate from administrative access on an on-premises Exchange server into Exchange Online. Whether the dedicated hybrid application has been deployed cannot be read from Active Directory, so this reports the exposure rather than the patch state - it needs confirming against the servers themselves."
        Impact = @(
            "Administrative access to an on-premises Exchange server can be turned into privileges in the cloud tenant"
            "The escalation leaves little in the tenant's own audit trail, because it arrives through a trusted principal"
            "Every other Exchange finding in this report gains the tenant as additional blast radius"
        )
        Attack = @(
            "1. Gain administrative access to an on-premises Exchange server through any of the paths in this report"
            "2. Use the shared service principal's credentials to obtain tokens against Exchange Online"
            "3. Act in the tenant as a trusted first-party application"
        )
        Remediation = @(
            "Install the Exchange hotfix (April 2025 or newer) and deploy the dedicated Exchange hybrid application"
            "Reset the shared service principal's credentials after switching, as Microsoft's guidance instructs"
            "Verify with Microsoft's Exchange Server Health Checker that the dedicated app is in use"
            "Treat every on-premises Exchange server as a tier-0 asset for as long as the hybrid trust exists"
        )
        RemediationCommands = @(
            @{
                Description = "Check whether the dedicated hybrid application is configured"
                Command = "# Run on an Exchange server: .\HealthChecker.ps1 -Server SERVERNAME  (reports the hybrid application state)"
            }
            @{
                Description = "Show the hybrid configuration recorded on-premises"
                Command = "Get-HybridConfiguration | Format-List"
            }
        )
        References = @(
            @{ Title = "CVE-2025-53786 - Exchange Server Hybrid Deployment Elevation of Privilege"; Url = "https://msrc.microsoft.com/update-guide/en-US/vulnerability/CVE-2025-53786" }
            @{ Title = "Deploy dedicated Exchange hybrid app"; Url = "https://learn.microsoft.com/en-us/exchange/hybrid-deployment/deploy-dedicated-exchange-hybrid-app" }
            @{ Title = "MDVM guidance for CVE-2025-53786"; Url = "https://techcommunity.microsoft.com/blog/vulnerability-management/mdvm-guidance-for-cve-2025-53786-exchange-hybrid-privilege-escalation/4442337" }
        )
        MITRE = "T1078.004"
        Triggers = @(
            @{ Attribute = 'HybridStatus'; Pattern = '^Hybrid with Exchange Online'; Severity = 'Hint' }
        )
    }

    # ========================================================================
    # EXCHANGE RBAC ROLE ASSIGNMENTS (Get-ExchangeRBACAssignments)
    # Triggered on the 'RiskVerdict' attribute of ExchangeRoleAssignment objects.
    # Every pattern is anchored and starts with a distinct word: the definition table is
    # an unordered hashtable, so two triggers that can both match one value would pick a
    # winner at random.
    # ========================================================================

    'EXCHANGE_RBAC_MAILBOX_IMPORT_EXPORT' = @{
        Title = "Mailbox Import Export Role Assigned"
        Risk = "Finding"
        BaseScore = 65
        Description = "The Mailbox Import Export role lets its holder export the contents of any mailbox in the organization to a PST file, and import one back. Exchange ships this role held by nobody, not even Organization Management - that group may only assign it, through a delegating assignment - so every assignment of it was made deliberately by someone. A delegating assignment elsewhere is one step short of the role: its holder can assign it, to an account of its own as well."
        Impact = @(
            "The complete contents of any mailbox can be written to a file and taken away"
            "No mailbox owner is notified and no mailbox permission is changed"
            "The import direction historically served as a web shell delivery path, by exporting a crafted message into a web-served directory"
        )
        Attack = @(
            "1. Obtain the account holding the role"
            "2. New-MailboxExportRequest against the target mailbox, writing to a UNC path the attacker controls"
            "3. Collect the PST and read it offline"
        )
        Remediation = @(
            "Remove the assignment where the export capability is not an ongoing operational need"
            "Where it is needed, assign it temporarily and remove it again afterwards"
            "Restrict the export destination to a monitored share"
            "Audit New-MailboxExportRequest in the Exchange admin audit log"
        )
        RemediationCommands = @(
            @{
                Description = "Show every holder of the Mailbox Import Export role"
                Command = "Get-ManagementRoleAssignment -Role 'Mailbox Import Export' | Select-Object Name,RoleAssigneeName,RoleAssigneeType,AssignmentMethod"
            }
            @{
                Description = "Remove a Mailbox Import Export role assignment"
                Command = "Remove-ManagementRoleAssignment -Identity 'ASSIGNMENT_NAME' -Confirm:`$false"
            }
            @{
                Description = "Review recent mailbox export requests"
                Command = "Get-MailboxExportRequest | Select-Object Name,Mailbox,FilePath,Status,RequestQueue"
            }
        )
        References = @(
            @{ Title = "Microsoft Exchange - Mailbox Post Compromise"; Url = "https://pentestlab.blog/2019/09/11/microsoft-exchange-mailbox-post-compromise/" }
            @{ Title = "Understanding management role assignments"; Url = "https://learn.microsoft.com/en-us/exchange/understanding-management-role-assignments-exchange-2013-help" }
        )
        Tools = @("Exchange Management Shell")
        MITRE = "T1114.002"
        Triggers = @(
            @{ Attribute = 'RiskVerdict'; Pattern = '^Mailbox export'; Severity = 'Finding' }

            # The damping for every RBAC verdict, not only this one: the trigger index is
            # keyed by attribute, so a severity-only trigger on RiskVerdict is consulted
            # for whatever value that attribute carries. An assignee that is already
            # privileged gains nothing from the role - the card and its remediation stay,
            # the colour says the assignment is hygiene rather than a path. Same mechanism
            # as ra_signature_gated on the certificate templates.
            @{ Attribute = 'RiskVerdict'; Custom = 'rbac_assignee_already_privileged'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    'EXCHANGE_RBAC_APPLICATION_IMPERSONATION' = @{
        Title = "ApplicationImpersonation Role Assigned"
        Risk = "Finding"
        BaseScore = 70
        Description = "The ApplicationImpersonation role lets its holder act as any mailbox in the organization over Exchange Web Services. Exchange ships it on the Hygiene Management role group only, for the anti-spam integration, and lets Organization Management assign it; every other assignment was made by someone. It is normally granted to an integration service account, and it is the single most useful Exchange role an attacker can inherit: one account, every mailbox, over a protocol that needs no special client. A delegating assignment is one step short of the role: its holder can assign it, to an account of its own as well."
        Impact = @(
            "Read, send and delete mail as any user in the organization"
            "Search every mailbox for credentials, contracts or security documentation"
            "Send mail as an executive from that executive's real mailbox - it appears in their Sent Items"
            "No mailbox permission is changed and the mailbox owner sees nothing"
        )
        Attack = @(
            "1. Compromise the account or service that holds the role, often a low-privilege integration account with a static password"
            "2. Connect to EWS with an impersonation header naming the target mailbox"
            "3. Enumerate and search mailboxes at will (MailSniper automates this)"
        )
        Remediation = @(
            "Remove the assignment where no application needs it"
            "Where an application does, scope the assignment with a management scope to the mailboxes it actually serves"
            "Treat every account holding this role as a tier-0 credential: long random password, no interactive logon, monitored"
            "Prefer modern per-application access over an organization-wide impersonation role"
        )
        RemediationCommands = @(
            @{
                Description = "Show every holder of ApplicationImpersonation"
                Command = "Get-ManagementRoleAssignment -Role ApplicationImpersonation | Select-Object Name,RoleAssigneeName,RoleAssigneeType,CustomRecipientWriteScope"
            }
            @{
                Description = "Remove an ApplicationImpersonation assignment"
                Command = "Remove-ManagementRoleAssignment -Identity 'ASSIGNMENT_NAME' -Confirm:`$false"
            }
            @{
                Description = "Scope an assignment to a defined set of mailboxes instead of the whole organization"
                Command = "New-ManagementScope -Name 'AppMailboxes' -RecipientRestrictionFilter { Department -eq 'Service' }; Set-ManagementRoleAssignment -Identity 'ASSIGNMENT_NAME' -CustomRecipientWriteScope 'AppMailboxes'"
            }
        )
        References = @(
            @{ Title = "MailSniper - weaponizing Exchange features"; Url = "https://starlog.is/articles/ai-dev-tools/dafthack-mailsniper" }
            @{ Title = "Microsoft Exchange - Mailbox Post Compromise"; Url = "https://pentestlab.blog/2019/09/11/microsoft-exchange-mailbox-post-compromise/" }
        )
        Tools = @("MailSniper", "Exchange Web Services")
        MITRE = "T1114.002"
        Triggers = @(
            @{ Attribute = 'RiskVerdict'; Pattern = '^Mailbox impersonation'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_RBAC_ROLE_MANAGEMENT' = @{
        Title = "Role Management Role Assigned Outside Organization Management"
        Risk = "Finding"
        BaseScore = 70
        Description = "The Role Management role lets its holder create and assign Exchange management roles, including to itself. Exchange ships it assigned to Organization Management; an assignment anywhere else means that principal can grant itself ApplicationImpersonation, Mailbox Import Export, or any other role in the organization."
        Impact = @(
            "Self-escalation to every other Exchange capability in one command"
            "Access to all mailbox content by way of the roles it can grant"
            "A quiet persistence mechanism - a new role assignment looks like administration, not intrusion"
        )
        Attack = @(
            "1. Obtain the principal holding Role Management"
            "2. New-ManagementRoleAssignment granting itself ApplicationImpersonation"
            "3. Read every mailbox over EWS"
        )
        Remediation = @(
            "Remove the assignment; Role Management belongs with Organization Management"
            "Audit New-ManagementRoleAssignment in the Exchange admin audit log"
            "Review every existing assignment after removing this one - the holder may already have granted itself others"
        )
        RemediationCommands = @(
            @{
                Description = "Show every holder of Role Management"
                Command = "Get-ManagementRoleAssignment -Role 'Role Management' | Select-Object Name,RoleAssigneeName,RoleAssigneeType"
            }
            @{
                Description = "List role assignments created recently"
                Command = "Search-AdminAuditLog -Cmdlets New-ManagementRoleAssignment -StartDate (Get-Date).AddDays(-90) | Select-Object RunDate,Caller,ObjectModified"
            }
        )
        References = @(
            @{ Title = "Understanding management role assignments"; Url = "https://learn.microsoft.com/en-us/exchange/understanding-management-role-assignments-exchange-2013-help" }
            @{ Title = "Exchange RBAC in action"; Url = "https://practical365.com/exchange-server-role-based-access-control-in-action/" }
        )
        Tools = @("Exchange Management Shell")
        MITRE = "T1098"
        Triggers = @(
            @{ Attribute = 'RiskVerdict'; Pattern = '^Role management'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_RBAC_UNSCOPED_ROLE_MANAGEMENT' = @{
        Title = "Unscoped Role Management Role Assigned"
        Risk = "Finding"
        BaseScore = 75
        Description = "The Unscoped Top Level Role Management role lets its holder create unscoped management roles, which may contain arbitrary scripts and cmdlets rather than only Exchange ones. Exchange ships this role held by nobody - Organization Management may only assign it - and it converts Exchange administration into code execution. A delegating assignment elsewhere is one step short of the role: its holder can assign it, to an account of its own as well."
        Impact = @(
            "Arbitrary script execution in the Exchange management context"
            "Code runs on the Exchange server, which is a domain member with far-reaching AD permissions"
            "The role publishes itself - anyone assigned the unscoped role can run its contents"
        )
        Attack = @(
            "1. Obtain the principal holding the role"
            "2. New-ManagementRole -UnScopedTopLevel wrapping an attacker-supplied script"
            "3. Assign the new role and invoke it"
        )
        Remediation = @(
            "Remove the assignment - very few organizations have a legitimate use for it"
            "Review every existing unscoped role for content that is not expected"
            "Audit New-ManagementRole in the Exchange admin audit log"
        )
        RemediationCommands = @(
            @{
                Description = "Show every holder of the unscoped role management capability"
                Command = "Get-ManagementRoleAssignment -Role 'Unscoped Role Management' | Select-Object Name,RoleAssigneeName,RoleAssigneeType"
            }
            @{
                Description = "List all unscoped top-level roles in the organization"
                Command = "Get-ManagementRole | Where-Object { `$_.RoleType -eq 'UnScoped' } | Select-Object Name,RoleType,Description"
            }
        )
        References = @(
            @{ Title = "Understanding management roles"; Url = "https://learn.microsoft.com/en-us/exchange/understanding-management-roles-exchange-2013-help" }
        )
        Tools = @("Exchange Management Shell")
        MITRE = "T1059.001"
        Triggers = @(
            @{ Attribute = 'RiskVerdict'; Pattern = '^Unscoped role management'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_RBAC_MAILBOX_SEARCH' = @{
        Title = "Mailbox Search Role Assigned Outside Discovery Management"
        Risk = "Finding"
        BaseScore = 60
        Description = "The Mailbox Search role lets its holder run discovery searches across every mailbox in the organization and copy the results into a discovery mailbox. Exchange ships it assigned to Discovery Management, a group that is normally empty; an assignment anywhere else is organization-wide read access to mail content under an administrative label."
        Impact = @(
            "Keyword search across every mailbox, including those of executives and administrators"
            "Results are copied into a discovery mailbox the holder can then open"
            "Passwords, contracts and security documentation are found by searching for them"
            "The activity looks like eDiscovery, which is exactly what it is"
        )
        Attack = @(
            "1. Obtain the principal holding the role"
            "2. New-MailboxSearch with a keyword list across all mailboxes"
            "3. Open the target discovery mailbox and read the copied items"
        )
        Remediation = @(
            "Remove the assignment; discovery belongs to a named, monitored group"
            "Keep Discovery Management empty and populate it only for the duration of a case"
            "Audit New-MailboxSearch and access to discovery mailboxes"
        )
        RemediationCommands = @(
            @{
                Description = "Show every holder of the Mailbox Search role"
                Command = "Get-ManagementRoleAssignment -Role 'Mailbox Search' | Select-Object Name,RoleAssigneeName,RoleAssigneeType"
            }
            @{
                Description = "List existing discovery searches"
                Command = "Get-MailboxSearch | Select-Object Name,CreatedBy,SearchQuery,TargetMailbox,Status"
            }
        )
        References = @(
            @{ Title = "Understanding management role assignments"; Url = "https://learn.microsoft.com/en-us/exchange/understanding-management-role-assignments-exchange-2013-help" }
        )
        Tools = @("Exchange Management Shell")
        MITRE = "T1114.002"
        Triggers = @(
            @{ Attribute = 'RiskVerdict'; Pattern = '^Mailbox search'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_RBAC_AD_PERMISSIONS' = @{
        Title = "Active Directory Permissions Role Assigned Outside Organization Management"
        Risk = "Finding"
        BaseScore = 70
        Description = "The Active Directory Permissions role exposes Add-ADPermission and Remove-ADPermission, which write Active Directory ACLs through the Exchange Trusted Subsystem's own privileges. Exchange ships it assigned to Organization Management. An assignment elsewhere hands a principal the ability to change directory permissions using Exchange's rights rather than its own."
        Impact = @(
            "Directory ACLs can be modified with the Exchange Trusted Subsystem's permissions"
            "Where the shared permissions model is in place, that reaches the domain object"
            "Send-As and Receive-As can be granted on any mailbox, which is mailbox access without a mailbox permission"
        )
        Attack = @(
            "1. Obtain the principal holding the role"
            "2. Add-ADPermission granting the attacker Send-As on a target mailbox, or an escalation ACE on a directory object"
            "3. Use the granted right directly"
        )
        Remediation = @(
            "Remove the assignment; this role belongs with Organization Management"
            "Verify the Exchange permissions model on the domain object (see the Exchange Permissions Model check)"
            "Audit Add-ADPermission in the Exchange admin audit log"
        )
        RemediationCommands = @(
            @{
                Description = "Show every holder of the Active Directory Permissions role"
                Command = "Get-ManagementRoleAssignment -Role 'Active Directory Permissions' | Select-Object Name,RoleAssigneeName,RoleAssigneeType"
            }
            @{
                Description = "Review recent Add-ADPermission calls"
                Command = "Search-AdminAuditLog -Cmdlets Add-ADPermission -StartDate (Get-Date).AddDays(-90) | Select-Object RunDate,Caller,ObjectModified,CmdletParameters"
            }
        )
        References = @(
            @{ Title = "Exchange-AD-Privesc"; Url = "https://github.com/gdedrouas/Exchange-AD-Privesc" }
            @{ Title = "Understanding management role assignments"; Url = "https://learn.microsoft.com/en-us/exchange/understanding-management-role-assignments-exchange-2013-help" }
        )
        Tools = @("Exchange Management Shell", "PowerView")
        MITRE = "T1222.001"
        Triggers = @(
            @{ Attribute = 'RiskVerdict'; Pattern = '^Directory permissions'; Severity = 'Finding' }
        )
    }

    'EXCHANGE_RBAC_DEFAULT_ASSIGNMENT' = @{
        Title = "High-Value Exchange Role on Its Shipped Role Group"
        Risk = "Hint"
        BaseScore = 20
        Description = "This high-value role sits on the role group Exchange assigns it to out of the box, or Organization Management may assign it to others through the delegating assignment Exchange setup creates for practically every role. Either way the assignment itself is expected. What is not automatically fine is who is in that group: the role group's membership is the real holder list, and compromising any member yields the role or the power to grant it."
        Impact = @(
            "Every member of the role group holds this capability"
            "Role groups such as Organization Management are frequently larger than anyone intends"
            "Discovery Management is meant to be empty between cases and often is not"
        )
        Remediation = @(
            "Review the role group's membership rather than the assignment"
            "Keep Discovery Management empty outside of active cases"
            "Require privileged access management for membership in Organization Management"
        )
        RemediationCommands = @(
            @{
                Description = "Show the membership of the Exchange role groups"
                Command = "Get-RoleGroup | ForEach-Object { Write-Host `$_.Name; Get-RoleGroupMember `$_.Name | Select-Object Name,RecipientType }"
            }
        )
        References = @(
            @{ Title = "Understanding management role groups"; Url = "https://learn.microsoft.com/en-us/exchange/understanding-management-role-groups-exchange-2013-help" }
        )
        MITRE = "T1098"
        Triggers = @(
            @{ Attribute = 'RiskVerdict'; Pattern = '^Default assignment'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # COMPUTER ACCOUNT FINDINGS
    # ============================================================================

    'COMPUTER_OBJECT_EXPLICIT_RIGHT' = @{
        Title = "Explicit Permission on a Computer Object Outside Tier-0"
        Risk = "Finding"
        BaseScore = 45
        Description = "A principal outside Tier-0 holds a permission on this computer object that is written on the object itself - not inherited from its OU, not one of the entries the default security descriptor of the computer class gives the creator, the operators and the administrators. Full control, a generic write or a DACL write takes the object over; a write on msDS-AllowedToActOnBehalfOfOtherIdentity is resource-based constrained delegation to the machine, one on msDS-KeyCredentialLink a shadow credential for it, the password reset right hands over the machine account itself, and all extended rights include reading its LAPS password. Each of these ends in administrative access to the computer."
        Impact = @(
            "Administrative access to the computer, through its own machine account or through delegation to it"
            "On a server that holds credentials, or on a domain controller, more than the computer"
        )
        Attack = @(
            "1. Attacker controls the listed principal"
            "2. Writes RBCD or a key credential on the computer, resets its password, or reads its LAPS password"
            "3. Obtains a service ticket to the computer as an administrator, or logs on with the local administrator password"
        )
        Remediation = @(
            "Remove the entry from the computer object, or replace it with the narrower right the task needs"
            "Delegate computer management on the OU to a group, where the OU permission check reports it, rather than per object"
        )
        RemediationCommands = @(
            @{
                Description = "Show the explicit entries on a computer object"
                Command = "(Get-Acl -Path ('AD:' + (Get-ADComputer 'COMPUTERNAME').DistinguishedName)).Access | Where-Object { -not `$_.IsInherited } | Format-Table IdentityReference,ActiveDirectoryRights,ObjectType,AccessControlType -AutoSize"
            }
        )
        References = @(
            @{ Title = "Computer class - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/c-computer" }
            @{ Title = "Resource-based constrained delegation - The Hacker Recipes"; Url = "https://www.thehacker.recipes/ad/movement/kerberos/delegations/rbcd" }
        )
        Tools = @("Rubeus", "Whisker", "Impacket", "PowerView")
        MITRE = "T1098"
        Triggers = @(
            @{ Attribute = 'explicitRights'; Pattern = '.'; Severity = 'Finding' }
        )
    }

    'COMPUTER_PASSWORD_NOT_ROTATED' = @{
        Title = "Machine Account Password Not Rotated"
        Risk = "Hint"
        BaseScore = 10
        Description = "This computer has logged on recently but has not changed its machine account password for far longer than a domain member does on its own - every 30 days by default. The change is switched off: by the policy 'Domain member: Disable machine account password changes', by a join tool on a non-Windows system that does not rotate, or on a cloned machine. A machine account key that does not change never ages out, so whoever extracted it once keeps the access it gives."
        Impact = @(
            "A once-extracted machine account key stays valid - from the host's LSA secrets, a backup or a disk image"
            "With it, service tickets to every service of the host can be forged (silver tickets), and the computer's own domain access can be used"
            "Microsoft names non-persistent VDI and embedded devices as the cases for switching the change off - with a change planned for each maintenance window"
        )
        Attack = @(
            "1. Attacker extracts the machine account key of the host once"
            "2. Forges service tickets to its services, or authenticates as the computer"
            "3. Keeps that access for as long as the password does not change"
        )
        Remediation = @(
            "Find out why the computer does not change its password: DisablePasswordChange or a long MaximumPasswordAge under the Netlogon parameters, a non-Windows join tool, or a clone"
            "Turn the change back on; on a non-Windows member configure the join tool to renew the machine password"
            "Where the change has to stay off, change the password in each maintenance window"
        )
        RemediationCommands = @(
            @{
                Description = "Read the rotation settings on the computer"
                Command = "Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' | Select-Object DisablePasswordChange,MaximumPasswordAge"
            }
            @{
                Description = "Change the machine account password now (run on the computer)"
                Command = "Nltest /sc_change_pwd:DOMAIN_NAME"
            }
        )
        References = @(
            @{ Title = "Domain member: Maximum machine account password age - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/domain-member-maximum-machine-account-password-age" }
            @{ Title = "Domain member: Disable machine account password changes - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/domain-member-disable-machine-account-password-changes" }
        )
        Tools = @("Mimikatz", "Rubeus", "Impacket")
        MITRE = "T1558.002"
        Triggers = @(
            @{ Attribute = 'machinePasswordAge'; Pattern = '^Not rotated'; Severity = 'Hint' }
        )
    }

    'DC_PASSWORD_NOT_ROTATED' = @{
        Title = "Domain Controller Machine Account Password Not Rotated"
        Risk = "Finding"
        BaseScore = 30
        Description = "This Domain Controller has logged on recently but has not changed its machine account password for far longer than it does on its own - every 30 days by default, like any domain member. A Domain Controller's machine account replicates the directory, so its key is a DCSync credential, and one that does not change keeps working for whoever obtained it once: from a system state backup, a snapshot of a virtual Domain Controller, or its memory."
        Impact = @(
            "A once-extracted Domain Controller key replicates every password hash of the domain (DCSync) for as long as it stays"
            "Service tickets to the Domain Controller's own services - LDAP, CIFS, HOST - can be forged with it"
        )
        Attack = @(
            "1. Attacker obtains the Domain Controller's machine account key once - from a backup, a VM snapshot or memory"
            "2. Replicates the domain's secrets with it (DCSync), or forges service tickets to the Domain Controller"
            "3. Keeps that access until the Domain Controller changes its password"
        )
        Remediation = @(
            "Find out why the Domain Controller does not change its password: 'Domain member: Disable machine account password changes' or a long maximum age applied to the Domain Controllers, or a restored or cloned Domain Controller"
            "Turn the change back on, so the Domain Controller changes its password at its next check"
        )
        RemediationCommands = @(
            @{
                Description = "Read the rotation settings on the Domain Controller"
                Command = "Get-ItemProperty 'HKLM:\SYSTEM\CurrentControlSet\Services\Netlogon\Parameters' | Select-Object DisablePasswordChange,MaximumPasswordAge"
            }
        )
        References = @(
            @{ Title = "Domain member: Maximum machine account password age - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/domain-member-maximum-machine-account-password-age" }
            @{ Title = "Domain member: Disable machine account password changes - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/domain-member-disable-machine-account-password-changes" }
        )
        Tools = @("Mimikatz", "Impacket")
        MITRE = "T1003.006"
        Triggers = @(
            @{ Attribute = 'machinePasswordAge'; Pattern = '^DOMAIN CONTROLLER'; Severity = 'Finding' }
        )
    }

    'MACHINE_QUOTA_UNRESTRICTED' = @{
        Title = "Unrestricted Machine Account Quota"
        Risk = "Hint"
        BaseScore = 15
        Description = "The ms-DS-MachineAccountQuota is greater than 0. This alone does not grant computer creation rights - it requires the SeMachineAccountPrivilege (typically granted via GPO). When both conditions are met, any authenticated user can add computer accounts that may be abused for RBCD attacks."
        Impact = @(
            "Any user can create machine accounts in the domain"
            "Machine accounts can be used for RBCD attacks"
            "Enables relay attacks requiring computer accounts"
            "Created accounts persist even if creator loses access"
        )
        Attack = @(
            "1. Attacker creates a computer account using quota"
            "2. Uses computer account for RBCD attack on target"
            "3. Impersonates any user to the target computer"
            "4. Achieves local admin on target"
        )
        Remediation = @(
            "Set ms-DS-MachineAccountQuota to 0"
            "Use dedicated groups for computer account creation"
            "Pre-stage computer accounts in AD"
            "Monitor for unexpected computer account creation"
        )
        References = @(
            @{ Title = "Machine Account Quota Abuse"; Url = "https://www.ired.team/offensive-security-experiments/active-directory-kerberos-abuse/resource-based-constrained-delegation-ad-computer-object-take-over-and-privilged-code-execution" }
            @{ Title = "MS-DS-MachineAccountQuota"; Url = "https://docs.microsoft.com/en-us/windows/win32/adschema/a-ms-ds-machineaccountquota" }
        )
        Tools = @("PowerMad", "Impacket", "SharpMad")
        MITRE = "T1136.002"
        Triggers = @(
            @{ Attribute = 'ms-DS-MachineAccountQuota'; Custom = 'gt_0'; Severity = 'Hint' }
            # Who can use the quota, beside it on the same object. "Only ..." is the policy
            # that keeps the privilege away from ordinary accounts: nothing to write up.
            @{ Attribute = 'whoCanAddComputers'; Pattern = '^Any authenticated user'; Severity = 'Hint' }
            @{ Attribute = 'whoCanAddComputers'; Pattern = '^Only '; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    # ============================================================================
    # INACTIVE / STALE ACCOUNT FINDINGS
    # ============================================================================

    'INACTIVE_PRIVILEGED_ACCOUNT' = @{
        Title = "Inactive Privileged Account"
        Risk = "Finding"
        BaseScore = 30
        Description = "This privileged account has not been used for an extended period but remains a member of administrative groups. Inactive privileged accounts increase attack surface without providing legitimate value."
        Impact = @(
            "Unused credentials may be targeted for compromise"
            "Password may be weak or unchanged for long periods"
            "Account may have been abandoned after personnel change"
            "Provides unnecessary attack surface for privilege escalation"
        )
        Attack = @(
            "1. Attacker identifies inactive privileged accounts"
            "2. Targets these accounts for password spraying or credential stuffing"
            "3. Compromised credentials provide immediate admin access"
            "4. Attack may go unnoticed due to account inactivity"
        )
        Remediation = @(
            "Disable or remove accounts inactive for more than 90 days"
            "Remove privileged group memberships from inactive accounts"
            "Implement automated account lifecycle management"
            "Require periodic re-certification of privileged access"
            "Enable account activity monitoring and alerting"
        )
        RemediationCommands = @(
            @{
                Description = "Find all privileged accounts inactive for more than 90 days"
                Command = "`$privilegedGroups = @('Domain Admins','Enterprise Admins','Schema Admins','Administrators'); `$inactiveDate = (Get-Date).AddDays(-90); Get-ADUser -Filter {(Enabled -eq `$true) -and (LastLogonDate -lt `$inactiveDate)} -Properties LastLogonDate,MemberOf | Where-Object { `$_.MemberOf | Where-Object { `$privilegedGroups -contains (`$_ -replace '^CN=([^,]+).*','`$1') } } | Select-Object Name,SamAccountName,LastLogonDate,@{Name='DaysSinceLastLogon';Expression={(New-TimeSpan -Start `$_.LastLogonDate -End (Get-Date)).Days}}"
            }
            @{
                Description = "Disable inactive privileged account"
                Command = "Disable-ADAccount -Identity 'USERNAME'"
            }
            @{
                Description = "Remove privileged group membership from inactive account"
                Command = "Remove-ADGroupMember -Identity 'Domain Admins' -Members 'USERNAME' -Confirm:`$false"
            }
        )
        References = @(
            @{ Title = "Account Management Best Practices"; Url = "https://docs.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory" }
        )
        Tools = @("PowerView", "ADRecon", "PingCastle")
        MITRE = "T1078.002"
        Triggers = @(
            @{ Attribute = 'daysSinceLastLogon'; Severity = 'Finding' }
        )
    }

    'ORPHANED_ADMIN_ACCOUNT' = @{
        Title = "Orphaned Admin Account (AdminCount without Membership)"
        Risk = "Hint"
        BaseScore = 30
        Description = "This account has AdminCount=1 but is no longer a member of any privileged group. These 'orphaned' accounts retain special ACL protections but may have residual permissions without active oversight."
        Impact = @(
            "Account may retain historical privileges not visible in group membership"
            "SDProp protection prevents normal ACL inheritance"
            "May have delegated permissions that persist after group removal"
            "Account management (password reset delegation) may be broken"
        )
        Attack = @(
            "1. Attacker identifies orphaned admin accounts"
            "2. These accounts may have residual permissions in AD"
            "3. May be overlooked in access reviews"
            "4. Can be used for stealthy privilege maintenance"
        )
        Remediation = @(
            "Clear AdminCount attribute on orphaned accounts"
            "Review and remove any residual permissions"
            "Run SDProp to reset ACLs to inherited defaults"
            "Implement regular audit of AdminCount vs group membership"
        )
        RemediationCommands = @(
            @{
                Description = "Find orphaned admin accounts (AdminCount=1 but not in protected groups)"
                Command = "`$protectedGroups = @('Domain Admins','Enterprise Admins','Schema Admins','Administrators','Account Operators','Server Operators','Print Operators','Backup Operators'); Get-ADUser -Filter {AdminCount -eq 1} -Properties MemberOf | Where-Object { -not (`$_.MemberOf | Where-Object { `$protectedGroups -contains (`$_ -replace '^CN=([^,]+).*','`$1') }) } | Select-Object SamAccountName,DistinguishedName"
            }
            @{
                Description = "Clear AdminCount attribute on orphaned account"
                Command = "Set-ADUser -Identity 'USERNAME' -Clear AdminCount"
            }
            @{
                Description = "Manually trigger SDProp to update ACLs (runs on PDC Emulator)"
                Command = "Invoke-Command -ComputerName PDC_EMULATOR -ScriptBlock { `$rootDSE = [ADSI]'LDAP://RootDSE'; `$rootDSE.Put('FixUpInheritance','1'); `$rootDSE.SetInfo() }"
            }
        )
        References = @(
            @{ Title = "AdminSDHolder and SDProp"; Url = "https://adsecurity.org/?p=1906" }
            @{ Title = "Protected Accounts and Groups - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-c--protected-accounts-and-groups-in-active-directory" }
        )
        Tools = @("PowerView", "ADACLScanner", "PingCastle")
        MITRE = "T1078.002"
        Triggers = @(
            @{ Attribute = 'isOrphaned'; Pattern = '^(True|Yes|1)$'; Severity = 'Hint' }
        )
    }

    'STALE_PASSWORD' = @{
        Title = "Stale Password (Not Changed for Extended Period)"
        Risk = "Finding"
        BaseScore = 35
        Description = "This account's password has not been changed for more than 5 years. Extremely stale passwords indicate severe password hygiene issues and significantly increase the risk of credential compromise."
        Impact = @(
            "Extremely high exposure window for brute-force or dictionary attacks"
            "Password very likely compromised or exposed over such a long period"
            "Old passwords may use severely outdated complexity requirements"
            "Service accounts with static passwords are prime targets for Kerberoasting"
            "Credentials almost certainly exist in old backups, password dumps, or breach databases"
        )
        Attack = @(
            "1. Attacker identifies accounts with very old passwords (via pwdLastSet attribute)"
            "2. Targets these accounts for password spraying with common/old passwords"
            "3. Service accounts: Kerberoasting yields hash for extended offline cracking"
            "4. Old passwords may match patterns from previous breaches"
            "5. Compromised credentials provide persistent access"
        )
        Remediation = @(
            "IMMEDIATE: Force password change for this account"
            "Implement regular password rotation policy (90-180 days for users, 30-60 days for service accounts)"
            "Use Group Managed Service Accounts (gMSA) for automatic password rotation"
            "Monitor pwdLastSet for accounts exceeding policy thresholds"
            "Enforce strong password complexity and minimum length"
            "Check compromised password lists (Have I Been Pwned, Azure AD Password Protection)"
            "Consider passwordless authentication methods (Windows Hello, FIDO2)"
        )
        RemediationCommands = @(
            @{
                Description = "Find all accounts with passwords older than 5 years"
                Command = "`$staleDate = (Get-Date).AddYears(-5); Get-ADUser -Filter {PasswordLastSet -lt `$staleDate} -Properties PasswordLastSet | Select-Object Name,SamAccountName,PasswordLastSet,@{Name='DaysSincePasswordChange';Expression={(New-TimeSpan -Start `$_.PasswordLastSet -End (Get-Date)).Days}}"
            }
            @{
                Description = "Force password change at next logon"
                Command = "Set-ADUser -Identity 'USERNAME' -ChangePasswordAtLogon `$true"
            }
            @{
                Description = "Set new random password and force change (for compromised accounts)"
                Command = "`$newPwd = [System.Web.Security.Membership]::GeneratePassword(20,5); Set-ADAccountPassword -Identity 'USERNAME' -NewPassword (ConvertTo-SecureString `$newPwd -AsPlainText -Force) -Reset; Set-ADUser -Identity 'USERNAME' -ChangePasswordAtLogon `$true"
            }
        )
        References = @(
            @{ Title = "Password Policy Best Practices - Microsoft"; Url = "https://docs.microsoft.com/en-us/microsoft-365/admin/misc/password-policy-recommendations" }
            @{ Title = "NIST Password Guidelines"; Url = "https://pages.nist.gov/800-63-3/sp800-63b.html" }
