        )
        Tools = @("PowerView", "ADRecon", "BloodHound", "PingCastle")
        MITRE = "T1110"
        Triggers = @(
            @{ Attribute = 'pwdLastSet'; Custom = 'pwdAge_gt_1825'; Severity = 'Finding' }
        )
    }

