    'PASSWORD_HISTORY_DISABLED' = @{
        Title = "Password History Disabled"
        Risk = "Hint"
        BaseScore = 10
        Description = "The password policy remembers no previous password - pwdHistoryLength is 0 on the domain, or msDS-PasswordHistoryLength on a fine-grained policy - so a user whose password was reset or expired can set the same one again at once. A password that leaked and was changed for that reason comes straight back. Microsoft's default domain policy remembers 24 passwords, the maximum, and recommends exactly that ('Enforce password history')."
        Impact = @(
            "A forced password change can be undone by setting the previous password again"
            "A leaked password that was reset can return the moment its owner sets it again"
        )
        Attack = @(
            "1. Attacker obtains a user's password"
            "2. The password is reset or expires, and the user sets the old one again"
            "3. The attacker's password works again"
        )
        Remediation = @(
            "Set 'Enforce password history' to 24 in the Default Domain Policy, and msDS-PasswordHistoryLength on fine-grained policies"
            "Set a minimum password age above 0 as well - without it, a history can be cycled through by changing the password several times in a row"
        )
        RemediationCommands = @(
            @{
                Description = "Show the password history and the minimum age of the domain"
                Command = "Get-ADDefaultDomainPasswordPolicy | Select-Object PasswordHistoryCount, MinPasswordAge"
            }
            @{
                Description = "Remember 24 passwords (the domain head; the Default Domain Policy is where it is normally set)"
                Command = "Set-ADDefaultDomainPasswordPolicy -Identity 'domain.com' -PasswordHistoryCount 24"
            }
            @{
                Description = "The same on a fine-grained password policy"
                Command = "Set-ADFineGrainedPasswordPolicy -Identity '<policy name>' -PasswordHistoryCount 24"
            }
        )
        References = @(
            @{ Title = "Enforce password history - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-10/security/threat-protection/security-policy-settings/enforce-password-history" }
        )
        Tools = @()
        MITRE = "T1110"
        Triggers = @(
            @{ Attribute = 'pwdHistoryLength'; Pattern = '^Disabled'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # ADCS ADDITIONAL FINDINGS
    # ============================================================================

    'ESC9_CT_NO_SECURITY_EXTENSION' = @{
        Title = "ESC9 - Certificate Template Without Security Extension"
        Risk = "Finding"
        BaseScore = 60
        Description = "The certificate template does not include the szOID_NTDS_CA_SECURITY_EXT security extension, which contains the requestor's SID, so the certificates it issues map to an account by UPN alone. Whether that is exploitable depends on a second condition on the domain controllers: StrongCertificateBindingEnforcement must be 0 or 1. It has defaulted to 2 (full enforcement) since February 2025, and a Group Policy lowering it is reported in the GPO registry section of this report as REGISTRY_ESC10_KDC_BINDING or REGISTRY_ESC10_KDC_BINDING_COMPAT. Where enforcement is 2, this template is a latent misconfiguration - it becomes a live path the moment somebody lowers the value or a machine is built from an older image."
        Impact = @(
            "Certificates not cryptographically bound to requestor"
            "Stolen certificates can be used by anyone"
            "No SID validation during authentication"
            "Enables certificate theft attacks"
        )
        Attack = @(
            "1. Attacker obtains certificate (theft, file share, etc.)"
            "2. Certificate not bound to original requestor's SID"
            "3. Attacker uses certificate to authenticate as original user"
            "4. No way to detect that wrong user is using certificate"
        )
        Remediation = @(
            "Enable StrongCertificateBindingEnforcement on DCs"
            "Include szOID_NTDS_CA_SECURITY_EXT in certificate templates"
            "Monitor for certificate-based authentication anomalies"
        )
        RemediationCommands = @(
            @{
                Description = "Remove CT_FLAG_NO_SECURITY_EXTENSION flag from certificate template"
                Command = @'
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Get current enrollment flag
$template = Get-ADObject -Identity $templateDN -Properties msPKI-Enrollment-Flag
$currentFlag = $template.'msPKI-Enrollment-Flag'

# Remove CT_FLAG_NO_SECURITY_EXTENSION (0x80000)
$newFlag = $currentFlag -band (-bnot 0x80000)

# Update template
Set-ADObject -Identity $templateDN -Replace @{'msPKI-Enrollment-Flag' = $newFlag}
'@
            }
            @{
                Description = "Enable StrongCertificateBindingEnforcement on all Domain Controllers"
                Command = @'
# Set registry value on all DCs (run via GPO or remotely)
$DCs = Get-ADDomainController -Filter *
foreach ($DC in $DCs) {
    Invoke-Command -ComputerName $DC.HostName -ScriptBlock {
        Set-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\Kdc' -Name 'StrongCertificateBindingEnforcement' -Value 2 -Type DWord
    }
}
'@
            }
            @{
                Description = "Verify certificate template includes szOID_NTDS_CA_SECURITY_EXT"
                Command = @'
# Check if template properly includes security extension
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"
$template = Get-ADObject -Identity $templateDN -Properties msPKI-Enrollment-Flag
if (($template.'msPKI-Enrollment-Flag' -band 0x80000) -eq 0x80000) {
    Write-Host "WARNING: Template has CT_FLAG_NO_SECURITY_EXTENSION enabled" -ForegroundColor Red
} else {
    Write-Host "OK: Template will include security extension" -ForegroundColor Green
}
'@
            }
        )
        References = @(
            @{ Title = "ESC9 and ESC10"; Url = "https://research.ifcr.dk/certipy-4-0-esc9-esc10-bloodhound-gui-new-attack-paths-d34c41f59f4" }
            @{ Title = "KB5014754 - Certificate-Based Authentication Changes - Microsoft"; Url = "https://support.microsoft.com/en-us/topic/kb5014754-certificate-based-authentication-changes-on-windows-domain-controllers-ad2c23b0-15d8-4340-a468-4d4f3b188f16" }
        )
        Tools = @("Certipy", "Certify")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC9'; Severity = 'Finding' }
            # Colour only. CT_FLAG_NO_SECURITY_EXTENSION suppresses the SID extension,
            # which matters when the KDC is in compatibility mode and a principal can
            # enroll with a subject of their choosing. The flag by itself is set on
            # templates issued for perfectly ordinary reasons.
            @{ Attribute = 'NoSecurityExtension'; Pattern = '^(True|Yes)$'; Severity = 'Finding'; SeverityOnly = $true }
        )
    }

