    'SCCM_SYSTEM_MANAGEMENT_ACL' = @{
        Title = "Write Access to the SCCM System Management Container"
        Risk = "Finding"
        BaseScore = 75
        Description = "This principal can write to CN=System Management,CN=System, the container Configuration Manager publishes its sites and management points in, and it is neither a site server nor one of the administrators the container expects. A client that uses Active Directory site discovery trusts what it finds there."
        Impact = @(
            "A management point published here is accepted by every client configured for Active Directory site discovery"
            "The client takes its policy, and the software that policy deploys, from that management point"
            "Policies carry the network access account credentials, which the client requests from the management point it trusts"
            "The blast radius is every managed client in the site, which in most domains is every workstation"
        )
        Attack = @(
            "1. Attacker gains control of a principal with write access to the container"
            "2. An mSSMSManagementPoint object naming a host the attacker controls is published"
            "3. Clients using AD site discovery resolve to it and request policy"
            "4. The rogue management point serves policy and collects what the clients send it, including credentials the real one would have issued"
        )
        Remediation = @(
            "Reduce the ACL to what Configuration Manager documents: Full Control for the site server computer accounts, and nothing else beyond the domain administrators"
            "Establish who granted the entry and when, from the directory service audit log (event 5136 on nTSecurityDescriptor)"
            "Where extension of the schema and this container were done years ago by a departed admin, treat the whole ACL as unreviewed rather than the one entry"
            "Clients can be moved off AD site discovery, but that changes the exposure rather than the permission - fix the ACL either way"
        )
        RemediationCommands = @(
            @{
                Description = "Show who can write to the container"
                Command = "(Get-Acl -Path 'AD:\CN=System Management,CN=System,DOMAIN_DN').Access | Where-Object { `$_.AccessControlType -eq 'Allow' -and `$_.ActiveDirectoryRights -match 'GenericAll|GenericWrite|WriteDacl|WriteOwner|CreateChild' }"
            }
            @{
                Description = "Show what is currently published in it"
                Command = "Get-ADObject -SearchBase 'CN=System Management,CN=System,DOMAIN_DN' -LDAPFilter '(objectClass=mSSMSManagementPoint)' -Properties mSSMSMPName,mSSMSSiteCode"
            }
        )
        References = @(
            @{ Title = "Misconfiguration Manager - ELEVATE and TAKEOVER techniques"; Url = "https://github.com/subat0mik/Misconfiguration-Manager" }
            @{ Title = "Extend the AD schema for Configuration Manager"; Url = "https://learn.microsoft.com/en-us/mem/configmgr/core/plan-design/network/extend-the-active-directory-schema" }
            @{ Title = "Create the System Management container"; Url = "https://learn.microsoft.com/en-us/mem/configmgr/core/plan-design/network/extend-the-active-directory-schema#create-the-system-management-container" }
        )
        Tools = @("SharpSCCM", "Misconfiguration-Manager", "PowerView", "ADACLScanner")
        MITRE = "T1484.001"
        Triggers = @(
            @{ Attribute = 'sccmContainerWrite'; Severity = 'Finding' }
        )
    }

    'SCOM_PRIVILEGED_SERVICE_ACCOUNT' = @{
        Title = "Privileged SCOM Service Account"
        Risk = "Finding"
        BaseScore = 70
        Description = "This System Center Operations Manager service account holds privileged rights in the domain. SCOM already makes its action and SDK accounts local administrator on every monitored server, and lets an operator run a task on any agent; a privileged account on top of that turns a management server compromise into a domain compromise."
        Impact = @(
            "The account is local administrator on every monitored server by design, so its credential is present in memory across the estate"
            "A SCOM operator can run a script or task on any agent, which is remote code execution wherever SCOM monitors"
            "With domain privileges attached, the same access reaches the domain rather than stopping at the monitored servers"
            "Management servers are rarely administered as Tier 0, so the account is usually easier to reach than what it can do"
        )
        Attack = @(
            "1. Attacker gains administrative access to a SCOM management server, or to any server the action account logs on to"
            "2. The service account credential is recovered from memory or from the SCOM configuration"
            "3. Its domain privileges are used directly - no further escalation is needed"
            "4. Alternatively a SCOM task is authored and run against every agent at once"
        )
        Remediation = @(
            "Take the domain privilege away: a SCOM action account needs rights on the monitored servers, not in Active Directory"
            "Use separate accounts for the action account, the SDK account and the data warehouse rather than one account for all of them"
            "Where the account must stay privileged, administer the management servers as Tier 0 - the account is only as protected as the weakest host it logs on to"
            "Consider a group Managed Service Account, whose password cannot be cracked and rotates on its own"
        )
        RemediationCommands = @(
            @{
                Description = "Show the group memberships of the account"
                Command = "Get-ADUser -Identity 'ACCOUNT_NAME' -Properties memberOf | Select-Object -ExpandProperty memberOf"
            }
            @{
                Description = "Show which SCOM accounts are configured (run on a management server)"
                Command = "Get-SCOMRunAsAccount | Select-Object Name, UserName, AccountType"
            }
        )
        References = @(
            @{ Title = "SCOM Run As accounts and security"; Url = "https://learn.microsoft.com/en-us/system-center/scom/plan-security-accounts" }
            @{ Title = "SharpSCOM"; Url = "https://github.com/breakfix/SharpSCOM" }
        )
        Tools = @("SharpSCOM", "BloodHound", "PowerView")
        MITRE = "T1078.002"
        Triggers = @(
            @{ Attribute = 'privilegedServiceAccount'; Severity = 'Finding' }
        )
    }

    'SCCM_SITE_HIERARCHY' = @{
        Title = "SCCM Multi-Site Hierarchy Detected"
        Risk = "Hint"
        BaseScore = 30
        Description = "A Central Administration Site (CAS) was identified, indicating a multi-site SCCM hierarchy. CAS servers control the entire SCCM hierarchy and are Tier 0 assets."
        Impact = @(
            "CAS controls all Primary and Secondary sites in the hierarchy"
            "Compromise of CAS enables code execution across ALL sites"
            "CAS is the single point of control for the entire SCCM infrastructure"
        )
        Attack = @(
            "1. Identify CAS server via mSSMSManagementPoint site hierarchy analysis"
            "2. Target CAS admin accounts or CAS server directly"
            "3. Deploy malicious applications to all sites from CAS"
            "4. Full control of managed endpoints across entire organization"
        )
        Remediation = @(
            "Treat CAS as Tier 0 infrastructure"
            "Restrict CAS admin access to dedicated admin accounts"
            "Enable SCCM audit logging on CAS"
            "Implement network segmentation for SCCM infrastructure"
        )
        References = @(
            @{ Title = "Misconfiguration Manager"; Url = "https://github.com/subat0mik/Misconfiguration-Manager" }
            @{ Title = "SCCM Hierarchy Attacks (SpecterOps)"; Url = "https://posts.specterops.io/sccm-hierarchy-takeover-with-high-availability-7dcbd3696b43" }
            @{ Title = "MECM Site Hierarchy - Microsoft"; Url = "https://learn.microsoft.com/en-us/mem/configmgr/core/plan-design/hierarchy/design-a-hierarchy-of-sites" }
        )
        Tools = @("SharpSCCM", "sccmhunter", "ConfigManBearPig")
        MITRE = "T1072"
    }

    'SCCM_PXE_EXPOSURE' = @{
        Title = "PXE Boot Server Detected"
        Risk = "Hint"
        BaseScore = 25
        Description = "PXE boot servers published in Active Directory may represent an attack surface. Tools like PXEThief can extract media variables containing Network Access Account (NAA) credentials or task sequence secrets from PXE responses if not properly secured."
        Impact = @(
            "NAA credentials or task sequence secrets can be extracted from PXE boot images"
            "Captured credentials often grant network-wide access to SCCM distribution points"
            "Rogue PXE responses via DHCP spoofing enable OS deployment manipulation"
            "Boot images may contain additional embedded credentials or domain join accounts"
        )
        Attack = @(
            "1. Identify PXE servers via AD connectionPoint or intellimirrorSCP objects"
            "2. Use PXEThief to request PXE boot media from the distribution point"
            "3. Extract media variables (NAA credentials, task sequence secrets)"
            "4. Use captured credentials for lateral movement or SCCM admin access"
        )
        Remediation = @(
            "Enable PXE password protection on all distribution points"
            "Use Enhanced HTTP or HTTPS instead of NAA for client communication"
            "Implement DHCP snooping and IP Source Guard to prevent PXE spoofing"
            "Restrict PXE boot to dedicated VLANs with network access control"
            "Migrate from NAA to Enhanced HTTP (removes credential exposure entirely)"
        )
        References = @(
            @{ Title = "PXEThief - Extracting Credentials from PXE Boot"; Url = "https://www.thehacker.recipes/ad/movement/sccm-mecm/" }
            @{ Title = "Misconfiguration Manager - CRED-4 PXE Abuse"; Url = "https://github.com/subat0mik/Misconfiguration-Manager" }
            @{ Title = "PXE Boot Security for MECM - Microsoft"; Url = "https://learn.microsoft.com/en-us/mem/configmgr/osd/plan-design/security-and-privacy-for-operating-system-deployment" }
        )
        Tools = @("PXEThief", "PXEThiefy", "sccmhunter")
        MITRE = "T1557"
    }

    'SCCM_SERVICE_ACCOUNT' = @{
        Title = "SCCM Service Account with SPN"
        Risk = "Hint"
        BaseScore = 25
        Description = "User accounts with SCCM-related Service Principal Names (SMS*) were found. These accounts typically have elevated privileges in the SCCM hierarchy. Kerberoast risk is covered separately by the Kerberoasting check."
        Impact = @(
            "Service account is kerberoastable - ticket can be requested and cracked offline"
            "SCCM service accounts often have local admin rights on SCCM servers"
            "Compromised service account may enable SCCM admin access and software deployment to all clients"
            "Account may have elevated AD permissions (adminCount, delegation rights)"
        )
        Attack = @(
            "1. Request Kerberos TGS ticket for the SMS* SPN (Kerberoasting)"
            "2. Crack the ticket offline to recover the plaintext password"
            "3. Authenticate as the service account to access SCCM infrastructure"
            "4. Use SCCM admin access for domain-wide code execution via software deployment"
        )
        Remediation = @(
            "Use Group Managed Service Accounts (gMSA) instead of regular user accounts"
            "Enforce long, complex passwords (25+ characters) on service accounts"
            "Add SCCM service accounts to the Protected Users group (prevents RC4)"
            "Enable AES-only Kerberos encryption for the service account"
            "Monitor for Kerberoasting activity (Event ID 4769 with RC4 encryption)"
        )
        References = @(
            @{ Title = "Kerberoasting SCCM Service Accounts"; Url = "https://www.thehacker.recipes/ad/movement/kerberos/kerberoast" }
            @{ Title = "SCCM Attack Techniques"; Url = "https://github.com/subat0mik/Misconfiguration-Manager" }
            @{ Title = "MECM Accounts and Permissions - Microsoft"; Url = "https://learn.microsoft.com/en-us/mem/configmgr/core/plan-design/hierarchy/accounts" }
        )
        Tools = @("Rubeus", "Impacket", "sccmhunter")
        MITRE = "T1558.003"
    }

    'SCCM_GROUP_BROAD_MEMBER' = @{
        Title = "Broad Group in an SCCM-Related Group"
        Risk = "Finding"
        BaseScore = 40
        Description = "A group whose name ties it to SCCM (ConfigMgr, MECM, or the site-to-site connection groups SCCM creates) has a broad group as a member - Domain Users, Domain Computers, Authenticated Users or Everyone. adPEAS recognises the group by its name and cannot read what it grants inside SCCM, but whatever that is - administrative roles in the console, rights on site servers or on the content they hold - every account the broad group covers holds it now."
        Impact = @(
            "Every account in the broad group inherits the SCCM group's access"
            "Where the group carries an SCCM administrative role, that is software deployment and script execution on every managed client"
            "Where it is a site system connection group, it is the site server's own access to the other site systems"
        )
        Attack = @(
            "1. Attacker with any domain account is, through the broad group, a member of the SCCM group"
            "2. Uses the access the group grants - in the console, on a site server share, or on the site database"
            "3. With an administrative role, deploys a script or an application to the clients"
        )
        Remediation = @(
            "Remove the broad group from the SCCM-related group"
            "Grant SCCM roles to named administrative groups only, and review the role assignments in the console"
        )
        RemediationCommands = @(
            @{
                Description = "Remove Domain Users from the group"
                Command = "Remove-ADGroupMember -Identity 'GROUP_NAME' -Members 'Domain Users' -Confirm:`$false"
            }
        )
        References = @(
            @{ Title = "Misconfiguration Manager - SCCM attack techniques"; Url = "https://github.com/subat0mik/Misconfiguration-Manager" }
            @{ Title = "MECM Accounts and Permissions - Microsoft"; Url = "https://learn.microsoft.com/en-us/mem/configmgr/core/plan-design/hierarchy/accounts" }
        )
        Tools = @("sccmhunter", "SharpSCCM")
        MITRE = "T1072"
        Triggers = @(
            @{ Attribute = 'broadMembers'; Pattern = '^BROAD'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # AZURE AD / HYBRID FINDINGS
    # ============================================================================

    'AZURE_AD_CONNECT_EXPOSED' = @{
        Title = "Azure AD Connect Server Exposure"
        Risk = "Finding"
        BaseScore = 50
        Description = "The Azure AD Connect server is a Tier 0 asset that synchronizes identities between on-premises AD and Azure AD. Compromise of this server enables cloud and on-premises domain compromise."
        Impact = @(
            "Azure AD Connect service account has DCSync rights"
            "Server stores Azure AD credentials in encrypted form"
            "Compromise enables Silver Ticket to Azure AD"
            "Can extract cloud credentials and NTLM hashes"
        )
        Attack = @(
            "1. Attacker compromises Azure AD Connect server"
            "2. Extracts MSOL account credentials"
            "3. Uses DCSync rights to dump all domain hashes"
            "4. Or forges tokens for Azure AD access"
        )
        Remediation = @(
            "Treat Azure AD Connect as Tier 0 infrastructure"
            "Limit access to dedicated admin accounts"
            "Enable PTA (Pass-through Auth) instead of password sync"
            "Monitor for suspicious AAD Connect activity"
        )
        RemediationCommands = @(
            @{
                Description = "View current AD DS Connector account permissions (MSOL account)"
                Command = "Import-Module ADSync; Get-ADSyncConnectorAccount -Connector 'Contoso.com' | Select-Object UserName,PasswordNeverExpires,PasswordLastSet"
            }
            @{
                Description = "Review MSOL account DCSync permissions on domain root"
                Command = "(Get-Acl 'AD:\DC=contoso,DC=com').Access | Where-Object {`$_.IdentityReference -like '*MSOL*' -and (`$_.ActiveDirectoryRights -match 'GenericAll|Replicating Directory Changes')} | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize"
            }
            @{
                Description = "Enable Entra Connect audit logging (requires 250MB-500MB log size)"
                Command = "# On Entra Connect server: wevtutil sl 'Microsoft-Windows-ADSync/Admin' /ms:524288000; # Then monitor event log: Get-WinEvent -LogName 'Microsoft-Windows-ADSync/Admin' -MaxEvents 50"
            }
            @{
                Description = "Monitor for interactive sign-ins by MSOL account (should only be non-interactive)"
                Command = "Get-ADUser -Filter {SamAccountName -like 'MSOL_*'} -Properties LastLogonDate,whenCreated | Select-Object Name,SamAccountName,LastLogonDate,whenCreated | Format-Table -AutoSize"
            }
            @{
                Description = "Audit Office 365 Unified Audit Logs for suspicious MSOL account activity"
                Command = "# In Microsoft 365 Compliance Center: Search Unified Audit Log for UserIds starting with MSOL_ with interactive logon events"
            }
            @{
                Description = "Restrict RDP and interactive access to Entra Connect server"
                Command = "# Use GPO: Computer Configuration > Policies > Windows Settings > Security Settings > Local Policies > User Rights Assignment > 'Allow log on through Remote Desktop Services' = Only specific admin accounts"
            }
        )
        References = @(
            @{ Title = "Azure AD Connect Security"; Url = "https://docs.microsoft.com/en-us/azure/active-directory/hybrid/whatis-azure-ad-connect" }
            @{ Title = "AAD Connect Attacks"; Url = "https://blog.xpnsec.com/azuread-connect-for-redteam/" }
            @{ Title = "Microsoft Entra Connect: Accounts and permissions"; Url = "https://learn.microsoft.com/en-us/entra/identity/hybrid/connect/reference-connect-accounts-permissions" }
            @{ Title = "Securing Microsoft Azure AD Connect"; Url = "https://www.hub.trimarcsecurity.com/post/securing-microsoft-azure-ad-connect" }
            @{ Title = "Targeting MSOL Accounts"; Url = "https://www.tevora.com/threat-blog/targeting-msol-accounts-to-compromise-internal-networks/" }
        )
        Tools = @("AADInternals", "ROADtools", "Mimikatz")
        MITRE = "T1003.006"
        Triggers = @(
            # Hint, not Finding. Both values are facts parsed out of the account
            # description - the host Entra Connect runs on, and the tenant it syncs to -
            # and neither states a misconfiguration. The section line above them is a Hint
            # for that reason, and an MSOL account exists in every hybrid domain, so red
            # here appeared in every such report and taught the reader to skip the block
            # that also carries the real findings. The card keeps Risk = Finding and its
            # BaseScore: what changed is the colour of the row, not the weight of the
            # finding.
            @{ Attribute = 'entraConnectServer'; Severity = 'Hint' }
            @{ Attribute = 'entraM365Tenant'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # COMPUTER OWNERSHIP FINDINGS
    # ============================================================================

    'ADFS_DKM_CONTAINER' = @{
        Title = "AD FS Deployed - Token Signing Key Held in the Directory"
        Risk = "Hint"
        BaseScore = 45
        Description = "This domain holds an AD FS DKM container. AD FS keeps the key that its token-signing certificate is encrypted with as an attribute of a contact object under CN=ADFS,CN=Microsoft,CN=Program Data. Its presence is not itself a misconfiguration - it says the federation service exists here, and that a second, quieter path into the connected cloud tenant runs through this domain."
        Impact = @(
            "Read access to the DKM key plus the AD FS configuration database yields the token-signing certificate"
            "With that certificate, SAML tokens can be issued for any federated user, including a global administrator - Golden SAML"
            "The token is signed rather than obtained by authenticating, so MFA at the identity provider does not apply and no sign-in the tenant can see takes place"
            "Resetting on-premises passwords does not revoke it: the signing certificate has to be rolled, twice, for the old key to stop being trusted"
        )
        Attack = @(
            "1. Attacker gains administrative access to an AD FS server or to the AD FS service account"
            "2. The DKM key is read from the container in AD and the encrypted configuration is read from the AD FS database"
            "3. The token-signing certificate is decrypted with the DKM key"
            "4. SAML tokens are forged for arbitrary users and accepted by every relying party, including Microsoft 365"
        )
        Remediation = @(
            "Treat AD FS servers as Tier 0: the same administrative isolation as a domain controller, no shared administration with member servers"
            "Restrict who can read the DKM container - only the AD FS service account needs it"
            "Roll the token-signing certificate twice after any suspicion of compromise; once is not enough, because the previous certificate stays trusted"
            "Where the federation exists only for Microsoft 365, consider moving to Entra ID directly, which removes the on-premises signing key altogether"
        )
        RemediationCommands = @(
            @{
                Description = "Show who can read the DKM container"
                Command = "Get-Acl -Path 'AD:\CN=ADFS,CN=Microsoft,CN=Program Data,DOMAIN_DN' | Select-Object -ExpandProperty Access"
            }
            @{
                Description = "Show the AD FS token-signing certificate and its validity"
                Command = "Get-AdfsCertificate -CertificateType Token-Signing"
            }
        )
        References = @(
            @{ Title = "Golden SAML - CyberArk"; Url = "https://www.cyberark.com/resources/threat-research-blog/golden-saml-newly-discovered-attack-technique-forges-authentication-to-cloud-apps" }
            @{ Title = "AD FS DKM and ADFSDump"; Url = "https://posts.specterops.io/a-shift-in-the-ecosystem-adfs-dkm-and-golden-saml-a34dbd0b4a2b" }
            @{ Title = "Securing AD FS Servers - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-fs/deployment/best-practices-securing-ad-fs" }
        )
        Tools = @("ADFSDump", "ADFSpoof", "AADInternals")
        MITRE = "T1606.002"
        Triggers = @(
            @{ Attribute = 'adfsDkmContainer'; Severity = 'Hint' }
        )
    }

    'MSSQL_SERVICE_ACCOUNT_PRIVILEGED' = @{
        Title = "SQL Server Running Under a Privileged Domain Account"
        Risk = "Finding"
        BaseScore = 70
        Description = "A SQL Server instance runs under a domain account that holds privileged rights in the domain - the MSSQLSvc service principal name sits on the account the Database Engine authenticates as. Every operating system command the instance runs, it runs as that account, and the host the service is configured on stores the account's password. Control of the instance or of its host is control of those rights."
        Impact = @(
            "A login in the sysadmin role enables xp_cmdshell and runs commands as the service account - the process it spawns has the same security rights as the SQL Server service account"
            "Where SQL Server Agent runs under the same account, a CmdExec job step does the same"
            "Windows keeps the password of every account a service is configured to run as in the LSA secrets of the host, so local administrator rights on a SQL host recover it"
            "SQL hosts are rarely administered as Tier 0, and sysadmin is routinely held by database administrators and application owners who are not domain administrators"
        )
        Attack = @(
            "1. Attacker obtains a sysadmin login on the instance - a weak sa password, a linked server, an over-privileged application login - or local administrator rights on the SQL host"
            "2. xp_cmdshell is enabled with sp_configure, or the service password is read from the LSA secrets of the host"
            "3. Commands run as the service account, or the recovered credential is used directly"
            "4. The account's domain privileges are used - no further escalation is needed"
        )
        Remediation = @(
            "Take the domain privilege away: SQL Server needs no privileged group membership to run"
            "Run the instance under a group Managed Service Account or a virtual account with the lowest rights that work, as Microsoft recommends for SQL Server services"
            "Use separate accounts for the Database Engine and SQL Server Agent, and for each instance"
            "Where the account must stay privileged, administer the SQL hosts as Tier 0 and grant sysadmin to Tier 0 administrators only"
        )
        RemediationCommands = @(
            @{
                Description = "Show the group memberships of the service account"
                Command = "Get-ADUser -Identity 'ACCOUNT_NAME' -Properties memberOf | Select-Object -ExpandProperty memberOf"
            }
            @{
                Description = "Show which account each SQL Server service runs under (run on the SQL host)"
                Command = "Get-CimInstance Win32_Service | Where-Object { `$_.Name -match '^(MSSQL|SQLAgent|SQLSERVERAGENT)' } | Select-Object Name, StartName"
            }
        )
        References = @(
            @{ Title = "Configure Windows service accounts and permissions - SQL Server"; Url = "https://learn.microsoft.com/en-us/sql/database-engine/configure-windows/configure-windows-service-accounts-and-permissions" }
            @{ Title = "xp_cmdshell (Transact-SQL)"; Url = "https://learn.microsoft.com/en-us/sql/relational-databases/system-stored-procedures/xp-cmdshell-transact-sql" }
            @{ Title = "Create a CmdExec job step"; Url = "https://learn.microsoft.com/en-us/ssms/agent/create-a-cmdexec-job-step" }
            @{ Title = "Cached and stored credentials technical overview"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-R2-and-2012/hh994565(v=ws.11)" }
        )
        Tools = @("PowerUpSQL", "Mimikatz", "BloodHound")
        MITRE = "T1078.002"
    }

    'LAPS_PASSWORD_NOT_ROTATED' = @{
        Title = "LAPS Password Stopped Rotating"
        Risk = "Finding"
        BaseScore = 60
        Description = "This computer has a LAPS password expiration time that lies in the past, so the client did not rotate when it was due. LAPS coverage reports it as protected; the local administrator password on the machine is as old as the day rotation stopped."
        Impact = @(
            "The local administrator password has not changed since rotation stopped, so a password captured then still works today"
            "The machine is counted as protected in every coverage figure, so nobody looks at it"
            "Anything that could read the password once - an over-permissive OU delegation since corrected, a backup, a screenshot in a ticket - still holds a valid credential"
            "Where several machines stopped rotating at the same time they may share the password that was set before LAPS took over, which restores exactly the lateral movement LAPS was deployed to stop"
        )
        Attack = @(
            "1. Attacker reads the LAPS password of a machine, or finds an old one from any source"
            "2. The password has not rotated, so it is still valid"
            "3. Local administrator on the machine yields its cached credentials and its machine account"
            "4. Machines that stopped rotating together often share one password, and the same credential opens the next host"
        )
        Remediation = @(
            "Find out why the client stopped rotating: the LAPS CSE is not installed or not running, the policy no longer reaches the machine, or the machine has been offline since"
            "Force a rotation once the client works again - Reset-LapsPassword for Windows LAPS, or clear the expiration attribute for Legacy LAPS"
            "Where the machine is simply gone, remove the stale computer account instead of leaving a live credential behind"
            "Turn on PasswordExpirationProtectionEnabled so a client cannot extend its own expiration time past the policy maximum"
        )
        RemediationCommands = @(
            @{
                Description = "Show the expiration time recorded in the directory"
                Command = "Get-ADComputer -Identity 'COMPUTER_NAME' -Properties 'ms-Mcs-AdmPwdExpirationTime','msLAPS-PasswordExpirationTime'"
            }
            @{
                Description = "Force an immediate rotation on the machine (Windows LAPS, run on the machine)"
                Command = "Reset-LapsPassword"
            }
            @{
                Description = "Check whether the LAPS policy still reaches the machine"
                Command = "Get-LapsDiagnostics"
            }
        )
        References = @(
            @{ Title = "Windows LAPS Troubleshooting"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-troubleshoot" }
            @{ Title = "Windows LAPS Management Policy Settings"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings" }
        )
        Tools = @("Get-LapsDiagnostics", "LAPS UI", "PowerView")
        MITRE = "T1078.003"
        Triggers = @(
            @{ Attribute = 'lapsPasswordStale'; Severity = 'Finding' }
            # The rotation row of the coverage summary.
            @{ Attribute = 'lapsRotation'; Pattern = '^Stopped on '; Severity = 'Finding' }
            @{ Attribute = 'lapsRotation'; Pattern = '^Every computer '; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'DSRM_PASSWORD_UNMANAGED' = @{
        Title = "DSRM Password Not Managed by Windows LAPS"
        Risk = "Note"
        BaseScore = 10
        Description = "Every domain controller has a Directory Services Restore Mode (DSRM) account - the local administrator of the mode a domain controller is restored in, its password set at promotion and checked against no password policy. Unless Windows LAPS manages it, nothing changes that password afterwards: it is as old as the domain controller or as the last manual reset, and Active Directory does not record which. Where Windows LAPS manages it, the domain controller's computer object carries msLAPS-PasswordExpirationTime, which is what this is read from; an expiration time long past means nothing rotates the password any more."
        Impact = @(
            "With console access - a hypervisor console is enough - the DSRM password logs on to a domain controller started in restore mode as its local administrator, with the directory database offline and open to copying"
            "Where DsrmAdminLogonBehavior is 2, the DSRM account logs on to the running domain controller at any time, over the network with its hash alone"
            "A DSRM password set once for every domain controller at promotion, or synchronized from a domain account with ntdsutil, is disclosed for all of them at once"
        )
        Remediation = @(
            "Let Windows LAPS manage the DSRM password: a policy with BackupDirectory 2, ADPasswordEncryptionEnabled 1 and BackupDsrmPassword 1 that applies to the domain controllers - this needs domain functional level 2016 and Windows Server 2019 or later domain controllers"
            "Until then, set a unique, long DSRM password on each domain controller and keep it in a vault"
            "Make sure no domain controller has DsrmAdminLogonBehavior set to 2"
        )
        RemediationCommands = @(
            @{
                Description = "Reset the DSRM password of a domain controller (run on it; prompts for the new password)"
                Command = "ntdsutil `"set dsrm password`" `"reset password on server null`" q q"
            }
            @{
                Description = "Show whether Windows LAPS manages the DSRM password of a domain controller"
                Command = "Get-LapsADPassword -Identity 'DC_NAME' | Select-Object ComputerName, Source, ExpirationTimestamp"
            }
        )
        References = @(
            @{ Title = "Windows LAPS architecture - DSRM password support"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-concepts-overview" }
            @{ Title = "Get started with Windows LAPS and Windows Server Active Directory"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-scenarios-windows-server-active-directory" }
            @{ Title = "Sneaky Active Directory Persistence #11: Directory Service Restore Mode"; Url = "https://adsecurity.org/?p=1785" }
        )
        Tools = @("Mimikatz")
        MITRE = "T1078.003"
        # The dsrmPassword row of the LAPS coverage summary. It was a line of its own that
        # named this card by FindingId.
        Triggers = @(
            @{ Attribute = 'dsrmPassword'; Pattern = '^(Not managed|No longer rotated) by Windows LAPS'; Severity = 'Note' }
            @{ Attribute = 'dsrmPassword'; Pattern = '^Managed by Windows LAPS on all'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'NON_DEFAULT_COMPUTER_OWNERS' = @{
        Title = "Computer with Non-Default Owner"
        Risk = "Hint"
        BaseScore = 40
        Description = "This computer object has a non-default owner. The owner of an AD object has implicit full control, including the ability to modify permissions. Non-default owners may indicate privilege escalation paths."
        Impact = @(
            "Object owner has implicit WriteDACL permission"
            "Owner can grant themselves any permission on the object"
            "May enable RBCD attacks if attacker owns the computer"
            "Non-standard ownership can indicate misconfiguration or compromise"
        )
        Attack = @(
            "1. Attacker identifies computer where they are owner"
            "2. Uses owner rights to grant themselves GenericAll"
            "3. Configures RBCD to impersonate any user"
            "4. Gains local admin access on target computer"
        )
        Remediation = @(
            "Review computer object owners across the domain"
            "Reset ownership to Domain Admins for critical systems"
            "Implement process to set correct owner during provisioning"
            "Monitor for ownership changes on computer objects"
        )
        References = @(
            @{ Title = "AD Object Ownership"; Url = "https://adsecurity.org/?p=1906" }
            @{ Title = "BloodHound Owns Edge"; Url = "https://bloodhound.specterops.io/resources/edges/owns" }
            @{ Title = "AD DS Object Permissions - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory" }
        )
        Tools = @("BloodHound", "PowerView", "ADACLScanner")
        MITRE = "T1222.001"
        Triggers = @(
            @{ Attribute = 'Owner'; Context = 'NonDefaultOwner'; Severity = 'Hint' }
        )
    }

    'COMPUTER_OWNERSHIP_REASSIGNED' = @{
        Title = "Computer Ownership Re-assigned After Creation"
        Risk = "Finding"
        BaseScore = 65
        Description = "The owner of this computer object is not the principal that created it. A workstation joined by a helpdesk technician leaves that technician as owner, which is ordinary and accounts for most non-default owners in a real domain. Ownership that changed afterwards did not happen by itself - somebody with the rights to do it took control of this computer object."
        Impact = @(
            "The owner holds implicit WriteDACL and can grant itself any right on the object"
            "Writing msDS-AllowedToActOnBehalfOfOtherIdentity gives local SYSTEM on the machine via resource-based constrained delegation"
            "Writing msDS-KeyCredentialLink gives a certificate that authenticates as the machine, with no password reset and nothing for the user to notice"
            "Ownership is not shown by the usual permission views, so this survives a review that only reads the DACL"
        )
        Attack = @(
            "1. Attacker gains control of the principal that owns the computer object"
            "2. Owner rights are used to write a DACL entry granting GenericAll"
            "3. msDS-AllowedToActOnBehalfOfOtherIdentity is set to an account the attacker controls"
            "4. S4U2Self plus S4U2Proxy yields a service ticket as any user, including a Domain Admin, against the machine"
        )
        Remediation = @(
            "Establish who changed the ownership and when, from the directory service audit log on the domain controllers (event 5136 on nTSecurityDescriptor)"
            "Reset the owner to Domain Admins, which is what a provisioning process should be setting"
            "Review the object's DACL as well - an owner that wanted access has usually already granted itself some"
            "Where computer objects are created by delegated staff, pre-create the accounts and set the owner explicitly instead of relying on the join"
        )
        RemediationCommands = @(
            @{
                Description = "Show the current owner and the recorded creator of the computer object"
                Command = "Get-ADComputer -Identity 'COMPUTER_NAME' -Properties nTSecurityDescriptor,mS-DS-CreatorSID | Select-Object Name,@{n='Owner';e={`$_.nTSecurityDescriptor.Owner}},mS-DS-CreatorSID"
            }
            @{
                Description = "Reset the owner to Domain Admins"
                Command = "`$acl = Get-Acl -Path 'AD:\COMPUTER_DN'; `$acl.SetOwner((New-Object System.Security.Principal.NTAccount('DOMAIN\Domain Admins'))); Set-Acl -Path 'AD:\COMPUTER_DN' -AclObject `$acl"
            }
        )
        References = @(
            @{ Title = "BloodHound Owns Edge"; Url = "https://bloodhound.specterops.io/resources/edges/owns" }
            @{ Title = "Resource-Based Constrained Delegation Abuse"; Url = "https://book.hacktricks.wiki/en/windows-hardening/active-directory-methodology/resource-based-constrained-delegation.html" }
            @{ Title = "Shadow Credentials (msDS-KeyCredentialLink)"; Url = "https://posts.specterops.io/shadow-credentials-abusing-key-trust-account-mapping-for-takeover-8ee1a53566ab" }
        )
        Tools = @("BloodHound", "PowerView", "Rubeus", "Whisker")
        MITRE = "T1222.001"
        Triggers = @(
            @{ Attribute = 'ownershipChanged'; Severity = 'Finding' }
        )
    }

    'NON_DEFAULT_USER_OWNERS' = @{
        Title = "User with Non-Default Owner"
        Risk = "Hint"
        BaseScore = 40
        Description = "This user object has a non-default owner. The owner of an AD object has implicit full control, including the ability to reset passwords and modify attributes. Non-default owners may indicate privilege escalation paths."
        Impact = @(
