    # ============================================================================
    # UNIX PASSWORD ATTRIBUTE FINDINGS
    # ============================================================================

    'READABLE_UNIX_PASSWORD_ATTRIBUTES' = @{
        Title = "Unix Password Attributes Readable"
        Risk = "Finding"
        BaseScore = 30
        Description = "This account has Unix password attributes (userPassword, unixUserPassword, sambaNTPassword, etc.) that are readable. These attributes may contain password hashes or even cleartext passwords."
        Impact = @(
            "Password hashes readable by any authenticated user"
            "May contain NTLM hashes in LM/NT format"
            "Legacy Unix integration often stores weak hashes"
            "Cleartext passwords possible in some configurations"
        )
        Attack = @(
            "1. Attacker queries AD for Unix password attributes"
            "2. Extracts password hashes from readable attributes"
            "3. Cracks hashes offline or uses Pass-the-Hash"
            "4. Gains access to accounts with populated attributes"
        )
        Remediation = @(
            "Change the passwords first - clearing the attribute does not revoke them. Every authenticated user in the domain could read them, sambaNTPassword is a directly usable NT hash, and the values are in every AD backup"
            "Remove unused Unix password attributes"
            "Mark the attributes confidential (searchFlags bit 7) so they are no longer readable by every authenticated user"
            "Migrate to modern authentication (Kerberos) for Unix systems"
            "Treat a populated userPassword as an active logon credential, not only as a leak: with the domain's plaintext policy enabled it authenticates"
        )
        RemediationCommands = @(
            @{
                Description = "Find all users with Unix password attributes populated"
                Command = "Get-ADUser -Filter * -Properties unixUserPassword,userPassword,msSFU30Password,sambaNTPassword,sambaLMPassword | Where-Object {`$_.unixUserPassword -or `$_.userPassword -or `$_.msSFU30Password -or `$_.sambaNTPassword -or `$_.sambaLMPassword} | Select-Object Name,SamAccountName,@{Name='HasUnixPassword';Expression={[bool]`$_.unixUserPassword}},@{Name='HasUserPassword';Expression={[bool]`$_.userPassword}},@{Name='HasSFU30Password';Expression={[bool]`$_.msSFU30Password}}"
            }
            @{
                Description = "Clear Unix password attributes from a specific user"
                Command = "Set-ADUser -Identity 'USERNAME' -Clear unixUserPassword,userPassword,msSFU30Password,sambaNTPassword,sambaLMPassword"
            }
            @{
                Description = "Clear Unix password attributes from all affected users (bulk operation)"
                Command = "Get-ADUser -Filter * -Properties unixUserPassword,userPassword,msSFU30Password,sambaNTPassword,sambaLMPassword | Where-Object {`$_.unixUserPassword -or `$_.userPassword -or `$_.msSFU30Password -or `$_.sambaNTPassword -or `$_.sambaLMPassword} | ForEach-Object { Set-ADUser -Identity `$_.SamAccountName -Clear unixUserPassword,userPassword,msSFU30Password,sambaNTPassword,sambaLMPassword; Write-Host `"Cleared Unix password attributes from `$(`$_.SamAccountName)`" }"
            }
            @{
                Description = "Mark the attributes confidential, which is what takes the read away. Forest-wide and needs Schema Admin - test first, a reader with only generic read loses access"
                Command = @'
# The predecessor of this command denied read on CN=Schema itself, which controls access
# to the schema objects and not to the values in the domain partition - it changed
# nothing about who can read userPassword on a user. The mechanism for "this attribute is
# no longer readable by everyone" is the fCONFIDENTIAL bit in searchFlags (bit 7, 128).
$schema = (Get-ADRootDSE).schemaNamingContext
foreach ($name in 'unixUserPassword', 'msSFU30Password', 'sambaNTPassword', 'sambaLMPassword') {
    $attr = Get-ADObject -SearchBase $schema -LDAPFilter "(lDAPDisplayName=$name)" -Properties searchFlags
    if ($attr) {
        Set-ADObject -Identity $attr.DistinguishedName -Replace @{ searchFlags = ($attr.searchFlags -bor 128) }
    }
}
'@
            }
            @{
                Description = "Restrict the read on one OU instead, if the forest-wide schema change is not wanted"
                Command = "dsacls 'OU=Unix,DC=domain,DC=com' /D 'NT AUTHORITY\Authenticated Users:RP;unixUserPassword'"
            }
        )
        References = @(
            @{ Title = "UNIX Attributes in AD"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/best-practices-for-securing-active-directory" }
            @{ Title = "Set-ADUser - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/powershell/module/activedirectory/set-aduser" }
        )
        Tools = @("PowerView", "ldapsearch", "ADExplorer")
        MITRE = "T1552.006"
        Triggers = @(
            # The card follows the format the value is stored in, which is what decides
            # what the find is worth: a cleartext password and an NT hash are usable as
            # they stand, an LM or DES hash falls in hours, a salted $6$ has to be cracked
            # first. The six attribute triggers below used to carry the card themselves,
            # pattern-less and Finding, so all of that was one red row at BaseScore 30 -
            # and the definition's own description names the difference it did not make.
            @{ Attribute = 'passwordFormat'; Pattern = ': (Cleartext|NT hash|LM hash|DES crypt|Unsalted digest)'; Severity = 'Finding' }
            # An attribute that is set and carries nothing, or carries the documented
            # empty-LM placeholder, is not a credential at all - and a yellow row for it
            # teaches a reader to skip the colour on the rows that are.
            @{ Attribute = 'passwordFormat'; Pattern = ': (No hash stored|Empty -)'; Severity = 'Note' }
            @{ Attribute = 'passwordFormat'; Severity = 'Hint' }

            # The value rows follow the same verdict through the predicate, which reads the
            # formats off the object. SeverityOnly: the format row above has named the card
            # already, and a second one would say the same thing twice.
            @{ Attribute = 'unixUserPassword'; Custom = 'unix_password_usable_as_is'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'userPassword'; Custom = 'unix_password_usable_as_is'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'msSFU30Password'; Custom = 'unix_password_usable_as_is'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'sambaNTPassword'; Custom = 'unix_password_usable_as_is'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'sambaLMPassword'; Custom = 'unix_password_usable_as_is'; Severity = 'Finding'; SeverityOnly = $true }

            # unicodePwd is write-only in Active Directory, so it never comes back from a
            # read and no format is computed for it. If one ever does arrive, red is right.
            @{ Attribute = 'unicodePwd'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # MANAGED SERVICE ACCOUNT FINDINGS
    # ============================================================================

    'STANDALONE_MSA_LEGACY' = @{
        Title = "Standalone Managed Service Account (Legacy)"
        Risk = "Hint"
        BaseScore = 20
        Description = "This domain uses standalone Managed Service Accounts (sMSA) which are less secure than Group Managed Service Accounts (gMSA). sMSAs can only be used on a single computer and have less robust password management."
        Impact = @(
            "Password management less robust than gMSA"
            "Tied to single computer - no failover capability"
            "Legacy technology with fewer security controls"
            "Should be migrated to gMSA where possible"
        )
        Attack = @(
            "1. sMSA passwords can potentially be extracted from the host"
            "2. No distributed password management like gMSA"
            "3. Compromise of host compromises sMSA"
        )
        Remediation = @(
            "Migrate sMSAs to Group Managed Service Accounts (gMSA)"
            "Implement gMSA for all new service accounts"
            "Review if sMSAs are still necessary"
            "Ensure proper ACLs on sMSA objects"
        )
        RemediationCommands = @(
            @{
                Description = "Find all standalone Managed Service Accounts (sMSA) in the domain"
                Command = "Get-ADServiceAccount -Filter {ObjectClass -eq 'msDS-ManagedServiceAccount'} -Properties ObjectClass | Where-Object {`$_.ObjectClass -notcontains 'msDS-GroupManagedServiceAccount'} | Select-Object Name,SamAccountName,DistinguishedName,Enabled"
            }
            @{
                Description = "Create KDS Root Key (required for gMSA, one-time setup per forest)"
                Command = "# For production (10 hour wait): Add-KdsRootKey -EffectiveTime ((Get-Date).AddHours(-10)); # For testing (immediate): Add-KdsRootKey -EffectiveImmediately"
            }
            @{
                Description = "Create security group for gMSA password retrieval authorization"
                Command = "New-ADGroup -Name 'gMSA-ServiceServers' -GroupScope Global -GroupCategory Security -Path 'OU=Groups,DC=domain,DC=com' -Description 'Servers authorized to retrieve gMSA passwords'"
            }
            @{
                Description = "Create new Group Managed Service Account (gMSA)"
                Command = "New-ADServiceAccount -Name 'gMSA_ServiceName' -DNSHostName 'gMSA_ServiceName.domain.com' -PrincipalsAllowedToRetrieveManagedPassword 'gMSA-ServiceServers' -ManagedPasswordIntervalInDays 30"
            }
            @{
                Description = "Verify gMSA creation and test password retrieval on target server"
                Command = "# On Domain Controller: Get-ADServiceAccount -Identity 'gMSA_ServiceName' -Properties *; # On target server: Test-ADServiceAccount -Identity 'gMSA_ServiceName'"
            }
        )
        References = @(
            @{ Title = "Group Managed Service Accounts Overview"; Url = "https://docs.microsoft.com/en-us/windows-server/security/group-managed-service-accounts/group-managed-service-accounts-overview" }
            @{ Title = "Manage Group Managed Service Accounts - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts/manage-group-managed-service-accounts" }
        )
        Tools = @("PowerShell AD Module", "PowerView")
        MITRE = "T1078.002"
        Triggers = @(
            @{ Attribute = 'objectClass'; Pattern = 'msDS-ManagedServiceAccount'; ExcludePattern = 'msDS-GroupManagedServiceAccount'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # GPO SCHEDULED TASK FINDINGS
    # ============================================================================

    'GPO_TASK_SYSTEM_UNC_PATH' = @{
        Title = "GPO Scheduled Task Runs as SYSTEM or a Privileged Account from UNC Path"
        Risk = "Finding"
        BaseScore = 45
        Description = "A GPO-deployed scheduled task runs as SYSTEM or as a privileged account and names a UNC network path on its command line - as the program it starts, or as a script or file handed to that program. Whoever can write that share controls what runs in that account on every computer the policy reaches, and so does whoever can answer for the server name where name resolution or unsigned SMB leave room for it. Where the host is an enabled computer of the domain and -OPSEC is not set, adPEAS reads the NTFS permissions of the file and of the folder it is in and names every account beyond the expected administrators that can write them. For a SYSTEM task, a path only privileged accounts can write is a hint rather than a finding: the administrators of that server still decide what runs as SYSTEM everywhere the policy applies. For a privileged account the task stays a finding either way, because it runs that account on every computer in scope. The share permissions are not read - a share's security descriptor is returned to administrators of the file server only - and over the network they can narrow the NTFS rights reported here, never widen them."
        Impact = @(
            "Task runs with SYSTEM privileges, or as a privileged domain account"
            "What it runs is loaded from a network share at every run"
            "Write access to the share = code execution in that account"
            "Affects all computers where the GPO is applied"
        )
        Attack = @(
            "1. Attacker reads the UNC path out of ScheduledTasks.xml in SYSVOL and checks the share's permissions"
            "2. Replaces the executable or script there with a malicious payload"
            "3. Task executes the payload as SYSTEM, or as the privileged account, on all affected hosts"
            "4. Gains SYSTEM access on multiple computers - or the privileges of that account, which for a domain administrator is the domain"
        )
        Remediation = @(
            "Start SYSTEM-context tasks from a local path that only administrators can write"
            "Do not run GPO-deployed tasks as a privileged domain account; give the task an account with only the rights it needs"
            "Ensure the share and the files on it are writable by administrators only - NTFS and share permissions both"
            "Implement code signing for scheduled task executables"
            "Review all GPO scheduled tasks for security"
        )
        RemediationCommands = @(
            @{
                Description = "List every UNC path a scheduled task in SYSVOL names (replace the domain name)"
                Command = "Get-ChildItem '\\contoso.com\SYSVOL\contoso.com\Policies' -Recurse -Filter ScheduledTasks.xml | ForEach-Object { `$file = `$_.FullName; `$xml = New-Object System.Xml.XmlDocument; `$xml.Load(`$file); `$xml.SelectNodes('//Exec/Command | //Exec/Arguments | //Properties/@appName | //Properties/@args') | Where-Object { `$_.InnerText -match '\\\\' } | ForEach-Object { [PSCustomObject]@{ File = `$file; Value = `$_.InnerText } } }"
            }
            @{
                Description = "Show who besides Administrators and SYSTEM may write the file or folder (NTFS; the share permissions apply on top and are read with Get-SmbShareAccess on the file server)"
                Command = "(Get-Acl '\\server\share\path').Access | Where-Object { `$_.AccessControlType -eq 'Allow' -and `$_.FileSystemRights -match 'Write|Modify|FullControl|CreateFiles' -and `$_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value -notmatch '^S-1-5-32-544`$|^S-1-5-18`$' } | Format-Table IdentityReference,FileSystemRights,IsInherited -AutoSize"
            }
            @{
                Description = "Remove explicit write access of Everyone, Authenticated Users, Users and Domain Users. Inherited entries have to be changed where they are defined. Do not add a Deny entry for Domain Users instead: every administrator account is a member of that group too, and the Deny would lock the administrators out"
                Command = "`$path = '\\server\share\path'; `$acl = Get-Acl `$path; `$acl.Access | Where-Object { -not `$_.IsInherited -and `$_.AccessControlType -eq 'Allow' -and `$_.FileSystemRights -match 'Write|Modify|FullControl|CreateFiles' -and `$_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value -match '^S-1-1-0`$|^S-1-5-11`$|^S-1-5-32-545`$|-513`$' } | ForEach-Object { [void]`$acl.RemoveAccessRule(`$_) }; Set-Acl -Path `$path -AclObject `$acl"
            }
            @{
                Description = "Modify the GPO scheduled task to use a local path instead of UNC (requires Group Policy Editor or XML editing)"
                Command = "# Edit GPO via Group Policy Management Console: Computer Configuration > Preferences > Control Panel Settings > Scheduled Tasks > [Task] > Actions > replace the UNC path with a local path only administrators can write, for example a folder below C:\Program Files - not a new folder in the root of C:, which inherits write access for Authenticated Users"
            }
        )
        References = @(
            @{ Title = "GPO Abuse"; Url = "https://wald0.com/?p=179" }
            @{ Title = "Scheduled Tasks via Group Policy - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/taskschd/task-scheduler-start-page" }
            @{ Title = "Get-GPPermission - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/powershell/module/grouppolicy/get-gppermission" }
        )
        Tools = @("SharpGPOAbuse", "PowerView", "GPO analysis")
        MITRE = "T1053.005"
        Triggers = @(
            # On the verdict Get-GPOScheduledTasks writes into RiskReason. The trigger named
            # an attribute 'scheduledTasks' that no module has ever produced, so this card
            # could not appear on any row - while the check reported exactly this case.
            # Anchored on the verdict's opening words, because RiskReason is shared with the
            # registry settings check.
            #
            # Two openings, two severities. "and uses UNC path" is the finding: an account
            # beyond the expected administrators can write the path, or it could not be
            # read. "from UNC path" is the hint for a path read in full that only
            # privileged accounts can write.
            @{ Attribute = 'RiskReason'; Pattern = '^Task runs as SYSTEM and uses UNC path'; Severity = 'Finding' }
            @{ Attribute = 'RiskReason'; Pattern = '^Task runs as SYSTEM from UNC path'; Severity = 'Hint' }
            # The same two openings for a task that runs as a privileged account, both a
            # finding: the account is one, whoever may write the share. Neither matches the
            # risky-directory verdict "Task runs as the privileged account X from C:\...",
            # which carries no UNC path.
            @{ Attribute = 'RiskReason'; Pattern = '^Task runs as the privileged account .+ and uses UNC path'; Severity = 'Finding' }
            @{ Attribute = 'RiskReason'; Pattern = '^Task runs as the privileged account .+ from UNC path'; Severity = 'Finding' }
            # One "path: Identity (Rights)" row per trustee that can write, written only
            # when there is one - a bare trigger, like SysvolPermissions on a GPO.
            @{ Attribute = 'UNCPathPermissions'; Severity = 'Finding' }
        )
    }

    'GPO_TASK_UNQUOTED_PATH' = @{
        Title = "GPO Scheduled Task with an Unquoted Program Path"
        Risk = "Note"
        BaseScore = 5
        Description = "A GPO-deployed scheduled task names a program whose path contains a space and is not quoted. That is the shape of the unquoted service path hijack, where Windows tries C:\Program.exe before C:\Program Files\..., but a scheduled task is not that case: the Task Scheduler service puts the program path in quotes itself when it starts the task. Measured on Windows 11, an unquoted Exec action started the intended program with and without arguments, and a program planted at the truncated path never ran. The path only matters where the same string is handed on to something that does split a command line - a cmd.exe /c line, a batch file, or a service definition built from the same value."
        Impact = @(
            "No hijack through the task itself: the Task Scheduler quotes the program path when it starts it"
            "It becomes one where the string reaches a shell - cmd.exe /c, a batch file, or a service ImagePath built from the same value"
            "Planting C:\Program.exe needs the right to create files in the root of the system drive, which ordinary users do not have by default"
        )
        Attack = @(
            "1. The same unquoted path is copied into a command line that gets split, such as cmd.exe /c or a service ImagePath"
            "2. There Windows tries each truncation in turn - C:\Program.exe before C:\Program Files\App Folder\task.exe"
            "3. An attacker who can create a file at the truncated location runs code in that context"
        )
        Remediation = @(
            "Quote program paths that contain spaces, as hygiene - the task itself is not exploitable through this"
            "Keep the root of the system drive free of create-file rights for ordinary users"
        )
        RemediationCommands = @(
            @{
                Description = "List every scheduled task program in SYSVOL whose path contains a space and is not quoted (replace the domain name)"
                Command = "Get-ChildItem '\\contoso.com\SYSVOL\contoso.com\Policies' -Recurse -Filter ScheduledTasks.xml | ForEach-Object { `$file = `$_.FullName; `$xml = New-Object System.Xml.XmlDocument; `$xml.Load(`$file); `$xml.SelectNodes('//Exec/Command | //Properties/@appName') | Where-Object { `$_.InnerText -match '\s' -and `$_.InnerText -notmatch '^`".*`"`$' } | ForEach-Object { [PSCustomObject]@{ File = `$file; Program = `$_.InnerText } } }"
            }
            @{
                Description = "Show who besides Administrators and SYSTEM may create files in the root of the system drive - what planting C:\Program.exe would need"
                Command = "(Get-Acl 'C:\').Access | Where-Object { `$_.AccessControlType -eq 'Allow' -and `$_.PropagationFlags -notmatch 'InheritOnly' -and `$_.FileSystemRights -match 'Write|Modify|FullControl|CreateFiles' -and `$_.IdentityReference.Translate([System.Security.Principal.SecurityIdentifier]).Value -notmatch '^S-1-5-32-544`$|^S-1-5-18`$' } | Format-Table IdentityReference,FileSystemRights -AutoSize"
            }
        )
        References = @(
            @{ Title = "Unquoted Service Paths"; Url = "https://attack.mitre.org/techniques/T1574/009/" }
            @{ Title = "CreateProcess and Path Handling - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/api/processthreadsapi/nf-processthreadsapi-createprocessw" }
        )
        Tools = @("PowerSploit", "SharpUp", "GPO analysis")
        MITRE = "T1574.009"
        Triggers = @(
            # On an attribute Get-GPOScheduledTasks writes only when the condition holds.
            # The definition had no triggers at all, so this write-up existed for a reader
            # who had no way to reach it. A Note, not a Hint: the Task Scheduler quotes the
            # program path itself, which was measured, so the row is hygiene, not a risk.
            @{ Attribute = 'gpoTaskUnquotedPath'; Severity = 'Note' }
        )
    }

    'GPO_TASK_CMD_UNQUOTED_PATH' = @{
        Title = "GPO Scheduled Task Hands cmd.exe an Unquoted Path"
        Risk = "Hint"
        BaseScore = 25
        Description = "A GPO-deployed scheduled task starts cmd.exe /c (or /k) with a program path that contains a space and is not quoted. Unlike the program field of the task, which the Task Scheduler quotes on its own, this is a command line that cmd.exe splits at the first space: for C:\Tools\My App\run.bat it starts C:\Tools\My.exe, .bat or .cmd if one exists, in the account the task runs as. Whether that is exploitable depends on who may create a file where the truncated path points. In the root of the system drive ordinary users may create folders but not files by Windows default; a folder an administrator created in that root inherits Modify for Authenticated Users."
        Impact = @(
            "Whoever can create the truncated program runs code in the task's account on every computer the policy reaches"
            "As SYSTEM, that is a local privilege escalation on each of them"
            "Until such a file exists, the task fails at every run - which usually goes unnoticed"
        )
        Attack = @(
            "1. Read the task out of ScheduledTasks.xml in SYSVOL as any domain user"
            "2. Check whether the directory of the truncated path is writable on a target - for C:\Tools\My App\run.bat that is C:\Tools"
            "3. Create C:\Tools\My.exe there"
            "4. The next run of the task starts it in the task's account"
        )
        Remediation = @(
            "Quote the program path inside the cmd.exe line, or make the program itself the task's program instead of starting it through cmd.exe"
            "Do not run scheduled tasks from a folder created in the root of a drive without hardening its permissions"
        )
        RemediationCommands = @(
            @{
                Description = "List every scheduled task in SYSVOL that hands cmd.exe a command line (replace the domain name)"
                Command = "Get-ChildItem '\\contoso.com\SYSVOL\contoso.com\Policies' -Recurse -Filter ScheduledTasks.xml | ForEach-Object { `$file = `$_.FullName; `$xml = New-Object System.Xml.XmlDocument; `$xml.Load(`$file); `$xml.SelectNodes('//Exec') | Where-Object { `$_.Command -match 'cmd(\.exe)?`"?`$' } | ForEach-Object { [PSCustomObject]@{ File = `$file; Command = `$_.Command; Arguments = `$_.Arguments } } }"
            }
        )
        References = @(
            @{ Title = "cmd - Microsoft Learn"; Url = "https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/cmd" }
            @{ Title = "Hijack Execution Flow: Path Interception by Unquoted Path - MITRE"; Url = "https://attack.mitre.org/techniques/T1574/009/" }
        )
        Tools = @("GPO analysis")
        MITRE = "T1574.009"
        Triggers = @(
            # On the statement Get-GPOScheduledTasks writes only when cmd.exe is handed such
            # a path. Where the truncated program would have to go into the root of the
            # system drive, ordinary users cannot create it by Windows default (measured),
            # and the row is a note; anywhere else it is a hint.
            @{ Attribute = 'gpoTaskCmdUnquotedPath'; Pattern = 'only administrators can create files'; Severity = 'Note' }
            @{ Attribute = 'gpoTaskCmdUnquotedPath'; ExcludePattern = 'only administrators can create files'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # ESC15 - NEW ADCS VARIANT
    # ============================================================================

    'ESC15_SCHEMA_V1_ENROLLEE_SUBJECT' = @{
        Title = "ESC15 - Schema v1 Template with Enrollee-Supplied Subject"
        Risk = "Finding"
        BaseScore = 60
        Description = "This certificate template uses Schema Version 1 and allows the enrollee to supply the subject name. On a v1 template the CA takes the Application Policies extension (1.3.6.1.4.1.311.21.10) out of the request, so the enrollee adds Client Authentication - or Certificate Request Agent - to a template that has neither, and supplies the subject of any account in the same request. Microsoft patched this as CVE-2024-49019 in November 2024. The patch level of the CA cannot be read over LDAP, which is the same reservation ESC9 carries about StrongCertificateBindingEnforcement, and is why this is reported as a finding on the template rather than scored down to a hint."
        Impact = @(
            "The enrollee injects the EKU: no client-authentication EKU is needed on the template, which is why no other check in this section flags it"
            "That makes it the one ESC that reaches exactly the templates everything else passes as harmless - a web server template is a typical case"
            "The subject comes from the request, so which account the certificate authenticates as is the attacker's choice"
            "Patched CA: direct exploitation blocked, but a v1 template remains less controllable than v2+ and cannot be confirmed as patched from here"
        )
        Attack = @(
            "1. Attacker enrolls using vulnerable v1 template on unpatched CA"
            "2. Injects Client Authentication EKU via Application Policies"
            "3. Specifies Domain Admin UPN in Subject Alternative Name"
            "4. Obtains a certificate that authenticates as the account it named"
            "5. Authenticates as Domain Admin via PKINIT"
        )
        Remediation = @(
            "Apply CVE-2024-49019 patch (November 2024 Patch Tuesday)"
            "Replace Schema v1 templates with v2+ duplicates"
            "Unpublish default v1 templates that are no longer needed"
            "Remove ENROLLEE_SUPPLIES_SUBJECT if not required"
            "Require CA Manager approval for subject requests"
            "Disable Application Policies extension: certutil -setreg policy\DisableExtensionList +1.3.6.1.4.1.311.21.10"
        )
        RemediationCommands = @(
            @{
                Description = "Duplicate Schema v1 template to v2+ (GUI method - run on CA or admin workstation)"
                Command = @'
# 1. Open Certificate Templates MMC (certtmpl.msc)
# 2. Right-click the vulnerable v1 template and select "Duplicate Template"
# 3. In the "Compatibility" tab, ensure Windows Server 2008 R2 or later (creates v2+)
# 4. In the "Subject Name" tab, select "Build from this Active Directory information"
# 5. Configure other settings as needed
# 6. Save the new template
# 7. Publish the new template on the CA
# 8. Unpublish the old v1 template

Write-Host "[!] This is a manual process requiring the Certificate Templates MMC" -ForegroundColor Yellow
'@
            }
            @{
                Description = "Unpublish vulnerable v1 template from CA"
                Command = @'
# Run on CA server
$templateName = "VulnerableV1Template"
certutil -deltemplate "$templateName"

# Or via PowerShell (requires RSAT-ADCS-Mgmt)
$caName = "$env:COMPUTERNAME\$((certutil -dump | Select-String 'Config:' | ForEach-Object { ($_ -split '\\')[-1].Trim() }))"
Remove-CATemplate -Name "$templateName" -Force
'@
            }
            @{
                Description = "Disable Application Policies extension on CA (prevents EKUwu attack)"
                Command = @'
# Run on CA server to block arbitrary Application Policy injection
certutil -setreg policy\DisableExtensionList +1.3.6.1.4.1.311.21.10

# Restart Certificate Services
net stop certsvc && net start certsvc

# Verify setting
certutil -getreg policy\DisableExtensionList
'@
            }
        )
        References = @(
            @{ Title = "TrustedSec - EKUwu (ESC15)"; Url = "https://trustedsec.com/blog/ekuwu-not-just-another-ad-cs-esc" }
            @{ Title = "CVE-2024-49019 - Microsoft"; Url = "https://msrc.microsoft.com/update-guide/vulnerability/CVE-2024-49019" }
            @{ Title = "Microsoft Defender for Identity - ESC15"; Url = "https://learn.microsoft.com/en-us/defender-for-identity/security-posture-assessments/certificates" }
        )
        Tools = @("Certipy", "Certify", "PSPKI")
        MITRE = "T1649"
        Triggers = @(
            # A Deny ACE on enrollment is hardening, so the row reads as a note rather than
            # a finding, and it names no card of its own.
            @{ Attribute = 'enrollmentDeniedPrincipals'; Severity = 'Note'; SeverityOnly = $true }

            # The two template caveats Get-ADCSVulnerabilities writes when a precondition
            # could not be read. Severity-only on purpose: they colour their own row and
            # name no card, because "this was not decided" is not a finding of its own -
            # and a card chosen by the highest base score must not be pulled here by a
            # caveat. ESC15 hosts them because it is the definition whose verdict both of
            # them withhold.
            @{ Attribute = 'escSchemaVersionUnread'; Severity = 'Hint'; SeverityOnly = $true }
            @{ Attribute = 'escPublicationUnread'; Severity = 'Hint'; SeverityOnly = $true }

            # Finding, not Hint. ESC15 was the lowest-rated ADCS definition at 30 while
            # being the only one that needs no client-authentication EKU on the template -
            # it reaches the templates every other ESC passes as harmless. The reservation
            # about the CA's patch level now stands in the text, where a reader sees it,
            # instead of silently halving the score.
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC15'; Severity = 'Finding' }
            # Colour only, and this was the broadest of them: schema version 1 is the
            # template version Windows 2000 and 2003 shipped, so a domain that has been
            # upgraded rather than rebuilt is full of them. ESC15 is a V1 template that
            # also lets the requester supply the subject and carries an authentication
            # EKU - the version on its own says only how old the template is.
            @{ Attribute = 'SchemaVersion'; Pattern = '^1$'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    # ============================================================================
    # ESC13 - ISSUANCE POLICY GROUP LINK
    # ============================================================================

    'CREDENTIAL_ROAMING_PRESENT' = @{
        Title = "Credential Roaming - Private Keys and DPAPI Master Keys Stored in AD"
        Risk = "Hint"
        BaseScore = 45
        Description = "This user object carries roamed credential material. Credential Roaming copies the public-key part of a Windows profile into attributes on the user object so that it follows the user to every machine they log on to: certificates, certificate requests, private keys in msPKIAccountCredentials, and the user's DPAPI master keys in msPKIDPAPIMasterKeys. A DPAPI master key is what protects everything else that user stored under DPAPI - saved RDP credentials in .rdg files, browser secrets, WLAN keys, the Credential Manager. The attributes hold ciphertext rather than plaintext, which is why this is reported as a hint on its own: a master key is sealed with a pre-key derived from the user's password and with the domain backup key, and the private keys are sealed with those master keys in turn. What it establishes is that the material is in the directory at all, which is the precondition for the rest."
        Impact = @(
            "Anybody who later obtains the user's password or hash decrypts the master keys and with them every DPAPI secret of that profile"
            "Anybody who obtains the domain backup key decrypts them without the user's password - and every domain administrator holds it"
            "A roamed client-authentication or smartcard certificate then impersonates the user through PKINIT or Schannel, with no password involved"
            "The material survives a password change, because the domain backup key path does not depend on the password"
            "DCSync, a copy of ntds.dit or an AD backup yields it regardless of any permission on the attributes"
        )
        Attack = @(
            "1. Read msPKIDPAPIMasterKeys and msPKIAccountCredentials from the target user object"
            "2. Export the domain backup key from a domain controller (lsadump::backupkeys /export) or use the user's password or hash"
            "3. Decrypt the master keys offline (dpapi::masterkey /in:<blob> /pvk:<backupkey>.pvk)"
            "4. Decrypt the private key out of msPKIAccountCredentials with the recovered master key"
            "5. Authenticate as the user with the recovered certificate, or decrypt their stored DPAPI secrets"
        )
        Remediation = @(
            "Turn Credential Roaming off where it is not genuinely needed - every unnecessary deployment puts private keys and master keys into the directory for nothing"
            "Mark msPKIAccountCredentials and msPKIDPAPIMasterKeys confidential in the schema, which stops ordinary users reading them"
            "Clear the attributes on accounts that no longer need roaming; disabling the policy does not remove what has already synchronised"
            "Prefer smartcards or Windows Hello for Business with non-exportable, TPM-bound keys, which never roam"
            "Treat the domain backup key as a Tier 0 secret and rotate it after a domain controller compromise, or all roamed material stays decryptable"
            "Keep clients on the September 2022 patch level or later for CVE-2022-30170, a client-side flaw in how roamed data is written back"
        )
        RemediationCommands = @(
            @{
                Description = "List every user carrying roamed credential material, without retrieving the blobs"
                Command = @'
Get-ADUser -LDAPFilter '(msPKIDPAPIMasterKeys=*)' -Properties msPKIRoamingTimeStamp |
    Select-Object SamAccountName, msPKIRoamingTimeStamp
'@
            }
            @{
                Description = "Read the confidential flag on both attributes (bit 7, value 128)"
                Command = @'
Get-ADObject -SearchBase (Get-ADRootDSE).schemaNamingContext `
    -LDAPFilter '(|(lDAPDisplayName=msPKIAccountCredentials)(lDAPDisplayName=msPKIDPAPIMasterKeys))' `
    -Properties lDAPDisplayName, searchFlags |
    Select-Object lDAPDisplayName, searchFlags,
        @{n='Confidential'; e={ ($_.searchFlags -band 128) -ne 0 }}
'@
            }
            @{
                Description = "Mark both attributes confidential. Forest-wide and needs Schema Admin - test first, a reader with only generic read loses access"
                Command = @'
$schema = (Get-ADRootDSE).schemaNamingContext
foreach ($name in 'ms-PKI-AccountCredentials', 'ms-PKI-DPAPIMasterKeys') {
    $attr = Get-ADObject -SearchBase $schema -LDAPFilter "(cn=$name)" -Properties searchFlags
    Set-ADObject -Identity $attr.DistinguishedName `
        -Replace @{ searchFlags = ($attr.searchFlags -bor 128) }
}
'@
            }
        )
        References = @(
            @{ Title = "Credential Roaming (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/credential-roaming" }
            @{ Title = "Confidential attributes (searchFlags fCONFIDENTIAL)"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-searchflags" }
            @{ Title = "CVE-2022-30170 - Credential Roaming elevation of privilege"; Url = "https://msrc.microsoft.com/update-guide/vulnerability/CVE-2022-30170" }
        )
        Tools = @("adPEAS", "SharpDPAPI", "mimikatz")
        MITRE = "T1552.004"
        Triggers = @(
            @{ Attribute = 'RoamedMaterial'; Severity = 'Hint' }

            # A roamed privileged account is a different proposition from a roamed helpdesk
            # account: the certificate it carries authenticates as that account, so the
            # recovered private key is a direct route to it.
            @{ Attribute = 'PrivilegedAccount'; Pattern = '^Yes$'; Severity = 'Finding' }
        )
    }

    'CREDENTIAL_ROAMING_READABLE' = @{
        Title = "Credential Roaming - Roamed Material Readable by Any Authenticated User"
        Risk = "Finding"
        BaseScore = 80
        Description = "The two attributes that hold roamed private keys and DPAPI master keys are not marked confidential in the schema, so reading them follows the ordinary read permissions of the user object. In a default domain that means every authenticated user can read the roamed material of every other user, including privileged ones. Readability is controlled by searchFlags bit 7, fCONFIDENTIAL, value 128; these attributes ship without it and most forests have never set it. The material is still ciphertext, so this is not an immediate takeover - but the one thing an attacker normally cannot obtain, the private key of another user, is then a single offline decryption away, and the key needed for that decryption is held by every domain administrator."
        Impact = @(
            "Any authenticated user harvests the roamed material of every user in the domain, with no special rights and nothing to exploit"
            "The harvest is a read, so it leaves no trace beyond LDAP query logging"
            "Combined with the domain backup key, or the target's password or hash, it yields their private keys and every DPAPI secret of their profile"
            "A roamed client-authentication certificate then authenticates as that user without their password"
            "Collected material stays usable after a password change, because decryption through the domain backup key does not depend on it"
        )
        Attack = @(
            "1. As any domain user, query every user object for msPKIDPAPIMasterKeys and msPKIAccountCredentials"
            "2. Store the blobs - no privileges were needed to read them and none are needed to keep them"
            "3. Wait for, or work towards, either the target's hash or the domain backup key"
            "4. Decrypt the master keys offline, then the private keys they protect"
            "5. Impersonate the user with a roamed authentication certificate"
        )
        Remediation = @(
            "Mark msPKIAccountCredentials and msPKIDPAPIMasterKeys confidential in the schema - this is the one change that stops ordinary users reading them"
            "Verify afterwards as a low-privileged user that the attributes no longer come back"
            "Turn Credential Roaming off where it is not needed, and clear the attributes that already synchronised"
            "Treat the domain backup key as a Tier 0 secret, since it is the other half of this"
            "Monitor for unusual read or replication activity against these attributes"
        )
        RemediationCommands = @(
            @{
                Description = "Mark both attributes confidential. Forest-wide and needs Schema Admin"
                Command = @'
$schema = (Get-ADRootDSE).schemaNamingContext
foreach ($name in 'ms-PKI-AccountCredentials', 'ms-PKI-DPAPIMasterKeys') {
    $attr = Get-ADObject -SearchBase $schema -LDAPFilter "(cn=$name)" -Properties searchFlags
    Set-ADObject -Identity $attr.DistinguishedName `
        -Replace @{ searchFlags = ($attr.searchFlags -bor 128) }
}
'@
            }
            @{
                Description = "The honest verification - run as a low-privileged user and expect nothing back"
                Command = @'
Get-ADUser <targetuser> -Properties msPKIAccountCredentials, msPKIDPAPIMasterKeys |
    Select-Object Name,
        @{n='Cred'; e={ @($_.msPKIAccountCredentials).Count }},
        @{n='MK';   e={ @($_.msPKIDPAPIMasterKeys).Count }}
'@
            }
        )
        References = @(
            @{ Title = "Confidential attributes (searchFlags fCONFIDENTIAL)"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-searchflags" }
            @{ Title = "Credential Roaming (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/credential-roaming" }
        )
        Tools = @("adPEAS", "SharpDPAPI", "mimikatz")
        MITRE = "T1552.004"
        Triggers = @(
            @{ Attribute = 'ReadableBy'; Pattern = '^Any authenticated user'; Severity = 'Finding' }

            # Confidential is the hardened state, so it is the one row in this section that
            # lowers the risk rather than raising it.
            @{ Attribute = 'ReadableBy'; Pattern = '^Control Access holders only'; Severity = 'Secure' }

            # Unknown is missing information, not a clean result. Yellow, so it reads as
            # something to go and check by hand rather than as either verdict.
            @{ Attribute = 'ReadableBy'; Pattern = '^Unknown'; Severity = 'Hint' }
        )
    }

    'CREDENTIAL_ROAMING_DELEGATED' = @{
        Title = "Credential Roaming - Read of Private Keys and Master Keys Delegated to a Principal"
        Risk = "Finding"
        BaseScore = 85
        Description = "A principal holds an explicit read of the Credential Roaming attributes on a container whose users carry roamed material. This is the case the confidential flag says nothing about, and the one most likely to have happened by accident: a delegation wizard pointed at the wrong attribute set, or a script copied from a Credential Roaming rollout guide, gives a helpdesk group a read of another user's private keys and DPAPI master keys. Nothing about the result looks unusual afterwards. Whether the right is live depends on the schema - a confidential attribute needs READ_PROPERTY and CONTROL_ACCESS, a non-confidential one needs only the former - so the same ACE is exploitable in one forest and dormant in another, and the row says which."
        Impact = @(
            "The holder reads another user's private keys and DPAPI master keys with a plain LDAP query, no exploit involved"
            "With the domain backup key, or the target's password or hash, that material decrypts offline"
            "A roamed client-authentication certificate then authenticates as the target without their password"
            "The right usually applies to a whole container, so it covers every user below it, not one account"
            "A right the confidential flag currently blocks becomes live the moment somebody clears the flag"
        )
        Attack = @(
            "1. As the delegated principal, read msPKIDPAPIMasterKeys and msPKIAccountCredentials from the users in scope"
            "2. Obtain the domain backup key, or the target's password or hash"
            "3. Decrypt the master keys offline, then the private keys they protect"
            "4. Authenticate as the target with a recovered certificate, or decrypt their stored DPAPI secrets"
        )
        Remediation = @(
            "Remove the ACE unless the principal genuinely needs to read other users' private keys - almost nothing does"
            "Check what the delegation was meant to grant; a wizard or script that produced this one has probably produced others"
            "Mark the two attributes confidential in the schema, which at least stops READ_PROPERTY alone from working"
            "Clear the attributes on accounts that do not need roaming, and turn Credential Roaming off where it is not needed"
            "Treat the domain backup key as a Tier 0 secret - it is the other half of every one of these findings"
        )
        RemediationCommands = @(
            @{
                Description = "Show the delegated read ACEs on a container, resolved to attribute names"
                Command = @'
$roaming = @{
    'b8dfa744-31dc-4ef1-ac7c-84baf7ef9da7' = 'ms-PKI-AccountCredentials'
    'b3f93023-9239-4f7c-b99c-6745d87adbc2' = 'ms-PKI-DPAPIMasterKeys'
    '6617e4ac-a2f1-43ab-b60c-11fbd1facf05' = 'ms-PKI-RoamingTimeStamp'
}
(Get-Acl "AD:\<container DN>").Access |
    Where-Object { $roaming.ContainsKey($_.ObjectType.ToString()) } |
    Select-Object IdentityReference, ActiveDirectoryRights, IsInherited,
        @{n='Attribute'; e={ $roaming[$_.ObjectType.ToString()] }}
'@
            }
            @{
                Description = "Remove one delegated read. Check the output above first - the ACE may be inherited, in which case it has to go from the container it is inherited from"
                Command = @'
$acl = Get-Acl "AD:\<container DN>"
$ace = $acl.Access | Where-Object {
    $_.IdentityReference -eq '<DOMAIN\principal>' -and
    $_.ObjectType -eq 'b3f93023-9239-4f7c-b99c-6745d87adbc2'
}
$null = $acl.RemoveAccessRule($ace)
Set-Acl -Path "AD:\<container DN>" -AclObject $acl
'@
            }
        )
        References = @(
            @{ Title = "Credential Roaming (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/credential-roaming" }
            @{ Title = "Confidential attributes - READ_PROPERTY plus CONTROL_ACCESS"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/mark-attribute-as-confidential" }
        )
        Tools = @("adPEAS", "SharpDPAPI", "mimikatz")
        MITRE = "T1552.004"
        Triggers = @(
            # The rights string is split per value by the dangerousRights transformer, so each
            # named attribute gets its own tooltip. ms-PKI- covers all three; the timestamp
            # alone is rated Low upstream and does not reach a default report.
            @{ Attribute = 'dangerousRights'; Pattern = 'ms-PKI-'; Severity = 'Finding' }
            @{ Attribute = 'dangerousRights'; Pattern = 'includes the roaming attributes'; Severity = 'Finding' }

            # The verdict row. Dormant is green because the flag is doing its job today, and
            # the row's own text says it goes live the moment that changes.
            @{ Attribute = 'EffectiveToday'; Pattern = '^Yes'; Severity = 'Finding' }
            @{ Attribute = 'EffectiveToday'; Pattern = '^No'; Severity = 'Secure' }
            @{ Attribute = 'EffectiveToday'; Pattern = '^Unknown'; Severity = 'Hint' }
        )
    }

    'ESC14_WEAK_EXPLICIT_MAPPING' = @{
        Title = "ESC14 - Weak Explicit Certificate Mapping"
        Risk = "Finding"
        BaseScore = 75
        Description = "The altSecurityIdentities attribute of this principal carries a certificate mapping in one of the three formats Microsoft classifies as weak (KB5014754): issuer and subject name, subject name alone, or an e-mail address. Each of those names something an attacker can put into a certificate of their own, so the mapping no longer proves which certificate it was written for. A certificate the attacker enrols with a matching subject or e-mail authenticates as this principal, and the CA's SID extension - the binding this attribute overrides - never gets a say."
        Impact = @(
            "Anyone able to obtain a certificate with a matching subject or e-mail authenticates as this principal"
            "On a template where the enrollee supplies the subject, that is a single certificate request"
            "The mapping survives a password change, so it is also a persistence mechanism"
            "Strong certificate binding enforcement on the domain controllers does not close it: an explicit mapping is honoured by design"
        )
        Remediation = @(
            "Replace the mapping with a strong format: X509IssuerSerialNumber, X509SKI or X509SHA1PublicKey"
            "Remove the mapping entirely where the account no longer needs certificate authentication"
            "Restrict who may write altSecurityIdentities on privileged accounts"
        )
        RemediationCommands = @(
            @{
                Description = "List every principal carrying a weak explicit mapping"
                Command = @'
Get-ADObject -LDAPFilter '(altSecurityIdentities=*)' -Properties altSecurityIdentities |
    ForEach-Object {
        foreach ($m in $_.altSecurityIdentities) {
            # Strong: <SKI>, <SHA1-PUKEY>, <SR>. Weak: <RFC822>, <S> without <SR>.
            if ($m -match '<SKI>|<SHA1-PUKEY>|<SR>') { continue }
            if ($m -match '<RFC822>|<S>') {
                [PSCustomObject]@{ Account = $_.Name; Mapping = $m }
            }
        }
    }
'@
            }
            @{
                Description = "Replace a weak mapping with the issuer and serial number of the intended certificate"
                Command = @'
$cert = Get-PfxCertificate -FilePath .\intended.cer
$issuer = ($cert.Issuer -split ',\s*') [array]::Reverse($issuer)
$strong = "X509:<I>$($issuer -join ',')<SR>$($cert.SerialNumber)"
Set-ADUser -Identity 'targetuser' -Replace @{ altSecurityIdentities = $strong }
'@
            }
        )
        References = @(
            @{ Title = "ADCS ESC14 Abuse Technique (SpecterOps)"; Url = "https://posts.specterops.io/adcs-esc14-abuse-technique-333a004dc2b9" }
            @{ Title = "KB5014754 - Certificate-based authentication changes"; Url = "https://support.microsoft.com/en-us/topic/kb5014754-certificate-based-authentication-changes-on-windows-domain-controllers-ad2c23b0-15d8-4340-a468-4d4f3b188f16" }
        )
        Triggers = @(
            @{ Attribute = 'weakCertificateMappings'; Severity = 'Finding' }
            @{ Attribute = 'mappingIsPrivilegedTarget'; Pattern = '^True$'; Severity = 'Finding' }
            @{ Attribute = 'strongCertificateMappings'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'ESC14_WRITABLE_MAPPING' = @{
        Title = "ESC14 - altSecurityIdentities Writable by a Non-Privileged Principal"
        Risk = "Finding"
        BaseScore = 80
        Description = "A non-privileged principal may write the altSecurityIdentities attribute of this privileged account. That attribute maps a certificate to the account explicitly, so the write is enough to add a mapping for a certificate the attacker already holds and then authenticate as the account. No certificate template misconfiguration is needed and nothing about the account itself changes."
        Impact = @(
            "The trustee adds a mapping for a certificate they control and authenticates as this account"
            "No password is changed and no group membership is touched, so the account looks untouched"
            "The mapping persists until somebody reads the attribute"
        )
        Remediation = @(
            "Remove WriteProperty on altSecurityIdentities, and the blanket rights that include it, from non-administrative principals"
            "Check the property-set delegations too: WriteProperty on the set that contains the attribute - usually Public-Information - grants it without naming it"
            "Check the owner of the account: an owner may rewrite the DACL and grant itself the write, so an owner outside the administrative tier is the same exposure"
            "Audit the attribute on privileged accounts: a mapping that is already there may have been added this way"
            "Monitor changes to altSecurityIdentities on privileged accounts"
        )
        RemediationCommands = @(
            @{
                Description = "Show who holds write access to altSecurityIdentities on an account"
                Command = @'
$dn = 'CN=Administrator,CN=Users,DC=contoso,DC=com'
$altSecGuid = [GUID]'00fbf30c-91fe-11d1-aebc-0000f80367c1'
(Get-Acl "AD:\$dn").Access |
    Where-Object {
        $_.AccessControlType -eq 'Allow' -and (
            $_.ActiveDirectoryRights -match 'GenericAll|GenericWrite|WriteDacl|WriteOwner' -or
            ($_.ActiveDirectoryRights -match 'WriteProperty' -and
             ($_.ObjectType -eq $altSecGuid -or $_.ObjectType -eq [GUID]::Empty))
        )
    } | Select-Object IdentityReference, ActiveDirectoryRights, ObjectType
'@
            }
        )
        References = @(
            @{ Title = "ADCS ESC14 Abuse Technique (SpecterOps)"; Url = "https://posts.specterops.io/adcs-esc14-abuse-technique-333a004dc2b9" }
        )
        Triggers = @(
            @{ Attribute = 'altSecurityIdentitiesWriters'; Severity = 'Finding' }

            # The Exchange service groups are listed separately by the check and carry
            # their own colour. The permission is real - Exchange Trusted Subsystem and
            # Organization Management hold blanket rights on user objects and that is a
            # known escalation path - but it is the by-design ACL the Exchange setup
            # writes, it lands on every privileged account in the domain at once, and it
            # is not the delegation ESC14 is looking for. Red on all of them trains the
            # reader to skip the section that also carries the real one.
            @{ Attribute = 'exchangeServiceWriters'; Severity = 'Hint' }
        )
    }

    'ESC13_ISSUANCE_POLICY_GROUP_LINK' = @{
        Title = "ESC13 - Issuance Policy Linked to AD Group"
        Risk = "Finding"
        BaseScore = 70
        Description = "A certificate template references an issuance policy OID that is linked to an AD group via the msDS-OIDToGroupLink attribute. When a user enrolls in this template, the resulting certificate grants automatic membership in the linked group. This can be abused for privilege escalation if non-privileged users can enroll."
        Impact = @(
            "Attacker enrolls in the template and gains membership in the linked AD group"
            "If the linked group is privileged, this directly escalates privileges"
            "Certificate-based group membership bypasses traditional group management controls"
            "The group membership is granted automatically upon certificate issuance"
        )
        Remediation = @(
            "Remove the msDS-OIDToGroupLink attribute from the issuance policy OID object"
            "Remove the issuance policy from the template's msPKI-Certificate-Policy attribute"
            "Restrict enrollment permissions to privileged users only"
            "Review which groups are linked to issuance policies and assess the security impact"
        )
        RemediationCommands = @(
            @{
                Description = "Remove msDS-OIDToGroupLink attribute from issuance policy OID"
                Command = @'
# Find OID objects with group links
$configNC = (Get-ADRootDSE).configurationNamingContext
$oidContainer = "CN=OID,CN=Public Key Services,CN=Services,$configNC"
$linkedOIDs = Get-ADObject -SearchBase $oidContainer -Filter {msDS-OIDToGroupLink -like "*"} -Properties msDS-OIDToGroupLink,displayName

foreach ($oid in $linkedOIDs) {
    Write-Host "[!] OID: $($oid.displayName) linked to: $($oid.'msDS-OIDToGroupLink')" -ForegroundColor Yellow
    # Remove the link
    Set-ADObject -Identity $oid.DistinguishedName -Clear msDS-OIDToGroupLink
    Write-Host "[+] Removed group link from OID: $($oid.displayName)" -ForegroundColor Green
}
'@
            }
            @{
                Description = "Remove issuance policy from vulnerable certificate template"
                Command = @'
$templateName = "VulnerableTemplate"
$configNC = (Get-ADRootDSE).configurationNamingContext
$templateDN = "CN=$templateName,CN=Certificate Templates,CN=Public Key Services,CN=Services,$configNC"

# Get current policies
$template = Get-ADObject -Identity $templateDN -Properties msPKI-Certificate-Policy
Write-Host "[!] Current policies: $($template.'msPKI-Certificate-Policy')" -ForegroundColor Yellow

# Remove all policies (or selectively remove specific OID)
Set-ADObject -Identity $templateDN -Clear msPKI-Certificate-Policy
Write-Host "[+] Removed issuance policies from template" -ForegroundColor Green
'@
            }
            @{
                Description = "List all OID-to-Group links in the environment"
                Command = @'
# Audit all OID-to-Group links
$configNC = (Get-ADRootDSE).configurationNamingContext
$oidContainer = "CN=OID,CN=Public Key Services,CN=Services,$configNC"
$linkedOIDs = Get-ADObject -SearchBase $oidContainer -Filter {msDS-OIDToGroupLink -like "*"} -Properties msDS-OIDToGroupLink,displayName,msPKI-Cert-Template-OID

foreach ($oid in $linkedOIDs) {
    $groupDN = $oid.'msDS-OIDToGroupLink'
    $group = Get-ADGroup -Identity $groupDN -Properties Name,Description
    Write-Host "`nOID: $($oid.displayName)" -ForegroundColor Cyan
    Write-Host "  OID Value: $($oid.'msPKI-Cert-Template-OID')"
    Write-Host "  Linked Group: $($group.Name)"
    Write-Host "  Group DN: $groupDN"
}
'@
            }
        )
        References = @(
            @{ Title = "ESC13 - ADCS Abuse Technique"; Url = "https://posts.specterops.io/adcs-esc13-abuse-technique-fda4272fbd53" }
            @{ Title = "Certified Pre-Owned - SpecterOps"; Url = "https://posts.specterops.io/certified-pre-owned-d95910965cd2" }
            @{ Title = "Issuance Policies and OID Group Links - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
        )
        Tools = @("Certipy", "Certify", "BloodHound")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'Vulnerabilities'; Pattern = 'ESC13'; Severity = 'Finding' }

            # The link row itself follows what the group is worth: red where enrollment
            # grants membership in a privileged group, yellow where it grants membership in
            # something that is not. Both are reported - a group nobody applied for is
            # still a membership - but a distribution group and Domain Admins used to be
            # the same finding at the same score.
            @{ Attribute = 'IssuancePolicyGroupLinks'; Pattern = '\[privileged'; Severity = 'Finding' }
            @{ Attribute = 'IssuancePolicyGroupLinks'; Pattern = '.'; Severity = 'Hint' }

            # And the same damping on the ESC13 row of the Vulnerabilities line, so the
            # card keeps its text and its remediation while the colour says what the link
            # is worth. This is the mechanism ra_signature_gated and manager_approval_gated
            # use for the two enrollment barriers.
            @{ Attribute = 'Vulnerabilities'; Custom = 'esc13_group_not_privileged'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    # ============================================================================
    # CA CERTIFICATE SECURITY FINDINGS
    # ============================================================================

    'ADCS_CA_WEAK_SIGNATURE' = @{
        Title = "CA Certificate Uses Weak Signature Algorithm"
        Risk = "Finding"
        BaseScore = 50
        Description = "The Certificate Authority's signing certificate uses a weak or deprecated signature algorithm (SHA-1, MD5, or MD2). Certificates signed with weak algorithms are vulnerable to collision attacks, potentially allowing attackers to forge certificates."
        Impact = @(
            "Weak hash algorithms are susceptible to collision attacks"
            "Forged certificates could be created that appear valid"
            "Modern security policies and browsers reject SHA-1 signed certificates"
        )
        Remediation = @(
            "Renew the CA certificate with SHA-256 or stronger signature algorithm"
            "Plan CA migration if the current CA does not support modern algorithms"
            "Verify all issued certificates also use strong signature algorithms"
        )
        RemediationCommands = @(
            @{
                Description = "Configure CA to use SHA-256 hash algorithm"
                Command = "certutil -setreg ca\csp\CNGHashAlgorithm SHA256"
            }
            @{
                Description = "Restart Certificate Services to apply changes"
                Command = "Restart-Service -Name CertSvc"
            }
            @{
                Description = "Verify current hash algorithm configuration"
                Command = "certutil -getreg ca\csp\CNGHashAlgorithm"
            }
        )
        References = @(
            @{ Title = "SHA-1 Deprecation - Microsoft"; Url = "https://techcommunity.microsoft.com/t5/windows-it-pro-blog/sha-1-windows-content-signing-is-ending/ba-p/3608963" }
            @{ Title = "Change SHA1 to SHA256 in Certification Authority - Evotec"; Url = "https://evotec.xyz/windows-server-how-to-change-sha1-to-sha256-sha384-or-sha512-options-in-certification-authority/" }
            @{ Title = "Migrate ADCS to SHA-2 - 4sysops"; Url = "https://4sysops.com/archives/how-to-migrate-active-directory-certificate-services-to-sha-2-and-key-storage-provider/" }
        )
        Tools = @("Certipy", "Certify", "certutil")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'CACertWeakSignature'; Pattern = '.'; Severity = 'Finding' }
            @{ Attribute = 'CACertSignatureAlgorithm'; Pattern = '(?i)sha1|md5|md2'; Severity = 'Finding' }
        )
    }

    'ADCS_CA_SHORT_KEY' = @{
        Title = "CA Certificate Uses Insufficient Key Length"
        Risk = "Finding"
        BaseScore = 50
        Description = "The Certificate Authority's signing certificate uses a public key shorter than 2048 bits. Short keys are vulnerable to factoring attacks and do not meet current security standards."
        Impact = @(
            "Keys shorter than 2048 bits can potentially be factored"
            "All certificates issued by this CA inherit the weak security"
            "Non-compliant with NIST SP 800-57 and industry standards"
        )
        Remediation = @(
            "Renew the CA certificate with at least 2048-bit RSA key (4096-bit recommended)"
            "For ECC keys, use P-256 or stronger curves"
            "Plan CA migration if the current key cannot be upgraded"
        )
        RemediationCommands = @(
            @{
                Description = "Renew CA certificate with 4096-bit key (generates new key)"
                Command = "certutil -renewCert"
            }
            @{
                Description = "Check current CA certificate key length"
                Command = "certutil -cainfo cert | findstr `"Public Key Length`""
            }
            @{
                Description = "Configure default key length for new CA certificates"
                Command = "# Renew CA cert via GUI (certsrv.msc) - specify 4096-bit key during renewal wizard"
            }
        )
        References = @(
            @{ Title = "NIST SP 800-57 Key Management"; Url = "https://csrc.nist.gov/publications/detail/sp/800-57-part-1/rev-5/final" }
            @{ Title = "Key Length Requirements for AD CS - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
            @{ Title = "Renew Windows Root CA Certificate - 4sysops"; Url = "https://4sysops.com/archives/renew-windows-root-ca-certificate/" }
        )
        Tools = @("Certipy", "Certify", "certutil")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'CACertShortKey'; Pattern = '.'; Severity = 'Finding' }
            @{ Attribute = 'CACertKeySize'; Pattern = '^(512|768|1024) bit$'; Severity = 'Finding' }
        )
    }

    'ADCS_CA_CERT_EXPIRED' = @{
        Title = "CA Certificate Has Expired"
        Risk = "Finding"
        BaseScore = 60
        Description = "The Certificate Authority's signing certificate has expired. An expired CA certificate means the CA can no longer issue valid certificates, and existing certificates may fail validation."
        Impact = @(
            "CA cannot issue new valid certificates"
            "Existing certificates signed by this CA may fail chain validation"
            "Certificate-based authentication (PKINIT, smart card) may stop working"
            "Services relying on auto-enrollment will fail"
        )
        Remediation = @(
            "Renew the CA certificate immediately"
            "If the CA is no longer needed, decommission it properly"
            "Verify all dependent services after certificate renewal"
        )
        RemediationCommands = @(
            @{
                Description = "Renew CA certificate with new key"
                Command = "certutil -renewCert"
            }
            @{
                Description = "Renew CA certificate keeping existing key"
                Command = "certutil -renewCert ReuseKeys"
            }
            @{
                Description = "Install renewed subordinate CA certificate"
                Command = "certutil -installCert <CACertFileName>"
            }
        )
        References = @(
            @{ Title = "Renewing CA Certificate - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
            @{ Title = "Renew Certificate Authority Certificates - Microsoft"; Url = "https://techcommunity.microsoft.com/blog/askds/renew-certificate-authority-certificates-on-windows-server-core-no-problem/4006988" }
        )
        Tools = @("certutil", "Certipy")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'CACertExpired'; Pattern = '.'; Severity = 'Finding' }
            @{ Attribute = 'CACertValidity'; Pattern = 'EXPIRED'; Severity = 'Finding' }
        )
    }

    'ADCS_CA_CROSS_DOMAIN' = @{
        Title = "CA Server in Different Domain"
        Risk = "Info"
        BaseScore = 0
        Description = "The CA server's computer object is in a different domain partition than the current query target. CA configuration data is shown from the forest-wide Configuration Partition."
        Triggers = @(
            @{ Attribute = 'caNote'; Severity = 'Hint'; SeverityOnly = $true }
        )
    }

    # ============================================================================
    # PKI INFRASTRUCTURE CERTIFICATE FINDINGS (Root CAs, NTAuth, AIA)
    # ============================================================================

    'PRIVILEGED_GROUP_ACL' = @{
        Title = "Control Over a Privileged Group That AdminSDHolder Does Not Protect"
        Risk = "Finding"
        BaseScore = 75
        Description = "A principal may change a privileged group that AdminSDHolder does not protect. SDProp resets the DACL of the protected groups every hour - Microsoft lists Account Operators, Administrators, Backup Operators, Domain Admins, Domain Controllers, Enterprise Admins, Enterprise Key Admins, Key Admins, Print Operators, Read-only Domain Controllers, Replicator, Schema Admins and Server Operators, unless character 16 of dsHeuristics takes the operator groups among them out - and leaves every other group with whatever ACEs it is given. Several of those are privileged in all but name: DnsAdmins can load code into the DNS service on the domain controllers, Group Policy Creator Owners create policy, the Exchange groups hold rights on the domain, and a group nested into one of them passes its membership on. Whoever may write the member attribute, use the Self-Membership validated write, rewrite the DACL, take ownership or already owns the group can make any account a member - their own included - and with it gets what the group can do."
        Impact = @(
            "The holder adds an account of its choosing to the group, and that account receives the group's rights at its next logon"
            "DnsAdmins membership leads to code execution as SYSTEM on the domain controllers that run DNS"
            "A right on a nested group is a right on every group it is nested into"
            "Nothing resets the ACE: unlike a protected group, this one keeps it until somebody removes it"
        )
        Attack = @(
            "1. As the holder, add a controlled account to the group with an LDAP write of its member attribute"
            "2. Sign in again so the new membership is in the token"
            "3. Use the group's rights - DnsAdmins: configure a plugin DLL for the DNS service (dnscmd /config /serverlevelplugindll), which it loads as SYSTEM when it next starts"
        )
        Remediation = @(
            "Remove the ACE unless the principal is meant to manage this group; an inherited one has to go at the container it comes from"
            "Move privileged groups into an OU that only Tier 0 administrators control, so no delegation on an ordinary OU reaches them"
            "Keep Account Operators empty - the group class gives them full control over every group AdminSDHolder does not protect"
            "Audit changes to the member attribute of these groups (event 4728/4732/4756, or 5136 on the object)"
        )
        RemediationCommands = @(
            @{
                Description = "Show who may change the membership, the permissions or the owner of a group"
                Command = @'
$acl = Get-Acl "AD:\<group DN>"
$acl.Owner
$acl.Access | Where-Object {
    $_.AccessControlType -eq 'Allow' -and
    $_.ActiveDirectoryRights -match 'GenericAll|GenericWrite|WriteDacl|WriteOwner|WriteProperty|Self'
} | Select-Object IdentityReference, ActiveDirectoryRights, ObjectType, IsInherited
'@
            }
        )
        References = @(
            @{ Title = "Appendix C - Protected Accounts and Groups in Active Directory (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-c--protected-accounts-and-groups-in-active-directory" }
            @{ Title = "Group class - default security descriptor (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/c-group" }
        )
        Tools = @("BloodHound", "PowerView", "dnscmd")
        MITRE = "T1098"
        Triggers = @(
            # The labels only this check writes. GenericAll, WriteDacl and WriteOwner keep the
            # generic cards they reach everywhere else.
            @{ Attribute = 'dangerousRights'; Pattern = 'may add a member to the group$|may add itself to the group$|^Owner of the group - '; Severity = 'Finding' }
            @{ Attribute = 'affectedGroups'; Custom = 'dangerous_rights_expected'; Severity = 'Hint'; SeverityOnly = $true }
            @{ Attribute = 'affectedGroups'; Severity = 'Finding' }
        )
    }

    'PRIVILEGED_ACCOUNT_ACL' = @{
        Title = "Control Over a Privileged Account"
        Risk = "Finding"
        BaseScore = 75
        Description = "A principal outside Tier-0 holds a right on a privileged account that lets it act as that account: it may reset the password, add a key credential (shadow credentials), give the account an SPN and crack the ticket, map a certificate onto it, switch off its pre-authentication, set a logon script, rewrite the DACL or take ownership. The account is a member of a privileged group, so the holder receives the group's rights. AdminSDHolder resets the DACL of the accounts it protects every hour; an entry found on such an account was added since, or the account is no longer protected. Every other privileged account - a member of DnsAdmins or of Group Policy Creator Owners, for instance - keeps what it is given, including what an OU delegation passes down."
        Impact = @(
            "The holder authenticates as the privileged account and holds every right of its groups"
            "Password reset and certificate mapping work without the account's password; a key credential leaves the password untouched and is easily missed"
            "An inherited right reaches every account below the OU it was delegated on"
        )
        Attack = @(
            "1. As the holder, add a key credential to the account (Whisker, pyWhisker) or reset its password"
            "2. Request a TGT for the account with the key (PKINIT) or the new password"
            "3. Use the account's group rights - Domain Admin, DnsAdmins code execution on the DNS servers, or policy creation"
        )
        Remediation = @(
            "Remove the entry from the account; an inherited one has to go at the container it comes from"
            "Keep privileged accounts in an OU that only Tier 0 administrators control, so no delegation on an ordinary OU reaches them"
            "Keep Account Operators empty - the user class gives them full control over every account AdminSDHolder does not protect"
        )
        RemediationCommands = @(
            @{
                Description = "Show who may take over an account through its DACL or its owner"
                Command = @'
$acl = Get-Acl "AD:\<account DN>"
$acl.Owner
$acl.Access | Where-Object {
    $_.AccessControlType -eq 'Allow' -and
    $_.ActiveDirectoryRights -match 'GenericAll|GenericWrite|WriteDacl|WriteOwner|WriteProperty|ExtendedRight'
} | Select-Object IdentityReference, ActiveDirectoryRights, ObjectType, IsInherited
'@
            }
        )
        References = @(
            @{ Title = "Appendix C - Protected Accounts and Groups in Active Directory (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-c--protected-accounts-and-groups-in-active-directory" }
            @{ Title = "User class - default security descriptor (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/c-user" }
            @{ Title = "Shadow Credentials - The Hacker Recipes"; Url = "https://www.thehacker.recipes/ad/movement/kerberos/shadow-credentials" }
        )
        Tools = @("BloodHound", "Whisker", "Rubeus", "PowerView")
        MITRE = "T1098"
        Triggers = @(
            # The labels only this check writes. GenericAll, WriteDacl and WriteOwner keep the
            # generic cards they reach everywhere else.
            @{ Attribute = 'dangerousRights'; Pattern = ' - may .*\bthe account\b|^Owner of the account - '; Severity = 'Finding' }
            @{ Attribute = 'affectedAccounts'; Custom = 'dangerous_rights_expected'; Severity = 'Hint'; SeverityOnly = $true }
            @{ Attribute = 'affectedAccounts'; Severity = 'Finding' }
        )
    }

    'NTAUTH_FOREIGN_ISSUER' = @{
        Title = "NTAuth Store - Issuer That Is No Enterprise CA of This Forest"
        Risk = "Hint"
        BaseScore = 45
        Description = "Every certificate in the NTAuth store names an issuer the domain controllers accept for certificate logon: a certificate it issues can authenticate as any account of the forest, through Kerberos PKINIT and Schannel alike. An Enterprise CA publishes its own certificate there when it is installed, so an entry that matches one of the forest's Enterprise CAs is accounted for. This one matches none. That is how a third-party CA issuing smart card logon certificates has to be added, and then it is intended - and it is also what a removed CA leaves behind, whose key may still exist on an old server or in a backup, and what somebody who once held Enterprise Admin rights adds to keep a way back in."
        Impact = @(
            "Whoever holds the issuer's private key can issue a certificate that logs on as any account, domain admins included"
            "The key of a removed CA often survives on a decommissioned server or in a backup that nobody watches any more"
            "Publishing an issuer to the store is a known way to keep access to a forest after it was compromised"
        )
        Attack = @(
            "1. Obtain the issuer's private key - from a retired CA server, a backup, or a CA the attacker set up and published"
            "2. Issue a certificate for the target account, signed with that key"
            "3. Authenticate with it through PKINIT and receive a TGT for the target account"
        )
        Remediation = @(
            "Establish what the issuer is, whether it is meant to issue logon certificates, and who controls its key"
            "Remove the entries of CAs that no longer exist or are not meant to be trusted: Enterprise PKI (pkiview.msc) > Manage AD Containers > NTAuthCertificates"
            "Audit changes to CN=NTAuthCertificates in the Configuration partition (event 5136)"
        )
        RemediationCommands = @(
            @{
                Description = "List the NTAuth store as this machine has cached it from the directory"
                Command = "certutil -enterprise -viewstore NTAuth"
            }
        )
        References = @(
            @{ Title = "Import third-party CAs into the Enterprise NTAuth store (Microsoft Learn)"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/certificates-and-public-key-infrastructure-pki/import-third-party-ca-to-enterprise-ntauth-store" }
        )
        Tools = @("certutil", "pkiview.msc", "Certipy")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'EnterpriseCA'; Pattern = '^No'; Severity = 'Hint' }
            # Colour only: an unread CA list is open, and a matched entry is the clean case.
            # Neither should open the card of an issuer nobody accounts for.
            @{ Attribute = 'EnterpriseCA'; Pattern = '^Unknown'; Severity = 'Hint'; SeverityOnly = $true }
            @{ Attribute = 'EnterpriseCA'; Pattern = '^Yes'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'PKI_WEAK_SIGNATURE_ALGORITHM' = @{
        Title = "PKI Certificate Uses Weak Signature Algorithm"
        Risk = "Finding"
        BaseScore = 50
        Description = "A trusted PKI certificate (Root CA, NTAuth, or AIA) uses a weak or deprecated signature algorithm such as SHA-1, MD5, or MD2. Certificates signed with weak algorithms are vulnerable to collision attacks, potentially allowing attackers to forge certificates that chain to the trusted root."
        Impact = @(
            "Weak hash algorithms are susceptible to collision attacks"
            "Forged certificates could be created that appear to chain to the trusted root"
            "Modern security policies and browsers reject SHA-1 signed certificates"
            "All certificates in the chain inherit the weakness of the root signature"
        )
        Remediation = @(
            "Renew the CA certificate with SHA-256 or stronger signature algorithm"
            "Plan CA migration if the current CA does not support modern algorithms"
            "Update all dependent certificates in the chain"
        )
        RemediationCommands = @(
            @{
                Description = "Configure CA to use SHA-256 hash algorithm"
                Command = "certutil -setreg ca\csp\CNGHashAlgorithm SHA256"
            }
            @{
                Description = "Restart Certificate Services to apply changes"
                Command = "Restart-Service -Name CertSvc"
            }
            @{
                Description = "Disable weak algorithms in certificate validation (registry)"
                Command = "New-Item -Path 'HKLM:\SOFTWARE\Microsoft\Cryptography\OID\EncodingType 0\CertDllCreateCertificateChainEngine\Config' -Force; Set-ItemProperty -Path 'HKLM:\SOFTWARE\Microsoft\Cryptography\OID\EncodingType 0\CertDllCreateCertificateChainEngine\Config' -Name 'WeakSignatureHashAlgorithm' -Value 'SHA1;MD5;MD2'"
            }
        )
        References = @(
            @{ Title = "SHA-1 Deprecation - Microsoft"; Url = "https://techcommunity.microsoft.com/t5/windows-it-pro-blog/sha-1-windows-content-signing-is-ending/ba-p/3608963" }
            @{ Title = "Disable Weak Cryptographic Algorithms - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/disable-weak-cryptographic-algorithms" }
            @{ Title = "Migrate ADCS to SHA-2 - 4sysops"; Url = "https://4sysops.com/archives/how-to-migrate-active-directory-certificate-services-to-sha-2-and-key-storage-provider/" }
        )
        Tools = @("certutil", "Certipy")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'SignatureAlgorithm'; Pattern = '(?i)sha1|md5|md2'; Severity = 'Finding' }
        )
    }

    'PKI_SHORT_KEY_LENGTH' = @{
        Title = "PKI Certificate Uses Insufficient Key Length"
        Risk = "Finding"
        BaseScore = 50
        Description = "A trusted PKI certificate (Root CA, NTAuth, or AIA) uses a public key shorter than 2048 bits. Short keys are vulnerable to factoring attacks and do not meet current security standards. All certificates issued under this CA inherit the weak security posture."
        Impact = @(
            "Keys shorter than 2048 bits can potentially be factored"
            "All certificates in the trust chain are affected"
            "Non-compliant with NIST SP 800-57 and industry standards"
        )
        Remediation = @(
            "Renew the CA certificate with at least 2048-bit RSA key (4096-bit recommended)"
            "For ECC keys, use P-256 or stronger curves"
            "Plan CA migration if the current key cannot be upgraded"
        )
        RemediationCommands = @(
            @{
                Description = "Identify templates with short key sizes"
                Command = "certutil -dstemplate | findstr `"[ msPKI-Minimal-Key-Size`" | findstr /v `"1024 2048 4096`""
            }
            @{
                Description = "Update certificate template minimum key size to 2048 (via GUI: Certificate Templates Console - Cryptography tab)"
                Command = "# Use Certificate Templates Console (certtmpl.msc) to modify template properties - set Minimum key size to 2048 or 4096"
            }
            @{
                Description = "Force reenrollment with new key size"
                Command = "# Use Certificate Templates Console - Right-click template - Reenroll All Certificate Holders"
            }
        )
        References = @(
            @{ Title = "NIST SP 800-57 Key Management"; Url = "https://csrc.nist.gov/publications/detail/sp/800-57-part-1/rev-5/final" }
            @{ Title = "Key Length Requirements for AD CS - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
            @{ Title = "Update for Minimum Certificate Key Length - Microsoft KB"; Url = "https://mskb.pkisolutions.com/kb/2661254" }
        )
        Tools = @("certutil", "Certipy")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'KeySize'; Pattern = '^(512|768|1024) bit$'; Severity = 'Finding' }
        )
    }

    'PKI_CERTIFICATE_EXPIRED' = @{
        Title = "PKI Certificate Has Expired"
        Risk = "Finding"
        BaseScore = 60
        Description = "A trusted PKI certificate (Root CA, NTAuth, or AIA) has expired. An expired certificate in the trust chain can cause widespread authentication failures and certificate validation errors."
        Impact = @(
            "Certificates chaining to an expired root will fail validation"
            "Certificate-based authentication (PKINIT, smart card) may stop working"
            "New certificate enrollment may be affected"
            "Trust relationships depending on this certificate break"
        )
        Remediation = @(
            "Renew the expired CA certificate"
            "If the CA is no longer needed, remove it from the trust store"
            "Verify all dependent services after certificate renewal"
        )
        RemediationCommands = @(
            @{
                Description = "Renew CA certificate with new key"
                Command = "certutil -renewCert"
            }
            @{
                Description = "Renew CA certificate keeping existing key"
                Command = "certutil -renewCert ReuseKeys"
            }
            @{
                Description = "Publish renewed certificate to Active Directory (Standalone CA)"
                Command = "certutil -f -dspublish <RootCACertificate-File> RootCA"
            }
        )
        References = @(
            @{ Title = "Renewing CA Certificate - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-cs/certificate-template-concepts" }
            @{ Title = "Renew Certificate Authority Certificates - Microsoft"; Url = "https://techcommunity.microsoft.com/blog/askds/renew-certificate-authority-certificates-on-windows-server-core-no-problem/4006988" }
        )
        Tools = @("certutil", "Certipy")
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'Status'; Pattern = 'EXPIRED'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # COMPUTER ACCOUNT CREATION FINDINGS
    # ============================================================================

    'COMPUTER_CONTAINER_CREATE_BROAD' = @{
        Title = "Create Computer Permissions Held by a Broad Group"
        Risk = "Finding"
        BaseScore = 50
        Description = "A group that holds most of the domain - Everyone, Authenticated Users, Domain Users, Domain Computers or BUILTIN\Users - may create computer objects in the default computer container. Every member can therefore create a machine account whose password they choose, without the ms-DS-MachineAccountQuota and without SeMachineAccountPrivilege entering into it."
        Impact = @(
            "Every member of the group can create a computer account it fully controls"
            "That account is the delegation source a resource-based constrained delegation attack needs"
            "It also supplies the machine account an NTLM relay to LDAP requires"
            "Hardening ms-DS-MachineAccountQuota to 0 does not close this - the permission is granted directly"
        )
        Attack = @(
            "1. Any member of the group creates a computer account in the container"
            "2. Sets its password, so it owns a machine identity"
            "3. Writes msDS-AllowedToActOnBehalfOfOtherIdentity on a target computer"
            "4. Requests a service ticket for a privileged user on that target"
        )
        Remediation = @(
            "Remove CreateChild for the computer class from the broad group on this container"
            "Grant it to a dedicated provisioning account instead, and only there"
            "If the finding names an inherited source the entry is not on this container - remove it where it is defined, or break inheritance here with SetAccessRuleProtection, which also cuts every other permission this container inherits"
            "Pre-stage computer accounts rather than letting users create them"
        )
        RemediationCommands = @(
            @{
                Description = "Show who may create child objects in the computer container"
                Command = "(Get-Acl 'AD:\CN=Computers,DC=domain,DC=com').Access | Where-Object { `$_.ActiveDirectoryRights -match 'CreateChild' } | Format-Table IdentityReference, ObjectType"
            }
            @{
                Description = "Remove the broad group's entry (replace the identity, then verify)"
                Command = "`$acl = Get-Acl 'AD:\CN=Computers,DC=domain,DC=com'; `$ace = `$acl.Access | Where-Object { `$_.IdentityReference -like '*Domain Users*' }; `$acl.RemoveAccessRule(`$ace); Set-Acl 'AD:\CN=Computers,DC=domain,DC=com' `$acl"
            }
        )
        References = @(
            @{ Title = "Resource-Based Constrained Delegation"; Url = "https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-constrained-delegation-overview" }
            @{ Title = "AddAllowedToAct - BloodHound"; Url = "https://bloodhound.specterops.io/resources/edges/add-allowed-to-act" }
        )
        Tools = @("PowerView", "BloodHound", "ADACLScanner")
        MITRE = "T1098"
        Triggers = @(
            # The breadth note is appended to the container right, so this pattern needs
            # both halves: the container phrase keeps it off a domain-object row, and the
            # note keeps it off a row for a named principal. Without the container half it
            # would collide with DANGEROUS_ACL_BROAD_GROUP, whose write-up is about the
            # domain object and scores 90.
            @{ Attribute = 'dangerousRights'; Pattern = 'in the computer container - granted to a broad group'; Severity = 'Finding' }
        )
    }

    'COMPUTER_CONTAINER_CREATE_PERMISSIONS' = @{
        Title = "Non-Default Create Computer Permissions"
        Risk = "Finding"
        BaseScore = 35
        Description = "The Computers container or specific OUs have explicit permissions allowing non-privileged users to create computer objects. This extends beyond the ms-DS-MachineAccountQuota and may enable additional attacks."
        Impact = @(
            "Users can create computer accounts beyond quota"
            "Created accounts can be used in RBCD attacks"
            "Enables relay attacks requiring machine accounts"
            "May bypass quota restrictions entirely"
        )
        Attack = @(
            "1. Attacker identifies create permissions on container"
            "2. Creates machine account using explicit permission"
            "3. Uses account for RBCD or relay attacks"
            "4. Achieves privilege escalation"
        )
        Remediation = @(
            "Audit ACLs on Computers container and OUs"
            "Remove explicit Create Computer permissions"
            "Use dedicated provisioning accounts only"
            "Implement computer account pre-staging"
        )
        RemediationCommands = @(
            @{
                Description = "View ACL on Computers container (check for Create Computer Object rights)"
                Command = "(Get-Acl 'AD:\CN=Computers,DC=domain,DC=com').Access | Where-Object {`$_.ActiveDirectoryRights -match 'CreateChild' -and `$_.ObjectType -eq 'bf967a86-0de6-11d0-a285-00aa003049e2'} | Format-Table IdentityReference,ActiveDirectoryRights,AccessControlType -AutoSize"
            }
            @{
                Description = "Remove Create Computer permission from Computers container"
                Command = "`$dn = 'AD:\CN=Computers,DC=domain,DC=com'; `$acl = Get-Acl `$dn; `$ace = `$acl.Access | Where-Object {`$_.IdentityReference -eq 'DOMAIN\User' -and `$_.ActiveDirectoryRights -match 'CreateChild'}; `$acl.RemoveAccessRule(`$ace); Set-Acl -AclObject `$acl -Path `$dn"
            }
            @{
                Description = "Set ms-DS-MachineAccountQuota to 0 (disable regular users from creating computers)"
                Command = "Set-ADDomain -Identity (Get-ADDomain).DistinguishedName -Replace @{'ms-DS-MachineAccountQuota'='0'}"
            }
            @{
                Description = "Find all OUs where specific principal can create computer objects"
                Command = "Get-ADOrganizationalUnit -Filter * | ForEach-Object { `$acl = Get-Acl `$_.DistinguishedName; `$createPerms = `$acl.Access | Where-Object {`$_.IdentityReference -like '*USERNAME*' -and `$_.ActiveDirectoryRights -match 'CreateChild' -and `$_.ObjectType -eq 'bf967a86-0de6-11d0-a285-00aa003049e2'}; if (`$createPerms) { [PSCustomObject]@{OU=`$_.Name; DN=`$_.DistinguishedName} } }"
            }
        )
        References = @(
            @{ Title = "Machine Account Attacks"; Url = "https://www.ired.team/offensive-security-experiments/active-directory-kerberos-abuse/resource-based-constrained-delegation-ad-computer-object-take-over-and-privilged-code-execution" }
            @{ Title = "MachineAccountQuota Attribute - Microsoft"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-ms-ds-machineaccountquota" }
        )
        Tools = @("PowerMad", "ADACLScanner", "BloodHound")
        MITRE = "T1136.002"
        Triggers = @(
            # This definition had no triggers at all, so nothing could ever name it.
            # Get-AddComputerRights does report the finding - it writes
            # dangerousRights = "CreateChild (Computer) in the computer container" on every
            # principal
            # holding that right - but measured, the row resolved to OU_PERM_CREATE_CHILD,
            # titled "CreateChild Rights on OU". The Computers container is not an OU, and
            # the point here is the one that definition does not make: whoever holds
            # CreateChild there can join machines regardless of ms-DS-MachineAccountQuota.
            #
            # The generic definition scores 50 against this one's 35, so a pattern alone
            # would not have been enough; it carries an ExcludePattern for this value now.
            # Gives the broad case up to COMPUTER_CONTAINER_CREATE_BROAD, which says the
            # thing this one does not: that every member of the group holds the right.
            @{ Attribute = 'dangerousRights'; Pattern = 'CreateChild \(Computer\) in the computer container'; ExcludePattern = 'granted to a broad group'; Severity = 'Finding' }
        )
    }

    'GPO_SEMACHINEACCOUNTPRIVILEGE_BROAD' = @{
        Title = "SeMachineAccountPrivilege Assigned via GPO"
        Risk = "Hint"
        BaseScore = 20
        Description = "The 'Add workstations to domain' user right (SeMachineAccountPrivilege) is configured via GPO. This setting controls who can join computers to the domain beyond the ms-DS-MachineAccountQuota."
        Impact = @(
            "Listed accounts can add computers to domain"
            "Works in addition to ms-DS-MachineAccountQuota"
            "May allow broader access than intended"
        )
        Attack = @(
            "1. Attacker identifies SeMachineAccountPrivilege assignment"
            "2. Joins attacker-controlled system to domain"
            "3. Uses machine account for further attacks"
            "4. RBCD, relay, or coercion attacks"
        )
        Remediation = @(
            "Restrict SeMachineAccountPrivilege to specific admin groups"
            "Avoid assigning to Authenticated Users or Everyone"
            "Implement controlled computer provisioning"
            "Monitor for unexpected computer account creation"
        )
        References = @(
            @{ Title = "User Rights Assignment"; Url = "https://docs.microsoft.com/en-us/windows/security/threat-protection/security-policy-settings/add-workstations-to-domain" }
        )
        Tools = @("GPO analysis", "secedit", "PowerView")
        MITRE = "T1136.002"
        Triggers = @(
            # Dangerous: broad groups that allow any authenticated user to join computers
            @{ Attribute = 'accounts'; Pattern = 'Authenticated Users|Everyone|INTERACTIVE|NETWORK'; Severity = 'Hint' }
            # Restricted: all other values (e.g., Administrators only) -> secure configuration
            @{ Attribute = 'accounts'; ExcludePattern = 'Authenticated Users|Everyone|INTERACTIVE|NETWORK'; Severity = 'Secure' }
        )
    }

    # ============================================================================
    # BLOODHOUND COLLECTOR
