    # ============================================================================
    # OPERATOR GROUP FINDINGS (from Get-ProtectedUsersStatus)
    # ============================================================================

    'PRIMARY_GROUP_IS_DC_GROUP' = @{
        Title = "Non-Computer Account With a Domain Controller Group as Primary Group"
        Risk = "Finding"
        BaseScore = 70
        Description = "This account is not a computer, and its primaryGroupID names Domain Controllers, Read-only Domain Controllers or Enterprise Read-only Domain Controllers. The primary group puts that group's RID in the account's token on every logon, so the account holds whatever access the directory and the file system grant to domain controllers - and it appears in no member attribute, so a review of group memberships does not show it. Changing primaryGroupID needs write access to the attribute and nothing else; it leaves the group's own membership untouched."
        Impact = @(
            "The account's token carries the Domain Controllers SID, so every ACE granted to that group applies to it"
            "The membership is invisible to anything that reads the group's member attribute, including most review scripts"
            "A user account in this state is not covered by the protections that apply to machine accounts"
        )
        Attack = @(
            "1. An attacker obtains write access to primaryGroupID on an account it controls"
            "2. Sets it to 516, 521 or 498 - the group's own membership does not change"
            "3. The next logon issues a token holding the domain controller group SID"
            "4. Everything that trusts that group now trusts this account"
        )
        Remediation = @(
            "Set primaryGroupID back to 513 (Domain Users) for a user account, or 515 (Domain Computers) for a machine that is not a domain controller"
            "Find out who could write the attribute: the change needs no group membership, so the path is an ACE on the object"
            "Audit directory changes to primaryGroupID - it is written rarely enough that every change is worth a look"
        )
        RemediationCommands = @(
            @{
                Description = "Put a user account back in Domain Users as its primary group"
                Command = "Set-ADUser -Identity 'ACCOUNT' -Replace @{ primaryGroupID = 513 }"
            }
            @{
                Description = "List every object whose primary group is a domain controller group"
                Command = "Get-ADObject -LDAPFilter '(|(primaryGroupID=516)(primaryGroupID=521)(primaryGroupID=498))' -Properties primaryGroupID,objectClass"
            }
        )
        References = @(
            @{ Title = "primaryGroupID attribute"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-primarygroupid" }
            @{ Title = "Well-known SIDs"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-identifiers" }
        )
        Tools = @("PowerView", "BloodHound")
        MITRE = "T1098"
        Triggers = @(
            @{ Attribute = 'primaryGroupIsDCGroup'; Severity = 'Finding' }
        )
    }

    'TIER0_NOT_IN_PROTECTED_USERS' = @{
        Title = "Tier-0 Account Not in Protected Users"
        Risk = "Finding"
        BaseScore = 30
        Description = "This account is a member of a Tier-0 group - Domain Admins, Enterprise Admins, Schema Admins or BUILTIN\Administrators - and is not in the 'Protected Users' security group. Protected Users is the only mechanism that turns off the credential formats an attacker harvests: NTLM, CredSSP, Digest and RC4 all stop working for its members, their credentials are no longer cached on the machines they log on to, and their tickets cannot be delegated. Outside the group every one of those remains available on every host the account touches. The main result of this check existed only as a line of text before this write-up; it had no description, no attack path, no remediation and no contribution to the score."
        Impact = @(
            "The account's NTLM hash is cached on every machine it logs on to and can be dumped from LSASS"
            "That hash is enough for pass-the-hash onto any other host that trusts it"
            "Its TGT can be delegated, so a compromised service can act as this account"
            "RC4 remains available for its service tickets, which makes them worth roasting"
            "A ten-hour TGT lifetime leaves a stolen ticket usable for a full working day"
        )
        Attack = @(
            "1. An attacker gains code execution on a server this account has logged on to"
            "2. Reads the cached credential or the Kerberos ticket out of LSASS"
            "3. Replays it against a domain controller - no password needed"
            "4. With a Tier-0 account that is the whole domain"
        )
        Remediation = @(
            "Add Tier 0 USER accounts to 'Protected Users'. It ends NTLM, CredSSP, Digest, RC4 and delegation for those accounts and stops their credentials being cached - check what depends on that first"
            "Do not put a computer account or a gMSA in the group: Microsoft advises against it and it has no effect there"
            "For a service account that cannot join the group, set 'Account is sensitive and cannot be delegated' and restrict msDS-SupportedEncryptionTypes to AES"
            "Use separate administrative accounts so that adding them to the group cannot break an interactive user's day-to-day work"
        )
        RemediationCommands = @(
            @{
                Description = "Add a Tier 0 user account to Protected Users - a user account, and after checking what it depends on"
                Command = "Add-ADGroupMember -Identity 'Protected Users' -Members 'TIER0_USER_ACCOUNT'"
            }
            @{
                Description = "Show who is in the group today"
                Command = "Get-ADGroupMember -Identity 'Protected Users'"
            }
        )
        References = @(
            @{ Title = "Protected Users Security Group"; Url = "https://learn.microsoft.com/en-us/windows-server/security/credentials-protection-and-management/protected-users-security-group" }
            @{ Title = "Securing Privileged Access - Tier model"; Url = "https://learn.microsoft.com/en-us/security/privileged-access-workstations/privileged-access-access-model" }
        )
        Tools = @("BloodHound", "mimikatz", "Rubeus")
        MITRE = "T1003.001"
        Triggers = @(
            # The attribute the check already writes on every Tier-0 account it reports.
            # 'Protected' is the earned verdict and reads as Secure; the excluded accounts
            # carry excludedReason instead and match neither.
            @{ Attribute = 'protectedUsersStatus'; Pattern = '^NOT PROTECTED$'; Severity = 'Finding' }
            @{ Attribute = 'protectedUsersStatus'; Pattern = '^Protected$'; Severity = 'Secure' }
        )
    }

    'OPERATOR_GROUP_MEMBERS' = @{
        Title = "Operator Group Has Active Members"
        Risk = "Hint"
        BaseScore = 25
        Description = "This operator-level group (such as Account Operators, Backup Operators, Print Operators, or Server Operators) has active members. While less privileged than Tier 0 groups like Domain Admins, these groups still have elevated capabilities that can be abused for privilege escalation."
        Impact = @(
            "Account Operators can create and modify non-admin accounts"
            "Backup Operators can back up and restore files on DCs including NTDS.dit"
            "Print Operators can load drivers on DCs (kernel-mode code execution)"
            "Server Operators can log on to DCs and manage services"
        )
        Remediation = @(
            "Review if members actually need membership in this operator group"
            "Follow least-privilege principle for group assignments"
            "Monitor membership changes in these groups"
            "Consider using delegated permissions instead of broad group membership"
        )
        References = @(
            @{ Title = "AD Built-In Groups"; Url = "https://docs.microsoft.com/en-us/windows-server/identity/ad-ds/plan/security-best-practices/appendix-b--privileged-accounts-and-groups-in-active-directory" }
            @{ Title = "Abusing Backup Operators"; Url = "https://www.bordergate.co.uk/backup-operator-privilege-escalation/" }
        )
        Tools = @("BloodHound", "PowerView")
        MITRE = "T1078.002"
        Triggers = @(
            @{ Attribute = 'OperatorGroup'; Severity = 'Hint' }
            @{ Attribute = 'MemberCount'; Custom = 'operator_group_has_members'; Severity = 'Hint' }
            # Hint, not Finding. No operator-group member in Protected Users is the
            # normal state of very nearly every domain, the line that prints these
            # objects calls itself informational ("consider for Protected Users"), and
            # this definition sets Risk = Hint - so a red row was the only one of the
            # four statements that disagreed with the other three.
            @{ Attribute = 'ProtectedCount'; Pattern = '^0$'; Severity = 'Hint' }
        )
    }

