    # ============================================================================
    # DOMAIN FUNCTIONAL LEVEL
    # ============================================================================

    'OLD_FUNCTIONAL_LEVEL' = @{
        Title = "Outdated Domain/Forest Functional Level"
        Risk = "Hint"
        BaseScore = 15
        Description = "The domain or forest functional level is set to an outdated version (Windows 2000, 2003, or 2008). This prevents the use of modern security features like Protected Users group, Authentication Policies, and LDAP improvements available in newer functional levels."
        Impact = @(
            "Cannot use Protected Users group (requires 2012 R2+)"
            "Cannot use Authentication Policies/Silos (requires 2012 R2+)"
            "Missing modern Kerberos improvements"
            "May indicate presence of legacy Domain Controllers"
        )
        Remediation = @(
            "Plan upgrade of all Domain Controllers to current OS version"
            "Raise domain/forest functional level after all DCs are upgraded"
            "Remove any remaining legacy Domain Controllers"
            "Test application compatibility before raising functional level"
        )
        References = @(
            @{ Title = "Forest and Domain Functional Levels"; Url = "https://docs.microsoft.com/en-us/windows-server/identity/ad-ds/active-directory-functional-levels" }
        )
        MITRE = "T1078"
        Triggers = @(
            # 2012 included, because Get-DomainInformation already colours the line for
            # it: its threshold is "[int]$DomainFunc -lt 7", which covers level 5 (2012)
            # and 6 (2012 R2). Without them here the line was yellow and the row that
            # carries the actual level stayed neutral - and both products are out of
            # support, so there is something to say about them.
            @{ Attribute = 'domainFunctionalLevel'; Pattern = 'Windows (2000|2003|2008|2012)'; Severity = 'Hint' }
            @{ Attribute = 'forestFunctionalLevel'; Pattern = 'Windows (2000|2003|2008|2012)'; Severity = 'Hint' }
        )
    }

    # What a deletion leaves behind - both forest-wide, read by Get-DomainInformation
    # through Get-ForestDeletionSetting (MS-ADTS 3.1.1.1.5.1, 3.1.1.9.1).
    'AD_RECYCLE_BIN_DISABLED' = @{
        Title = "Active Directory Recycle Bin Not Enabled"
        Risk = "Hint"
        BaseScore = 10
        Description = "The forest has not enabled the Active Directory Recycle Bin, although its functional level allows it. A deleted object then becomes a tombstone that keeps only a few attributes: its group memberships and most of its other values are gone, so a restore brings back an empty shell and an investigation finds little. A mass deletion by an attacker - or by mistake - can only be undone from a backup, by an authoritative restore. With the Recycle Bin, a deleted object keeps virtually all of its state and can be restored without loss. It is forest-wide and cannot be disabled once enabled."
        Impact = @(
            "A deleted user, group or computer comes back without its group memberships and most attributes"
            "Recovery from a destructive attack on the directory needs a backup and an authoritative restore"
            "Deleted objects say little about what they were, which hampers an investigation"
        )
        Attack = @(
            "1. Attacker with sufficient rights deletes accounts, groups or OUs to disrupt the domain or cover tracks"
            "2. Without the Recycle Bin, the deleted objects lose their memberships and attributes"
            "3. Recovery depends on a recent backup and an authoritative restore"
        )
        Remediation = @(
            "Enable the Recycle Bin (forest functional level Windows Server 2008 R2 or higher); it cannot be disabled again"
            "Objects deleted before it was enabled stay tombstones - it protects deletions from then on"
        )
        RemediationCommands = @(
            @{
                Description = "Check whether the Recycle Bin is enabled"
                Command = "Get-ADOptionalFeature -Filter { Name -like 'Recycle*' } | Select-Object Name, EnabledScopes"
            }
            @{
                Description = "Enable it for the forest"
                Command = "Enable-ADOptionalFeature -Identity 'Recycle Bin Feature' -Scope ForestOrConfigurationSet -Target '<forest root domain>'"
            }
        )
        References = @(
            @{ Title = "Recycle Bin Optional Feature - MS-ADTS 3.1.1.9.1"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/e9482178-ee53-4b6c-841d-5259d6261985" }
        )
        Tools = @()
        MITRE = "T1485"
        Triggers = @(
            @{ Attribute = 'recycleBin'; Pattern = '^Disabled'; Severity = 'Hint' }
        )
    }

    'SYSVOL_FRS_REPLICATION' = @{
        Title = "SYSVOL Still Replicated by FRS"
        Risk = "Hint"
        BaseScore = 10
        Description = "SYSVOL - the share that carries every Group Policy and the logon scripts - is still replicated by the File Replication Service, either because the domain was never migrated to DFS Replication or because the migration stopped before Eliminated. FRS is deprecated, and Microsoft blocks it: no domain controller running Windows Server 1709 or later can be added to a domain that still replicates SYSVOL with FRS (KB4025991, KB4023141). A domain in this state cannot replace its domain controllers with supported ones before it migrates, and it usually still runs old ones."
        Impact = @(
            "No domain controller from Windows Server 1709 on can be added until SYSVOL is migrated"
            "The domain is held to old domain controllers, with their missing security features and patches"
            "FRS replicates less reliably than DFSR: a policy or a script can differ between domain controllers"
        )
        Remediation = @(
            "Migrate SYSVOL to DFS Replication with dfsrmig on the PDC emulator: Prepared, Redirected, Eliminated"
            "The domain functional level must be Windows Server 2008 or higher"
            "Finish a migration that stopped halfway - FRS keeps replicating until the state is Eliminated"
        )
        RemediationCommands = @(
            @{
                Description = "Show the global migration state (run on a domain controller)"
                Command = "dfsrmig /getglobalstate"
            }
            @{
                Description = "Start or continue the migration, one state at a time, waiting for each to converge"
                Command = "dfsrmig /setglobalstate 1; dfsrmig /getmigrationstate  # then 2, then 3"
            }
        )
        References = @(
            @{ Title = "Windows Server version 1709 no longer supports FRS (KB4025991)"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/networking/windows-server-version-1709-no-longer-supports-frs" }
            @{ Title = "NTFRS deprecation blocks the installation of replica DCs (KB4023141)"; Url = "https://learn.microsoft.com/en-us/troubleshoot/windows-server/active-directory/ntfrs-deprecation-blocks-replic-dc-installation" }
            @{ Title = "DFSR SYSVOL Migration FAQ - Microsoft AskDS"; Url = "https://learn.microsoft.com/en-us/archive/blogs/askds/dfsr-sysvol-migration-faq-useful-trivia-that-may-save-your-follicles" }
        )
        Tools = @()
        MITRE = "T1484.001"
        Triggers = @(
            @{ Attribute = 'sysvolReplication'; Pattern = '^FRS'; Severity = 'Hint' }
        )
    }

    'TOMBSTONE_LIFETIME_SHORT' = @{
        Title = "Tombstone Lifetime Shorter Than 180 Days"
        Risk = "Hint"
        BaseScore = 5
        Description = "The tombstone lifetime of the forest - tombstoneLifetime on CN=Directory Service, 60 days when the attribute is not set (MS-ADTS 3.1.1.1.5.1) - is shorter than the 180 days Microsoft sets in a new forest. It is also the useful life of a backup: a backup older than the tombstone lifetime can no longer be restored, and a domain controller offline for longer has to be rebuilt. A short value is usually inherited from a forest created on Windows 2000 or an early Windows Server 2003, not chosen."
        Impact = @(
            "Backups older than the tombstone lifetime cannot be restored"
            "A compromise noticed late leaves fewer clean backups to recover from"
            "A domain controller offline longer than the tombstone lifetime has to be rebuilt"
        )
        Remediation = @(
            "Set tombstoneLifetime on CN=Directory Service,CN=Windows NT,CN=Services in the configuration partition to 180"
            "Keep backups of at least two domain controllers per domain, younger than the tombstone lifetime"
        )
        RemediationCommands = @(
            @{
                Description = "Show the tombstone lifetime (empty means 60 days)"
                Command = "Get-ADObject ('CN=Directory Service,CN=Windows NT,CN=Services,' + (Get-ADRootDSE).configurationNamingContext) -Properties tombstoneLifetime | Select-Object tombstoneLifetime"
            }
            @{
                Description = "Set it to 180 days"
                Command = "Set-ADObject ('CN=Directory Service,CN=Windows NT,CN=Services,' + (Get-ADRootDSE).configurationNamingContext) -Replace @{tombstoneLifetime=180}"
            }
        )
        References = @(
            @{ Title = "Tombstone Lifetime and Deleted-Object Lifetime - MS-ADTS 3.1.1.1.5.1"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/1887de08-2a9e-4694-95e2-898cde411180" }
            @{ Title = "Active Directory Security Tip #7: The Tombstone Lifetime"; Url = "https://adsecurity.org/?p=4600" }
        )
        Tools = @()
        MITRE = "T1490"
        Triggers = @(
            @{ Attribute = 'tombstoneLifetime'; Pattern = 'below the 180-day default$'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # PRE-WINDOWS 2000 COMPATIBLE ACCESS
    # ============================================================================
    #
    # Two definitions rather than one, because the attack differs: with Anonymous Logon in
    # the group no credentials are needed at all, with any other broad principal one valid
    # account is. Each sits on an attribute only Get-PrivilegedGroupMembers writes, so
    # neither can attach itself to another check's membership row.

    'PREWIN2000_ANONYMOUS_MEMBER' = @{
        Title = "Anonymous Logon in Pre-Windows 2000 Compatible Access"
        Risk = "Finding"
        BaseScore = 70
        Description = "The Pre-Windows 2000 Compatible Access group grants its members read access to every user and group object in the domain. Anonymous Logon is a member, so that read requires no credentials: an unauthenticated client on the network can enumerate the whole directory."
        Impact = @(
            "The complete user, group and computer inventory can be read without an account"
            "Service accounts, descriptions, group memberships and account flags are all exposed, which is the input for password spraying and for picking a target"
            "Pre-authentication reconnaissance leaves no failed logon behind"
        )
        Attack = @(
            "1. Attacker reaches a domain controller on the network with no credentials"
            "2. Binds to LDAP anonymously, or opens a null SMB session"
            "3. Enumerates users, groups and computers including descriptions and SPNs"
            "4. Picks targets for AS-REP roasting, Kerberoasting or spraying from what the directory volunteered"
        )
        Remediation = @(
            "Remove Anonymous Logon from Pre-Windows 2000 Compatible Access"
            "The group exists for Windows NT 4.0 era clients and RAS servers; on a domain without them it should be empty"
            "Check what depends on it first - some legacy appliances and older NAS devices bind anonymously"
        )
        RemediationCommands = @(
            @{
                Description = "List the members of the group, language-independently by its well-known SID"
                Command = "Get-ADGroup -Identity 'S-1-5-32-554' -Properties member | Select-Object -ExpandProperty member"
            }
            @{
                Description = "Remove Anonymous Logon from the group"
                Command = "Remove-ADGroupMember -Identity 'S-1-5-32-554' -Members 'CN=S-1-5-7,CN=ForeignSecurityPrincipals,DC=DOMAIN,DC=COM' -Confirm:`$false"
            }
        )
        References = @(
            @{ Title = "Pre-Windows 2000 Compatible Access"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups" }
            @{ Title = "Anonymous LDAP enumeration"; Url = "https://www.thehacker.recipes/ad/recon/ldap" }
        )
        Tools = @("ldapsearch", "enum4linux", "windapsearch")
        MITRE = "T1087.002"
        Triggers = @(
            @{ Attribute = 'prewin2000AnonymousMember'; Severity = 'Finding' }
        )
    }

    'PREWIN2000_DEFAULT_MEMBER' = @{
        Title = "Authenticated Users in Pre-Windows 2000 Compatible Access"
        Risk = "Hint"
        BaseScore = 15
        Description = "The Pre-Windows 2000 Compatible Access group grants its members read access to every user and group object in the domain, and Authenticated Users is a member. This is how Microsoft ships the group - it is still pre-populated in new forests on Windows Server 2022 and 2025 - so it is the configuration as delivered rather than something that was changed. Worth removing, but not before checking what depends on it."
        Impact = @(
            "Any account that can authenticate may enumerate every user and group in the domain"
            "That includes the group memberships an attacker needs to choose a target"
            "The group also reads tokenGroupsGlobalAndUniversal, which Authenticated Users alone cannot"
        )
        Attack = @(
            "1. An attacker authenticates with any account, however unprivileged"
            "2. Enumerates users, groups and memberships across the domain"
            "3. Chooses targets from what it finds, without touching a privileged object"
        )
        Remediation = @(
            "Check what depends on it first: ADFS 3.0 WebForms authentication and Cisco ISE are documented to require this membership and break without it"
            "Remove Authenticated Users from the group once nothing needs it"
            "Grant the read explicitly to the accounts that turn out to need it instead"
        )
        RemediationCommands = @(
            @{
                Description = "Show the current members"
                Command = "Get-ADGroupMember -Identity 'S-1-5-32-554'"
            }
        )
        References = @(
            @{ Title = "Security risks of Pre-Windows 2000 Compatibility Access"; Url = "https://www.semperis.com/blog/security-risks-pre-windows-2000-compatibility-windows-2022/" }
            @{ Title = "Pre-Windows 2000 Compatible Access and ADFS"; Url = "https://learn.microsoft.com/en-us/archive/msdn-technet-forums/e8dfacba-985f-4042-abeb-f341bf37522f" }
        )
        Tools = @("PowerView", "BloodHound")
        MITRE = "T1087.002"
        Triggers = @(
            # Its own attribute, so the default case is told from a principal somebody
            # added by hand. The check decides which attribute to write, by SID.
            @{ Attribute = 'prewin2000DefaultMember'; Severity = 'Hint' }
        )
    }

    'PREWIN2000_BROAD_MEMBER' = @{
        Title = "Broad Principal in Pre-Windows 2000 Compatible Access"
        Risk = "Finding"
        BaseScore = 45
        Description = "The Pre-Windows 2000 Compatible Access group grants its members read access to every user and group object in the domain. A broad principal is a member - Everyone, Authenticated Users, Domain Users, Domain Computers or a comparable group - so any account in the domain, including the least privileged one and every machine account, can read the whole directory."
        Impact = @(
            "Any single compromised account or machine account reads the full user, group and computer inventory"
            "Account descriptions, SPNs, group memberships and account flags are all exposed, which is the input for Kerberoasting and for choosing a target"
            "Read access this broad defeats the point of removing read permissions elsewhere in the directory"
        )
        Attack = @(
            "1. Attacker obtains any domain account, however unprivileged"
            "2. Reads every user and group object through the permissions this group grants"
            "3. Harvests SPNs, descriptions and group memberships"
            "4. Picks the shortest path to a privileged account from what the directory volunteered"
        )
        Remediation = @(
            "Remove the broad principal from Pre-Windows 2000 Compatible Access"
            "The group exists for Windows NT 4.0 era clients and RAS servers; on a domain without them it should be empty"
            "A domain installed with 'pre-Windows 2000 compatible permissions' gets this membership by default, so finding it says nothing about a mistake - it still has to be removed"
        )
        RemediationCommands = @(
            @{
                Description = "List the members of the group, language-independently by its well-known SID"
                Command = "Get-ADGroup -Identity 'S-1-5-32-554' -Properties member | Select-Object -ExpandProperty member"
            }
            @{
                Description = "Remove a member from the group"
                Command = "Remove-ADGroupMember -Identity 'S-1-5-32-554' -Members 'MEMBER_DN' -Confirm:`$false"
            }
        )
        References = @(
            @{ Title = "Pre-Windows 2000 Compatible Access"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/understand-security-groups" }
            @{ Title = "Active Directory recon over LDAP"; Url = "https://www.thehacker.recipes/ad/recon/ldap" }
        )
        Tools = @("PowerView", "BloodHound", "ldapsearch")
        MITRE = "T1087.002"
        Triggers = @(
            @{ Attribute = 'prewin2000BroadMember'; Severity = 'Finding' }
        )
    }

    # ============================================================================
    # ANONYMOUS LDAP READABLE ATTRIBUTES
    # ============================================================================

    'ANON_LDAP_READABLE_ATTRS' = @{
        Title = "Anonymous LDAP Readable Attributes"
        Risk = "Hint"
        BaseScore = 20
        Description = "Specific attributes are readable via anonymous LDAP binding. While the Domain Controller allows anonymous access, these are the attributes that can be enumerated without authentication."
        Impact = @(
            "Unauthenticated enumeration of specific directory attributes"
            "Information gathering for targeted attacks"
        )
        Remediation = @(
            "Disable anonymous LDAP access entirely"
            "Restrict dsHeuristics to remove ANONYMOUS LOGON access"
        )
        References = @(
            @{ Title = "Anonymous LDAP Operations"; Url = "https://docs.microsoft.com/en-us/troubleshoot/windows-server/identity/anonymous-ldap-operations-active-directory-disabled" }
        )
        MITRE = "T1087"
        Triggers = @(
            @{ Attribute = 'anonymousReadableAttributes'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # LAPS UNPROTECTED COMPUTERS
    # ============================================================================

    'LAPS_UNPROTECTED_COMPUTERS' = @{
        Title = "Computers Without LAPS Protection"
        Risk = "Finding"
        BaseScore = 35
        Description = "These computers in the OU do not have LAPS deployed, meaning their local administrator passwords are not managed. Without LAPS, local admin passwords may be identical across systems, enabling lateral movement."
        Impact = @(
            "Local admin passwords may be identical across systems"
            "Compromising one system enables lateral movement via Pass-the-Hash"
            "No automatic password rotation for local accounts"
        )
        Remediation = @(
            "Deploy Windows LAPS to all computers in the OU"
            "Configure LAPS via GPO for password complexity and rotation"
        )
        References = @(
            @{ Title = "Windows LAPS Overview"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview" }
        )
        Tools = @("LAPSToolkit")
        MITRE = "T1078.003"
        Triggers = @(
            # The Custom predicate is what keeps this card off a hybrid-joined fleet. With
            # BackupDirectory set to Microsoft Entra ID, Windows LAPS manages and rotates
            # the password and by design writes no msLAPS attribute into Active Directory,
            # so the absence of one is not evidence of anything. LAPS_COVERAGE_NOT_IN_AD
            # then carries the row instead.
            @{ Attribute = 'lapsUnprotectedComputers'; Custom = 'laps_backup_in_ad'; Severity = 'Finding' }
            # The count on the coverage summary. Anchored at the end: where a policy
            # escrows outside Active Directory the row goes on "carry no LAPS attribute
            # in Active Directory" and belongs to LAPS_COVERAGE_NOT_IN_AD - and the card
            # metadata of the report asks without the row's object, so the text has to
            # decide it, not a predicate.
            @{ Attribute = 'lapsUnprotected'; Pattern = '^\d+ of \d+ computers? \([\d.]+%\)$'; Severity = 'Finding' }
            @{ Attribute = 'lapsUnprotected'; Pattern = '^None - '; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'LAPS_COVERAGE_NOT_IN_AD' = @{
        Title = "LAPS Coverage Cannot Be Read From Active Directory"
        Risk = "Hint"
        BaseScore = 15
        Description = "A Windows LAPS policy in this domain backs the managed password up somewhere other than Active Directory. For a computer in that policy's scope, Windows LAPS still manages and rotates the local administrator password, but it escrows it to Microsoft Entra ID (BackupDirectory = 1) or nowhere at all (BackupDirectory = 0) - so no msLAPS attribute appears on the computer object, and the coverage figure this check computes from those attributes says nothing about whether the password is managed."
        Impact = @(
            "The computers listed here have no LAPS attribute in Active Directory, which is the expected state for an Entra-escrowed policy and not a finding in itself"
            "What cannot be confirmed from Active Directory is whether each of them is really in that policy's scope - a computer outside it has no managed password at all, and looks identical from here"
            "With BackupDirectory = 0 the password is not escrowed anywhere, which means nobody can retrieve it: the account is effectively locked out rather than managed"
        )
        Attack = @(
            "Nothing follows from this state by itself. It is reported so the coverage figure above is not read as evidence of unmanaged passwords when it is not."
        )
        Remediation = @(
            "Confirm in Microsoft Entra ID (Devices -> Local administrator password recovery) that the computers listed here really do have an escrowed password"
            "For an on-premises fleet, set BackupDirectory = 2 so the password is escrowed to Active Directory and this check can assess it"
            "BackupDirectory = 0 is worth correcting on its own terms: the password rotates and nobody can read it"
            "Where both are in use, scope the two policies so it is documented which computers are escrowed where"
        )
        References = @(
            @{ Title = "Windows LAPS BackupDirectory policy setting"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings" }
            @{ Title = "Windows LAPS with Microsoft Entra ID"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-scenarios-azure-active-directory" }
        )
        Tools = @("Get-LapsAADPassword", "Microsoft Entra admin center")
        MITRE = "T1078.003"
        Triggers = @(
            @{ Attribute = 'lapsBackupOutsideAD'; Severity = 'Hint' }
            @{ Attribute = 'lapsUnprotected'; Pattern = 'carry no LAPS attribute in Active Directory$'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # GPO AFFECTED COMPUTER COUNT
    # ============================================================================

    'GPO_WIDE_IMPACT' = @{
        Title = "GPO Affects Many Computers"
        Risk = "Finding"
        BaseScore = 30
        Description = "This GPO finding affects a large number of computers. The wider the impact scope, the more critical the finding becomes, as exploitation would compromise more systems simultaneously."
        Impact = @(
            "GPO settings apply to all affected computers"
            "Malicious modifications impact multiple systems simultaneously"
            "Larger scope amplifies any security vulnerability"
        )
        Remediation = @(
            "Review GPO permissions and ensure strict access control"
            "Reduce the scope with security filtering, and leave Domain Computers a read: since MS16-072 a user policy is fetched in the computer account's context, so removing Authenticated Users without that read stops the GPO applying to users"
            "A WMI filter narrows the scope differently - it runs on the client at every refresh rather than taking the read away - so the two are not interchangeable"
        )
        References = @(
            @{ Title = "Group Policy Security"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-policy/group-policy-overview" }
        )
        MITRE = "T1484.001"
        Triggers = @(
            @{ Attribute = 'affectedComputerCount'; Custom = 'affected_computers_gt_10'; Severity = 'Finding' }
            @{ Attribute = 'affectedComputerCount'; Custom = 'affected_computers_gt_0'; Severity = 'Hint' }
        )
    }

    # ============================================================================
    # META / STATUS ATTRIBUTES
    # ============================================================================

    'LAPS_GPO_PASSWORD_LENGTH' = @{
        Title = "LAPS Password Shorter Than the Default"
        Risk = "Hint"
        BaseScore = 25
        Description = "This LAPS policy sets a password length below 14 characters, which is the product default and the value Microsoft's own administrative template ships with. LAPS passwords are never typed by a person and never remembered, so there is no reason to shorten one: the only effect is that the hash of the local administrator account becomes cheaper to crack once it has been captured from a machine. The value was read from the GPO and reported by adPEAS before this write-up existed, with nothing said about it either way."
        Impact = @(
            "A shorter random password is proportionally cheaper to crack offline"
            "The local administrator hash is what gets captured, and it is what gets cracked"
            "Nobody types a LAPS password, so the shorter value buys nothing"
        )
        Attack = @(
            "1. Attacker dumps the local SAM or captures the NTLM hash of the local administrator"
            "2. Cracks it offline - the shorter the password, the sooner that finishes"
            "3. Uses the password or its hash on every machine where the policy produced the same length"
        )
        Remediation = @(
            "Set the password length back to 14 or higher in the LAPS policy"
            "Windows LAPS supports passphrases, which are longer again for the same operational cost"
        )
        RemediationCommands = @(
            @{
                Description = "Windows LAPS: the policy value that sets the length"
                Command = "# Computer Configuration\Administrative Templates\System\LAPS\Password Settings -> Password Length"
            }
            @{
                Description = "Read the configured length from a client"
                Command = "Get-ItemProperty 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Name PasswordLength"
            }
        )
        References = @(
            @{ Title = "LAPS Password Policy Settings"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings" }
        )
        Tools = @("hashcat", "Get-LAPSDiagnostics")
        Triggers = @(
            @{ Attribute = 'PasswordLength'; Custom = 'laps_pwd_length_lt_14'; Severity = 'Hint' }
        )
    }

    'LAPS_GPO_PASSWORD_AGE' = @{
        Title = "LAPS Rotation Interval Above the Default"
        Risk = "Finding"
        BaseScore = 40
        Description = "This LAPS policy rotates the local administrator password less often than every 30 days, which is the product default. The interval is the upper bound on how long a password that was captured once keeps working: with 365 days - the maximum LAPS accepts - a password read off one machine stays valid on that machine for up to a year. Above three months this is reported as a finding, between the default and three months as a hint, because that range is still a deliberate operational choice rather than a lapse."
        Impact = @(
            "A captured local administrator password stays valid until the next rotation"
            "The interval is the upper bound on the useful life of one capture"
            "Lateral movement with a cracked or dumped password has that long to run"
        )
        Attack = @(
            "1. Attacker reads or cracks the local administrator password of one machine"
            "2. Uses it until LAPS rotates it - which the policy decides"
            "3. Where the same interval applies domain-wide, that window is domain-wide too"
        )
        Remediation = @(
            "Set the rotation interval back to 30 days or fewer"
            "Windows LAPS can reset the password after each use (PostAuthenticationActions), which makes the interval nearly irrelevant"
        )
        RemediationCommands = @(
            @{
                Description = "Windows LAPS: the policy value that sets the interval"
                Command = "# Computer Configuration\Administrative Templates\System\LAPS\Password Settings -> Password Age (Days)"
            }
            @{
                Description = "Read the configured interval from a client"
                Command = "Get-ItemProperty 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Name PasswordAgeDays"
            }
        )
        References = @(
            @{ Title = "LAPS Password Policy Settings"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings" }
            @{ Title = "LAPS Post-Authentication Actions"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-concepts-overview#post-authentication-actions" }
        )
        Tools = @("Get-LAPSDiagnostics")
        Triggers = @(
            # Two triggers, one card, mutually exclusive predicates - the same shape
            # SID_HISTORY_INJECTION uses. Overlapping ones would pick their winner by
            # hashtable order.
            @{ Attribute = 'PasswordAgeDays'; Custom = 'laps_pwd_age_gt_90'; Severity = 'Finding' }
            @{ Attribute = 'PasswordAgeDays'; Custom = 'laps_pwd_age_31_90'; Severity = 'Hint' }
        )
    }

    'LAPS_GPO_DISABLED' = @{
        Title = "LAPS Switched Off by Group Policy"
        Risk = "Finding"
        BaseScore = 55
        Description = "A Group Policy sets AdmPwdEnabled = 0, the central switch of Legacy LAPS - the policy called 'Enable local admin password management'. Where the schema extension and the computer attributes are in place, this is the most misleading state LAPS has: every password the clients wrote before the switch was turned off is still in the directory, still valid on the machine, and no longer rotating. The coverage figure counts those machines as protected, because the attribute is there."
        Impact = @(
            "Local administrator passwords stop rotating and keep the value they last had"
            "Those values remain readable in the directory for whoever is delegated the attribute"
            "The expiration attribute keeps its last date, so the machines look managed"
            "A password captured from one machine stays valid indefinitely"
        )
        Attack = @(
            "1. Attacker reads ms-Mcs-AdmPwdExpirationTime and sees a date that never moves"
            "2. Obtains the password of one machine - from the directory or from the machine itself"
            "3. It keeps working, because nothing is going to change it"
        )
        Remediation = @(
            "Set 'Enable local admin password management' back to Enabled, or remove the policy if LAPS was replaced"
            "After re-enabling, force a rotation so the passwords that stood still are replaced"
            "If LAPS was deliberately retired, remove the delegated read permissions on the attributes as well - the stored passwords outlive the policy"
        )
        RemediationCommands = @(
            @{
                Description = "The policy value behind this finding"
                Command = "# Computer Configuration\Administrative Templates\LAPS -> Enable local admin password management"
            }
            @{
                Description = "Force a rotation on one machine after re-enabling (Legacy LAPS)"
                Command = "Reset-AdmPwdPassword -ComputerName 'COMPUTER_NAME'"
            }
            @{
                Description = "Find the machines whose expiration time stopped moving"
                Command = "Get-ADComputer -Filter * -Properties ms-Mcs-AdmPwdExpirationTime | Where-Object { `$_.'ms-Mcs-AdmPwdExpirationTime' } | Select-Object Name,@{n='Expires';e={[DateTime]::FromFileTime(`$_.'ms-Mcs-AdmPwdExpirationTime')}}"
            }
        )
        References = @(
            @{ Title = "Legacy LAPS Operations Guide"; Url = "https://learn.microsoft.com/en-us/previous-versions/mt227395(v=msdn.10)" }
            @{ Title = "Windows LAPS Policy Settings"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-management-policy-settings" }
        )
        Tools = @("Get-AdmPwdPassword", "PowerView")
        Triggers = @(
            @{ Attribute = 'lapsPolicyState'; Pattern = '^Disabled'; Severity = 'Finding' }
            @{ Attribute = 'lapsPolicyState'; Pattern = '^Enabled$'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'LAPS_GPO_NO_POST_AUTH_RESET' = @{
        Title = "Windows LAPS Does Not Reset the Password After Use"
        Risk = "Hint"
        BaseScore = 20
        Description = "A Group Policy sets PostAuthenticationActions = 0. Windows LAPS can reset the managed password once the session that used it ends - optionally logging the account off or rebooting as well - which turns a retrieved password into a single-use credential. With 0 the password a technician, a script or an attacker retrieved today stays valid until the rotation interval runs out."
        Impact = @(
            "A password that was retrieved once keeps working until the next scheduled rotation"
            "The rotation interval, not the use of the password, decides the exposure window"
            "Nothing in the directory records that the password was used"
        )
        Remediation = @(
            "Set the post-authentication action to reset the password, which is the Windows LAPS default behaviour"
            "Where a reset alone is not enough, the logoff and reboot variants end the session that used it"
        )
        RemediationCommands = @(
            @{
                Description = "The policy value behind this finding"
                Command = "# Computer Configuration\Administrative Templates\System\LAPS -> Post-authentication actions"
            }
            @{
                Description = "Read the configured action from a client"
                Command = "Get-ItemProperty 'HKLM:\Software\Microsoft\Windows\CurrentVersion\Policies\LAPS' -Name PostAuthenticationActions"
            }
        )
        References = @(
            @{ Title = "LAPS Post-Authentication Actions"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-concepts-overview#post-authentication-actions" }
        )
        Tools = @("Get-LAPSDiagnostics")
        Triggers = @(
            @{ Attribute = 'PostAuthActions'; Pattern = '^Disabled'; Severity = 'Hint' }
            @{ Attribute = 'PostAuthActions'; Pattern = '^Reset'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    'GMSA_ROTATION_INTERVAL_LONG' = @{
        Title = "gMSA Password Rotates Rarely"
        Risk = "Hint"
        BaseScore = 20
        Description = "This group managed service account rotates its password less often than every 90 days. The point of a gMSA is that the password is long, random and changed by the directory without anybody holding it - a long interval gives that up gradually, because a password recovered once stays valid until the next rotation. The interval is therefore the upper bound on how long a single theft keeps paying. Microsoft's default is 30 days. The value cannot be changed afterwards: msDS-ManagedPasswordInterval is set when the account is created and is read-only from then on, so a different interval means creating the account again."
        Impact = @(
            "A password read from the directory stays valid until the next rotation"
            "The interval is the upper bound on the useful life of one theft"
            "An interval far above the default is usually unintentional - it was typed once at creation"
        )
        Attack = @(
            "1. Attacker retrieves msDS-ManagedPassword for the gMSA (see the password access findings)"
            "2. Derives the Kerberos keys from the blob and authenticates as the service"
            "3. Keeps doing so until the interval expires - with 365 days, for up to a year"
        )
        Remediation = @(
            "Create the account again with the default interval; msDS-ManagedPasswordInterval cannot be changed on an existing gMSA"
            "Check who may retrieve the password while the long interval stands - those principals are the exposure"
        )
        RemediationCommands = @(
            @{
                Description = "Show the rotation interval of every gMSA in the domain"
                Command = "Get-ADServiceAccount -Filter * -Properties msDS-ManagedPasswordInterval | Select-Object Name,msDS-ManagedPasswordInterval"
            }
            @{
                Description = "Create a replacement with the default 30-day interval"
                Command = "New-ADServiceAccount -Name 'GMSA_NAME' -DNSHostName 'GMSA_NAME.contoso.com' -ManagedPasswordIntervalInDays 30"
            }
        )
        References = @(
            @{ Title = "Group Managed Service Accounts Overview"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts-overview" }
            @{ Title = "msDS-ManagedPasswordInterval"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-msds-managedpasswordinterval" }
        )
        Tools = @("PowerShell", "GMSAPasswordReader")
        Triggers = @(
            @{ Attribute = 'msDS-ManagedPasswordInterval'; Custom = 'gmsa_interval_gt_90'; Severity = 'Hint' }
        )
    }

    'GMSA_MEMBERSHIP_OWNER' = @{
        Title = "gMSA Password Access Descriptor Owned by a Non-Privileged Principal"
        Risk = "Finding"
        BaseScore = 60
        Description = "msDS-GroupMSAMembership is a security descriptor, and who may retrieve this gMSA's password is the DACL inside it. The owner of a security descriptor may rewrite that DACL whether or not the DACL grants it anything - so this principal can add itself as a password reader and then read msDS-ManagedPassword. It does not appear among the readers today, which is why an analysis that looks only at the ACEs reports the account as properly restricted."
        Impact = @(
            "The owner can grant itself password retrieval and remove the entry afterwards"
            "It holds that right without appearing in any list of password readers"
            "The gMSA's Kerberos keys follow from the password blob, so this is full control of the service identity"
            "Where the gMSA is privileged, this is a path into that privilege"
        )
        Attack = @(
            "1. Attacker controls the owner of msDS-GroupMSAMembership"
            "2. Rewrites the descriptor to grant itself ReadProperty"
            "3. Reads msDS-ManagedPassword and derives the account's Kerberos keys"
            "4. Authenticates as the gMSA, then restores the descriptor"
        )
        Remediation = @(
            "Set the owner of msDS-GroupMSAMembership back to Domain Admins or SYSTEM"
            "Review who holds WriteOwner on the gMSA object itself - that right leads back here"
            "Treat whoever created the account as a holder of its password until the owner is corrected"
        )
        RemediationCommands = @(
            @{
                Description = "Show the owner of the password access descriptor of every gMSA"
                Command = "Get-ADServiceAccount -Filter * -Properties msDS-GroupMSAMembership | ForEach-Object { `$sd = New-Object System.DirectoryServices.ActiveDirectorySecurity; `$sd.SetSecurityDescriptorBinaryForm(`$_.'msDS-GroupMSAMembership'); [PSCustomObject]@{ Name = `$_.Name; Owner = `$sd.GetOwner([System.Security.Principal.NTAccount]) } }"
            }
            @{
                Description = "Rewrite the descriptor with the intended readers, which also resets its owner"
                Command = "Set-ADServiceAccount -Identity 'GMSA_NAME' -PrincipalsAllowedToRetrieveManagedPassword 'GMSA_HOSTS'"
            }
        )
        References = @(
            @{ Title = "msDS-GroupMSAMembership"; Url = "https://learn.microsoft.com/en-us/windows/win32/adschema/a-msds-groupmsamembership" }
            @{ Title = "Group Managed Service Accounts Overview"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/ad-ds/manage/group-managed-service-accounts/group-managed-service-accounts-overview" }
            @{ Title = "Owner Rights on an Object - MS-ADTS"; Url = "https://learn.microsoft.com/en-us/openspecs/windows_protocols/ms-adts/d2435927-0999-4c62-8c6d-13ba31a52e1a" }
        )
        Tools = @("PowerShell", "GMSAPasswordReader", "PowerView")
        Triggers = @(
            # The annotation Get-ManagedServiceAccountSecurity writes on a gMSA whose
            # descriptor owner is neither a default owner nor a privileged principal. No
            # pattern: the attribute is only ever written when that is the case.
            @{ Attribute = 'gmsaMembershipOwner'; Severity = 'Finding' }
        )
    }

    'GMSA_MEMBERSHIP_INFO' = @{
        Title = "gMSA Membership Information"
        Risk = "Hint"
        BaseScore = 15
        Description = "This shows the membership/principal configuration for a Group Managed Service Account (gMSA). The listed principals can retrieve the managed password for this service account."
        Impact = @(
