    # Certificate Name/Enrollment Flags (severity-only triggers for flags)
    'CERT_FLAG_SEVERITY' = @{
        # Colour only, by design: the colour of a certificate flag; the ESC definitions carry the reader's text.
        # Declared rather than left to be inferred, because a definition whose only
        # triggers are SeverityOnly can never produce a finding card - and one carrying a
        # full write-up in that state is a text nobody can open. Test-Project checks for
        # exactly that and skips the ones marked here.
        ColourOnly = $true
        Title = "Certificate Template Flags"
        Risk = "Finding"
        BaseScore = 30
        Description = "Certificate template flag classifications for severity display."
        Impact = @(
            "Security-relevant certificate template flags affect enrollment behavior"
        )
        Remediation = @(
            "Review and secure certificate template flag configuration"
        )
        RemediationCommands = @(
            @{
                Description = "Disable ENROLLEE_SUPPLIES_SUBJECT flag via Certificate Templates Console"
                Command = "# Use certtmpl.msc - Subject Name tab - uncheck 'Supply in the request'"
            }
            @{
                Description = "Enable PEND_ALL_REQUESTS flag (require CA manager approval)"
                Command = "# Use certtmpl.msc - Issuance Requirements tab - check 'CA certificate manager approval'"
            }
            @{
                Description = "View template flags via certutil"
                Command = "certutil -dstemplate <TemplateName> | findstr `"msPKI-Certificate-Name-Flag msPKI-Enrollment-Flag`""
            }
        )
        MITRE = "T1649"
        Triggers = @(
            @{ Attribute = 'CertificateNameFlag'; Pattern = 'ENROLLEE_SUPPLIES_SUBJECT'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'EnrollmentFlag'; Pattern = 'NO_SECURITY_EXTENSION'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'EnrollmentFlag'; Pattern = 'PEND_ALL_REQUESTS'; Severity = 'Secure'; SeverityOnly = $true }
            @{ Attribute = 'EnrollmentFlagDisplay'; Pattern = 'NO_SECURITY_EXTENSION'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'EnrollmentFlagDisplay'; Pattern = 'PEND_ALL_REQUESTS'; Severity = 'Secure'; SeverityOnly = $true }
        )
    }

    # Exchange Endpoints (WebEndpoints for Exchange, separate from ADCS WebEnrollmentEndpoints)
    'EXCHANGE_WEB_ENDPOINTS' = @{
        Title = "Exchange Web Endpoints Security"
        Risk = "Finding"
        BaseScore = 40
        Description = "Exchange web endpoints expose authentication interfaces. Endpoints using NTLM authentication are vulnerable to relay attacks unless Extended Protection for Authentication (EPA) is enabled. EPA binds authentication to the TLS channel, preventing relay. It is configured per virtual directory, so each endpoint listed carries its own verdict and one of them being protected says nothing about the others - MRSProxy in particular sits inside the EWS directory but is governed separately, and a pre-authentication remote code execution chain has been demonstrated against it on servers where only that endpoint was left unprotected. An endpoint marked [EPA: Undetermined] offers NTLM and rejected adPEAS's probe, which carries random credentials and is rejected whether or not EPA is enforced; Exchange 2019 CU14 and later enable Extended Protection by default, so read the state of such an endpoint on the server before treating it as relayable."
        Impact = @(
            "HTTP + NTLM endpoints are vulnerable to NTLM relay"
            "HTTPS + NTLM without EPA is also vulnerable"
            "Relay attacks can compromise Exchange mailboxes"
            "A relayed machine account can reach service endpoints that write files, which has yielded web shells running as SYSTEM"
        )
        Attack = @(
            "1. Coerce or capture an authentication from a domain account or machine account"
            "2. Relay it to an Exchange endpoint that offers NTLM without binding it to the TLS channel"
            "3. Act as the relayed identity against that endpoint - mailbox access through EWS, or the service methods of an endpoint such as MRSProxy"
            "4. An Exchange server compromised this way reaches every mailbox, and through Exchange's directory permissions often the domain"
        )
        Remediation = @(
            "Enable EPA on all Exchange endpoints, and verify it per virtual directory rather than per server"
            "Disable HTTP access and require HTTPS"
            "Keep the servers on a current cumulative and security update - several relay paths were closed by update rather than by configuration"
            "Turn MRSProxy off on servers that perform no cross-forest or hybrid mailbox moves"
        )
        RemediationCommands = @(
            @{
                Description = "Check the Extended Protection state of every virtual directory"
                Command = "# Run Microsoft's script on the Exchange server: .\ExchangeExtendedProtectionManagement.ps1 -ShowExtendedProtection"
            }
            @{
                Description = "Show whether MRSProxy is published on each EWS virtual directory"
                Command = "Get-WebServicesVirtualDirectory -ADPropertiesOnly | Select-Object Identity,MRSProxyEnabled"
            }
        )
        References = @(
            @{ Title = "Exchange Security Best Practices"; Url = "https://docs.microsoft.com/en-us/exchange/plan-and-deploy/post-installation-tasks/security-best-practices" }
            @{ Title = "Configure Extended Protection in Exchange Server"; Url = "https://learn.microsoft.com/en-us/exchange/plan-and-deploy/post-installation-tasks/security-best-practices/exchange-extended-protection" }
        )
        MITRE = "T1187"
        Triggers = @(
            # EPA enabled is the mitigation this card describes, so an endpoint that has it
            # must not carry the card: the row went green through the severity-only trigger
            # and kept the "NTLM endpoints are vulnerable to relay" write-up, while the
            # Secure definition that fits it was reachable from the AD CS attribute only.
            @{ Attribute = 'WebEndpoints'; Pattern = 'NTLM'; ExcludePattern = '\[EPA:\s*Enabled\]'; Severity = 'Finding' }
        )
    }

    # Constrained Delegation (regular, non-protocol transition)
    'CONSTRAINED_DELEGATION' = @{
        Title = "Constrained Delegation Configured"
        Risk = "Finding"
        BaseScore = 40
        Description = "This account has constrained delegation configured. It can impersonate users to the specified services when they authenticate to this account."
        Impact = @(
            "Can impersonate authenticating users to configured target services"
            "If any target SPN points at a Domain Controller, privilege escalation is possible"
        )
        Remediation = @(
            "Review if constrained delegation is still required"
            "Limit target services to minimum necessary"
        )
        RemediationCommands = @(
            @{
                Description = "Remove constrained delegation target SPNs"
                Command = "Set-ADUser -Identity 'ACCOUNT_NAME' -Clear msDS-AllowedToDelegateTo"
            }
            @{
                Description = "List all target SPNs for constrained delegation"
                Command = "Get-ADUser -Identity 'ACCOUNT_NAME' -Properties msDS-AllowedToDelegateTo | Select-Object -ExpandProperty msDS-AllowedToDelegateTo"
            }
            @{
                Description = "Find all accounts with constrained delegation"
                Command = "Get-ADObject -LDAPFilter '(msDS-AllowedToDelegateTo=*)' -Properties msDS-AllowedToDelegateTo,userAccountControl"
            }
        )
        References = @(
            @{ Title = "Constrained Delegation"; Url = "https://learn.microsoft.com/en-us/windows-server/security/kerberos/kerberos-constrained-delegation-overview" }
        )
        Tools = @("Rubeus", "Impacket")
        MITRE = "T1550.003"
        Triggers = @(
            # Moved here from CONSTRAINED_DELEGATION_PROTOCOL_TRANSITION. A set
            # msDS-AllowedToDelegateTo on its own is Kerberos-only constrained delegation:
            # real, worth reporting, but it needs an actual user authentication to the
            # account. Protocol transition is the UAC flag, and that definition keeps it.
            # Until this move the definition had no triggers and could never be reached.
            #
            # Gated, because the account with TRUSTED_TO_AUTH_FOR_DELEGATION is a
            # materially different thing and has a card of its own. This trigger had no
            # pattern and no predicate, so every delegation target row of every account
            # got this card - including the accounts where its central claim, "when they
            # authenticate to this account", is false: with protocol transition no
            # authentication from the impersonated user is required at all. The reader
            # looking at the target SPNs got the understated statement.
            #
            # The two predicates are each other's inverse rather than relying on which
            # trigger is examined first: the index is built from an unordered hashtable
            # and its order differs between Windows PowerShell 5.1 and PowerShell 7.
            @{ Attribute = 'msDS-AllowedToDelegateTo'; Custom = 'is_kerberos_only_delegation'; Severity = 'Finding' }
        )
    }

