            @{ Attribute = 'credentialType'; Custom = 'credential_needs_review'; Severity = 'Hint'; SeverityOnly = $true }
            # Default: any credentialType = Hint
            @{ Attribute = 'credentialType'; Severity = 'Hint'; SeverityOnly = $true }
