        MITRE = "T1078.003"
        Triggers = @(
            @{ Attribute = 'BackupDirectory'; Pattern = 'Disabled|Microsoft Entra ID only'; Severity = 'Finding' }
            @{ Attribute = 'BackupDirectory'; Pattern = '^Active Directory$'; Severity = 'Secure'; SeverityOnly = $true }
        )
