        )
        References = @(
            @{ Title = "Windows LAPS overview"; Url = "https://learn.microsoft.com/en-us/windows-server/identity/laps/laps-overview" }
        )
        Tools = @("adPEAS")
        MITRE = "T1078.003"
        Triggers = @(
            # Note, not Hint, and the same colour the row carries in every other GPO check:
            # a policy that reaches nothing is the one line in a finding block that lowers
            # the risk. "Unknown" is the yellow one - that is missing information, not a
            # mitigating fact.
            # SeverityOnly: 'LinkedOUs' is written by twelve check modules across six
            # categories, not just by the LAPS check. Without this the LAPS card and its
            # text ("The LAPS settings in this GPO apply to no computer at all") attached
            # itself to printer driver policies, SMB signing policies, LDAP configuration,
            # scheduled tasks and user rights assignments. The colouring above is right for
            # all of them, the finding is not.
            @{ Attribute = 'LinkedOUs'; Pattern = '^Not linked'; Severity = 'Note'; SeverityOnly = $true }
            @{ Attribute = 'LinkedOUs'; Pattern = '^Unknown - linkage'; Severity = 'Hint'; SeverityOnly = $true }

            # ...and an attribute of its own, which is what makes this card reachable at
            # all. Both triggers above are SeverityOnly - they colour the row and never
            # produce a finding id - so the write-up below was written for a reader who
            # could never open it: the policy that really is linked nowhere, the case this
            # definition exists for, appeared as an unremarkable "Not linked" line with no
            # tooltip, no card and no remediation, and was missing from the findings part
            # of the HTML report entirely.
            #
            # lapsGpoNotLinked is set by Get-LAPSConfiguration and by nothing else, which
            # is the point: LinkedOUs is written by twelve check modules across six
            # categories, and a card saying "The LAPS settings in this GPO apply to no
            # computer at all" cannot be attached to a printer driver policy.
            @{ Attribute = 'lapsGpoNotLinked'; Severity = 'Hint' }
        )
    }

    # Hardcoded scriptPath (UNC or absolute local path)
    'GPO_SCRIPT_OUTSIDE_POLICY_STORE' = @{
        Title = "GPO Script Executed From Outside the Policy Store"
        Risk = "Finding"
        BaseScore = 60
        Description = "A Group Policy runs this script from a path that is not the policy's own Scripts folder in SYSVOL - a file share, the domain's NETLOGON scripts folder, or a local path on every target machine. Whoever may write that file decides what runs, and a startup or shutdown script runs as SYSTEM on every machine the policy reaches. For a UNC path adPEAS reads the NTFS permissions of the file and of its folder over SMB, where it may connect - the domain's own name and enabled computers of the domain, not under -OPSEC - and names whoever beyond the administrators may write them (scriptPathPermissions). The share permissions apply on top over the network and are not read; a local path exists on each computer and is not read either."
        Impact = @(
            "Write access to the script file is code execution in the script's context - SYSTEM for startup and shutdown scripts"
            "The scope is every machine or every user the GPO applies to, at every boot or every logon"
            "A UNC path also makes each machine authenticate to that host, which is an NTLM coercion surface"
            "A local path has to exist on every target, so one machine where it does not is a place to plant it"
        )
        Attack = @(
            "1. Attacker reads the policy's scripts.ini or psscripts.ini out of SYSVOL, which any authenticated user may do"
            "2. Checks who may write the path it names - a share with loose permissions, or a local directory users can write"
            "3. Replaces the script, or creates it where it is missing"
            "4. Waits for the next boot or logon, and the code runs in the script's context"
        )
        Remediation = @(
            "Keep GPO scripts in the policy's own Scripts folder, where the GPO's permissions decide who may change them - that is what the Group Policy editor does by default"
            "Where a share must be used, confirm that only administrators may write the file and the folder above it, and prefer a path that is not reachable by the machines' own accounts"
            "Check whether the script exists at all on every target: a missing file on one machine is a place to plant one"
            "Review the script's content too - it is readable by every authenticated user in SYSVOL, so credentials in it are already exposed"
        )
        RemediationCommands = @(
            @{
                Description = "Show the scripts a GPO runs and where they come from"
                Command = "Get-GPOReport -Name 'GPO_NAME' -ReportType Xml | Select-String -Pattern 'Script'"
            }
            @{
                Description = "Show who may write the script file"
                Command = "(Get-Acl '\\SERVER\SHARE\script.bat').Access | Format-Table IdentityReference, FileSystemRights, AccessControlType -AutoSize"
            }
        )
        References = @(
            @{ Title = "Boot or Logon Initialization Scripts - MITRE ATT&CK"; Url = "https://attack.mitre.org/techniques/T1037/" }
            @{ Title = "Group Policy script settings - Microsoft"; Url = "https://learn.microsoft.com/en-us/previous-versions/windows/it-pro/windows-server-2012-r2-and-2012/dn789196(v=ws.11)" }
        )
        Tools = @("PowerView", "BloodHound")
        MITRE = "T1037"
        Triggers = @(
            @{ Attribute = 'scriptRisk'; Pattern = '^Runs as SYSTEM from a path outside'; Severity = 'Finding' }
            @{ Attribute = 'scriptRisk'; Pattern = '^Runs as the logged-on user from a path outside'; Severity = 'Hint' }

            # NETLOGON, or SYSVOL outside a GPO folder: not the policy's own folder either,
            # so the card applies, but its default permissions let administrators write -
            # a hint under SYSTEM, a note under the user.
            @{ Attribute = 'scriptRisk'; Pattern = '^Runs as SYSTEM from NETLOGON'; Severity = 'Hint' }
            @{ Attribute = 'scriptRisk'; Pattern = '^Runs as the logged-on user from NETLOGON'; Severity = 'Note' }

            # The permissions read over SMB (Set-GPOScriptWriteAccess). A principal beyond
            # the administrators may write the script: a finding in either context. Read in
            # full and only administrators may: a note in NETLOGON, whose administrators are
            # the domain's, a hint on another server, whose administrators decide what runs.
            # Severity only - the openings above still pick the card - and disjoint from each
            # other and from the policy-store colour below.
            @{ Attribute = 'scriptRisk'; Pattern = ' can change it by NTFS permission'; Severity = 'Finding'; SeverityOnly = $true }
            @{ Attribute = 'scriptRisk'; Pattern = '^Runs as .+ from NETLOGON or SYSVOL outside a GPO folder - only '; Severity = 'Note'; SeverityOnly = $true }
            @{ Attribute = 'scriptRisk'; Pattern = '^Runs as .+ from a path outside the policy store - only '; Severity = 'Hint'; SeverityOnly = $true }
            # One "path: Identity (Rights)" row per trustee that can write, written only when
            # there is one.
            @{ Attribute = 'scriptPathPermissions'; Severity = 'Finding' }

            # The script in the policy store: a colour and no card, because the GPO
            # permissions decide who may change it and the GPO permission checks are what
            # report those. The ExcludePattern keeps this one off the four cases above -
            # a severity-only trigger without a pattern matches every value of its
            # attribute, and that pass runs first.
            @{ Attribute = 'scriptRisk'; ExcludePattern = 'outside the policy store|outside a GPO folder'; Severity = 'Note'; SeverityOnly = $true }

            @{ Attribute = 'scriptParameterCredential'; Severity = 'Finding' }
        )
    }

    'LOGON_SCRIPT_WRITABLE' = @{
        Title = "Logon Script a Principal Beyond the Administrators May Change"
        Risk = "Finding"
        BaseScore = 65
        Description = "Accounts run this logon script - their scriptPath names it, relative to the NETLOGON share - and Windows runs it at every logon of each of them, as that account. A principal beyond the administrators may change the script or create files in its folder by NTFS permission, and so run code as every account that has the script set; a privileged account among them runs it with the privileges it holds. adPEAS reads the NTFS permissions of the file and of its folder over SMB; the share permissions apply on top over the network and are not read."
