<#
.SYNOPSIS
    Exports finding definitions as JSON for embedding in HTML.
.PARAMETER Minified
    If set, outputs minified JSON without indentation.
.RETURNS
    JSON string of all finding definitions.
#>
function Export-FindingDefinitionsJson {
    [CmdletBinding()]
    param(
        [switch]$Minified
    )

    # Convert hashtable to format suitable for JSON
    $jsonObject = @{}

    foreach ($key in $Script:FindingDefinitions.Keys) {
        $def = $Script:FindingDefinitions[$key]

        # Convert References array of hashtables to array of objects
        $refs = [System.Collections.Generic.List[object]]::new()
        if ($def.References) {
            foreach ($ref in $def.References) {
                $refs.Add(@{ title = $ref.Title; url = $ref.Url })
            }
        }

        # Convert Tools - support both old string format and new object format
        $tools = [System.Collections.Generic.List[object]]::new()
        if ($def.Tools) {
            foreach ($tool in $def.Tools) {
                if ($tool -is [hashtable] -or $tool -is [System.Collections.Specialized.OrderedDictionary]) {
                    $tools.Add(@{ name = $tool.Name; url = $tool.Url })
                } else {
                    # String format - resolve URL from central repository
                    $toolUrl = $Script:ToolUrls[$tool]
                    $tools.Add(@{ name = [string]$tool; url = $toolUrl })
                }
            }
        }

        # Convert RemediationCommands array of hashtables to array of objects
        $remediationCmds = [System.Collections.Generic.List[object]]::new()
        if ($def.RemediationCommands) {
            foreach ($cmd in $def.RemediationCommands) {
                $remediationCmds.Add(@{ description = $cmd.Description; command = $cmd.Command })
            }
        }

        $jsonObject[$key] = @{
            title = $def.Title
            risk = $def.Risk
            baseScore = $def.BaseScore
            description = $def.Description
            impact = $def.Impact
            attack = $def.Attack
            remediation = $def.Remediation
            remediationCommands = $remediationCmds.ToArray()
            references = $refs.ToArray()
            tools = $tools.ToArray()
            mitre = $def.MITRE
        }
    }

    if ($Minified) {
        return ($jsonObject | ConvertTo-Json -Depth 10 -Compress)
    } else {
        return ($jsonObject | ConvertTo-Json -Depth 10)
    }
}

# =============================================================================
# BUILD INVERTED INDEX for fast attribute -> FindingId + Severity lookup
# =============================================================================
# Reads Triggers from each FindingDefinition and builds an inverted index.
# Used by Get-FindingIdForAttribute (tooltip lookup) and Get-SeverityFromTrigger (severity).
#
# Structure: $Script:FindingTriggerIndex['attributeName'] = @(
#   @{ FindingId = 'XXX'; Pattern = 'regex'; ExcludePattern = 'regex'; Context = 'ctx';
#      Custom = 'func'; Severity = 'Hint'; ParentRisk = 'Finding' }
# )
#
# Severity resolution order:
#   1. Trigger.Severity (explicit per-trigger override, e.g. "Hint" for Optional values)
#   2. FindingDefinition.Risk (parent definition risk level, e.g. "Finding")

$Script:FindingTriggerIndex = @{}
$triggerLists = @{}  # Temporary List<object> per attribute for O(1) append

foreach ($findingId in $Script:FindingDefinitions.Keys) {
    $definition = $Script:FindingDefinitions[$findingId]

    # Skip if no Triggers defined
    if (-not $definition.ContainsKey('Triggers') -or $null -eq $definition.Triggers) {
        continue
    }

    foreach ($trigger in $definition.Triggers) {
        if (-not $trigger.Attribute) { continue }

        $attrName = $trigger.Attribute.ToLower()

        if (-not $triggerLists.ContainsKey($attrName)) {
            $triggerLists[$attrName] = [System.Collections.Generic.List[object]]::new()
        }

        $triggerLists[$attrName].Add(@{
            FindingId      = $findingId
            Pattern        = $trigger.Pattern
            ExcludePattern = $trigger.ExcludePattern
            Context        = $trigger.Context
            Custom         = $trigger.Custom
            Severity       = $trigger.Severity      # Optional: per-trigger severity override
            SeverityOnly   = $trigger.SeverityOnly   # If $true, Get-FindingIdForAttribute skips this
            ParentRisk     = $definition.Risk        # Parent definition risk level
            # Needed so Get-TriggerMatch can pick the most severe match instead of the
            # first one this list happens to hold - see the comment there.
            BaseScore      = if ($definition.ContainsKey('BaseScore')) { [int]$definition.BaseScore } else { 0 }
        })
    }
}

# Convert Lists to arrays for the final index (arrays are faster to iterate)
foreach ($key in $triggerLists.Keys) {
    $Script:FindingTriggerIndex[$key] = $triggerLists[$key].ToArray()
}
Remove-Variable -Name triggerLists -ErrorAction SilentlyContinue

<#
.SYNOPSIS
    Maps attribute names/values to finding definition IDs for tooltip display.
.DESCRIPTION
    Thin wrapper around Get-TriggerMatch that returns only the FindingId.
    Returns $null if no tooltip should be shown.
.PARAMETER Name
    The attribute name (e.g., 'servicePrincipalName', 'userAccountControl').
.PARAMETER Value
    The attribute value to check against patterns.
.PARAMETER Context
    Optional context string for context-specific triggers.
.RETURNS
    FindingId string or $null.
#>
function Get-FindingIdForAttribute {
    [CmdletBinding()]
    param(
        [string]$Name,
        $Value,
        [string]$Context = $null
    )

    $match = Get-TriggerMatch -Name $Name -Value $Value -Context $Context
    return $match.FindingId
}

<#
.SYNOPSIS
    Determines attribute severity from FindingDefinitions triggers.
.DESCRIPTION
    Thin wrapper around Get-TriggerMatch that returns only the Severity.
    Returns $null if no trigger matches (caller should use "Standard" as fallback).
.PARAMETER Name
    The attribute name (e.g., 'LDAPSigning', 'servicePrincipalName').
.PARAMETER Value
    The attribute value to check against patterns.
.PARAMETER IsComputer
    Set to $true if the source object is a computer account.
.PARAMETER SourceObject
    Optional. The source AD object for context-aware triggers.
.PARAMETER Context
    Optional context string for context-specific triggers.
.RETURNS
    Severity string ("Finding", "Hint", "Secure", "Note") or $null if no trigger matches.
#>
function Get-SeverityFromTrigger {
    [CmdletBinding()]
    param(
        [string]$Name,
        $Value,
        [bool]$IsComputer = $false,
        $SourceObject = $null,
        [string]$Context = $null
    )

    $match = Get-TriggerMatch -Name $Name -Value $Value -IsComputer $IsComputer `
        -SourceObject $SourceObject -Context $Context
    $severity = $match.Severity
    if ($severity -eq 'Standard') { return $null }
    return $severity
}

<#
.SYNOPSIS
    Combined severity and FindingId lookup in a single pass.
.DESCRIPTION
    Returns both severity and FindingId for an attribute value from FindingDefinitions.
    Eliminates the need for separate Get-AttributeSeverity + Get-FindingIdForAttribute calls.

    The function performs two lookups:
    1. Severity: Via two-pass evaluation (SeverityOnly triggers first, then normal triggers)
    2. FindingId: Via normal triggers only (SeverityOnly triggers are excluded)

    When both are found in the same trigger match, only one index lookup is needed.
.PARAMETER Name
    The attribute name.
.PARAMETER Value
    The attribute value.
.PARAMETER IsComputer
    Whether the source object is a computer account.
.PARAMETER SourceObject
    The source AD object for context-aware triggers.
.PARAMETER Context
    Optional context string for context-specific triggers.
.RETURNS
    PSCustomObject with Severity (string or "Standard") and FindingId (string or $null).
    Returns $null if attribute has no triggers at all.
#>
function Get-TriggerMatch {
    [CmdletBinding()]
    param(
        [string]$Name,
        $Value,
        [bool]$IsComputer = $false,
        $SourceObject = $null,
        [string]$Context = $null
    )

    # Default return object for no-match cases
    $noMatch = [PSCustomObject]@{ Severity = 'Standard'; FindingId = $null }

    if ([string]::IsNullOrEmpty($Name)) { return $noMatch }

    # Auto-detect IsComputer from SourceObject via central helper
    if (-not $IsComputer -and $SourceObject) {
        $IsComputer = Test-IsComputerObject -Object $SourceObject
    }

    $attrNameLower = $Name.ToLower()
    $strValue = [string]$Value

    if (-not $Script:FindingTriggerIndex.ContainsKey($attrNameLower)) {
        return $noMatch
    }

    $triggers = $Script:FindingTriggerIndex[$attrNameLower]
    $resultSeverity = $null
    $resultFindingId = $null
    $bestTrigger = $null

    # Tie-break for two triggers with the same BaseScore: the more specific one wins, so a
    # Custom predicate or a Pattern beats a bare fallback trigger on the same attribute.
    $isMoreSpecific = {
        param($a, $b)
        $sa = [int][bool]$a.Custom + [int][bool]$a.Pattern
        $sb = [int][bool]$b.Custom + [int][bool]$b.Pattern
        if ($sa -ne $sb) { return ($sa -gt $sb) }
        return ([string]$a.FindingId -lt [string]$b.FindingId)
    }

    # Pass 1: SeverityOnly triggers (priority for severity)
    # Pass 2: Normal triggers (provide both severity fallback and FindingId)
    foreach ($pass in @($true, $false)) {
        foreach ($trigger in $triggers) {
            $isSeverityOnly = [bool]$trigger.SeverityOnly
            if ($isSeverityOnly -ne $pass) { continue }

            # Check Context requirement
            if ($trigger.Context) {
                if (-not $Context -or $Context -notmatch $trigger.Context) { continue }
            }

            # Check ExcludePattern
            if ($trigger.ExcludePattern) {
                if ($strValue -match $trigger.ExcludePattern) { continue }
            }

            # Determine if trigger matches
            $matched = $false
            if ($trigger.Custom) {
                $customResult = Test-CustomTrigger -CustomType $trigger.Custom -Value $Value `
                    -IsComputer $IsComputer -SourceObject $SourceObject
                if (-not $customResult) { continue }
                if ($trigger.Pattern) {
                    if ($strValue -notmatch $trigger.Pattern) { continue }
                }
                $matched = $true
            } elseif ($trigger.Pattern) {
                if ($strValue -match $trigger.Pattern) { $matched = $true }
            } else {
                $matched = $true
            }

            if (-not $matched) { continue }

            if ($isSeverityOnly) {
                # SeverityOnly triggers only colour the row; the first match wins, and they
                # keep priority over the severity of the finding selected below.
                if ($null -eq $resultSeverity) {
                    $resultSeverity = if ($trigger.Severity) { $trigger.Severity } else { $trigger.ParentRisk }
                }
                continue
            }

            # Among ALL matching triggers take the most severe finding by BaseScore, not the
            # first one this list happens to hold. The index is built by iterating
            # $Script:FindingDefinitions.Keys, an unordered hashtable, so "first" is the hash
            # bucket order - and that differs between runtimes. Measured on the same source
            # with the same keys, attribute 'Vulnerabilities', value "ESC2, ESC3":
            # Windows PowerShell 5.1 answered ESC2_TEMPLATE (BaseScore 80), PowerShell 7
            # answered ESC3_TEMPLATE (75). Same template, different card, different
            # remediation, decided by the host the scan ran on.
            # On a tie the MORE SPECIFIC trigger wins - one with a Custom predicate or a
            # Pattern beats a bare fallback trigger on the same attribute. That is what
            # makes the deliberate two-trigger pattern work: SID_HISTORY_INJECTION pairs a
            # Custom 'is_privileged_sid' trigger (Finding) with a pattern-less one (Hint)
            # for every other SID, both carrying the same FindingId and BaseScore. Without
            # this rule the severity of a privileged SID in sIDHistory depended on which of
            # the two the hashtable happened to list first.
            # Last tie-break is the FindingId, so the answer is stable either way.
            if ($null -eq $bestTrigger -or
                [int]$trigger.BaseScore -gt [int]$bestTrigger.BaseScore -or
                ([int]$trigger.BaseScore -eq [int]$bestTrigger.BaseScore -and
                 (& $isMoreSpecific $trigger $bestTrigger))) {
                $bestTrigger = $trigger
            }
        }
    }

    if ($null -ne $bestTrigger) {
        $resultFindingId = $bestTrigger.FindingId
        if ($null -eq $resultSeverity) {
            $resultSeverity = if ($bestTrigger.Severity) { $bestTrigger.Severity } else { $bestTrigger.ParentRisk }
        }
    }

    if ($null -eq $resultSeverity -and $null -eq $resultFindingId) {
        return $noMatch
    }

    return [PSCustomObject]@{
        Severity  = if ($resultSeverity) { $resultSeverity } else { 'Standard' }
        FindingId = $resultFindingId
    }
}

<#
.SYNOPSIS
    Tests one userAccountControl flag on the object a trigger is evaluating.

.DESCRIPTION
    The UAC transformer renders every flag as a value of its own, so a trigger's $Value
    holds the single flag under test and a question about a different flag has to be put
    to the object. The attribute is read by name rather than out of the object's
    ToString(), which used to be the implementation and made any attribute containing the
    flag's text - a description, for instance - answer this question.

    Takes both forms the attribute can have: the flag names ConvertFrom-LDAPAttribute
    produces, and the raw number, in case the object was built without that conversion.

.PARAMETER SourceObject
    The object the trigger is evaluating, if the caller supplied one.

.PARAMETER Value
    The trigger's value, used only when the object carries no userAccountControl.

.PARAMETER FlagName
    Name of the flag, e.g. 'SERVER_TRUST_ACCOUNT'.

.PARAMETER FlagBit
    The same flag's bit, for the numeric form.

.OUTPUTS
    [bool]
#>
<#
.SYNOPSIS
    Whether a sIDHistory value holds a privileged SID that did not come from a source
    domain.
.DESCRIPTION
    sIDHistory exists to hold the SID an account had in a *source* domain. Two kinds of
    entry therefore cannot be migration records at all:

      - a SID of the domain the object already lives in, and
      - a SID that belongs to no domain - BUILTIN and NT AUTHORITY SIDs such as
        S-1-5-32-548, which ADMT does not write.

    Either of those together with a privileged RID is the signature of SID history
    injection, and it is the one statement the check can make without knowing anything
    about the environment. A privileged SID of another S-1-5-21 domain is the opposite: it
    is what every migration of an administrator leaves behind.

    The value may be a bare SID, a "NAME (SID)" display string or an object carrying a SID
    property, so the SID is extracted rather than assumed.

    Returns $false when the domain SID is unknown, which is the milder reading: the
    comparison cannot be made, and the alternative accuses every account a migration ever
    touched.
.PARAMETER Value
    The attribute value to examine.
.OUTPUTS
    Boolean
#>
function Test-IsLocalPrivilegedSIDHistory {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value
    )

    $ownDomainSID = $null
    if ($Script:LDAPContext -and $Script:LDAPContext.DomainSID) {
        $ownDomainSID = [string]$Script:LDAPContext.DomainSID
    }
    if ([string]::IsNullOrWhiteSpace($ownDomainSID)) { return $false }

    $candidate = $null
    if ($Value -is [string]) { $candidate = $Value }
    elseif ($null -ne $Value -and $Value.PSObject.Properties['SID']) { $candidate = [string]$Value.SID }
    else { $candidate = [string]$Value }
    if ([string]::IsNullOrWhiteSpace($candidate)) { return $false }

    # The SID out of whatever the row carries. 'CONTOSO\jdoe (S-1-5-21-...-1105)', a bare
    # 'S-1-5-21-...-1105' and 'S-1-5-32-548' all have to work.
    if ($candidate -notmatch '(S-1-[0-9]+(?:-[0-9]+)+)') { return $false }
    $sid = $Matches[1]

    # From another domain, so a migration record. The trailing dash is what keeps a
    # different domain whose SID starts with the same digits from counting as this one.
    if (($sid -like 'S-1-5-21-*') -and ($sid -notlike "$ownDomainSID-*")) { return $false }

    # Test-IsPrivileged, not a second copy of the RID list: the check that writes the
    # finding uses it, and two different answers to "is this privileged" about the same
    # SID is how a row ends up coloured against its own card.
    #
    # The $null guard is not decoration. This runs inside the render path, where it can be
    # reached with Test-IsPrivileged replaced by a stub, and Pester evaluates test bodies
    # under Set-StrictMode -Version Latest - which is dynamically scoped, so it reaches in
    # here. Reading .Category off $null would then throw rather than answer.
    $privResult = Test-IsPrivileged -Identity $sid -IncludeOperators
    if (-not $privResult) { return $false }
    return ($privResult.Category -in @('Privileged', 'Operator'))
}

function Test-UACFlagOnObject {
    [CmdletBinding()]
    [OutputType([bool])]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $SourceObject,

        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $Value,

        [Parameter(Mandatory = $true)]
        [string]$FlagName,

        [Parameter(Mandatory = $true)]
        [int]$FlagBit
    )

    $uac = $null
    if ($SourceObject -and $SourceObject.PSObject.Properties['userAccountControl']) {
        $uac = $SourceObject.userAccountControl
    }
    if ($null -eq $uac -or ([string]$uac).Length -eq 0) { $uac = $Value }

    $uacText = ''
    if ($uac -is [array]) { $uacText = ($uac -join ' ') } else { $uacText = [string]$uac }
    if ([string]::IsNullOrWhiteSpace($uacText)) { return $false }

    if ($uacText -match '^\s*\d+\s*$') {
        return ((([int64]$uacText.Trim()) -band $FlagBit) -ne 0)
    }

    return ($uacText -match [regex]::Escape($FlagName))
}

<#
.SYNOPSIS
    Evaluates custom trigger conditions.
.DESCRIPTION
    Handles special cases that can't be expressed as simple regex patterns.
    Supports SourceObject for context-aware triggers (SID-based, computer detection).
#>
<#
.SYNOPSIS
    The decoded Kerberos encryption types of an object, or an empty list.

.DESCRIPTION
    msDS-SupportedEncryptionTypes reaches a trigger one element at a time, because
    Get-TriggerMatch is called per element of a multi-value attribute. "RC4 and no AES" is
    not something a single element can say, so the encryption-type predicates read the
    whole list off the source object through this.

    The Kerberos feature flags that share the attribute - FAST, compound identity, claims,
    resource SID compression - are not encryption types and are left out, so a predicate
    asking "is there an AES type here" cannot be answered by one of them.

.PARAMETER SourceObject
    The object the row belongs to. $null yields an empty list, which each predicate treats
    as "cannot tell".

.OUTPUTS
    [string[]] of the decoded names, as ConvertFrom-LDAPAttribute wrote them.

.NOTES
    Internal helper for Test-CustomTrigger.
#>
function Get-EncryptionTypeList {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $false)]
        [AllowNull()]
        $SourceObject
    )

    # $null rather than an empty array for "nothing to say". An empty array does not
    # survive a return intact - the pipeline unrolls the wrapper - and @($null) is a
    # one-element array, so the callers below test with -not and a count, which is true
    # for both. Returning an empty array here made every caller see one entry.
    if (-not $SourceObject) { return $null }

    $encProp = $SourceObject.PSObject.Properties['msDS-SupportedEncryptionTypes']
    if (-not $encProp -or $null -eq $encProp.Value) { return $null }

    $names = @()
    foreach ($entry in @($encProp.Value)) {
        $text = ([string]$entry).Trim()
        if (-not $text) { continue }
        # The -SK bit is no type of the account's keys: it makes the KDC use AES session
        # keys where RC4 ones would be used (MS-KILE 2.2.7). 0x24, RC4 with AES session
        # keys - Microsoft's recommendation for an account that must keep RC4 - still
        # encrypts the ticket with RC4. Counted as AES, it hid the RC4-only account.
        if ($text -like '*-SK') { continue }
        if ($text -like 'RC4*' -or $text -like 'AES*' -or $text -like 'DES*') { $names += $text }
    }

    if (@($names).Count -eq 0) { return $null }
    return [string[]]$names
}

function Test-CustomTrigger {
    param(
        [string]$CustomType,
        $Value,
        [bool]$IsComputer = $false,
        $SourceObject = $null
    )

    switch ($CustomType) {
        # =====================================================================
        # Context-aware triggers (require SourceObject)
        # =====================================================================

        # Which kind of constrained delegation this account has.
        #
        # TRUSTED_TO_AUTH_FOR_DELEGATION (0x1000000) is the whole difference. With it,
        # S4U2Self returns a forwardable ticket and the account can impersonate anyone to
        # its configured services with no request from that user at all. Without it,
        # S4U2Proxy needs a forwardable ticket the user themselves obtained - a real
        # authentication to this account has to happen first.
        #
        # One predicate per card, each the inverse of the other, so the two can never both
        # match and the answer does not depend on which trigger the index happens to hold
        # first. Both default to the milder reading when the flag cannot be read: claiming
        # protocol transition on an account whose userAccountControl did not arrive would
        # be an accusation drawn from missing data.

        'is_protocol_transition_delegation' {
            return (Test-UACFlagOnObject -SourceObject $SourceObject -Value $null `
                -FlagName 'TRUSTED_TO_AUTH_FOR_DELEGATION' -FlagBit 0x1000000)
        }

        'is_kerberos_only_delegation' {
            return (-not (Test-UACFlagOnObject -SourceObject $SourceObject -Value $null `
                -FlagName 'TRUSTED_TO_AUTH_FOR_DELEGATION' -FlagBit 0x1000000))
        }

        'laps_backup_in_ad' {
            # True - the finding applies - unless Get-LAPSConfiguration marked the row.
            # It sets lapsBackupOutsideAD when a Windows LAPS policy escrows the password
            # outside Active Directory, which makes a missing msLAPS attribute the
            # expected state rather than evidence of an unmanaged password.
            #
            # Defaults to true: a row without the marker is the ordinary case, and a
            # predicate that failed open the other way would silence the finding
            # everywhere.
            if (-not $SourceObject) { return $true }
            $lapsCaveat = $SourceObject.PSObject.Properties['lapsBackupOutsideAD']
            if ($lapsCaveat -and $lapsCaveat.Value) { return $false }
            return $true
        }

        # =====================================================================
        # Kerberos encryption types
        # =====================================================================
        #
        # Get-TriggerMatch is called once per element of a multi-value attribute, so each
        # of these decides about one row while reading the whole list off the source
        # object: "RC4 and no AES" is not a statement any single element can make.
        #
        # Without a source object the list cannot be read, and each predicate then falls
        # back to what the row alone supports - which for the two findings means not
        # claiming anything.

        'enc_rc4_without_aes' {
            if (([string]$Value) -notlike 'RC4*') { return $false }
            $encList = @(Get-EncryptionTypeList -SourceObject $SourceObject | Where-Object { $_ })
            if ($encList.Count -eq 0) { return $false }
            return (@($encList | Where-Object { $_ -like 'AES*' }).Count -eq 0)
        }

        'enc_des_enabled' {
            # DES needs no context: a single DES row is the finding.
            return (([string]$Value) -like 'DES*')
        }

        'enc_not_configured_with_spn' {
            # ConvertFrom-LDAPAttribute renders a stored 0 as "Not configured", and
            # Get-KerberoastableAccounts writes the same for an account that has no value
            # at all - an absent attribute produces no row by itself.
            # Only reported where it matters: an account with a service principal name can
            # be roasted, and the absence of the attribute leaves RC4 on the table. On an
            # ordinary user without an SPN it is the normal state and says nothing.
            if (([string]$Value) -ne 'Not configured') { return $false }
            if (-not $SourceObject) { return $false }
            $spnProp = $SourceObject.PSObject.Properties['servicePrincipalName']
            if (-not $spnProp) { return $false }
            return (@($spnProp.Value | Where-Object { $_ }).Count -gt 0)
        }

        'enc_aes_only' {
            if (([string]$Value) -notlike 'AES*') { return $false }
            $encList = @(Get-EncryptionTypeList -SourceObject $SourceObject | Where-Object { $_ })
            if ($encList.Count -eq 0) { return $false }
            return (@($encList | Where-Object { $_ -like 'RC4*' -or $_ -like 'DES*' }).Count -eq 0)
        }

        'rbac_assignee_already_privileged' {
            # Exchange role assignment only: true when the principal the role was assigned
            # to is privileged in its own right, which Get-ExchangeRBACAssignments records
            # on the row. Defaults to false without the annotation, which is the undamped
            # reading - a row that cannot say what the assignee holds must not be treated
            # as if it held everything already.
            if (-not $SourceObject) { return $false }
            $privilege = $SourceObject.PSObject.Properties['assigneePrivilege']
            if ($privilege -and $privilege.Value) { return $true }
            return $false
        }

        'esc13_group_not_privileged' {
            # Certificate template only: true when the issuance policy on this template
            # links to a group that Test-IsPrivileged does not call privileged. Enrollment
            # then grants a membership nobody applied for, which stays a finding - but not
            # the one that ends the engagement.
            #
            # Defaults to false without a source object or without the annotation, which is
            # the undamped reading: a template that cannot say what its link is worth must
            # not be treated as if the link were harmless. It also only answers for a
            # template that has such a link at all.
            if (-not $SourceObject) { return $false }
            $linkFlag = $SourceObject.PSObject.Properties['issuancePolicyGroupPrivileged']
            if (-not $linkFlag) { return $false }
            if ([string]::IsNullOrWhiteSpace([string]$SourceObject.Vulnerabilities)) { return $false }
            if ([string]$SourceObject.Vulnerabilities -notmatch 'ESC13') { return $false }
            return (-not $linkFlag.Value)
        }

        'esc_enrollment_rights_unread' {
            # Certificate template only: true when Get-ADCSVulnerabilities could not read
            # who may enroll, which is what its 'Unknown' enrollment state writes onto the
            # object. Used SeverityOnly, so it damps the colour of every ESC row on that
            # template without touching the finding card or its remediation.
            #
            # Defaults to false with no source object, which is the undamped reading: a
            # row that cannot say the rights were unread must not be treated as if they
            # were.
            if (-not $SourceObject) { return $false }
            $caveat = $SourceObject.PSObject.Properties['escEnrollmentRightsUnread']
            if ($caveat -and $caveat.Value) { return $true }
            return $false
        }

        'ra_signature_gated' {
            # Certificate template only: true when a required enrollment agent co-signature makes
            # the template's enrollment-driven ESC findings a two-step attack instead of a direct
            # one. Used SeverityOnly, so it damps the colour without changing the finding card.
            #
            # Returns $false (no damping, full severity) in three cases:
            #   - no co-signature is required at all
            #   - the template is ESC4-vulnerable: write access lets an attacker drop the
            #     msPKI-RA-Signature requirement before enrolling, so it is no barrier
            #   - an enrollment agent template is enrollable by non-privileged principals, which
            #     makes the co-signature a formality rather than an obstacle
            if (-not $SourceObject) { return $false }

            $raCount = $SourceObject.RASignatureCount
            if ($null -eq $raCount) { return $false }
            $raCountInt = 0
            if (-not [int]::TryParse([string]$raCount, [ref]$raCountInt)) { return $false }
            if ($raCountInt -lt 1) { return $false }

            if ([string]$SourceObject.Vulnerabilities -match 'ESC4') { return $false }
            if ($SourceObject.EnrollmentAgentChainReachable) { return $false }

            return $true
        }

        'manager_approval_gated' {
            # Certificate template only: true when the template requires manager approval
            # (msPKI-Enrollment-Flag PEND_ALL_REQUESTS), which holds every request in the
            # pending queue until a certificate manager releases it. Used SeverityOnly, for
            # the same reason as ra_signature_gated above: approval is a barrier, not a fix.
            # The template still hands out whatever it hands out the moment somebody
            # approves, and the approver has no way to see the subject the requester
            # supplied is a lie.
            #
            # It was previously not consulted at all, so ESC1/ESC2/ESC3/ESC9/ESC13/ESC15
            # were reported at full severity on templates where no request can be issued
            # without a human in the loop.
            #
            # Returns $false (no damping, full severity) in two cases:
            #   - approval is not required
            #   - the template is ESC4-vulnerable: write access lets an attacker clear
            #     PEND_ALL_REQUESTS before enrolling, exactly as it lets them clear the
            #     co-signature requirement
            if (-not $SourceObject) { return $false }
            if (-not $SourceObject.ManagerApprovalRequired) { return $false }
            if ([string]$SourceObject.Vulnerabilities -match 'ESC4') { return $false }

            return $true
        }

        'is_not_computer' {
            # Returns true if the source object is NOT a computer account
            # Used for servicePrincipalName: SPNs on user accounts = Finding, on computers = expected
            if ($IsComputer) { return $false }
            if ($SourceObject -and (Test-IsComputerObject -Object $SourceObject)) {
                return $false
            }
            return $true
        }

        { $_ -like 'user_right_is_*' } {
            # Shared by all 22 GPO_USERRIGHT_* definitions' GrantedBeyondDefault trigger, one
            # CustomType per right rather than one case per right: Get-TriggerMatch always
            # resolves FindingId to the trigger's OWNING definition, never to a value a Custom
            # evaluator returns, so the only way to route the holder-name row to the right's
            # own definition (SeDebugPrivilege's tooltip rather than SeShutdownPrivilege's) is
            # for each definition to carry a trigger that only fires for its own right. The
            # right itself travels inside the CustomType string instead of 22 near-identical
            # case blocks.
            if (-not $SourceObject) { return $false }
            $wantRight = $CustomType.Substring('user_right_is_'.Length)
            return ([string]$SourceObject.userRight -eq $wantRight)
        }

        'is_unexplained_admincount' {
            # Whether adminCount=1 on this account is explained by a current membership.
            # SDProp sets it on the members of the protected groups and nothing clears it
            # when a membership ends; only on an account that is no longer a member does it
            # say something.
            #
            # Get-InactiveAdminAccounts decides the same question and marks its rows with
            # isOrphaned, and that answer is used where it exists, so the two rows of one
            # card cannot disagree. Otherwise Test-IsPrivileged answers, which follows
            # nesting and the primary group; operator groups count, SDProp protects them
            # too. The built-in Administrator and krbtgt are protected accounts in their
            # own right, member of anything or not. Replicator is protected as well but
            # counted in neither tier, so a member of it alone still reads as unexplained.
            #
            # Without a source object, or without the helper, the row keeps the hint it
            # always had: answering "admin" on a lookup that could not be made would hide
            # the orphan.
            if (-not $SourceObject) { return $true }
            $orphanMark = $SourceObject.PSObject.Properties['isOrphaned']
            if ($orphanMark -and $null -ne $orphanMark.Value) { return ($orphanMark.Value -eq $true) }
            if ([string]$SourceObject.objectSid -match '^S-1-5-21-\d+-\d+-\d+-(500|502)$') { return $false }
            if (-not (Get-Command -Name 'Test-IsPrivileged' -ErrorAction SilentlyContinue)) { return $true }
            $privilege = Test-IsPrivileged -Identity $SourceObject
            return ($privilege.Category -notin @('Privileged', 'Operator'))
        }

        'is_privileged_sid' {
            # Returns true if the SID belongs to a privileged group/user
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { $null }
            if (-not $sid) { return $false }
            $privResult = Test-IsPrivileged -Identity $sid
            return ($privResult.Category -eq 'Privileged')
        }

        # Whether an sIDHistory entry is a privileged SID that did not come from a source
        # domain - this domain's own SID, or one that belongs to no domain at all. Two
        # predicates, each the inverse of the other, so the two triggers that use them
        # cannot both hold and the answer does not depend on index order.
        #
        # Both answer "could be a migration record" when the domain SID cannot be read,
        # which is the milder reading: calling an entry an injection on a comparison that
        # could not be made would accuse every migrated administrator.

        'is_local_privileged_sid_history' {
            return (Test-IsLocalPrivilegedSIDHistory -Value $Value)
        }

        'is_not_local_privileged_sid_history' {
            return (-not (Test-IsLocalPrivilegedSIDHistory -Value $Value))
        }

        'is_operator_sid' {
            # Returns true if the SID belongs to an operator group
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { $null }
            if (-not $sid) { return $false }
            $privResult = Test-IsPrivileged -Identity $sid
            return ($privResult.Category -eq 'Operator')
        }

        'is_broad_group_sid' {
            # Returns true if the SID is a broad group (Everyone, Authenticated Users,
            # BUILTIN\Users, Domain Users, Domain Guests, Domain Computers).
            #
            # Through Test-IsBroadTrustee, which asks both lists. This used to call
            # Test-IsBroadGroupSID alone, and that one only knows the well-known SIDs -
            # Domain Users is a domain-relative RID and lives in the other list. So a
            # certificate template enrollable by Domain Users, which is the commonest
            # ADCS misconfiguration there is and the precondition for ESC1, resolved to
            # no finding id at all, and so did a gMSA whose password Domain Computers may
            # retrieve. The comment above already claimed Domain Users was covered.
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { [string]$Value }
            if (-not $sid) { return $false }
            if (Get-Command -Name 'Test-IsBroadTrustee' -ErrorAction SilentlyContinue) {
                return (Test-IsBroadTrustee -SID $sid)
            }
            # Fallback: check common broad group SID patterns
            $privResult = Test-IsPrivileged -Identity $sid
            return ($privResult.Category -eq 'BroadGroup')
        }

        'is_not_default_owner' {
            # Returns true if the Owner SID is NOT a default owner (DA, EA, Administrators, SYSTEM)
            if ($SourceObject -and $SourceObject.OwnerSID) {
                $isDefault = Test-IsDefaultOwner -SID $SourceObject.OwnerSID
                return (-not $isDefault)
            }
            return $false
        }

        'is_within_forest_trust' {
            # Returns true if the trust is a within-forest trust (for SID filtering context)
            if ($SourceObject -and $SourceObject.isWithinForest -eq $true) {
                return $true
            }
            return $false
        }

        'is_not_within_forest_trust' {
            # The inverse, and it is not redundant. A SeverityOnly trigger sets the colour
            # but never a FindingId, so the second pass still runs and the general trigger
            # still attached the tooltip: a within-forest trust was coloured Standard while
            # being told its disabled SID filtering was a security risk. Inside one forest
            # that is how trusts are supposed to work. Guarding the general trigger keeps
            # the tooltip off without changing the two-pass rule, which ESC3 relies on to
            # damp a colour while deliberately keeping another definition's finding card.
            if ($SourceObject -and $SourceObject.isWithinForest -eq $true) {
                return $false
            }
            return $true
        }

        'is_gpo_finding_object' {
            # Returns true if the GPO object has DangerousPermissions or DangerousSettings
            # Used to prevent Scope/LinkedOUs severity coloring on informational GPO displays
            # (e.g. LDAPConfigGPO, SMBSigningGPO) where domain-wide scope is just context, not a finding
            if (-not $SourceObject) { return $false }
            $hasDangerousPerms = $SourceObject.PSObject.Properties['DangerousPermissions'] -and $SourceObject.DangerousPermissions
            $hasDangerousSettings = $SourceObject.PSObject.Properties['DangerousSettings'] -and $SourceObject.DangerousSettings
            return ($hasDangerousPerms -or $hasDangerousSettings)
        }

        'operator_group_has_members' {
            # The operator-group rows of Get-ProtectedUsersStatus only. The SCCM and SCOM
            # group rows carry a MemberCount too, and the trigger index is keyed by the
            # attribute name alone - so every SCCM or SCOM group with a member collected
            # the card about Account, Backup, Print and Server Operators. Without the row
            # there is no telling whose count it is, so that answers no as well.
            if (-not $SourceObject -or "$($SourceObject._adPEASObjectType)" -ne 'OperatorGroup') { return $false }
            $memberTotal = 0
            if ([int]::TryParse([string]$Value, [ref]$memberTotal)) {
                return ($memberTotal -gt 0)
            }
            return $false
        }

        'is_hardcoded_path' {
            # User accounts only. The attribute is called scriptPath on a user object and
            # ScriptPath on the rows Get-GPOScriptPaths produces, and the trigger index is
            # keyed by the lowercased name - so every GPO script with a UNC or absolute
            # path collected this card, whose text explains that "this user account has a
            # scriptPath attribute" pointing somewhere unusual. The GPO rows have a card of
            # their own now: GPO_SCRIPT_OUTSIDE_POLICY_STORE.
            if ($SourceObject -and "$($SourceObject._adPEASObjectType)" -eq 'GPOScriptPath') { return $false }
            # Returns true if scriptPath is a UNC path (\\server\share) or absolute local path (C:\...)
            $strVal = [string]$Value
            if ([string]::IsNullOrWhiteSpace($strVal)) { return $false }
            return ($strVal -match '^\\\\[^\\]+\\' -or $strVal -match '^[A-Za-z]:[\\\/]')
        }

        'is_dc_uac' {
            # True if the object's userAccountControl carries SERVER_TRUST_ACCOUNT, which
            # is what makes it a domain controller.
            #
            # The flags have to come off the object rather than out of $Value: the UAC
            # transformer renders every flag as its own value, so $Value holds only the
            # one flag being tested. Reading the whole SourceObject as a string - which is
            # what this did - meant any other attribute containing the text
            # SERVER_TRUST_ACCOUNT, a description for instance, dampened the finding too.
            return (Test-UACFlagOnObject -SourceObject $SourceObject -Value $Value -FlagName 'SERVER_TRUST_ACCOUNT' -FlagBit 0x2000)
        }

        'is_not_dc_uac' {
            # The negation, for a finding that is a finding everywhere except on a domain
            # controller: TRUSTED_FOR_DELEGATION is the normal state of a DC, and the
            # remediation for unconstrained delegation would take it down.
            return (-not (Test-UACFlagOnObject -SourceObject $SourceObject -Value $Value -FlagName 'SERVER_TRUST_ACCOUNT' -FlagBit 0x2000))
        }

        'is_exchange_eol' {
            # Returns true if the Exchange version/build is EOL (not Standard severity)
            # For ExchangeBuildNumber: check build directly
            # For ExchangeVersion: check via SourceObject for build number
            $strValue = [string]$Value
            $severity = 'Standard'
            if ($strValue -match '^\d+\.\d+\.\d+') {
                # Build number format (e.g., 15.2.2562.37)
                $severity = Get-ExchangeSeverity -BuildNumber $strValue
            } elseif ($SourceObject) {
                # ExchangeVersion attribute - check SourceObject for build number
                $buildNum = if ($SourceObject.PSObject.Properties['ExchangeBuildNumber']) { $SourceObject.ExchangeBuildNumber } else { $null }
                if ($buildNum) {
                    $severity = Get-ExchangeSeverity -BuildNumber $buildNum
                } else {
                    $severity = Get-ExchangeSeverity -ProductName $strValue
                }
            } else {
                $severity = Get-ExchangeSeverity -ProductName $strValue
            }
            return ($severity -ne 'Standard')
        }

        'rbcd_principal_is_dangerous' {
            # Whether the check's own assessment of the principals found something. It
            # reads what the check decided rather than deciding again - see
            # Get-ResourceBasedConstrainedDelegation for the three cases that qualify: a
            # broad group, a principal the domain does not expect to delegate, and an
            # unresolved trustee that still holds the delegation.
            if ($SourceObject -and $SourceObject.rbcdTarget) { return $true }
            foreach ($entry in @($SourceObject.rbcdPrincipalRisk)) {
                if ([string]::IsNullOrWhiteSpace($entry)) { continue }
                if ($entry -match 'a broad group|not an identity this domain expects|unresolved - a deleted or foreign principal') { return $true }
            }
            return $false
        }

        'laps_read_is_expected' {
            # Whether this row's read access is the one the account is meant to have.
            # Get-LAPSCredentialAccess sets lapsReadContext only when the bound principal
            # is privileged, which is where "expected" comes from - the predicate does not
            # decide it, it reads what the check decided.
            if ($SourceObject -and $SourceObject.lapsReadContext) { return $true }
            return $false
        }

        'unix_password_usable_as_is' {
            # Whether any value on this object can be used without cracking anything.
            # Test-UnixPasswordUsableAsIs lives beside Get-UnixPasswordFormat so the
            # wording and the verdict that reads it cannot drift apart.
            if ($SourceObject -and $SourceObject.passwordFormat) {
                return (Test-UnixPasswordUsableAsIs -Format @($SourceObject.passwordFormat))
            }
            return $false
        }

        'credential_needs_review' {
            # Returns true if the source object has credentialType "(needs review)" (Tier2 pattern)
            if ($SourceObject -and $SourceObject.credentialType -and $SourceObject.credentialType -match '\(needs review\)') {
                return $true
            }
            return $false
        }

        'credential_not_needs_review' {
            # The inverse, for the Tier 1 triggers. A Tier 2 row carries the marker on
            # credentialType, so a trigger on matchedLine cannot exclude it by pattern -
            # the line itself says nothing about the tier. Without this, the Tier 1 card
            # (BaseScore 45) claimed every Tier 2 row from the Tier 2 card (20).
            if ($SourceObject -and $SourceObject.credentialType -and $SourceObject.credentialType -match '\(needs review\)') {
                return $false
            }
            return $true
        }

        'dangerous_rights_expected' {
            # Returns true if dangerousRightsSeverity indicates expected/privileged permissions
            if ($SourceObject -and $SourceObject.dangerousRightsSeverity) {
                return ($SourceObject.dangerousRightsSeverity -in @('Expected', 'Attention', 'Hint'))
            }
            return $false
        }

        'is_dnsadmins_sid' {
            # Returns true if the SID resolves to DnsAdmins (no fixed RID)
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { $null }
            if (-not $sid) { return $false }
            $resolvedName = ConvertFrom-SID -SID $sid
            return ($resolvedName -match '\\DnsAdmins$')
        }

        'is_esxadmins_sid' {
            # ESX Admins has no fixed RID either - VMware ESXi matches it by name, which is
            # the whole of CVE-2024-37085.
            $sid = if ($Value -is [string] -and $Value -match '^S-1-') { $Value }
                   elseif ($Value -is [PSCustomObject] -and $Value.PSObject.Properties['SID']) { $Value.SID }
                   else { $null }
            if (-not $sid) { return $false }
            $resolvedName = ConvertFrom-SID -SID $sid
            return ($resolvedName -match '\\ESX Admins$')
        }

        'days_over_365' {
            # Integer value > 365 (for daysSinceLastLogon/krbtgtPasswordAge)
            $strValue = [string]$Value
            if ($strValue -match '^(\d+)') {
                return ([int]$Matches[1] -gt 365)
            }
            return $false
        }

        'days_91_to_365' {
            # Integer value in range 91-365 (> 90 and <= 365)
            $strValue = [string]$Value
            if ($strValue -match '^(\d+)') {
                $days = [int]$Matches[1]
                return ($days -gt 90 -and $days -le 365)
            }
            return $false
        }

        'days_181_to_365' {
            # Integer value in range 181-365 (> 180 and <= 365)
            $strValue = [string]$Value
            if ($strValue -match '^(\d+)') {
                $days = [int]$Matches[1]
                return ($days -gt 180 -and $days -le 365)
            }
            return $false
        }

        'lt_8' {
            # Integer value < 8 or "Disabled" (for minimum password length = Finding)
            $strValue = [string]$Value
            if ($strValue -match 'Disabled') { return $true }
            $intValue = 0
            if ([int]::TryParse($strValue, [ref]$intValue)) {
                return ($intValue -lt 8)
            }
            if ($strValue -match '^(\d+)') {
                if ([int]::TryParse($Matches[1], [ref]$intValue)) {
                    return ($intValue -lt 8)
                }
            }
            return $false
        }

        'affected_computers_gt_10' {
            # Integer value > 10
            $intValue = 0
            if ([int]::TryParse([string]$Value, [ref]$intValue)) {
                return ($intValue -gt 10)
            }
            return $false
        }

        'affected_computers_gt_0' {
            # Integer value > 0 but <= 10
            $intValue = 0
            if ([int]::TryParse([string]$Value, [ref]$intValue)) {
                return ($intValue -gt 0 -and $intValue -le 10)
            }
            return $false
        }

        # =====================================================================
        # Existing custom triggers (unchanged)
        # =====================================================================

        'pwdAge_gt_1825' {
            # Password age > 5 years (1825 days)
            $pwdDate = Get-DateFromValue -Value $Value
            if ($pwdDate) {
                $pwdAge = ((Get-Date) - $pwdDate).Days
                return ($pwdAge -gt 1825)
            }
            return $false
        }
        'pwdAge_365_1825' {
            # Password age between 1-5 years
            $pwdDate = Get-DateFromValue -Value $Value
            if ($pwdDate) {
                $pwdAge = ((Get-Date) - $pwdDate).Days
                return ($pwdAge -gt 365 -and $pwdAge -le 1825)
            }
            return $false
        }
        'laps_pwd_length_lt_14' {
            # The LAPS password length a GPO sets, in characters. 14 is the product default
            # and what Microsoft's own template ships; below that the policy is weaker than
            # an untouched installation. 0 is not a length - it reads as "not set".
            $lengthValue = 0
            if ([int]::TryParse([string]$Value, [ref]$lengthValue)) {
                return ($lengthValue -gt 0 -and $lengthValue -lt 14)
            }
            return $false
        }
        'laps_pwd_age_31_90' {
            # Rotation interval in days, above the 30-day default but still within three
            # months. Mutually exclusive with laps_pwd_age_gt_90 on purpose: two triggers on
            # one attribute that can both match a value pick their winner by hashtable
            # enumeration order, which differs between PowerShell hosts.
            $ageValue = 0
            if ([int]::TryParse([string]$Value, [ref]$ageValue)) {
                return ($ageValue -gt 30 -and $ageValue -le 90)
            }
            return $false
        }
        'laps_pwd_age_gt_90' {
            # A local administrator password that stands for more than three months. The
            # maximum LAPS accepts is 365.
            $ageValue = 0
            if ([int]::TryParse([string]$Value, [ref]$ageValue)) {
                return ($ageValue -gt 90)
            }
            return $false
        }
        'gmsa_interval_gt_90' {
            # The gMSA password rotation interval, in days. Only a gMSA carries
            # msDS-ManagedPasswordInterval at all, so this predicate cannot colour
            # anything else - and the attribute was requested by Get-DomainUser
            # -ShowGMSADetails and then never read.
            $intervalDays = 0
            if ([int]::TryParse([string]$Value, [ref]$intervalDays)) {
                return ($intervalDays -gt 90)
            }
            return $false
        }
        'gt_0' {
            # Integer value > 0
            $intValue = 0
            if ([int]::TryParse([string]$Value, [ref]$intValue)) {
                return ($intValue -gt 0)
            }
            return $false
        }
        'lt_12' {
            # Integer value < 12 (for password length)
            $strValue = [string]$Value

            # "Disabled" is how the password policy renders a minimum length of 0, and it
            # is the worst state the setting has. Without this line it was the only value
            # that produced no finding at all: the row stood neutral in the report with no
            # impact, no remediation and no score, while "7 characters" was a finding. The
            # lt_8 predicate directly above has carried the same line for longer.
            if ($strValue -match 'Disabled') { return $true }

            $intValue = 0
            if ([int]::TryParse($strValue, [ref]$intValue)) {
                return ($intValue -lt 12)
            }
            if ($strValue -match '^(\d+)') {
                if ([int]::TryParse($Matches[1], [ref]$intValue)) {
                    return ($intValue -lt 12)
                }
            }
            return $false
        }
        'lt_10_minutes' {
            # Lockout duration < 10 minutes (extract number from "5 minutes")
            $strValue = [string]$Value
            # Skip "Forever" / "manual unlock" - those are secure
            if ($strValue -match 'Forever|Permanent|manual') {
                return $false
            }
            $intValue = 0
            if ([int]::TryParse($strValue, [ref]$intValue)) {
                return ($intValue -gt 0 -and $intValue -lt 10)
            }
            if ($strValue -match '^(\d+)') {
                if ([int]::TryParse($Matches[1], [ref]$intValue)) {
                    return ($intValue -gt 0 -and $intValue -lt 10)
                }
            }
            return $false
        }
        default {
            return $false
        }
    }
}

<#
.SYNOPSIS
    Converts various date value formats to DateTime.
.DESCRIPTION
    Handles pwdLastSet (FileTime), DateTime objects, and string representations.
#>
function Get-DateFromValue {
    param($Value)

    if ($null -eq $Value) { return $null }

    # Already a DateTime
    if ($Value -is [DateTime]) {
        return $Value
    }

    # FileTime (Int64)
    if ($Value -is [Int64] -or $Value -is [long]) {
        if ($Value -gt 0) {
            try {
                return [DateTime]::FromFileTime($Value)
            } catch {
                return $null
            }
        }
        return $null
    }

    # String representation
    $strValue = [string]$Value
    if ([string]::IsNullOrEmpty($strValue)) { return $null }

    # Try parsing as FileTime
    $longValue = 0
    if ([long]::TryParse($strValue, [ref]$longValue) -and $longValue -gt 0) {
        try {
            return [DateTime]::FromFileTime($longValue)
        } catch {
            # Fall through to DateTime parse
        }
    }

    # Try parsing as DateTime
    $dtValue = [DateTime]::MinValue
    if ([DateTime]::TryParse($strValue, [ref]$dtValue)) {
        return $dtValue
    }

    return $null
}

